pub const OwnedRowsLakeExpressionAggregateRequest = struct {
    request: lake_rows.ExpressionAggregateRequest,
    expressions: []algebraic_segment.ExpressionSpec = &.{},

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        for (self.expressions) |expression| {
            alloc.free(expression.name);
            if (expression.value_column.len != 0) alloc.free(expression.value_column);
        }
        if (self.expressions.len > 0) alloc.free(self.expressions);
        self.* = undefined;
    }
};

pub const OwnedRowsPlan = union(enum) {
    query: OwnedRowsQueryPlan,
    aggregate: OwnedRowsAggregatePlan,
    window: OwnedRowsWindowPlan,
    join: OwnedRowsJoinPlan,
    lateral: OwnedRowsLateralPlan,

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        switch (self.*) {
            .query => |*plan| plan.deinit(alloc),
            .aggregate => |*plan| plan.deinit(alloc),
            .window => |*plan| plan.deinit(alloc),
            .join => |*plan| plan.deinit(alloc),
            .lateral => |*plan| plan.deinit(alloc),
        }
        self.* = undefined;
    }
};

pub const RowsPlanOperation = enum {
    query,
    aggregate,
    window,
    join,
    lateral,
};

