    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        if (self.left_table.len > 0) alloc.free(self.left_table);
        if (self.right_table.len > 0) alloc.free(self.right_table);
        self.* = undefined;
    }
