pub fn buildRowsInsertSourceBatchFromLiteralRowsDbAcrossRangesAndDefaultContextAndRowScalarSubqueriesAlloc(
    alloc: std.mem.Allocator,
    db: *db_mod.DB,
    table_name: []const u8,
    target_schema: runtime_schema.TableSchema,
    source_schema: runtime_schema.TableSchema,
    req: db_mod.types.RelationalRowsInsertSourceRequest,
    literal_source_rows: []const []const u8,
    literal_source_row_scalar_subqueries: []const []const db_mod.types.RelationalRowsScalarSubqueryProjection,
    source_ranges: []const db_mod.types.RelationalRowsDocKeyRange,
    conflict_resolver: ?UniqueSelectorResolver,
    default_context: DefaultValueContext,
) !OwnedRowsBatchRequest {
    if (literal_source_rows.len == 0) return error.InvalidRowsRequest;
    if (req.source.source_cte.len != 0) return error.InvalidRowsRequest;
    if (literal_source_row_scalar_subqueries.len != 0 and literal_source_row_scalar_subqueries.len != literal_source_rows.len) return error.InvalidRowsRequest;

    const materialized_rows = try literalRowsWithHiddenScalarSubqueriesFromDbAlloc(
        alloc,
        db,
        source_schema,
        req.source.scalar_subqueries,
        literal_source_row_scalar_subqueries,
        literal_source_rows,
        source_ranges,
    );
    defer freeStringSlice(alloc, materialized_rows);

    return try buildRowsInsertSourceBatchWithSchemasAndDefaultContextAlloc(
        alloc,
        table_name,
        target_schema,
        source_schema,
        req,
        materialized_rows,
        conflict_resolver,
        default_context,
    );
}

fn literalRowsWithHiddenScalarSubqueriesFromDbAlloc(
    alloc: std.mem.Allocator,
    db: *db_mod.DB,
    source_schema: runtime_schema.TableSchema,
    scalar_subqueries: []const db_mod.types.RelationalRowsScalarSubqueryProjection,
    row_scalar_subqueries: []const []const db_mod.types.RelationalRowsScalarSubqueryProjection,
    literal_source_rows: []const []const u8,
    source_ranges: []const db_mod.types.RelationalRowsDocKeyRange,
) ![]const []const u8 {
    const rows = try alloc.alloc([]const u8, literal_source_rows.len);
    var initialized: usize = 0;
    errdefer {
        for (rows[0..initialized]) |row| alloc.free(row);
        alloc.free(rows);
    }

    for (literal_source_rows, 0..) |row_json, i| {
        const effective_scalar_subqueries = if (row_scalar_subqueries.len != 0 and row_scalar_subqueries[i].len != 0) row_scalar_subqueries[i] else scalar_subqueries;
        rows[i] = if (!hiddenScalarSubqueriesPresent(effective_scalar_subqueries))
            try alloc.dupe(u8, row_json)
        else
            try rowJsonWithHiddenScalarSubqueriesFromDbAlloc(alloc, db, source_schema, row_json, effective_scalar_subqueries, source_ranges);
        initialized += 1;
    }
    return rows;
}

const LiteralScalarSubqueryValue = struct {
    output: []const u8,
    value_json: []const u8,
};

fn hiddenScalarSubqueriesPresent(scalar_subqueries: []const db_mod.types.RelationalRowsScalarSubqueryProjection) bool {
    for (scalar_subqueries) |projection| {
        if (projection.hidden) return true;
    }
    return false;
}

fn rowJsonWithHiddenScalarSubqueriesFromDbAlloc(
    alloc: std.mem.Allocator,
    db: *db_mod.DB,
    source_schema: runtime_schema.TableSchema,
    row_json: []const u8,
    scalar_subqueries: []const db_mod.types.RelationalRowsScalarSubqueryProjection,
    source_ranges: []const db_mod.types.RelationalRowsDocKeyRange,
) ![]const u8 {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidRowsRequest;

    var scalar_values = std.ArrayListUnmanaged(LiteralScalarSubqueryValue).empty;
    defer {
        for (scalar_values.items) |value| alloc.free(value.value_json);
        scalar_values.deinit(alloc);
    }

    for (scalar_subqueries) |projection| {
        if (!projection.hidden) continue;
        const value_json = try scalarSubqueryProjectionValueJsonFromDbAlloc(alloc, db, source_schema, parsed.value, projection, source_ranges);
        errdefer alloc.free(value_json);
        try scalar_values.append(alloc, .{
            .output = projection.output,
            .value_json = value_json,
        });
    }
    return try rowJsonWithHiddenScalarValuesFromParsedAlloc(alloc, parsed.value, scalar_values.items);
}

fn scalarSubqueryProjectionValueJsonFromDbAlloc(
    alloc: std.mem.Allocator,
    db: *db_mod.DB,
    source_schema: runtime_schema.TableSchema,
    outer_row: std.json.Value,
    projection: db_mod.types.RelationalRowsScalarSubqueryProjection,
    source_ranges: []const db_mod.types.RelationalRowsDocKeyRange,
) ![]const u8 {
    var query = projection.query;
    var correlated_predicates: []runtime_schema.RelationalCheck = &.{};
    defer freeOwnedRelationalChecks(alloc, correlated_predicates);
    var combined_predicates: []runtime_schema.RelationalCheck = &.{};
    defer if (combined_predicates.len > 0) alloc.free(combined_predicates);
    if (projection.correlations.len != 0) {
        correlated_predicates = try lateralCorrelationPredicatesAlloc(alloc, outer_row, projection.correlations);
        if (correlated_predicates.len != projection.correlations.len) return try alloc.dupe(u8, "null");
        combined_predicates = try combinedBorrowedAndOwnedRelationalChecksAlloc(alloc, projection.query.predicates, correlated_predicates);
        query.predicates = combined_predicates;
    }

    var result = try db.queryRelationalRowsAcrossRanges(alloc, source_schema, query, source_ranges);
    defer result.deinit(alloc);
    if (result.rows.len > 1) return error.InvalidRowsRequest;
    if (result.rows.len == 0) return try alloc.dupe(u8, "null");

    var parsed = std.json.parseFromSlice(std.json.Value, alloc, result.rows[0], .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    const value = jsonValueAtPath(parsed.value, projection.output_field) orelse return try alloc.dupe(u8, "null");
    return try jsonValueStringifyAlloc(alloc, value.*);
}

fn lateralCorrelationPredicatesAlloc(
    alloc: std.mem.Allocator,
    left_row: std.json.Value,
    correlations: []const db_mod.types.RelationalRowsLateralCorrelation,
) ![]runtime_schema.RelationalCheck {
    const predicates = try alloc.alloc(runtime_schema.RelationalCheck, correlations.len);
    var initialized: usize = 0;
    errdefer {
        freeOwnedRelationalCheckContents(alloc, predicates[0..initialized]);
        alloc.free(predicates);
    }
    for (correlations) |correlation| {
        const selected = jsonValueAtPath(left_row, correlation.left_field) orelse break;
        if (selected.* == .null) break;
        const value_json = switch (selected.*) {
            .bool, .integer, .float, .string => try jsonValueStringifyAlloc(alloc, selected.*),
            else => return error.InvalidRowsRequest,
        };
        var value_transferred = false;
        errdefer if (!value_transferred) alloc.free(value_json);
        const name = try alloc.dupe(u8, "");
        var name_transferred = false;
        errdefer if (!name_transferred) alloc.free(name);
        const field = try alloc.dupe(u8, correlation.right_field);
        var field_transferred = false;
        errdefer if (!field_transferred) alloc.free(field);
        predicates[initialized] = .{
            .name = name,
            .field = field,
            .op = correlation.op,
            .value_json = value_json,
        };
        initialized += 1;
        name_transferred = true;
        field_transferred = true;
        value_transferred = true;
    }
    if (initialized != correlations.len) {
        freeOwnedRelationalCheckContents(alloc, predicates[0..initialized]);
        alloc.free(predicates);
        return &.{};
    }
    return predicates;
}

fn combinedBorrowedAndOwnedRelationalChecksAlloc(
    alloc: std.mem.Allocator,
    borrowed: []const runtime_schema.RelationalCheck,
    owned: []const runtime_schema.RelationalCheck,
) ![]runtime_schema.RelationalCheck {
    const combined = try alloc.alloc(runtime_schema.RelationalCheck, borrowed.len + owned.len);
    @memcpy(combined[0..borrowed.len], borrowed);
    @memcpy(combined[borrowed.len..], owned);
    return combined;
}

fn freeOwnedRelationalChecks(alloc: std.mem.Allocator, checks: []const runtime_schema.RelationalCheck) void {
    freeOwnedRelationalCheckContents(alloc, checks);
    if (checks.len > 0) alloc.free(checks);
}

fn freeOwnedRelationalCheckContents(alloc: std.mem.Allocator, checks: []const runtime_schema.RelationalCheck) void {
    for (checks) |check| {
        if (check.name.len > 0) alloc.free(@constCast(check.name));
        if (check.field.len > 0) alloc.free(@constCast(check.field));
        if (check.value_json) |value_json| if (value_json.len > 0) alloc.free(@constCast(value_json));
    }
}

fn rowJsonWithHiddenScalarValuesAlloc(
    alloc: std.mem.Allocator,
    row_json: []const u8,
    scalar_values: []const LiteralScalarSubqueryValue,
) ![]const u8 {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidRowsRequest;
    return try rowJsonWithHiddenScalarValuesFromParsedAlloc(alloc, parsed.value, scalar_values);
}

fn rowJsonWithHiddenScalarValuesFromParsedAlloc(
    alloc: std.mem.Allocator,
    row_value: std.json.Value,
    scalar_values: []const LiteralScalarSubqueryValue,
) ![]const u8 {
    if (row_value != .object) return error.InvalidRowsRequest;
    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.writeByte('{');
    var first = true;
    for (row_value.object.keys(), row_value.object.values()) |field, value| {
        for (scalar_values) |scalar_value| {
            if (std.mem.eql(u8, field, scalar_value.output)) return error.InvalidRowsRequest;
        }
        if (!first) try writer.writeByte(',');
        first = false;
        try writer.print("{f}:", .{std.json.fmt(field, .{})});
        try std.json.Stringify.value(value, .{}, writer);
    }
    for (scalar_values) |scalar_value| {
        if (!first) try writer.writeByte(',');
        first = false;
        try writer.print("{f}:{s}", .{ std.json.fmt(scalar_value.output, .{}), scalar_value.value_json });
    }
    try writer.writeByte('}');
    return try out.toOwnedSlice();
}

pub fn buildRowsInsertSourcePlanBatchOnJsonRowsAlloc(
    alloc: std.mem.Allocator,
    table_name: []const u8,
    target_schema: runtime_schema.TableSchema,
    base_source_schema: runtime_schema.TableSchema,
    plan: OwnedRowsInsertSourcePlan,
    base_source_rows: []const []const u8,
    conflict_resolver: ?UniqueSelectorResolver,
) !OwnedRowsBatchRequest {
    if (target_schema.storage_mode != .relational or target_schema.primary_key == null) return error.InvalidRowsRequest;
    if (base_source_schema.storage_mode != .relational) return error.InvalidRowsRequest;
    try validateRowsPlanRanges(plan.ranges);

    const planned_ctes = try planRowsCteOutputsAlloc(alloc, base_source_schema, plan.ctes);
    defer freeRowsPlannedCtes(alloc, planned_ctes);
    try validateRowsInsertSourceAgainstPlannedCteOutput(planned_ctes, plan.insert_source);

    var materialized_ctes = std.ArrayListUnmanaged(RowsJsonMaterializedCte).empty;
    defer {
        for (materialized_ctes.items) |*cte| cte.deinit(alloc);
        materialized_ctes.deinit(alloc);
    }
    try materializeRowsJsonCtesAlloc(alloc, base_source_schema, base_source_rows, plan.ranges, plan.ctes, planned_ctes, &materialized_ctes);

    var final_source_rows: []const []const u8 = base_source_rows;
    var final_source_schema = base_source_schema;
    var final_source_ranges: []const db_mod.types.RelationalRowsDocKeyRange = plan.ranges;
    var loaded_final_source: ?OwnedRowsQueryResult = null;
    defer if (loaded_final_source) |*loaded| loaded.deinit(alloc);
    if (plan.insert_source.source.source_cte.len != 0) {
        const cte = findRowsJsonMaterializedCte(materialized_ctes.items, plan.insert_source.source.source_cte) orelse return error.InvalidRowsRequest;
        switch (cte.rows) {
            .memory => |result| final_source_rows = result.rows,
            .spilled => |spill| {
                loaded_final_source = try loadRowsJsonSpilledCteAlloc(alloc, spill);
                final_source_rows = loaded_final_source.?.rows;
            },
        }
        final_source_schema = cte.schema;
        final_source_ranges = &.{};
    }

    var final_source_query = plan.insert_source.source;
    final_source_query.source_cte = "";
    var final_source_result = try executeRowsQueryOnJsonRowsAcrossRangesAlloc(alloc, final_source_schema, final_source_query, final_source_rows, final_source_ranges);
    defer final_source_result.deinit(alloc);

    var batch = try buildRowsInsertSourceBatchFromSelectedRowsWithSchemasAndDefaultContextAlloc(
        alloc,
        table_name,
        target_schema,
        final_source_schema,
        plan.insert_source,
        final_source_result.rows,
        conflict_resolver,
        .{},
    );
    batch.req.sync_level = plan.sync_level;
    return batch;
}

pub fn buildRowsInsertSourcePlanBatchFromDbAlloc(
    alloc: std.mem.Allocator,
    db: *db_mod.DB,
    table_name: []const u8,
    target_schema: runtime_schema.TableSchema,
    base_source_schema: runtime_schema.TableSchema,
    plan: OwnedRowsInsertSourcePlan,
    conflict_resolver: ?UniqueSelectorResolver,
) !OwnedRowsBatchRequest {
    if (base_source_schema.storage_mode != .relational or base_source_schema.primary_key == null) return error.InvalidRowsRequest;
    const base_preimages = try db.collectRelationalRowsPreimagesAcrossRangesAlloc(alloc, base_source_schema, .{ .select_all = true }, plan.ranges);
    defer db_mod.types.freeRelationalRowsCollectedRows(alloc, base_preimages);

    const base_rows = try alloc.alloc([]const u8, base_preimages.len);
    defer alloc.free(base_rows);
    for (base_preimages, 0..) |row, i| base_rows[i] = row.json;

    return try buildRowsInsertSourcePlanBatchOnJsonRowsAlloc(
        alloc,
        table_name,
        target_schema,
        base_source_schema,
        plan,
        base_rows,
        conflict_resolver,
    );
}

pub fn executeRowsQueryPlanOnJsonRowsAlloc(
    alloc: std.mem.Allocator,
    base_schema: runtime_schema.TableSchema,
    plan: OwnedRowsQueryPlan,
    base_rows: []const []const u8,
) !OwnedRowsQueryResult {
    if (base_schema.storage_mode != .relational) return error.InvalidRowsRequest;
    try validateRowsPlanRanges(plan.ranges);

    const planned_ctes = try planRowsCteOutputsAlloc(alloc, base_schema, plan.ctes);
    defer freeRowsPlannedCtes(alloc, planned_ctes);
    try validateRowsQueryAgainstPlannedCteOutput(planned_ctes, plan.query);

    var materialized_ctes = std.ArrayListUnmanaged(RowsJsonMaterializedCte).empty;
    defer {
        for (materialized_ctes.items) |*cte| cte.deinit(alloc);
        materialized_ctes.deinit(alloc);
    }
    try materializeRowsJsonCtesAlloc(alloc, base_schema, base_rows, plan.ranges, plan.ctes, planned_ctes, &materialized_ctes);

    var query_rows: []const []const u8 = base_rows;
    var query_schema = base_schema;
    var query_ranges: []const db_mod.types.RelationalRowsDocKeyRange = plan.ranges;
    var loaded_query_source: ?OwnedRowsQueryResult = null;
    defer if (loaded_query_source) |*loaded| loaded.deinit(alloc);
    if (plan.query.source_cte.len != 0) {
        const cte = findRowsJsonMaterializedCte(materialized_ctes.items, plan.query.source_cte) orelse return error.InvalidRowsRequest;
        switch (cte.rows) {
            .memory => |result| query_rows = result.rows,
            .spilled => |spill| {
                loaded_query_source = try loadRowsJsonSpilledCteAlloc(alloc, spill);
                query_rows = loaded_query_source.?.rows;
            },
        }
        query_schema = cte.schema;
        query_ranges = &.{};
    }

    var query = plan.query;
    query.source_cte = "";
    return try executeRowsQueryOnJsonRowsAcrossRangesAlloc(alloc, query_schema, query, query_rows, query_ranges);
}

pub fn executeRowsQueryPlanFromDbAlloc(
    alloc: std.mem.Allocator,
    db: *db_mod.DB,
    base_schema: runtime_schema.TableSchema,
    plan: OwnedRowsQueryPlan,
) !OwnedRowsQueryResult {
    if (base_schema.storage_mode != .relational or base_schema.primary_key == null) return error.InvalidRowsRequest;
    var base_rows = try collectRowsPlanRowsFromDbAlloc(alloc, db, base_schema, plan.ranges);
    defer base_rows.deinit(alloc);

    return try executeRowsQueryPlanOnJsonRowsAlloc(alloc, base_schema, plan, base_rows.rows);
}

pub fn executeRowsSetOperationPlanOnJsonRowsAlloc(
    alloc: std.mem.Allocator,
    base_schema: runtime_schema.TableSchema,
    plan: db_mod.types.RelationalRowsSetOperationPlan,
    base_rows: []const []const u8,
) !OwnedRowsQueryResult {
    return try executeRowsSetOperationPlanOnJsonRowsWithSourcesAlloc(alloc, base_schema, plan, base_rows, &.{});
}

pub fn executeRowsSetOperationPlanOnJsonRowsWithSourcesAlloc(
    alloc: std.mem.Allocator,
    base_schema: runtime_schema.TableSchema,
    plan: db_mod.types.RelationalRowsSetOperationPlan,
    base_rows: []const []const u8,
    cte_sources: []const RowsCteJsonSource,
) !OwnedRowsQueryResult {
    if (base_schema.storage_mode != .relational) return error.InvalidRowsRequest;
    if (plan.left.ctes.len != 0 or plan.right.ctes.len != 0) return error.InvalidRowsRequest;
    try validateRowsPlanRanges(plan.left.ranges);
    try validateRowsPlanRanges(plan.right.ranges);

    const cte_ranges = try rowsPlanRangesForSetOperationAlloc(alloc, plan.left.ranges, plan.right.ranges);
    defer if (cte_ranges.len > 0) alloc.free(cte_ranges);
    var materialized_ctes = try materializeRowsJsonPlanCtesWithSourcesAlloc(alloc, base_schema, base_rows, cte_ranges, plan.ctes, cte_sources);
    defer materialized_ctes.deinit(alloc);
    try validateRowsQueryAgainstPlannedCteOutput(materialized_ctes.planned, plan.left.query);
    try validateRowsQueryAgainstPlannedCteOutput(materialized_ctes.planned, plan.right.query);

    var left = try executeRowsSetOperationSideOnJsonRowsAlloc(
        alloc,
        base_schema,
        base_rows,
        materialized_ctes.ctes.items,
        "set_operation_left",
        plan.left,
    );
    defer left.deinit(alloc);
    var right = try executeRowsSetOperationSideOnJsonRowsAlloc(
        alloc,
        base_schema,
        base_rows,
        materialized_ctes.ctes.items,
        "set_operation_right",
        plan.right,
    );
    defer right.deinit(alloc);

    var combined = try db_mod.DB.relationalRowsSetOperationRowsAlloc(alloc, plan.operation, left.rows, right.rows);
    var combined_owned = true;
    defer if (combined_owned) row_spill.freeJsonRows(alloc, combined);

    const materialized_bytes = db_mod.types.relationalRowsCteMaterializedJsonBytes(combined) orelse return error.UnsupportedRowsQuery;
    switch (db_mod.types.relationalRowsSetOperationMaterializationDecision(plan, combined.len, materialized_bytes)) {
        .memory => {},
        .reject => return error.RelationalRowsCteMaterializationRejected,
        .spill => {
            combined = try row_spill.spillAndReloadOwnedJsonRowsAlloc(alloc, combined, materialized_bytes, "set-operation");
            combined_owned = true;
        },
    }
    return try db_mod.DB.queryRelationalRowsFromSourceRowsStaticAlloc(alloc, "set_operation", combined, .{
        .select_all = true,
        .order_by = plan.order_by,
        .limit = plan.limit,
        .offset = plan.offset,
    });
}

fn executeRowsSetOperationSideOnJsonRowsAlloc(
    alloc: std.mem.Allocator,
    base_schema: runtime_schema.TableSchema,
    base_rows: []const []const u8,
    materialized_ctes: []RowsJsonMaterializedCte,
    base_name: []const u8,
    plan: OwnedRowsQueryPlan,
) !OwnedRowsQueryResult {
    var source = (try rowsJsonSourceForQueryAlloc(alloc, materialized_ctes, base_name, base_schema, base_rows, plan.query.source_cte)) orelse return error.InvalidRowsRequest;
    defer source.deinit(alloc);
    var query = plan.query;
    query.source_cte = "";
    const ranges: []const db_mod.types.RelationalRowsDocKeyRange = if (plan.query.source_cte.len == 0) plan.ranges else &.{};
    return try executeRowsQueryOnJsonRowsAcrossRangesAlloc(alloc, source.schema, query, source.rows, ranges);
}

pub fn executeRowsAggregatePlanOnJsonRowsAlloc(
    alloc: std.mem.Allocator,
    base_schema: runtime_schema.TableSchema,
    plan: OwnedRowsAggregatePlan,
    base_rows: []const []const u8,
) !db_mod.types.RelationalRowsAggregateResult {
    if (base_schema.storage_mode != .relational) return error.InvalidRowsRequest;
    try validateRowsPlanRanges(plan.ranges);
    try validateRowsAggregatePlanCteOutputAlloc(alloc, base_schema, plan);

    var materialized_ctes = try materializeRowsJsonPlanCtesAlloc(alloc, base_schema, base_rows, plan.ranges, plan.ctes);
    defer materialized_ctes.deinit(alloc);

