    var out = std.ArrayListUnmanaged(db_mod.types.RelationalRowsDocKeyRange).empty;
    errdefer out.deinit(alloc);
    for (sorted) |range| {
        if (out.items.len == 0) {
            try out.append(alloc, range);
            continue;
        }
        const last = &out.items[out.items.len - 1];
        if (rowsDocKeyRangesOverlapOrTouch(last.*, range)) {
            last.end = rowsDocKeyRangeMaxEnd(last.end, range.end);
        } else {
            try out.append(alloc, range);
        }
    }
    return try out.toOwnedSlice(alloc);
}

fn rowsDocKeyRangesOverlapOrTouch(lhs: db_mod.types.RelationalRowsDocKeyRange, rhs: db_mod.types.RelationalRowsDocKeyRange) bool {
    if (lhs.end.len == 0) return true;
    if (rhs.start.len == 0) return true;
    return std.mem.order(u8, rhs.start, lhs.end) != .gt;
}

fn rowsDocKeyRangeMaxEnd(lhs: []const u8, rhs: []const u8) []const u8 {
    if (lhs.len == 0 or rhs.len == 0) return "";
    return if (std.mem.order(u8, lhs, rhs) == .lt) rhs else lhs;
}

fn rowsDocKeyRangeLessThan(_: void, lhs: db_mod.types.RelationalRowsDocKeyRange, rhs: db_mod.types.RelationalRowsDocKeyRange) bool {
    if (lhs.start.len == 0) return rhs.start.len != 0;
    if (rhs.start.len == 0) return false;
    const start_order = std.mem.order(u8, lhs.start, rhs.start);
    if (start_order != .eq) return start_order == .lt;
    if (lhs.end.len == 0) return false;
    if (rhs.end.len == 0) return true;
    return std.mem.order(u8, lhs.end, rhs.end) == .lt;
}

fn materializeRowsJsonCtesAlloc(
    alloc: std.mem.Allocator,
    base_schema: runtime_schema.TableSchema,
    base_rows: []const []const u8,
    ranges: []const db_mod.types.RelationalRowsDocKeyRange,
    ctes: []const db_mod.types.RelationalRowsCte,
    planned_ctes: []const RowsPlannedCte,
    materialized_ctes: *std.ArrayListUnmanaged(RowsJsonMaterializedCte),
) !void {
    return try materializeRowsJsonCtesWithSourcesAlloc(alloc, base_schema, base_rows, ranges, ctes, &.{}, planned_ctes, materialized_ctes);
}

fn rowsJsonSourceForCteSideAlloc(
    alloc: std.mem.Allocator,
    materialized_ctes: []RowsJsonMaterializedCte,
    base_name: []const u8,
    base_schema: runtime_schema.TableSchema,
    base_rows: []const []const u8,
    source_cte: []const u8,
    table_name: []const u8,
    cte_sources: []const RowsCteJsonSource,
) !?RowsJsonSource {
    if (source_cte.len != 0) return try rowsJsonSourceForQueryAlloc(alloc, materialized_ctes, base_name, base_schema, base_rows, source_cte);
    if (table_name.len == 0 or cte_sources.len == 0) return .{ .name = base_name, .schema = base_schema, .rows = base_rows };
    for (cte_sources) |source| {
        if (std.mem.eql(u8, source.table_name, table_name)) {
            return .{ .name = table_name, .schema = source.schema, .rows = source.rows };
        }
    }
    return null;
}

fn materializeRowsJsonCtesWithSourcesAlloc(
    alloc: std.mem.Allocator,
    base_schema: runtime_schema.TableSchema,
    base_rows: []const []const u8,
    ranges: []const db_mod.types.RelationalRowsDocKeyRange,
    ctes: []const db_mod.types.RelationalRowsCte,
    cte_sources: []const RowsCteJsonSource,
    planned_ctes: []const RowsPlannedCte,
    materialized_ctes: *std.ArrayListUnmanaged(RowsJsonMaterializedCte),
) !void {
    if (ctes.len != planned_ctes.len) return error.InvalidRowsRequest;
    for (ctes, 0..) |cte, cte_index| {
        var result: OwnedRowsQueryResult = if (cte.join) |join| blk: {
            const left_schema = rowsReadCteSideOutputSchema(base_schema, planned_ctes[0..cte_index], join.left, cte.left_table, cte_sources) orelse return error.InvalidRowsRequest;
            const right_schema = rowsReadCteSideOutputSchema(base_schema, planned_ctes[0..cte_index], join.right, cte.right_table, cte_sources) orelse return error.InvalidRowsRequest;
            var left_source = (try rowsJsonSourceForCteSideAlloc(alloc, materialized_ctes.items, "cte_join_left", left_schema, base_rows, join.left.source_cte, cte.left_table, cte_sources)) orelse return error.InvalidRowsRequest;
            defer left_source.deinit(alloc);
            var left_query = rowsJoinSideSourceQuery(join.left);
            left_query.source_cte = "";
            const left_ranges: []const db_mod.types.RelationalRowsDocKeyRange = if (join.left.source_cte.len == 0) ranges else &.{};
            var left_result = try executeRowsQueryOnJsonRowsAcrossRangesAlloc(alloc, left_source.schema, left_query, left_source.rows, left_ranges);
            defer left_result.deinit(alloc);

            var right_source = (try rowsJsonSourceForCteSideAlloc(alloc, materialized_ctes.items, "cte_join_right", right_schema, base_rows, join.right.source_cte, cte.right_table, cte_sources)) orelse return error.InvalidRowsRequest;
            defer right_source.deinit(alloc);
            var right_query = rowsJoinSideSourceQuery(join.right);
            right_query.source_cte = "";
            const right_ranges: []const db_mod.types.RelationalRowsDocKeyRange = if (join.right.source_cte.len == 0) ranges else &.{};
            var right_result = try executeRowsQueryOnJsonRowsAcrossRangesAlloc(alloc, right_source.schema, right_query, right_source.rows, right_ranges);
            defer right_result.deinit(alloc);

            var cte_join = join;
            _ = db_mod.types.relationalRowsSelectJoinStrategy(cte_join, left_result.rows.len, right_result.rows.len, db_mod.types.relationalRowsJoinInputsSortedOnJoinKeys(cte_join)) orelse return error.UnsupportedRowsQuery;
            cte_join.left.source_cte = "";
            cte_join.right.source_cte = "";
            cte_join.left.doc_key_range = null;
            cte_join.right.doc_key_range = null;
            var join_result = try db_mod.DB.joinRelationalRowsFromSourceRowsAlloc(alloc, cte_join, left_result.rows, right_result.rows);
            const rows = join_result.rows;
            join_result.rows = &.{};
            break :blk .{ .rows = rows, .total = join_result.total_rows };
        } else if (cte.lateral) |lateral_req| blk: {
            const left_schema = rowsReadCteSideOutputSchema(base_schema, planned_ctes[0..cte_index], lateral_req.left, cte.left_table, cte_sources) orelse return error.InvalidRowsRequest;
            const right_schema = rowsReadCteSideOutputSchema(base_schema, planned_ctes[0..cte_index], lateral_req.right, cte.right_table, cte_sources) orelse return error.InvalidRowsRequest;
            var left_source = (try rowsJsonSourceForCteSideAlloc(alloc, materialized_ctes.items, "cte_lateral_left", left_schema, base_rows, lateral_req.left.source_cte, cte.left_table, cte_sources)) orelse return error.InvalidRowsRequest;
            defer left_source.deinit(alloc);
            var left_query = rowsLateralLeftSourceQuery(lateral_req.left);
            left_query.source_cte = "";
            const left_ranges: []const db_mod.types.RelationalRowsDocKeyRange = if (lateral_req.left.source_cte.len == 0) ranges else &.{};
            var left_result = try executeRowsQueryOnJsonRowsAcrossRangesAlloc(alloc, left_source.schema, left_query, left_source.rows, left_ranges);
            defer left_result.deinit(alloc);

            var right_source = (try rowsJsonSourceForCteSideAlloc(alloc, materialized_ctes.items, "cte_lateral_right", right_schema, base_rows, lateral_req.right.source_cte, cte.right_table, cte_sources)) orelse return error.InvalidRowsRequest;
            defer right_source.deinit(alloc);
            var lateral = lateral_req;
            lateral.left.source_cte = "";
            lateral.right.source_cte = "";
            const right_ranges: []const db_mod.types.RelationalRowsDocKeyRange = if (lateral_req.right.source_cte.len == 0) ranges else &.{};
            if (right_ranges.len > 0 and lateral.right.doc_key_range != null) return error.InvalidRowsRequest;
            var range_filtered_right_rows = std.ArrayListUnmanaged([]const u8).empty;
            defer range_filtered_right_rows.deinit(alloc);
            const ranged_right_rows = try rowsJsonSourceRowsForRangesAlloc(alloc, right_source.schema, right_source.rows, right_ranges, &range_filtered_right_rows);

            var doc_range_filtered_right_rows = std.ArrayListUnmanaged([]const u8).empty;
            defer doc_range_filtered_right_rows.deinit(alloc);
            const right_rows = if (lateral.right.doc_key_range) |_|
                try rowsJsonSourceRowsForDocKeyRangeAlloc(alloc, right_source.schema, ranged_right_rows, lateral.right.doc_key_range, &doc_range_filtered_right_rows)
            else
                ranged_right_rows;
            lateral.left.doc_key_range = null;
            lateral.right.doc_key_range = null;
            var lateral_result = try db_mod.DB.lateralRelationalRowsFromSourceRowsStaticAlloc(alloc, lateral, left_result.rows, right_rows);
            const rows = lateral_result.rows;
            lateral_result.rows = &.{};
            break :blk .{ .rows = rows, .total = lateral_result.total_rows };
        } else blk: {
            if (cte.query.row_claim != null or cte.query.doc_key_range != null) return error.InvalidRowsRequest;
            const source_schema = rowsPlannedQuerySourceSchema(base_schema, planned_ctes[0..cte_index], cte.query) orelse return error.InvalidRowsRequest;
            var source = (try rowsJsonSourceForQueryAlloc(alloc, materialized_ctes.items, "cte_source", base_schema, base_rows, cte.query.source_cte)) orelse return error.InvalidRowsRequest;
            defer source.deinit(alloc);

            var query = cte.query;
            query.source_cte = "";
            const source_ranges: []const db_mod.types.RelationalRowsDocKeyRange = if (cte.query.source_cte.len == 0) ranges else &.{};
            break :blk try executeRowsQueryOnJsonRowsAcrossRangesAlloc(alloc, source_schema, query, source.rows, source_ranges);
        };
        var result_transferred = false;
        errdefer if (!result_transferred) result.deinit(alloc);
        const materialized_bytes = db_mod.types.relationalRowsCteMaterializedJsonBytes(result.rows) orelse return error.UnsupportedRowsQuery;
        var materialized_rows: RowsJsonMaterializedCteRows = switch (db_mod.types.relationalRowsCteMaterializationDecision(cte, result.rows.len, materialized_bytes)) {
            .memory => blk: {
                result_transferred = true;
                break :blk .{ .memory = result };
            },
            .spill => blk: {
                const spill = try spillRowsJsonCteResultAlloc(alloc, result, materialized_bytes);
                result.deinit(alloc);
                result_transferred = true;
                break :blk .{ .spilled = spill };
            },
            .reject => return error.RelationalRowsCteMaterializationRejected,
        };
        var materialized_rows_transferred = false;
        errdefer if (!materialized_rows_transferred) materialized_rows.deinit(alloc);
        try materialized_ctes.append(alloc, .{
            .name = cte.name,
            .schema = rowsSchemaFromPlannedCte(planned_ctes[cte_index]),
            .rows = materialized_rows,
        });
        materialized_rows_transferred = true;
    }
}

fn findRowsJsonMaterializedCte(ctes: []RowsJsonMaterializedCte, name: []const u8) ?*RowsJsonMaterializedCte {
    for (ctes) |*cte| {
        if (std.mem.eql(u8, cte.name, name)) return cte;
    }
    return null;
}

pub const UniqueSelectorResolver = struct {
    ptr: *anyopaque,
    resolve: *const fn (
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        constraint_name: []const u8,
        encoded_value: []const u8,
    ) anyerror!?[]u8,
    resolve_temporal: ?*const fn (
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        constraint_name: []const u8,
        encoded_value: []const u8,
        encoded_point: []const u8,
    ) anyerror!?[]u8 = null,
    resolve_temporal_overlap: ?*const fn (
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        constraint_name: []const u8,
        encoded_value: []const u8,
        encoded_start: []const u8,
        encoded_end: []const u8,
    ) anyerror!?[]u8 = null,
    resolve_primary: ?*const fn (
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        physical_key: []const u8,
    ) anyerror!bool = null,
    lookup_primary: ?*const fn (
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        physical_key: []const u8,
    ) anyerror!?ResolvedPrimaryRow = null,

    pub fn resolveUnique(
        self: UniqueSelectorResolver,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        constraint_name: []const u8,
        encoded_value: []const u8,
    ) !?[]u8 {
        return try self.resolve(self.ptr, alloc, table_name, constraint_name, encoded_value);
    }

    pub fn resolveTemporalUnique(
        self: UniqueSelectorResolver,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        constraint_name: []const u8,
        encoded_value: []const u8,
        encoded_point: []const u8,
    ) !?[]u8 {
        const func = self.resolve_temporal orelse return error.UnsupportedRowsSelector;
        return try func(self.ptr, alloc, table_name, constraint_name, encoded_value, encoded_point);
    }

    pub fn resolveTemporalUniqueOverlap(
        self: UniqueSelectorResolver,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        constraint_name: []const u8,
        encoded_value: []const u8,
        encoded_start: []const u8,
        encoded_end: []const u8,
    ) !?[]u8 {
        const func = self.resolve_temporal_overlap orelse return error.UnsupportedRowsSelector;
        return try func(self.ptr, alloc, table_name, constraint_name, encoded_value, encoded_start, encoded_end);
    }

    pub fn primaryExists(
        self: UniqueSelectorResolver,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        physical_key: []const u8,
    ) !bool {
        const func = self.resolve_primary orelse return error.UnsupportedRowsSelector;
        return try func(self.ptr, alloc, table_name, physical_key);
    }

    pub fn lookupPrimary(
        self: UniqueSelectorResolver,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        physical_key: []const u8,
    ) !?ResolvedPrimaryRow {
        const func = self.lookup_primary orelse return error.UnsupportedRowsSelector;
        return try func(self.ptr, alloc, table_name, physical_key);
    }
};

pub const ResolvedPrimaryRow = struct {
    json: []u8,
    version: u64,

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        alloc.free(self.json);
        self.* = undefined;
    }
};

pub fn parseRowsBatchRequest(
    alloc: std.mem.Allocator,
    body: []const u8,
    schema: runtime_schema.TableSchema,
) !OwnedRowsBatchRequest {
    return try parseRowsBatchRequestWithResolverAndDefaultContext(alloc, "", body, schema, null, .{});
}

pub fn parseRowsBatchRequestWithResolver(
    alloc: std.mem.Allocator,
    table_name: []const u8,
    body: []const u8,
    schema: runtime_schema.TableSchema,
    unique_resolver: ?UniqueSelectorResolver,
) !OwnedRowsBatchRequest {
    return try parseRowsBatchRequestWithResolverAndDefaultContext(alloc, table_name, body, schema, unique_resolver, .{});
}

pub fn parseRowsBatchRequestWithResolverAndDefaultContext(
    alloc: std.mem.Allocator,
    table_name: []const u8,
    body: []const u8,
    schema: runtime_schema.TableSchema,
    unique_resolver: ?UniqueSelectorResolver,
    default_context: DefaultValueContext,
) !OwnedRowsBatchRequest {
    if (schema.storage_mode != .relational or schema.primary_key == null) return error.InvalidRowsRequest;
    if (body.len == 0) return error.InvalidRowsRequest;

    var parsed = std.json.parseFromSlice(std.json.Value, alloc, body, .{
        .allocate = .alloc_always,
    }) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(parsed.value.object, &.{ "operations", "sync_level" });
    const operations_value = parsed.value.object.get("operations") orelse return error.InvalidRowsRequest;
    if (operations_value != .array) return error.InvalidRowsRequest;
    const sync_level = if (parsed.value.object.get("sync_level")) |value|
        db_mod.types.parsePublicSyncLevelJson(value) orelse return error.InvalidRowsRequest
    else
        db_mod.types.SyncLevel.propose;

    var writes = std.ArrayListUnmanaged(db_mod.types.BatchWrite).empty;
    errdefer {
        freeWrites(alloc, writes.items);
        writes.deinit(alloc);
    }
    var deletes = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        freeDeletes(alloc, deletes.items);
        deletes.deinit(alloc);
    }
    var relational_identity_rewrites = std.ArrayListUnmanaged(db_mod.types.RelationalIdentityRewrite).empty;
    errdefer {
        freeRelationalIdentityRewrites(alloc, relational_identity_rewrites.items);
        relational_identity_rewrites.deinit(alloc);
    }
    var transforms = std.ArrayListUnmanaged(db_mod.types.DocumentTransform).empty;
    errdefer {
        freeTransforms(alloc, transforms.items);
        transforms.deinit(alloc);
    }
    var predicates = std.ArrayListUnmanaged(db_mod.types.TransactionVersionPredicate).empty;
    errdefer {
        freePredicates(alloc, predicates.items);
        predicates.deinit(alloc);
    }
    var returning_rows = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        freeDeletes(alloc, returning_rows.items);
        returning_rows.deinit(alloc);
    }
    var proposed_conflict_targets = std.StringHashMapUnmanaged(void).empty;
    defer {
        var keys = proposed_conflict_targets.keyIterator();
        while (keys.next()) |key| alloc.free(@constCast(key.*));
        proposed_conflict_targets.deinit(alloc);
    }

    var inserted: u32 = 0;
    var deleted: u32 = 0;
    var transformed: u32 = 0;

    for (operations_value.array.items) |op_value| {
        if (op_value != .object) return error.InvalidRowsRequest;
        const op_text_value = op_value.object.get("op") orelse return error.InvalidRowsRequest;
        if (op_text_value != .string) return error.InvalidRowsRequest;
        const op_text = op_text_value.string;
        try validateRowsBatchOperationEnvelope(op_value, op_text);

        if (std.mem.eql(u8, op_text, "insert") or std.mem.eql(u8, op_text, "upsert")) {
            const row_value = op_value.object.get("row") orelse return error.InvalidRowsRequest;
            if (row_value != .object) return error.InvalidRowsRequest;
            if (op_value.object.get("on_conflict")) |conflict_value| {
                if (!std.mem.eql(u8, op_text, "insert")) return error.InvalidRowsRequest;
                try appendInsertWithConflictAlloc(
                    alloc,
                    table_name,
                    schema,
                    row_value,
                    op_value,
                    conflict_value,
                    unique_resolver orelse return error.UnsupportedRowsSelector,
                    &writes,
                    &transforms,
                    &predicates,
                    &returning_rows,
                    &proposed_conflict_targets,
                    &inserted,
                    &transformed,
                    default_context,
                );
            } else {
                try appendInsertAlloc(
                    alloc,
                    schema,
                    row_value,
                    std.mem.eql(u8, op_text, "insert"),
                    &writes,
                    &predicates,
                    default_context,
                );
                try appendReturningProjectionAlloc(alloc, schema, &returning_rows, op_value, writes.items[writes.items.len - 1].value);
                inserted += 1;
            }
            continue;
        }

        if (std.mem.eql(u8, op_text, "delete")) {
            const key = (try physicalPrimaryKeyFromWhereAlloc(alloc, table_name, schema, op_value.object.get("where") orelse return error.InvalidRowsRequest, unique_resolver, false)) orelse return error.RowSelectorNotFound;
            var key_transferred = false;
            errdefer if (!key_transferred) alloc.free(key);
            var returning_base = try returningBaseRowForKey(alloc, table_name, key, unique_resolver, op_value);
            defer if (returning_base) |*row| row.deinit(alloc);
            try appendExpectedVersionPredicateAlloc(alloc, &predicates, op_value, key);
            if (returning_base) |row| {
                try appendVersionPredicateAlloc(alloc, &predicates, key, row.version);
                try appendReturningProjectionFromJsonAlloc(alloc, schema, &returning_rows, op_value, row.json);
            }
            try deletes.append(alloc, key);
            key_transferred = true;
            deleted += 1;
            continue;
        }

        if (std.mem.eql(u8, op_text, "rewrite_identity")) {
            try appendRewriteIdentityAlloc(
                alloc,
                table_name,
                schema,
                op_value,
                unique_resolver,
                &writes,
                &deletes,
                &relational_identity_rewrites,
                &predicates,
                &returning_rows,
                &inserted,
                &deleted,
            );
            continue;
        }

        if (std.mem.eql(u8, op_text, "update")) {
            const key = (try physicalPrimaryKeyFromWhereAlloc(alloc, table_name, schema, op_value.object.get("where") orelse return error.InvalidRowsRequest, unique_resolver, false)) orelse return error.RowSelectorNotFound;
            var key_transferred = false;
            errdefer if (!key_transferred) alloc.free(key);
            const needs_planned_row = hasMutationExpression(op_value) or schemaHasGeneratedColumns(schema) or schema.checks.len != 0 or hasReturningProjection(op_value);
            var returning_base = if (needs_planned_row)
                try lookupBaseRowForKey(alloc, table_name, key, unique_resolver)
            else
                null;
            defer if (returning_base) |*row| row.deinit(alloc);
            var parsed_existing: std.json.Parsed(std.json.Value) = undefined;
            var parsed_existing_loaded = false;
            defer if (parsed_existing_loaded) parsed_existing.deinit();
            const existing_row_value: ?std.json.Value = if (returning_base) |row| blk: {
                parsed_existing = std.json.parseFromSlice(std.json.Value, alloc, row.json, .{}) catch return error.InvalidRowsRequest;
                parsed_existing_loaded = true;
                if (parsed_existing.value != .object) return error.InvalidRowsRequest;
                break :blk parsed_existing.value;
            } else null;
            var operations = try updateTransformOperationsAlloc(alloc, schema, op_value, existing_row_value, null);
            var operations_transferred = false;
            errdefer if (!operations_transferred) freeTransformOps(alloc, operations);
            operations = try extendOperationsWithOnUpdateAlloc(alloc, operations, schema);
            try appendExpectedVersionPredicateAlloc(alloc, &predicates, op_value, key);
            if (returning_base) |row| {
                try appendVersionPredicateAlloc(alloc, &predicates, key, row.version);
                const projected_json = (try db_mod.transform.resolveDocumentTransform(alloc, row.json, .{ .key = key, .operations = operations })) orelse return error.RowSelectorNotFound;
                defer alloc.free(projected_json);
                const planned_json = try plannedExistingRelationalRowJsonAlloc(alloc, schema, projected_json);
                defer alloc.free(planned_json);
                if (schemaHasGeneratedColumns(schema)) operations = try extendOperationsWithGeneratedColumnsAlloc(alloc, operations, schema, planned_json);
                try appendReturningProjectionFromJsonAlloc(alloc, schema, &returning_rows, op_value, planned_json);
            }
            try transforms.append(alloc, .{ .key = key, .operations = operations });
            key_transferred = true;
            operations_transferred = true;
            transformed += 1;
            continue;
        }

        return error.InvalidRowsRequest;
    }

    try validateRowsBatchTargetKeys(writes.items, deletes.items, relational_identity_rewrites.items, transforms.items);

    const writes_owned = try writes.toOwnedSlice(alloc);
    errdefer {
        freeWrites(alloc, writes_owned);
        alloc.free(writes_owned);
    }
    const deletes_owned = try deletes.toOwnedSlice(alloc);
    errdefer {
        freeDeletes(alloc, deletes_owned);
        alloc.free(deletes_owned);
    }
    const relational_identity_rewrites_owned = try relational_identity_rewrites.toOwnedSlice(alloc);
    errdefer {
        freeRelationalIdentityRewrites(alloc, relational_identity_rewrites_owned);
        alloc.free(relational_identity_rewrites_owned);
    }
    const transforms_owned = try transforms.toOwnedSlice(alloc);
    errdefer {
        freeTransforms(alloc, transforms_owned);
        alloc.free(transforms_owned);
    }
    const predicates_owned = try predicates.toOwnedSlice(alloc);
    errdefer {
        freePredicates(alloc, predicates_owned);
        alloc.free(predicates_owned);
    }
    const returning_rows_owned = try returning_rows.toOwnedSlice(alloc);
    errdefer {
        freeDeletes(alloc, returning_rows_owned);
        alloc.free(returning_rows_owned);
    }

    return .{
        .writes = writes_owned,
        .deletes = deletes_owned,
        .relational_identity_rewrites = relational_identity_rewrites_owned,
        .transforms = transforms_owned,
        .predicates = predicates_owned,
        .returning_rows = returning_rows_owned,
        .req = .{
            .writes = writes_owned,
            .deletes = deletes_owned,
            .relational_identity_rewrites = relational_identity_rewrites_owned,
            .transforms = transforms_owned,
            .predicates = predicates_owned,
            .sync_level = sync_level,
        },
        .inserted = inserted,
        .deleted = deleted,
        .transformed = transformed,
    };
}

fn validateRowsBatchOperationEnvelope(op_value: std.json.Value, op_text: []const u8) !void {
    if (std.mem.eql(u8, op_text, "insert")) {
        try requireJsonObjectOnlyKeys(op_value.object, &.{ "op", "row", "on_conflict", "returning", "returning_expressions" });
    } else if (std.mem.eql(u8, op_text, "upsert")) {
        try requireJsonObjectOnlyKeys(op_value.object, &.{ "op", "row", "returning", "returning_expressions" });
    } else if (std.mem.eql(u8, op_text, "update")) {
        try requireJsonObjectOnlyKeys(op_value.object, &.{ "op", "where", "patch", "patch_expr", "increment", "increment_expr", "json_set", "array_update", "returning", "returning_expressions", "expected_version" });
    } else if (std.mem.eql(u8, op_text, "rewrite_identity")) {
        try requireJsonObjectOnlyKeys(op_value.object, &.{ "op", "where", "patch", "patch_expr", "increment", "increment_expr", "json_set", "array_update", "returning", "returning_expressions", "expected_version" });
    } else if (std.mem.eql(u8, op_text, "delete")) {
        try requireJsonObjectOnlyKeys(op_value.object, &.{ "op", "where", "returning", "returning_expressions", "expected_version" });
    } else {
        return error.InvalidRowsRequest;
    }
}

fn appendRewriteIdentityAlloc(
    alloc: std.mem.Allocator,
    table_name: []const u8,
    schema: runtime_schema.TableSchema,
    op_value: std.json.Value,
    unique_resolver: ?UniqueSelectorResolver,
    writes: *std.ArrayListUnmanaged(db_mod.types.BatchWrite),
    deletes: *std.ArrayListUnmanaged([]const u8),
    relational_identity_rewrites: *std.ArrayListUnmanaged(db_mod.types.RelationalIdentityRewrite),
    predicates: *std.ArrayListUnmanaged(db_mod.types.TransactionVersionPredicate),
    returning_rows: *std.ArrayListUnmanaged([]const u8),
    inserted: *u32,
    deleted: *u32,
) !void {
    _ = writes;
    _ = deletes;
    const old_key = (try physicalPrimaryKeyFromWhereAlloc(alloc, table_name, schema, op_value.object.get("where") orelse return error.InvalidRowsRequest, unique_resolver, false)) orelse return error.RowSelectorNotFound;
    var old_key_transferred = false;
    errdefer if (!old_key_transferred) alloc.free(old_key);

    var base = try lookupBaseRowForKey(alloc, table_name, old_key, unique_resolver);
    defer base.deinit(alloc);

    var parsed_existing = std.json.parseFromSlice(std.json.Value, alloc, base.json, .{}) catch return error.InvalidRowsRequest;
    defer parsed_existing.deinit();
    if (parsed_existing.value != .object) return error.InvalidRowsRequest;

    var operations = try rewriteIdentityTransformOperationsAlloc(alloc, schema, op_value, parsed_existing.value);
    defer freeTransformOps(alloc, operations);
    operations = try extendOperationsWithOnUpdateAlloc(alloc, operations, schema);

    const projected_json = (try db_mod.transform.resolveDocumentTransform(alloc, base.json, .{ .key = old_key, .operations = operations })) orelse return error.RowSelectorNotFound;
    defer alloc.free(projected_json);
    const planned_json = try plannedExistingRelationalRowJsonAlloc(alloc, schema, projected_json);
    var planned_json_transferred = false;
    errdefer if (!planned_json_transferred) alloc.free(planned_json);

    const new_key = try physicalPrimaryKeyFromRowJsonAlloc(alloc, schema, planned_json);
    var new_key_transferred = false;
    errdefer if (!new_key_transferred) alloc.free(new_key);
    if (std.mem.eql(u8, old_key, new_key)) return error.InvalidRowsRequest;

    try appendExpectedVersionPredicateAlloc(alloc, predicates, op_value, old_key);
    try appendVersionPredicateAlloc(alloc, predicates, old_key, base.version);
    try appendVersionPredicateAlloc(alloc, predicates, new_key, 0);

    try relational_identity_rewrites.append(alloc, .{
        .old_key = old_key,
        .new_key = new_key,
        .value = planned_json,
    });
    old_key_transferred = true;
    new_key_transferred = true;
    planned_json_transferred = true;

    try appendReturningProjectionFromJsonAlloc(alloc, schema, returning_rows, op_value, planned_json);
    inserted.* += 1;
    deleted.* += 1;
}

fn validateRowsBatchTargetKeys(
    writes: []const db_mod.types.BatchWrite,
    deletes: []const []const u8,
    relational_identity_rewrites: []const db_mod.types.RelationalIdentityRewrite,
    transforms: []const db_mod.types.DocumentTransform,
) !void {
    for (writes, 0..) |write, i| {
        for (writes[i + 1 ..]) |other| {
            if (std.mem.eql(u8, write.key, other.key)) return error.InvalidRowsRequest;
        }
        for (deletes) |key| {
            if (std.mem.eql(u8, write.key, key)) return error.InvalidRowsRequest;
        }
        for (relational_identity_rewrites) |rewrite| {
            if (std.mem.eql(u8, write.key, rewrite.old_key) or std.mem.eql(u8, write.key, rewrite.new_key)) return error.InvalidRowsRequest;
        }
        for (transforms) |transform| {
            if (std.mem.eql(u8, write.key, transform.key)) return error.InvalidRowsRequest;
        }
    }

    for (deletes, 0..) |key, i| {
        for (deletes[i + 1 ..]) |other| {
            if (std.mem.eql(u8, key, other)) return error.InvalidRowsRequest;
        }
        for (transforms) |transform| {
            if (std.mem.eql(u8, key, transform.key)) return error.InvalidRowsRequest;
        }
    }

    for (relational_identity_rewrites, 0..) |rewrite, i| {
        if (std.mem.eql(u8, rewrite.old_key, rewrite.new_key)) return error.InvalidRowsRequest;
        for (relational_identity_rewrites[i + 1 ..]) |other| {
            if (std.mem.eql(u8, rewrite.old_key, other.old_key) or
                std.mem.eql(u8, rewrite.old_key, other.new_key) or
                std.mem.eql(u8, rewrite.new_key, other.old_key) or
                std.mem.eql(u8, rewrite.new_key, other.new_key)) return error.InvalidRowsRequest;
        }
        for (deletes) |key| {
            if (std.mem.eql(u8, rewrite.old_key, key) or std.mem.eql(u8, rewrite.new_key, key)) return error.InvalidRowsRequest;
        }
        for (transforms) |transform| {
            if (std.mem.eql(u8, rewrite.old_key, transform.key) or std.mem.eql(u8, rewrite.new_key, transform.key)) return error.InvalidRowsRequest;
        }
    }

    for (transforms, 0..) |transform, i| {
        for (transforms[i + 1 ..]) |other| {
            if (std.mem.eql(u8, transform.key, other.key)) return error.InvalidRowsRequest;
        }
    }
}

pub fn parseRowsGetRequest(
    alloc: std.mem.Allocator,
    body: []const u8,
    schema: runtime_schema.TableSchema,
) !OwnedRowsGetRequest {
    return try parseRowsGetRequestWithResolver(alloc, "", body, schema, null);
}

pub fn parseRowsGetRequestWithResolver(
    alloc: std.mem.Allocator,
    table_name: []const u8,
    body: []const u8,
    schema: runtime_schema.TableSchema,
    unique_resolver: ?UniqueSelectorResolver,
) !OwnedRowsGetRequest {
    if (schema.storage_mode != .relational or schema.primary_key == null) return error.InvalidRowsRequest;
    if (body.len == 0) return error.InvalidRowsRequest;

    var parsed = std.json.parseFromSlice(std.json.Value, alloc, body, .{
        .allocate = .alloc_always,
    }) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(parsed.value.object, &.{ "keys", "include_physical_key" });

    const include_physical_key = if (parsed.value.object.get("include_physical_key")) |value| blk: {
        if (value != .bool) return error.InvalidRowsRequest;
        break :blk value.bool;
    } else false;

    const keys_value = parsed.value.object.get("keys") orelse return error.InvalidRowsRequest;
    if (keys_value != .array) return error.InvalidRowsRequest;

    var keys = std.ArrayListUnmanaged(?[]const u8).empty;
    errdefer {
        freeOptionalKeys(alloc, keys.items);
        keys.deinit(alloc);
    }
    var identities = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        freeDeletes(alloc, identities.items);
        identities.deinit(alloc);
    }

    for (keys_value.array.items) |selector| {
        const key = try physicalPrimaryKeyFromWhereAlloc(alloc, table_name, schema, selector, unique_resolver, true);
        var key_transferred = false;
        errdefer if (!key_transferred) if (key) |value| alloc.free(value);
        const identity_json = try identityResponseJsonAlloc(alloc, selector);
        var identity_transferred = false;
        errdefer if (!identity_transferred) alloc.free(identity_json);
        try keys.append(alloc, key);
        key_transferred = true;
        try identities.append(alloc, identity_json);
        identity_transferred = true;
    }

    const keys_owned = try keys.toOwnedSlice(alloc);
    errdefer {
        freeOptionalKeys(alloc, keys_owned);
        alloc.free(keys_owned);
    }
    const identities_owned = try identities.toOwnedSlice(alloc);
    errdefer {
        freeDeletes(alloc, identities_owned);
        alloc.free(identities_owned);
    }
    return .{
        .keys = keys_owned,
        .identities_json = identities_owned,
        .include_physical_key = include_physical_key,
    };
}

fn freeRowsQueryArrayAnyPredicatesNoSlice(alloc: std.mem.Allocator, predicates: []const db_mod.types.RelationalRowsArrayAnyPredicate) void {
    for (predicates) |predicate| {
        alloc.free(predicate.field);
        alloc.free(predicate.value_json);
    }
}

fn freeRowsQueryAccessPredicateGroups(alloc: std.mem.Allocator, groups: []const db_mod.types.RelationalRowsAccessPredicateGroup) void {
    for (groups) |group| {
        for (group.predicates) |predicate| {
            alloc.free(predicate.field);
            if (predicate.value_json) |value_json| alloc.free(value_json);
        }
        if (group.predicates.len > 0) alloc.free(group.predicates);
        freeRowsQueryArrayAnyPredicatesNoSlice(alloc, group.array_any);
        if (group.array_any.len > 0) alloc.free(group.array_any);
        for (group.array_contains) |predicate| {
            alloc.free(predicate.field);
            alloc.free(predicate.value_json);
        }
        if (group.array_contains.len > 0) alloc.free(group.array_contains);
        for (group.array_eq) |predicate| {
            alloc.free(predicate.field);
            alloc.free(predicate.value_json);
        }
        if (group.array_eq.len > 0) alloc.free(group.array_eq);
        for (group.in_predicates) |predicate| {
            alloc.free(predicate.field);
            alloc.free(predicate.values_json);
            if (predicate.collation) |collation| alloc.free(collation);
        }
        if (group.in_predicates.len > 0) alloc.free(group.in_predicates);
        for (group.json_contains) |predicate| {
            alloc.free(predicate.field);
            alloc.free(predicate.value_json);
        }
        if (group.json_contains.len > 0) alloc.free(group.json_contains);
        for (group.json_path_eq) |predicate| {
            alloc.free(predicate.field);
            alloc.free(predicate.path);
            alloc.free(predicate.value_json);
        }
        if (group.json_path_eq.len > 0) alloc.free(group.json_path_eq);
        for (group.json_path_exists) |predicate| {
            alloc.free(predicate.field);
            alloc.free(predicate.path);
        }
        if (group.json_path_exists.len > 0) alloc.free(group.json_path_exists);
        for (group.text_patterns) |predicate| {
            alloc.free(predicate.field);
            alloc.free(predicate.pattern);
        }
        if (group.text_patterns.len > 0) alloc.free(group.text_patterns);
    }
    if (groups.len > 0) alloc.free(groups);
}

pub fn parseRowsQueryRequest(
    alloc: std.mem.Allocator,
    body: []const u8,
    schema: runtime_schema.TableSchema,
) !OwnedRowsQueryRequest {
    if (schema.storage_mode != .relational or schema.primary_key == null) return error.InvalidRowsRequest;
    return try parseRowsQueryStreamRequest(alloc, body, schema);
}

fn parseRowsQueryStreamRequest(
    alloc: std.mem.Allocator,
    body: []const u8,
    schema: runtime_schema.TableSchema,
) anyerror!OwnedRowsQueryRequest {
    if (schema.storage_mode != .relational) return error.InvalidRowsRequest;
    if (body.len == 0) return error.InvalidRowsRequest;

    var parsed = std.json.parseFromSlice(std.json.Value, alloc, body, .{
        .allocate = .alloc_always,
    }) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(parsed.value.object, &.{ "source_cte", "where", "expression_where", "expression_any", "expression_not", "expression_array_contains", "select", "json_extract", "array_length", "coalesce", "field_aliases", "expressions", "scalar_subqueries", "distinct_on", "distinct_on_expressions", "order_by", "limit", "offset", "total_mode", "profile", "row_claim", "doc_key_range" });

    const source_cte = try parseRowsQuerySourceCteAlloc(alloc, parsed.value.object.get("source_cte"));
    errdefer if (source_cte.len > 0) alloc.free(source_cte);

    const predicates = try parseRowsQueryPredicatesAlloc(alloc, schema, parsed.value.object.get("where"));
    errdefer freeOwnedQueryPredicates(alloc, predicates);

    const or_predicates = try parseRowsQueryOrPredicateGroupsAlloc(alloc, schema, parsed.value.object.get("where"));
    errdefer freeRowsQueryPredicateGroups(alloc, or_predicates);

    const not_predicates = try parseRowsQueryNotPredicateGroupsAlloc(alloc, schema, parsed.value.object.get("where"));
    errdefer freeRowsQueryPredicateGroups(alloc, not_predicates);

    const access_or_predicates = try parseRowsQueryAccessPredicateGroupsAlloc(alloc, schema, parsed.value.object.get("where"), "any");
    errdefer freeRowsQueryAccessPredicateGroups(alloc, access_or_predicates);

    const access_not_predicates = try parseRowsQueryAccessPredicateGroupsAlloc(alloc, schema, parsed.value.object.get("where"), "not");
    errdefer freeRowsQueryAccessPredicateGroups(alloc, access_not_predicates);

    const expression_predicates = try parseRowsQueryExpressionPredicatesAlloc(alloc, schema, parsed.value.object.get("expression_where"));
    errdefer freeRowsQueryExpressionConditions(alloc, expression_predicates);

    const expression_or_predicates = try parseRowsQueryExpressionPredicateGroupsAlloc(alloc, schema, parsed.value.object.get("expression_any"));
    errdefer freeRowsQueryExpressionPredicateGroups(alloc, expression_or_predicates);

    const expression_not_predicates = try parseRowsQueryExpressionPredicateGroupsAlloc(alloc, schema, parsed.value.object.get("expression_not"));
    errdefer freeRowsQueryExpressionPredicateGroups(alloc, expression_not_predicates);

    const expression_array_contains = try parseRowsQueryExpressionArrayContainsPredicatesAlloc(alloc, schema, parsed.value.object.get("expression_array_contains"));
    errdefer freeRowsQueryExpressionArrayContainsPredicates(alloc, expression_array_contains);

    const array_any = try parseRowsQueryArrayAnyPredicatesAlloc(alloc, schema, parsed.value.object.get("where"));
    errdefer freeRowsQueryArrayAnyPredicates(alloc, array_any);

    const array_contains = try parseRowsQueryArrayContainsPredicatesAlloc(alloc, schema, parsed.value.object.get("where"));
    errdefer freeRowsQueryArrayContainsPredicates(alloc, array_contains);

    const array_eq = try parseRowsQueryArrayEqPredicatesAlloc(alloc, schema, parsed.value.object.get("where"));
    errdefer freeRowsQueryArrayEqPredicates(alloc, array_eq);

    const in_predicates = try parseRowsQueryInPredicatesAlloc(alloc, schema, parsed.value.object.get("where"));
    errdefer freeRowsQueryInPredicates(alloc, in_predicates);

    const json_contains = try parseRowsQueryJsonContainsPredicatesAlloc(alloc, schema, parsed.value.object.get("where"));
    errdefer freeRowsQueryJsonContainsPredicates(alloc, json_contains);

    const json_path_eq = try parseRowsQueryJsonPathEqPredicatesAlloc(alloc, schema, parsed.value.object.get("where"));
    errdefer freeRowsQueryJsonPathEqPredicates(alloc, json_path_eq);

    const json_path_exists = try parseRowsQueryJsonPathExistsPredicatesAlloc(alloc, schema, parsed.value.object.get("where"));
    errdefer freeRowsQueryJsonPathExistsPredicates(alloc, json_path_exists);

    const text_patterns = try parseRowsQueryTextPatternPredicatesAlloc(alloc, schema, parsed.value.object.get("where"));
    errdefer freeRowsQueryTextPatternPredicates(alloc, text_patterns);

    const select_parsed = try parseRowsQuerySelectAlloc(alloc, schema, parsed.value.object.get("select"));
    errdefer {
        for (select_parsed.fields) |field| alloc.free(field);
        if (select_parsed.fields.len > 0) alloc.free(select_parsed.fields);
    }

    const json_extract = try parseRowsQueryJsonExtractProjectionsAlloc(alloc, schema, parsed.value.object.get("json_extract"));
    errdefer freeRowsQueryJsonExtractProjections(alloc, json_extract);

    const array_length = try parseRowsQueryArrayLengthProjectionsAlloc(alloc, schema, parsed.value.object.get("array_length"));
    errdefer freeRowsQueryArrayLengthProjections(alloc, array_length);

    const coalesce = try parseRowsQueryCoalesceProjectionsAlloc(alloc, schema, parsed.value.object.get("coalesce"));
    errdefer freeRowsQueryCoalesceProjections(alloc, coalesce);

    const expressions = try parseRowsQueryExpressionProjectionsAlloc(alloc, schema, parsed.value.object.get("expressions"));
    errdefer freeRowsQueryExpressionProjections(alloc, expressions);

    const field_aliases = try parseRowsQueryFieldAliasProjectionsAlloc(alloc, schema, parsed.value.object.get("field_aliases"));
    errdefer freeRowsQueryFieldAliasProjections(alloc, field_aliases);

    const scalar_subqueries = try parseRowsQueryScalarSubqueryProjectionsAlloc(alloc, schema, parsed.value.object.get("scalar_subqueries"));
    errdefer freeRowsQueryScalarSubqueryProjections(alloc, scalar_subqueries);

    const order_by = try parseRowsQueryOrderAlloc(alloc, schema, parsed.value.object.get("order_by"));
    errdefer {
        freeRowsQueryOrder(alloc, order_by);
        if (order_by.len > 0) alloc.free(order_by);
    }

    const distinct_on = try parseRowsQueryDistinctOnAlloc(alloc, schema, parsed.value.object.get("distinct_on"), order_by);
    errdefer {
        for (distinct_on) |field| alloc.free(field);
        if (distinct_on.len > 0) alloc.free(distinct_on);
    }
    const distinct_on_expressions = try parseRowsQueryDistinctOnExpressionsAlloc(alloc, schema, parsed.value.object.get("distinct_on_expressions"), order_by);
    errdefer freeRowsQueryExpressions(alloc, distinct_on_expressions);
    if (distinct_on.len > 0 and distinct_on_expressions.len > 0) return error.InvalidRowsRequest;

    const row_claim = try parseRowsQueryRowClaimAlloc(alloc, parsed.value.object.get("row_claim"));
    errdefer if (row_claim) |claim| if (claim.owner_id.len > 0) alloc.free(claim.owner_id);
    if (row_claim != null and schema.primary_key == null) return error.InvalidRowsRequest;
    if (row_claim != null and (distinct_on.len > 0 or distinct_on_expressions.len > 0)) return error.InvalidRowsRequest;
    if (row_claim != null and source_cte.len != 0) return error.InvalidRowsRequest;

    const doc_key_range = try parseRowsQueryDocKeyRangeAlloc(alloc, parsed.value.object.get("doc_key_range"));
    errdefer if (doc_key_range) |range| {
        if (range.start.len > 0) alloc.free(range.start);
        if (range.end.len > 0) alloc.free(range.end);
    };
    if (doc_key_range != null and schema.primary_key == null) return error.InvalidRowsRequest;

    try validateRowsQueryProjectionOutputs(schema, select_parsed, json_extract, array_length, coalesce, field_aliases, expressions, scalar_subqueries);

    return .{
        .source_cte = source_cte,
        .predicates = predicates,
        .array_any = array_any,
        .array_contains = array_contains,
        .array_eq = array_eq,
        .in_predicates = in_predicates,
        .json_contains = json_contains,
        .json_path_eq = json_path_eq,
        .json_path_exists = json_path_exists,
        .text_patterns = text_patterns,
        .or_predicates = or_predicates,
        .not_predicates = not_predicates,
        .access_or_predicates = access_or_predicates,
        .access_not_predicates = access_not_predicates,
        .expression_predicates = expression_predicates,
        .expression_or_predicates = expression_or_predicates,
        .expression_not_predicates = expression_not_predicates,
        .expression_array_contains = expression_array_contains,
        .select = select_parsed.fields,
        .json_extract = json_extract,
        .array_length = array_length,
        .coalesce = coalesce,
        .field_aliases = field_aliases,
        .expressions = expressions,
        .scalar_subqueries = scalar_subqueries,
        .select_all = select_parsed.all,
        .distinct_on = distinct_on,
        .distinct_on_expressions = distinct_on_expressions,
        .order_by = order_by,
        .row_claim = row_claim,
        .doc_key_range = doc_key_range,
        .limit = try parseOptionalU32(parsed.value.object.get("limit")),
        .offset = (try parseOptionalU32(parsed.value.object.get("offset"))) orelse 0,
        .total_mode = try parseRowsQueryTotalMode(parsed.value.object.get("total_mode")),
        .profile = (try parseOptionalBool(parsed.value.object.get("profile"))) orelse false,
    };
}

fn parseRowsQueryTotalMode(maybe_value: ?std.json.Value) !db_mod.types.RelationalRowsQueryRequest.TotalMode {
    const value = maybe_value orelse return .exact;
    if (value != .string) return error.InvalidRowsRequest;
    if (std.mem.eql(u8, value.string, "exact")) return .exact;
    if (std.mem.eql(u8, value.string, "bounded")) return .bounded;
    if (std.mem.eql(u8, value.string, "none")) return .none;
    return error.InvalidRowsRequest;
}

fn rowsQueryExpressionsEqual(lhs: db_mod.types.RelationalRowsExpression, rhs: db_mod.types.RelationalRowsExpression) bool {
    if (lhs.kind != rhs.kind or
        !std.mem.eql(u8, lhs.field, rhs.field) or
        lhs.field_source != rhs.field_source or
        !std.mem.eql(u8, lhs.value_json, rhs.value_json) or
        !std.mem.eql(u8, lhs.json_path, rhs.json_path) or
        lhs.json_as_text != rhs.json_as_text or
        lhs.cast_type != rhs.cast_type or
        lhs.operands.len != rhs.operands.len or
        lhs.case_branches.len != rhs.case_branches.len or
        lhs.case_else.len != rhs.case_else.len)
    {
        return false;
    }
    for (lhs.operands, rhs.operands) |left, right| {
        if (!rowsQueryExpressionsEqual(left, right)) return false;
    }
    for (lhs.case_branches, rhs.case_branches) |left, right| {
        if (!rowsQueryExpressionConditionsEqual(left.when, right.when)) return false;
        if (!rowsQueryExpressionsEqual(left.then, right.then)) return false;
    }
    for (lhs.case_else, rhs.case_else) |left, right| {
        if (!rowsQueryExpressionsEqual(left, right)) return false;
    }
    return true;
}

fn rowsQueryExpressionConditionsEqual(
    lhs: db_mod.types.RelationalRowsExpressionCondition,
    rhs: db_mod.types.RelationalRowsExpressionCondition,
) bool {
    if (lhs.op != rhs.op or lhs.rhs.len != rhs.rhs.len) return false;
    if (!rowsQueryExpressionsEqual(lhs.lhs, rhs.lhs)) return false;
    for (lhs.rhs, rhs.rhs) |left, right| {
        if (!rowsQueryExpressionsEqual(left, right)) return false;
    }
    return true;
}

fn parseRowsQueryDistinctOnAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    maybe_distinct_on: ?std.json.Value,
    order_by: []const RowsQueryOrder,
) ![]const []const u8 {
    const value = maybe_distinct_on orelse return &.{};
    if (value != .array or value.array.items.len == 0) return error.InvalidRowsRequest;
    if (order_by.len < value.array.items.len) return error.InvalidRowsRequest;

    const fields = try alloc.alloc([]const u8, value.array.items.len);
    var initialized: usize = 0;
    errdefer {
        for (fields[0..initialized]) |field| alloc.free(field);
        alloc.free(fields);
    }
    for (value.array.items, 0..) |field_value, i| {
        if (field_value != .string or field_value.string.len == 0 or std.mem.eql(u8, field_value.string, "*")) return error.InvalidRowsRequest;
        _ = findRelationalColumn(schema.relational_columns, field_value.string) orelse return error.InvalidRowsRequest;
        if (order_by[i].expression != null or order_by[i].field.len == 0 or !std.mem.eql(u8, order_by[i].field, field_value.string)) return error.InvalidRowsRequest;
        fields[initialized] = try alloc.dupe(u8, field_value.string);
        initialized += 1;
    }
    return fields;
}

fn parseRowsQueryDistinctOnExpressionsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    maybe_distinct_on: ?std.json.Value,
    order_by: []const RowsQueryOrder,
) ![]const db_mod.types.RelationalRowsExpression {
    const value = maybe_distinct_on orelse return &.{};
    if (value != .array or value.array.items.len == 0) return error.InvalidRowsRequest;
    if (order_by.len < value.array.items.len) return error.InvalidRowsRequest;

    const expressions = try alloc.alloc(db_mod.types.RelationalRowsExpression, value.array.items.len);
    var initialized: usize = 0;
    errdefer {
        for (expressions[0..initialized]) |expression| freeRowsQueryExpression(alloc, expression);
        alloc.free(expressions);
    }
    for (value.array.items, 0..) |expression_value, i| {
        const expression = try parseRowsQueryExpressionAlloc(alloc, schema, expression_value);
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeRowsQueryExpression(alloc, expression);
        if (order_by[i].expression == null or !rowsQueryExpressionsEqual(order_by[i].expression.?, expression)) return error.InvalidRowsRequest;
        expressions[initialized] = expression;
        expression_transferred = true;
        initialized += 1;
    }
    return expressions;
}

pub fn parseRowsMutationSourceRequest(
    alloc: std.mem.Allocator,
    body: []const u8,
    schema: runtime_schema.TableSchema,
) !OwnedRowsMutationSourceRequest {
    if (schema.storage_mode != .relational or schema.primary_key == null) return error.InvalidRowsRequest;
    if (body.len == 0) return error.InvalidRowsRequest;

    var parsed = std.json.parseFromSlice(std.json.Value, alloc, body, .{
        .allocate = .alloc_always,
    }) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(parsed.value.object, &.{ "op", "source", "rewrite_identity", "restart_identity", "patch", "patch_expr", "increment", "increment_expr", "json_set", "array_update", "temporal_portion", "returning", "returning_expressions" });

    const op_value = parsed.value.object.get("op") orelse return error.InvalidRowsRequest;
    if (op_value != .string) return error.InvalidRowsRequest;
    const kind: db_mod.types.RelationalRowsMutationKind = if (std.mem.eql(u8, op_value.string, "update"))
        .update
    else if (std.mem.eql(u8, op_value.string, "delete"))
        .delete
    else
        return error.InvalidRowsRequest;
    const rewrite_identity = (try parseOptionalBool(parsed.value.object.get("rewrite_identity"))) orelse false;
    if (rewrite_identity and kind != .update) return error.InvalidRowsRequest;
    const restart_identity = (try parseOptionalBool(parsed.value.object.get("restart_identity"))) orelse false;
    if (restart_identity and kind != .delete) return error.InvalidRowsRequest;

    const source_value = parsed.value.object.get("source") orelse return error.InvalidRowsRequest;
    if (source_value != .object) return error.InvalidRowsRequest;
    const source_json = try jsonValueStringifyAlloc(alloc, source_value);
    defer alloc.free(source_json);
    var source = try parseRowsQueryRequest(alloc, source_json, schema);
    errdefer source.deinit(alloc);
    if (source.row_claim == null) return error.InvalidRowsRequest;
    if (source.row_claim.?.owner_id.len == 0 or source.row_claim.?.lease_ms == 0) return error.InvalidRowsRequest;
    if (source.source_cte.len != 0) return error.InvalidRowsRequest;
    if (restart_identity and !rowsQueryIsClaimedWholeTableMutationSource(source)) return error.InvalidRowsRequest;

    var operations: []db_mod.types.TransformOp = &.{};
    var patch_expressions: []db_mod.types.RelationalRowsExpressionAssignment = &.{};
    var increment_expressions: []db_mod.types.RelationalRowsExpressionAssignment = &.{};
    var json_set_expressions: []db_mod.types.RelationalRowsJsonSetExpressionAssignment = &.{};
    if (kind == .update) {
        operations = try staticUpdateTransformOperationsAlloc(alloc, schema, parsed.value, true, rewrite_identity);
        errdefer freeTransformOps(alloc, operations);
        patch_expressions = try parseRowsMutationExpressionAssignmentsAlloc(alloc, schema, parsed.value.object.get("patch_expr"), false, false, rewrite_identity, source.scalar_subqueries);
        errdefer freeRowsExpressionAssignments(alloc, patch_expressions);
        increment_expressions = try parseRowsMutationExpressionAssignmentsAlloc(alloc, schema, parsed.value.object.get("increment_expr"), true, false, false, source.scalar_subqueries);
        errdefer freeRowsExpressionAssignments(alloc, increment_expressions);
        json_set_expressions = try parseRowsMutationJsonSetExpressionAssignmentsAlloc(alloc, schema, parsed.value.object.get("json_set"), false);
        errdefer freeRowsJsonSetExpressionAssignments(alloc, json_set_expressions);
        if (operations.len == 0 and patch_expressions.len == 0 and increment_expressions.len == 0 and json_set_expressions.len == 0) return error.InvalidRowsRequest;
        try validateRowsMutationUpdateTargetPaths(operations, patch_expressions, increment_expressions, json_set_expressions, &.{});
    } else if (parsed.value.object.get("patch") != null or parsed.value.object.get("patch_expr") != null or parsed.value.object.get("increment") != null or parsed.value.object.get("increment_expr") != null or parsed.value.object.get("json_set") != null or parsed.value.object.get("array_update") != null) {
        return error.InvalidRowsRequest;
    }
    errdefer freeTransformOps(alloc, operations);
    errdefer freeRowsExpressionAssignments(alloc, patch_expressions);
    errdefer freeRowsExpressionAssignments(alloc, increment_expressions);
    errdefer freeRowsJsonSetExpressionAssignments(alloc, json_set_expressions);

    const temporal_portion = try parseRowsTemporalPortionAlloc(alloc, schema, parsed.value.object.get("temporal_portion"));
    errdefer if (temporal_portion) |portion| freeRowsTemporalPortion(alloc, portion);
    if (restart_identity and temporal_portion != null) return error.InvalidRowsRequest;

    const returning = try parseMutationSourceReturningAlloc(alloc, schema, parsed.value.object.get("returning"), parsed.value.object.get("returning_expressions"), source.scalar_subqueries);
    errdefer {
        for (returning.fields) |field| alloc.free(field);
        if (returning.fields.len > 0) alloc.free(returning.fields);
        for (returning.expressions) |projection| {
            alloc.free(projection.output);
            freeRowsQueryExpression(alloc, projection.expression);
        }
        if (returning.expressions.len > 0) alloc.free(returning.expressions);
    }
    if (restart_identity and (returning.all or returning.fields.len != 0 or returning.expressions.len != 0)) return error.InvalidRowsRequest;

    return .{ .req = .{
        .kind = kind,
        .source = source,
        .rewrite_identity = rewrite_identity,
        .restart_identity = restart_identity,
        .operations = operations,
        .patch_expressions = patch_expressions,
        .increment_expressions = increment_expressions,
        .json_set_expressions = json_set_expressions,
        .temporal_portion = temporal_portion,
        .returning = returning.fields,
        .returning_expressions = returning.expressions,
        .returning_all = returning.all,
    } };
}

pub fn encodeRowsMutationSourceRequestAlloc(
    alloc: std.mem.Allocator,
    req: db_mod.types.RelationalRowsMutationSourceRequest,
) ![]u8 {
    if (req.patch_expressions.len != 0 or
        req.increment_expressions.len != 0 or
        req.json_set_expressions.len != 0 or
        req.returning_expressions.len != 0 or
        req.temporal_portion != null)
    {
        return error.UnsupportedOperation;
    }

    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;

    try writer.writeAll("{\"op\":");
    try writer.print("{f}", .{std.json.fmt(rowsMutationKindText(req.kind), .{})});
    try writer.writeAll(",\"source\":");
    try encodeRowsMutationSourceQueryRequest(writer, req.source);

    if (req.rewrite_identity) try writer.writeAll(",\"rewrite_identity\":true");
    if (req.restart_identity) try writer.writeAll(",\"restart_identity\":true");
    if (req.operations.len != 0) {
        if (req.kind != .update) return error.UnsupportedOperation;
        try writer.writeAll(",\"patch\":{");
        for (req.operations, 0..) |op, i| {
            if (op.op != .set or op.path.len == 0) return error.UnsupportedOperation;
            const value_json = op.value_json orelse return error.UnsupportedOperation;
            if (i > 0) try writer.writeByte(',');
            try writer.print("{f}:", .{std.json.fmt(op.path, .{})});
            try writer.writeAll(value_json);
        }
        try writer.writeByte('}');
    }
    if (req.returning_all or req.returning.len != 0) {
        try writer.writeAll(",\"returning\":[");
        if (req.returning_all) {
            try writer.print("{f}", .{std.json.fmt("*", .{})});
        } else {
            for (req.returning, 0..) |field, i| {
                if (field.len == 0) return error.UnsupportedOperation;
                if (i > 0) try writer.writeByte(',');
                try writer.print("{f}", .{std.json.fmt(field, .{})});
            }
        }
        try writer.writeByte(']');
    }
    try writer.writeByte('}');
    return try out.toOwnedSlice();
}

pub fn encodeRowsJoinedMutationSourceRequestAlloc(
    alloc: std.mem.Allocator,
    req: db_mod.types.RelationalRowsJoinedMutationSourceRequest,
) ![]u8 {
    if (req.ctes.len != 0 or
        req.match_expression_predicates.len != 0 or
        req.match_expression_or_predicates.len != 0 or
        req.match_expression_not_predicates.len != 0 or
        req.match_expression_array_contains.len != 0 or
        req.rewrite_identity or
        req.patch_expressions.len != 0 or
        req.increment_expressions.len != 0 or
        req.json_set_expressions.len != 0 or
        req.returning_expressions.len != 0)
    {
        return error.UnsupportedOperation;
    }
    if (req.join.join_type != .inner or
        req.join.strategy != .auto or
        req.join.select.len != 0 or
        req.join.on_expression_predicates.len != 0 or
        req.join.on_expression_or_predicates.len != 0 or
        req.join.on_expression_not_predicates.len != 0 or
        req.join.on_expression_array_contains.len != 0 or
        req.join.match_expression_predicates.len != 0 or
        req.join.match_expression_or_predicates.len != 0 or
        req.join.match_expression_not_predicates.len != 0 or
        req.join.match_expression_array_contains.len != 0)
    {
        return error.UnsupportedOperation;
    }

    const target_query = if (req.target_side == .left) req.join.left else req.join.right;
    const source_query = if (req.target_side == .left) req.join.right else req.join.left;
    if (target_query.row_claim == null or source_query.row_claim != null) return error.UnsupportedOperation;

    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;

    try writer.writeAll("{\"op\":");
    try writer.print("{f}", .{std.json.fmt(rowsMutationKindText(req.kind), .{})});
    if (req.source_table.len != 0) {
        try writer.print(",\"source_table\":{f}", .{std.json.fmt(req.source_table, .{})});
    }
    try writer.print(",\"target_side\":{f}", .{std.json.fmt(rowsJoinProjectionSideText(req.target_side), .{})});
    try writer.writeAll(",\"join\":");
    try encodeRowsJoinedMutationSourceJoin(writer, req.join);

    if (req.source_assignments.len != 0) {
        if (req.kind != .update) return error.UnsupportedOperation;
        try writer.writeAll(",\"source_assignments\":[");
        for (req.source_assignments, 0..) |assignment, i| {
            if (assignment.field.len == 0 or assignment.source_field.len == 0) return error.UnsupportedOperation;
            if (i > 0) try writer.writeByte(',');
            try writer.print(
                "{{\"target_field\":{f},\"side\":{f},\"field\":{f}}}",
                .{
                    std.json.fmt(assignment.field, .{}),
                    std.json.fmt(rowsJoinProjectionSideText(assignment.source_side), .{}),
                    std.json.fmt(assignment.source_field, .{}),
                },
            );
        }
        try writer.writeByte(']');
    }
    if (req.operations.len != 0) {
        if (req.kind != .update) return error.UnsupportedOperation;
        try writer.writeAll(",\"patch\":{");
        for (req.operations, 0..) |op, i| {
            if (op.op != .set or op.path.len == 0) return error.UnsupportedOperation;
            const value_json = op.value_json orelse return error.UnsupportedOperation;
            if (i > 0) try writer.writeByte(',');
            try writer.print("{f}:", .{std.json.fmt(op.path, .{})});
            try writer.writeAll(value_json);
        }
        try writer.writeByte('}');
    }
    if (req.returning_all or req.returning.len != 0) {
        try writer.writeAll(",\"returning\":[");
        if (req.returning_all) {
            try writer.print("{f}", .{std.json.fmt("*", .{})});
        } else {
            for (req.returning, 0..) |field, i| {
                if (field.len == 0) return error.UnsupportedOperation;
                if (i > 0) try writer.writeByte(',');
                try writer.print("{f}", .{std.json.fmt(field, .{})});
            }
        }
        try writer.writeByte(']');
    }
    try writer.writeByte('}');
    return try out.toOwnedSlice();
}

fn encodeRowsJoinedMutationSourceJoin(writer: *std.Io.Writer, req: db_mod.types.RelationalRowsJoinRequest) !void {
    try writer.writeAll("{\"left\":");
    try encodeRowsMutationSourceQueryRequest(writer, req.left);
    try writer.writeAll(",\"right\":");
    try encodeRowsMutationSourceQueryRequest(writer, req.right);
    if (req.on.len != 0) {
        try writer.writeAll(",\"on\":[");
        for (req.on, 0..) |join_on, i| {
            if (join_on.left_field.len == 0 or join_on.right_field.len == 0) return error.UnsupportedOperation;
            if (i > 0) try writer.writeByte(',');
            try writer.print(
                "{{\"left_field\":{f},\"right_field\":{f}}}",
                .{ std.json.fmt(join_on.left_field, .{}), std.json.fmt(join_on.right_field, .{}) },
            );
        }
        try writer.writeByte(']');
    }
    if (req.order_by.len != 0) {
        try writer.writeAll(",\"order_by\":[");
        for (req.order_by, 0..) |order, i| {
            if (order.expression != null or order.field.len == 0) return error.UnsupportedOperation;
            if (i > 0) try writer.writeByte(',');
            try writer.writeByte('{');
            try writer.print("\"field\":{f}", .{std.json.fmt(order.field, .{})});
            if (order.direction == .desc) try writer.writeAll(",\"direction\":\"desc\"");
            if (order.null_test) |null_test| {
                try writer.writeAll(",\"null_test\":");
                try writer.print("{f}", .{std.json.fmt(rowsQueryOrderNullTestText(null_test), .{})});
            }
            try writer.writeByte('}');
        }
        try writer.writeByte(']');
    }
    if (req.limit) |limit| try writer.print(",\"limit\":{d}", .{limit});
    if (req.offset != 0) try writer.print(",\"offset\":{d}", .{req.offset});
    try writer.writeByte('}');
}

fn rowsMutationKindText(kind: db_mod.types.RelationalRowsMutationKind) []const u8 {
    return switch (kind) {
        .update => "update",
        .delete => "delete",
    };
}

fn rowsJoinProjectionSideText(side: db_mod.types.RelationalRowsJoinProjectionSide) []const u8 {
    return switch (side) {
        .left => "left",
        .right => "right",
    };
}

fn encodeRowsMutationSourceQueryRequest(writer: *std.Io.Writer, req: db_mod.types.RelationalRowsQueryRequest) !void {
    if (req.source_cte.len != 0 or
        req.array_any.len != 0 or
        req.array_contains.len != 0 or
        req.array_eq.len != 0 or
        req.in_predicates.len != 0 or
        req.json_contains.len != 0 or
        req.json_path_eq.len != 0 or
        req.json_path_exists.len != 0 or
        req.text_patterns.len != 0 or
        req.access_or_predicates.len != 0 or
        req.access_not_predicates.len != 0 or
        req.expression_predicates.len != 0 or
        req.expression_or_predicates.len != 0 or
        req.expression_not_predicates.len != 0 or
        req.expression_array_contains.len != 0 or
        req.select.len != 0 or
        req.json_extract.len != 0 or
        req.array_length.len != 0 or
        req.coalesce.len != 0 or
        req.field_aliases.len != 0 or
        req.expressions.len != 0 or
        !req.select_all or
        req.distinct_on.len != 0 or
        req.distinct_on_expressions.len != 0)
    {
        return error.UnsupportedOperation;
    }

    try writer.writeByte('{');
    var wrote = false;
    if (req.predicates.len != 0 or req.or_predicates.len != 0 or req.not_predicates.len != 0) {
        try writer.writeAll("\"where\":");
        try encodeRowsMutationSourceWhere(writer, req);
        wrote = true;
    }
    if (req.order_by.len != 0) {
        if (wrote) try writer.writeByte(',');
        try writer.writeAll("\"order_by\":[");
        for (req.order_by, 0..) |order, i| {
            if (order.expression != null or order.field.len == 0) return error.UnsupportedOperation;
            if (i > 0) try writer.writeByte(',');
            try writer.writeByte('{');
            try writer.print("\"field\":{f}", .{std.json.fmt(order.field, .{})});
            if (order.direction == .desc) try writer.writeAll(",\"direction\":\"desc\"");
            if (order.null_test) |null_test| {
                try writer.writeAll(",\"null_test\":");
                try writer.print("{f}", .{std.json.fmt(rowsQueryOrderNullTestText(null_test), .{})});
            }
            try writer.writeByte('}');
        }
        try writer.writeByte(']');
        wrote = true;
    }
    if (req.limit) |limit| {
        if (wrote) try writer.writeByte(',');
        try writer.print("\"limit\":{d}", .{limit});
        wrote = true;
    }
    if (req.offset != 0) {
        if (wrote) try writer.writeByte(',');
        try writer.print("\"offset\":{d}", .{req.offset});
        wrote = true;
    }
    if (req.row_claim) |claim| {
        if (wrote) try writer.writeByte(',');
        try writer.writeAll("\"row_claim\":");
        try encodeRowsMutationSourceRowClaim(writer, claim);
        wrote = true;
    }
    if (req.doc_key_range) |range| {
        if (wrote) try writer.writeByte(',');
        try writer.writeAll("\"doc_key_range\":{");
        try writer.print("\"start\":{f},\"end\":{f}", .{ std.json.fmt(range.start, .{}), std.json.fmt(range.end, .{}) });
        try writer.writeByte('}');
    }
    try writer.writeByte('}');
}

fn encodeRowsMutationSourceWhere(writer: *std.Io.Writer, req: db_mod.types.RelationalRowsQueryRequest) !void {
    const scalar_atoms = req.predicates.len + req.in_predicates.len;
    const grouped = scalar_atoms != 1 or req.or_predicates.len != 0 or req.not_predicates.len != 0;
    if (!grouped and req.predicates.len == 1) return try encodeRowsMutationSourcePredicate(writer, req.predicates[0]);
    if (!grouped and req.in_predicates.len == 1) return try encodeRowsMutationSourceInPredicate(writer, req.in_predicates[0]);

    try writer.writeByte('{');
    var wrote = false;
    if (req.predicates.len != 0 or req.in_predicates.len != 0) {
        try writer.writeAll("\"all\":[");
        var i: usize = 0;
        for (req.predicates) |predicate| {
            if (i > 0) try writer.writeByte(',');
            try encodeRowsMutationSourcePredicate(writer, predicate);
            i += 1;
        }
        for (req.in_predicates) |predicate| {
            if (i > 0) try writer.writeByte(',');
            try encodeRowsMutationSourceInPredicate(writer, predicate);
            i += 1;
        }
        try writer.writeByte(']');
        wrote = true;
    }
    if (req.or_predicates.len != 0) {
        if (wrote) try writer.writeByte(',');
        try writer.writeAll("\"any\":[");
        for (req.or_predicates, 0..) |group, i| {
            if (group.predicates.len == 0) return error.UnsupportedOperation;
            if (i > 0) try writer.writeByte(',');
            try encodeRowsMutationSourcePredicateGroup(writer, group);
        }
        try writer.writeByte(']');
        wrote = true;
    }
    if (req.not_predicates.len != 0) {
        if (wrote) try writer.writeByte(',');
        try writer.writeAll("\"not\":[");
        for (req.not_predicates, 0..) |group, i| {
            if (group.predicates.len == 0) return error.UnsupportedOperation;
            if (i > 0) try writer.writeByte(',');
            try encodeRowsMutationSourcePredicateGroup(writer, group);
        }
        try writer.writeByte(']');
    }
    try writer.writeByte('}');
}

fn encodeRowsMutationSourcePredicateGroup(writer: *std.Io.Writer, group: db_mod.types.RelationalRowsPredicateGroup) !void {
    if (group.predicates.len == 1) return try encodeRowsMutationSourcePredicate(writer, group.predicates[0]);
    try writer.writeAll("{\"all\":[");
    for (group.predicates, 0..) |predicate, i| {
        if (i > 0) try writer.writeByte(',');
        try encodeRowsMutationSourcePredicate(writer, predicate);
    }
    try writer.writeAll("]}");
}

fn encodeRowsMutationSourcePredicate(writer: *std.Io.Writer, predicate: runtime_schema.RelationalCheck) !void {
    if (predicate.expression != null or predicate.field.len == 0) return error.UnsupportedOperation;
    try writer.writeByte('{');
    try writer.print("\"field\":{f},\"op\":{f}", .{
        std.json.fmt(predicate.field, .{}),
        std.json.fmt(rowsPredicateOpText(predicate.op), .{}),
    });
    if (rowsQueryPredicateNeedsValue(predicate.op)) {
        const value_json = predicate.value_json orelse return error.UnsupportedOperation;
        try writer.writeAll(",\"value\":");
        try writer.writeAll(value_json);
    } else if (predicate.value_json != null) {
        return error.UnsupportedOperation;
    }
    try writer.writeByte('}');
}

fn encodeRowsMutationSourceInPredicate(writer: *std.Io.Writer, predicate: db_mod.types.RelationalRowsInPredicate) !void {
    if (predicate.field.len == 0 or predicate.values_json.len == 0) return error.UnsupportedOperation;
    try writer.writeByte('{');
    try writer.print("\"field\":{f},\"op\":{f},\"value\":", .{
        std.json.fmt(predicate.field, .{}),
        std.json.fmt(if (predicate.negated) "not_in" else "in", .{}),
    });
    try writer.writeAll(predicate.values_json);
    try writer.writeByte('}');
}

fn rowsPredicateOpText(op: runtime_schema.RelationalCheckOp) []const u8 {
    return switch (op) {
        .is_null => "is_null",
        .is_not_null => "is_not_null",
        .eq => "eq",
        .ne => "ne",
        .gt => "gt",
        .gte => "gte",
        .lt => "lt",
        .lte => "lte",
        .is_distinct => "is_distinct",
        .is_not_distinct => "is_not_distinct",
    };
}

fn rowsQueryOrderNullTestText(null_test: RowsQueryOrderNullTest) []const u8 {
    return switch (null_test) {
        .is_null => "is_null",
        .is_not_null => "is_not_null",
    };
}

fn encodeRowsMutationSourceRowClaim(writer: *std.Io.Writer, claim: db_mod.types.RowClaimRequest) !void {
    const txn_id = claim.txn_id orelse return error.UnsupportedOperation;
    var txn_hex: [32]u8 = undefined;
    encodeRowsMutationSourceTxnIdHex(txn_id, &txn_hex);
    try writer.writeByte('{');
    try writer.print("\"mode\":{f},\"wait_policy\":{f},\"lease_ms\":{d},\"owner_id\":{f},\"transaction_id\":{f}", .{
        std.json.fmt(rowsClaimModeText(claim.mode), .{}),
        std.json.fmt(rowsClaimWaitPolicyText(claim.effectiveWaitPolicy()), .{}),
        claim.lease_ms,
        std.json.fmt(claim.owner_id, .{}),
        std.json.fmt(txn_hex[0..], .{}),
    });
    if (claim.skip_locked) try writer.writeAll(",\"skip_locked\":true");
    try writer.writeByte('}');
}

fn rowsClaimModeText(mode: db_mod.types.RowClaimMode) []const u8 {
    return switch (mode) {
        .for_update => "for_update",
        .for_no_key_update => "for_no_key_update",
        .for_share => "for_share",
        .for_key_share => "for_key_share",
    };
}

fn rowsClaimWaitPolicyText(policy: db_mod.types.RowClaimWaitPolicy) []const u8 {
    return switch (policy) {
        .wait => "wait",
        .nowait => "nowait",
        .skip_locked => "skip_locked",
    };
}

fn encodeRowsMutationSourceTxnIdHex(txn_id: db_mod.types.TxnId, out: *[32]u8) void {
    const alphabet = "0123456789abcdef";
    for (txn_id, 0..) |byte, i| {
        out[i * 2] = alphabet[byte >> 4];
        out[i * 2 + 1] = alphabet[byte & 0x0f];
    }
}

fn rowsQueryIsClaimedWholeTableMutationSource(source: db_mod.types.RelationalRowsQueryRequest) bool {
    return source.row_claim != null and
        source.source_cte.len == 0 and
        source.predicates.len == 0 and
        source.array_any.len == 0 and
        source.array_contains.len == 0 and
        source.array_eq.len == 0 and
        source.in_predicates.len == 0 and
        source.json_contains.len == 0 and
        source.json_path_eq.len == 0 and
        source.json_path_exists.len == 0 and
        source.text_patterns.len == 0 and
        source.or_predicates.len == 0 and
        source.not_predicates.len == 0 and
        source.access_or_predicates.len == 0 and
        source.access_not_predicates.len == 0 and
        source.expression_predicates.len == 0 and
        source.expression_or_predicates.len == 0 and
        source.expression_not_predicates.len == 0 and
        source.expression_array_contains.len == 0 and
        source.select.len == 0 and
        source.json_extract.len == 0 and
        source.array_length.len == 0 and
        source.coalesce.len == 0 and
        source.field_aliases.len == 0 and
        source.expressions.len == 0 and
        source.distinct_on.len == 0 and
        source.distinct_on_expressions.len == 0 and
        source.order_by.len == 0 and
        source.doc_key_range == null and
        source.limit == null and
        source.offset == 0;
}

fn parseRowsTemporalPortionAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    maybe_value: ?std.json.Value,
) !?db_mod.types.RelationalRowsTemporalPortion {
    const value = maybe_value orelse return null;
    if (value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(value.object, &.{ "period", "from", "to" });
    const period_value = value.object.get("period") orelse return error.InvalidRowsRequest;
    if (period_value != .string or period_value.string.len == 0) return error.InvalidRowsRequest;
    const period = findRelationalPeriod(schema.periods, period_value.string) orelse return error.InvalidRowsRequest;
    const start_column = findRelationalColumn(schema.relational_columns, period.start_column) orelse return error.InvalidRowsRequest;
    const end_column = findRelationalColumn(schema.relational_columns, period.end_column) orelse return error.InvalidRowsRequest;
    if (start_column.field_type != end_column.field_type) return error.InvalidRowsRequest;
    const from_value = value.object.get("from") orelse return error.InvalidRowsRequest;
    const to_value = value.object.get("to") orelse return error.InvalidRowsRequest;
    const from_bound = try rowsTemporalPortionStartBound(from_value, start_column);
    const to_bound = try rowsTemporalPortionEndBound(to_value, end_column);
    if (!rowsTemporalPortionBoundLessThan(from_bound, to_bound)) return error.InvalidRowsRequest;
    return .{
        .period = try alloc.dupe(u8, period_value.string),
        .from_json = try jsonValueStringifyAlloc(alloc, from_value),
        .to_json = try jsonValueStringifyAlloc(alloc, to_value),
    };
}

const RowsTemporalPortionBound = union(enum) {
    neg_infinity,
    number: f64,
    datetime_ns: i64,
    pos_infinity,
};

fn rowsTemporalPortionStartBound(value: std.json.Value, column: runtime_schema.RelationalColumn) !RowsTemporalPortionBound {
    if (value == .null) return if (column.nullable) .neg_infinity else error.InvalidRowsRequest;
    return try rowsTemporalPortionFiniteBound(value, column);
}

fn rowsTemporalPortionEndBound(value: std.json.Value, column: runtime_schema.RelationalColumn) !RowsTemporalPortionBound {
    if (value == .null) return if (column.nullable) .pos_infinity else error.InvalidRowsRequest;
    return try rowsTemporalPortionFiniteBound(value, column);
}

fn rowsTemporalPortionFiniteBound(value: std.json.Value, column: runtime_schema.RelationalColumn) !RowsTemporalPortionBound {
    return switch (column.field_type) {
        .numeric => switch (value) {
            .integer => |number| .{ .number = @floatFromInt(number) },
            .float => |number| .{ .number = number },
            else => error.InvalidRowsRequest,
        },
        .datetime => switch (value) {
            .integer => |number| .{ .datetime_ns = number },
            else => error.InvalidRowsRequest,
        },
        else => error.InvalidRowsRequest,
    };
}

fn rowsTemporalPortionBoundLessThan(left: RowsTemporalPortionBound, right: RowsTemporalPortionBound) bool {
    return switch (left) {
        .neg_infinity => right != .neg_infinity,
        .number => |value| switch (right) {
            .number => |other| value < other,
            .pos_infinity => true,
            else => false,
        },
        .datetime_ns => |value| switch (right) {
            .datetime_ns => |other| value < other,
            .pos_infinity => true,
            else => false,
        },
        .pos_infinity => false,
    };
}

fn freeRowsTemporalPortion(alloc: std.mem.Allocator, portion: db_mod.types.RelationalRowsTemporalPortion) void {
    alloc.free(@constCast(portion.period));
    alloc.free(@constCast(portion.from_json));
    alloc.free(@constCast(portion.to_json));
}

pub fn parseRowsInsertSourceRequest(
    alloc: std.mem.Allocator,
    body: []const u8,
    schema: runtime_schema.TableSchema,
) !OwnedRowsInsertSourceRequest {
    return try parseRowsInsertSourceRequestWithSchemas(alloc, body, schema, schema);
}

pub fn parseRowsInsertSourceRequestWithSchemas(
    alloc: std.mem.Allocator,
    body: []const u8,
    target_schema: runtime_schema.TableSchema,
    source_schema: runtime_schema.TableSchema,
) !OwnedRowsInsertSourceRequest {
    return try parseRowsInsertSourceRequestWithSchemasAndSourceCteMode(alloc, body, target_schema, source_schema, false);
}

fn parseRowsInsertSourceRequestWithSchemasAndSourceCteMode(
    alloc: std.mem.Allocator,
    body: []const u8,
    target_schema: runtime_schema.TableSchema,
    source_schema: runtime_schema.TableSchema,
    allow_source_cte: bool,
) !OwnedRowsInsertSourceRequest {
    if (target_schema.storage_mode != .relational or target_schema.primary_key == null) return error.InvalidRowsRequest;
    if (source_schema.storage_mode != .relational) return error.InvalidRowsRequest;
    if (source_schema.primary_key == null and !allow_source_cte) return error.InvalidRowsRequest;
    if (body.len == 0) return error.InvalidRowsRequest;

    var parsed = std.json.parseFromSlice(std.json.Value, alloc, body, .{
        .allocate = .alloc_always,
    }) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(parsed.value.object, &.{ "op", "source_table", "source", "assignments", "on_conflict", "returning", "returning_expressions" });

    const op_value = parsed.value.object.get("op") orelse return error.InvalidRowsRequest;
    if (op_value != .string or !std.mem.eql(u8, op_value.string, "insert")) return error.InvalidRowsRequest;

    const source_table = try parseRowsInsertSourceTableAlloc(alloc, parsed.value.object.get("source_table"));
    errdefer if (source_table.len > 0) alloc.free(source_table);

    const source_value = parsed.value.object.get("source") orelse return error.InvalidRowsRequest;
    if (source_value != .object) return error.InvalidRowsRequest;
    const source_json = try jsonValueStringifyAlloc(alloc, source_value);
    defer alloc.free(source_json);
    var source = if (allow_source_cte)
        try parseRowsQueryStreamRequest(alloc, source_json, source_schema)
    else
        try parseRowsQueryRequest(alloc, source_json, source_schema);
    errdefer source.deinit(alloc);
    if (source.row_claim != null) return error.InvalidRowsRequest;
    if (source.doc_key_range != null and source.source_cte.len != 0) return error.InvalidRowsRequest;
    if (source.source_cte.len != 0 and !allow_source_cte) return error.InvalidRowsRequest;

    const assignments = try parseRowsInsertSourceAssignmentsWithSchemasAlloc(alloc, target_schema, source_schema, parsed.value.object.get("assignments") orelse return error.InvalidRowsRequest);
    errdefer freeRowsExpressionAssignments(alloc, assignments);

    const on_conflict: ?db_mod.types.RelationalRowsOnConflict = if (parsed.value.object.get("on_conflict")) |on_conflict_value| blk: {
        break :blk try parseRowsOnConflictAlloc(alloc, target_schema, on_conflict_value);
    } else null;
    errdefer if (on_conflict) |conflict| freeRowsOnConflict(alloc, conflict);

    const returning = try parseMutationSourceReturningAlloc(alloc, target_schema, parsed.value.object.get("returning"), parsed.value.object.get("returning_expressions"), &.{});
    errdefer {
        for (returning.fields) |field| alloc.free(field);
        if (returning.fields.len > 0) alloc.free(returning.fields);
        for (returning.expressions) |projection| {
            alloc.free(projection.output);
            freeRowsQueryExpression(alloc, projection.expression);
        }
        if (returning.expressions.len > 0) alloc.free(returning.expressions);
    }

    const req: db_mod.types.RelationalRowsInsertSourceRequest = .{
        .source_table = source_table,
        .source = source,
        .assignments = assignments,
        .on_conflict = on_conflict,
        .returning = returning.fields,
        .returning_expressions = returning.expressions,
        .returning_all = returning.all,
    };
    db_mod.DB.validateRelationalRowsInsertSourceRequestWithSchemas(target_schema, source_schema, req) catch return error.InvalidRowsRequest;
    return .{ .req = req };
}

fn parseRowsInsertSourceTableAlloc(alloc: std.mem.Allocator, maybe_source_table: ?std.json.Value) ![]const u8 {
    const value = maybe_source_table orelse return "";
    if (value != .string) return error.InvalidRowsRequest;
    if (value.string.len == 0) return "";
    for (value.string) |c| {
        const valid = std.ascii.isAlphanumeric(c) or c == '_' or c == '-';
        if (!valid) return error.InvalidRowsRequest;
    }
    return try alloc.dupe(u8, value.string);
}

pub fn parseRowsJoinedMutationSourceRequest(
    alloc: std.mem.Allocator,
    body: []const u8,
    schema: runtime_schema.TableSchema,
) !OwnedRowsJoinedMutationSourceRequest {
    return try parseRowsJoinedMutationSourceRequestWithSchemas(alloc, body, schema, schema);
}

pub fn parseRowsJoinedMutationSourceRequestWithSchemas(
    alloc: std.mem.Allocator,
    body: []const u8,
    target_schema: runtime_schema.TableSchema,
    source_schema: runtime_schema.TableSchema,
) !OwnedRowsJoinedMutationSourceRequest {
    if (target_schema.storage_mode != .relational or target_schema.primary_key == null) return error.InvalidRowsRequest;
    if (source_schema.storage_mode != .relational or source_schema.primary_key == null) return error.InvalidRowsRequest;
    if (body.len == 0) return error.InvalidRowsRequest;

    var parsed = std.json.parseFromSlice(std.json.Value, alloc, body, .{
        .allocate = .alloc_always,
    }) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(parsed.value.object, &.{ "op", "ctes", "source_table", "target_side", "join", "match_expression_where", "match_expression_any", "match_expression_not", "match_expression_array_contains", "rewrite_identity", "source_assignments", "patch", "patch_expr", "increment", "increment_expr", "json_set", "returning", "returning_expressions" });

    const op_value = parsed.value.object.get("op") orelse return error.InvalidRowsRequest;
    if (op_value != .string) return error.InvalidRowsRequest;
    const kind: db_mod.types.RelationalRowsMutationKind = if (std.mem.eql(u8, op_value.string, "update"))
        .update
    else if (std.mem.eql(u8, op_value.string, "delete"))
        .delete
    else
        return error.InvalidRowsRequest;
    const rewrite_identity = (try parseOptionalBool(parsed.value.object.get("rewrite_identity"))) orelse false;
    if (rewrite_identity and kind != .update) return error.InvalidRowsRequest;

    const source_table = try parseRowsJoinedMutationSourceTableAlloc(alloc, parsed.value.object.get("source_table"));
    errdefer if (source_table.len > 0) alloc.free(source_table);

    const target_side = try parseRowsJoinSide(parsed.value.object.get("target_side") orelse return error.InvalidRowsRequest);
    const ctes = try parseRowsCtesAlloc(alloc, source_schema, parsed.value.object.get("ctes"));
    errdefer freeRowsCtes(alloc, ctes);
    const planned_ctes = try planRowsCteOutputsAlloc(alloc, source_schema, ctes);
    defer freeRowsPlannedCtes(alloc, planned_ctes);
    const join_value = parsed.value.object.get("join") orelse return error.InvalidRowsRequest;
    const left_schema = if (target_side == .left) target_schema else try rowsSchemaForJoinSideValue(source_schema, planned_ctes, join_value, "left");
    const right_schema = if (target_side == .right) target_schema else try rowsSchemaForJoinSideValue(source_schema, planned_ctes, join_value, "right");
    var join = try parseRowsJoinedMutationJoinAllocWithSchemas(alloc, left_schema, right_schema, join_value, target_side);
    errdefer join.deinit(alloc);
    const target_query = if (target_side == .left) join.left else join.right;
    const source_query = if (target_side == .left) join.right else join.left;
    if (target_query.source_cte.len != 0) return error.InvalidRowsRequest;
    try validateRowsQuerySourceCteReference(ctes, source_query);
    try validateRowsJoinAgainstPlannedCteOutput(planned_ctes, join);

    const match_expression_predicates = try parseRowsJoinedMutationMatchExpressionPredicatesAlloc(alloc, target_schema, source_schema, parsed.value.object.get("match_expression_where"));
    errdefer freeRowsQueryExpressionConditions(alloc, match_expression_predicates);
    const match_expression_or_predicates = try parseRowsJoinedMutationMatchExpressionPredicateGroupsAlloc(alloc, target_schema, source_schema, parsed.value.object.get("match_expression_any"));
    errdefer freeRowsQueryExpressionPredicateGroups(alloc, match_expression_or_predicates);
    const match_expression_not_predicates = try parseRowsJoinedMutationMatchExpressionPredicateGroupsAlloc(alloc, target_schema, source_schema, parsed.value.object.get("match_expression_not"));
    errdefer freeRowsQueryExpressionPredicateGroups(alloc, match_expression_not_predicates);
    const match_expression_array_contains = try parseRowsJoinedMutationMatchExpressionArrayContainsPredicatesAlloc(alloc, target_schema, source_schema, parsed.value.object.get("match_expression_array_contains"));
    errdefer freeRowsQueryExpressionArrayContainsPredicates(alloc, match_expression_array_contains);

    var source_assignments: []const db_mod.types.RelationalRowsJoinedMutationFieldAssignment = &.{};
    var operations: []db_mod.types.TransformOp = &.{};
    var patch_expressions: []db_mod.types.RelationalRowsExpressionAssignment = &.{};
    var increment_expressions: []db_mod.types.RelationalRowsExpressionAssignment = &.{};
    var json_set_expressions: []db_mod.types.RelationalRowsJsonSetExpressionAssignment = &.{};
    if (kind == .update) {
        source_assignments = try parseRowsJoinedMutationFieldAssignmentsAllocWithSchemas(alloc, target_schema, source_schema, parsed.value.object.get("source_assignments"), target_side, rewrite_identity);
        errdefer freeRowsJoinedMutationFieldAssignments(alloc, source_assignments);
        operations = try staticUpdateTransformOperationsAlloc(alloc, target_schema, parsed.value, true, rewrite_identity);
        errdefer freeTransformOps(alloc, operations);
        patch_expressions = try parseRowsJoinedMutationExpressionAssignmentsAlloc(alloc, target_schema, source_schema, parsed.value.object.get("patch_expr"), false, rewrite_identity);
        errdefer freeRowsExpressionAssignments(alloc, patch_expressions);
        increment_expressions = try parseRowsJoinedMutationExpressionAssignmentsAlloc(alloc, target_schema, source_schema, parsed.value.object.get("increment_expr"), true, false);
        errdefer freeRowsExpressionAssignments(alloc, increment_expressions);
        json_set_expressions = try parseRowsJoinedMutationJsonSetExpressionAssignmentsAlloc(alloc, target_schema, source_schema, parsed.value.object.get("json_set"));
        errdefer freeRowsJsonSetExpressionAssignments(alloc, json_set_expressions);
        if (source_assignments.len == 0 and operations.len == 0 and patch_expressions.len == 0 and increment_expressions.len == 0 and json_set_expressions.len == 0) return error.InvalidRowsRequest;
        try validateRowsMutationUpdateTargetPaths(operations, patch_expressions, increment_expressions, json_set_expressions, source_assignments);
    } else if (parsed.value.object.get("source_assignments") != null or parsed.value.object.get("patch") != null or parsed.value.object.get("patch_expr") != null or parsed.value.object.get("increment") != null or parsed.value.object.get("increment_expr") != null or parsed.value.object.get("json_set") != null) {
        return error.InvalidRowsRequest;
    }
    errdefer freeRowsJoinedMutationFieldAssignments(alloc, source_assignments);
    errdefer freeTransformOps(alloc, operations);
    errdefer freeRowsExpressionAssignments(alloc, patch_expressions);
    errdefer freeRowsExpressionAssignments(alloc, increment_expressions);
    errdefer freeRowsJsonSetExpressionAssignments(alloc, json_set_expressions);

    const returning = try parseJoinedMutationSourceReturningAlloc(alloc, target_schema, source_schema, parsed.value.object.get("returning"), parsed.value.object.get("returning_expressions"));
    errdefer freeParsedMutationSourceReturning(alloc, returning);

    return .{ .req = .{
        .kind = kind,
        .ctes = ctes,
        .source_table = source_table,
        .target_side = target_side,
        .join = join,
        .match_expression_predicates = match_expression_predicates,
        .match_expression_or_predicates = match_expression_or_predicates,
        .match_expression_not_predicates = match_expression_not_predicates,
        .match_expression_array_contains = match_expression_array_contains,
        .rewrite_identity = rewrite_identity,
        .source_assignments = source_assignments,
        .operations = operations,
        .patch_expressions = patch_expressions,
        .increment_expressions = increment_expressions,
        .json_set_expressions = json_set_expressions,
        .returning = returning.fields,
        .returning_expressions = returning.expressions,
        .returning_all = returning.all,
    } };
}

pub fn parseRowsAggregateRequest(
    alloc: std.mem.Allocator,
    body: []const u8,
    schema: runtime_schema.TableSchema,
) !OwnedRowsAggregateRequest {
    if (schema.storage_mode != .relational) return error.InvalidRowsRequest;
    if (body.len == 0) return error.InvalidRowsRequest;

    var parsed = std.json.parseFromSlice(std.json.Value, alloc, body, .{
        .allocate = .alloc_always,
    }) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(parsed.value.object, &.{ "source", "group_by", "group_expressions", "aggregations", "having", "having_expressions", "having_any", "having_not", "order_by", "limit", "offset" });

    var source: OwnedRowsQueryRequest = if (parsed.value.object.get("source")) |source_value| blk: {
        if (source_value != .object) return error.InvalidRowsRequest;
        const source_json = try jsonValueStringifyAlloc(alloc, source_value);
        defer alloc.free(source_json);
        break :blk try parseRowsQueryStreamRequest(alloc, source_json, schema);
    } else .{};
    errdefer source.deinit(alloc);
    if (source.row_claim != null) return error.InvalidRowsRequest;
    if (source.doc_key_range != null and source.source_cte.len != 0) return error.InvalidRowsRequest;

    const group_by = try parseRowsAggregateGroupByAlloc(alloc, schema, parsed.value.object.get("group_by"));
    errdefer freeStringSlice(alloc, group_by);

    const group_expressions = try parseRowsQueryExpressionProjectionsAlloc(alloc, schema, parsed.value.object.get("group_expressions"));
    errdefer freeRowsQueryExpressionProjections(alloc, group_expressions);

    const aggregations = try parseRowsAggregateSpecsAlloc(alloc, schema, parsed.value.object.get("aggregations"), group_by.len + group_expressions.len > 0);
    errdefer freeRowsAggregateSpecs(alloc, aggregations);

    const output_columns = try rowsAggregateOutputColumnsAlloc(alloc, schema, group_by, group_expressions, aggregations);
    defer if (output_columns.len > 0) alloc.free(output_columns);

    const having_predicates = try parseRowsAggregateOutputPredicatesAlloc(alloc, schema, group_by, group_expressions, aggregations, parsed.value.object.get("having"));
    errdefer {
        freeQueryPredicates(alloc, having_predicates);
        if (having_predicates.len > 0) alloc.free(having_predicates);
    }

    const having_expressions = try parseRowsAggregateOutputExpressionsAlloc(alloc, schema, group_by, group_expressions, aggregations, parsed.value.object.get("having_expressions"));
    errdefer freeRowsQueryExpressionConditions(alloc, having_expressions);

    const having_any = try parseRowsAggregateOutputExpressionGroupsAlloc(alloc, schema, group_by, group_expressions, aggregations, parsed.value.object.get("having_any"));
    errdefer freeRowsQueryExpressionPredicateGroups(alloc, having_any);

    const having_not = try parseRowsAggregateOutputExpressionGroupsAlloc(alloc, schema, group_by, group_expressions, aggregations, parsed.value.object.get("having_not"));
    errdefer freeRowsQueryExpressionPredicateGroups(alloc, having_not);

    const order_by = try parseRowsAggregateOutputOrderAlloc(alloc, schema, group_by, group_expressions, aggregations, parsed.value.object.get("order_by"));
    errdefer {
        freeRowsQueryOrder(alloc, order_by);
        if (order_by.len > 0) alloc.free(order_by);
    }

    return .{
        .source = source,
        .group_by = group_by,
        .group_expressions = group_expressions,
        .aggregations = aggregations,
        .having_predicates = having_predicates,
        .having_expressions = having_expressions,
        .having_any = having_any,
        .having_not = having_not,
        .order_by = order_by,
        .limit = try parseOptionalU32(parsed.value.object.get("limit")),
        .offset = (try parseOptionalU32(parsed.value.object.get("offset"))) orelse 0,
    };
}

