    if ((left_ranges.len == 0) != (right_ranges.len == 0)) return error.InvalidRowsRequest;
    const planned_ctes = try planRowsCteOutputsAlloc(alloc, cte_base_schema, ctes);
    defer freeRowsPlannedCtes(alloc, planned_ctes);
