    try validateRowsJoinAgainstPlannedCteOutput(planned_ctes, join);

    return .{
        .ctes = ctes,
        .left_table = left_table,
        .right_table = right_table,
        .left_ranges = left_ranges,
        .right_ranges = right_ranges,
        .join = join,
    };
