fn freeRowsMutationSourceResponseTransform(alloc: std.mem.Allocator, transform: db_mod.types.DocumentTransform) void {
    alloc.free(@constCast(transform.key));
    for (transform.operations) |op| {
        alloc.free(@constCast(op.path));
        if (op.value_json) |value_json| alloc.free(@constCast(value_json));
    }
    if (transform.operations.len > 0) alloc.free(@constCast(transform.operations));
}

fn rowsMutationSourceResponseString(obj: std.json.ObjectMap, field: []const u8) ?[]const u8 {
    return switch (obj.get(field) orelse return null) {
        .string => |text| text,
        else => null,
    };
}

fn rowsMutationSourceResponseTransformOp(text: []const u8) ?db_mod.types.TransformOpType {
    inline for (std.meta.fields(db_mod.types.TransformOpType)) |field| {
        const op: db_mod.types.TransformOpType = @enumFromInt(field.value);
        if (std.mem.eql(u8, text, db_mod.transform.transformOpText(op))) return op;
    }
    if (std.mem.eql(u8, text, "$set_on_insert")) return .set_on_insert;
    return null;
}

pub fn executeRowsQueryOnJsonRowsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    request: OwnedRowsQueryRequest,
    rows: []const []const u8,
) !OwnedRowsQueryResult {
    if (schema.storage_mode != .relational) return error.InvalidRowsRequest;
    if (request.source_cte.len != 0) return error.UnsupportedRowsQuery;
    if (request.row_claim != null) return error.UnsupportedRowsQuery;
    if (request.doc_key_range != null and schema.primary_key == null) return error.InvalidRowsRequest;
    try validateRowsQueryProjectionOutputs(
        schema,
        .{ .fields = request.select, .all = request.select_all },
        request.json_extract,
        request.array_length,
        request.coalesce,
        request.field_aliases,
        request.expressions,
        request.scalar_subqueries,
    );

    var candidates = std.ArrayListUnmanaged(QueryCandidate).empty;
    defer {
        for (candidates.items) |candidate| freeQueryOrderKeySlice(alloc, candidate.order_keys);
        candidates.deinit(alloc);
    }

    for (rows, 0..) |row_json, ordinal| {
        if (!try rowJsonInDocKeyRangeAlloc(alloc, schema, row_json, request.doc_key_range)) continue;
        var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidRowsRequest;
        defer parsed.deinit();
        if (parsed.value != .object) return error.InvalidRowsRequest;
        if (!try queryRequestPredicatesPass(alloc, parsed.value, request)) continue;

        const order_keys = try queryOrderKeysAlloc(alloc, parsed.value, request.order_by);
        errdefer freeQueryOrderKeys(alloc, order_keys);
        try candidates.append(alloc, .{
            .row_json = row_json,
            .order_keys = order_keys,
            .ordinal = ordinal,
        });
    }

    if (request.order_by.len > 0) {
        std.sort.pdq(QueryCandidate, candidates.items, QuerySortContext{ .order_by = request.order_by }, queryCandidateLessThan);
    }

    var candidate_indexes = std.ArrayListUnmanaged(usize).empty;
    defer candidate_indexes.deinit(alloc);
    if (request.distinct_on.len > 0 or request.distinct_on_expressions.len > 0) {
        try appendRowsQueryDistinctOnIndexesAlloc(alloc, candidates.items, schema.relational_columns, request.distinct_on, request.distinct_on_expressions, &candidate_indexes);
    } else {
        try candidate_indexes.ensureUnusedCapacity(alloc, candidates.items.len);
        for (0..candidates.items.len) |i| candidate_indexes.appendAssumeCapacity(i);
    }

    const total: u32 = @intCast(candidate_indexes.items.len);
    const start = @min(@as(usize, request.offset), candidate_indexes.items.len);
    const limited_len: usize = if (request.limit) |limit|
        @min(@as(usize, limit), candidate_indexes.items.len - start)
    else
        candidate_indexes.items.len - start;

    var out_rows = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (out_rows.items) |row| alloc.free(@constCast(row));
        out_rows.deinit(alloc);
    }
    for (candidate_indexes.items[start .. start + limited_len]) |candidate_index| {
        const candidate = candidates.items[candidate_index];
        const projected = try projectRowsQueryRowAlloc(alloc, request, candidate.row_json);
        var projected_transferred = false;
        errdefer if (!projected_transferred) alloc.free(projected);
        try out_rows.append(alloc, projected);
        projected_transferred = true;
    }

    const total_shape = rowsQueryTotalShape(total, out_rows.items.len, request.offset, request.limit, request.total_mode);
    return .{
        .rows = try out_rows.toOwnedSlice(alloc),
        .total = total_shape.total,
        .total_exact = total_shape.total_exact,
        .include_profile = request.profile,
    };
}

const RowsQueryTotalShape = struct {
    total: u32,
    total_exact: bool,
};

fn rowsQueryTotalShape(
    exact_total: u32,
    returned_len: usize,
    offset: u32,
    limit: ?u32,
    total_mode: db_mod.types.RelationalRowsQueryRequest.TotalMode,
) RowsQueryTotalShape {
    switch (total_mode) {
        .exact => return .{ .total = exact_total, .total_exact = true },
        .bounded => {
            const page_limit = limit orelse return .{ .total = exact_total, .total_exact = true };
            if (returned_len < @as(usize, page_limit)) return .{ .total = exact_total, .total_exact = true };
            const bound = @min(@as(u64, exact_total), @as(u64, offset) + @as(u64, page_limit));
            return .{ .total = @intCast(bound), .total_exact = false };
        },
        .none => {
            const page_limit = limit orelse return .{ .total = exact_total, .total_exact = true };
            if (returned_len < @as(usize, page_limit)) return .{ .total = exact_total, .total_exact = true };
            return .{ .total = @intCast(returned_len), .total_exact = false };
        },
    }
}

pub fn buildLakeRowsScanRequestForRowsQueryAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    request: OwnedRowsQueryRequest,
) !OwnedRowsLakeScanRequest {
    if (schema.storage_mode != .relational) return error.InvalidRowsRequest;
    if (request.source_cte.len != 0) return error.UnsupportedRowsQuery;
    if (request.row_claim != null) return error.UnsupportedRowsQuery;
    if (request.doc_key_range != null and schema.primary_key == null) return error.InvalidRowsRequest;
    try validateLakeRowsQueryPredicateGroupsSupported(alloc, schema, request);
    for (request.distinct_on) |field| {
        const column = findRelationalColumn(schema.relational_columns, field) orelse return error.InvalidRowsRequest;
        if (column.field_type == .embedding) return error.UnsupportedRowsQuery;
    }
    for (request.distinct_on_expressions) |expression| {
        const output_type = try rowsExpressionOutputType(alloc, schema, expression);
        if (output_type == .embedding) return error.UnsupportedRowsQuery;
    }
    for (request.array_any) |predicate| {
        const column = findRelationalColumn(schema.relational_columns, predicate.field) orelse return error.InvalidRowsRequest;
        if (column.field_type != .array) return error.InvalidRowsRequest;
    }
    for (request.array_contains) |predicate| {
        const column = findRelationalColumn(schema.relational_columns, predicate.field) orelse return error.InvalidRowsRequest;
        if (column.field_type != .array) return error.InvalidRowsRequest;
    }
    for (request.array_eq) |predicate| {
        const column = findRelationalColumn(schema.relational_columns, predicate.field) orelse return error.InvalidRowsRequest;
        if (column.field_type != .array) return error.InvalidRowsRequest;
    }
    for (request.in_predicates) |predicate| {
        const column = findRelationalColumn(schema.relational_columns, predicate.field) orelse return error.InvalidRowsRequest;
        switch (column.field_type) {
            .embedding => return error.UnsupportedRowsQuery,
            else => {},
        }
    }
    for (request.json_contains) |predicate| {
        const column = findRelationalColumn(schema.relational_columns, predicate.field) orelse return error.InvalidRowsRequest;
        if (column.field_type != .json) return error.InvalidRowsRequest;
    }
    for (request.json_path_eq) |predicate| {
        const column = findRelationalColumn(schema.relational_columns, predicate.field) orelse return error.InvalidRowsRequest;
        if (column.field_type != .json) return error.InvalidRowsRequest;
    }
    for (request.json_path_exists) |predicate| {
        const column = findRelationalColumn(schema.relational_columns, predicate.field) orelse return error.InvalidRowsRequest;
        if (column.field_type != .json) return error.InvalidRowsRequest;
    }
    for (request.json_extract) |projection| {
        const column = findRelationalColumn(schema.relational_columns, projection.field) orelse return error.InvalidRowsRequest;
        if (column.field_type != .json) return error.InvalidRowsRequest;
    }
    for (request.array_length) |projection| {
        const column = findRelationalColumn(schema.relational_columns, projection.field) orelse return error.InvalidRowsRequest;
        if (column.field_type != .array and column.field_type != .json and column.field_type != .embedding) return error.InvalidRowsRequest;
    }
    for (request.field_aliases) |projection| {
        const column = findRelationalColumn(schema.relational_columns, projection.field) orelse return error.InvalidRowsRequest;
        switch (column.field_type) {
            .embedding => return error.UnsupportedRowsQuery,
            else => {},
        }
    }
    for (request.coalesce) |projection| {
        for (projection.operands) |operand| {
            switch (operand.kind) {
                .field => {
                    const column = findRelationalColumn(schema.relational_columns, operand.field) orelse return error.InvalidRowsRequest;
                    if (column.field_type == .embedding) return error.UnsupportedRowsQuery;
                },
                .value => {},
            }
        }
    }
    for (request.text_patterns) |predicate| {
        const column = findRelationalColumn(schema.relational_columns, predicate.field) orelse return error.InvalidRowsRequest;
        if (column.field_type != .keyword and column.field_type != .text and column.field_type != .link) return error.InvalidRowsRequest;
    }
    for (request.expression_predicates) |condition| {
        try validateRowsExpressionConditionTypes(alloc, schema, condition.lhs, condition.op, condition.rhs);
    }
    for (request.expression_array_contains) |predicate| {
        if ((try rowsExpressionOutputType(alloc, schema, predicate.expression)) != .array) return error.InvalidRowsRequest;
        var values = std.json.parseFromSlice(std.json.Value, alloc, predicate.value_json, .{}) catch return error.InvalidRowsRequest;
        defer values.deinit();
        if (values.value != .array) return error.InvalidRowsRequest;
        try validateRowsStringArrayValue(values.value);
    }
    for (request.expressions) |projection| {
        if (projection.output.len == 0) return error.InvalidRowsRequest;
        const output_type = try rowsExpressionOutputType(alloc, schema, projection.expression);
        if (output_type == .embedding) return error.UnsupportedRowsQuery;
    }
    for (request.order_by) |order| {
        if (order.expression) |expression| {
            const output_type = try rowsExpressionOutputType(alloc, schema, expression);
            if (output_type == .embedding) return error.UnsupportedRowsQuery;
        } else {
            if (order.field.len == 0) return error.InvalidRowsRequest;
            const column = findRelationalColumn(schema.relational_columns, order.field) orelse return error.InvalidRowsRequest;
            switch (column.field_type) {
                .embedding => return error.UnsupportedRowsQuery,
                else => {},
            }
        }
    }

    const projected_columns = try lakeRowsProjectedColumnsAlloc(alloc, schema, request);
    errdefer {
        for (projected_columns) |column| alloc.free(@constCast(column));
        if (projected_columns.len > 0) alloc.free(projected_columns);
    }

    var predicate_bytes_value: ?[]const u8 = null;
    errdefer if (predicate_bytes_value) |value| alloc.free(@constCast(value));
    const predicate: ?lake_rows.Predicate = if (request.predicates.len != 1 or request.predicates[0].op != .eq) null else pred_blk: {
        const source = request.predicates[0];
        const value_json = source.value_json orelse return error.InvalidRowsRequest;
        const column = findRelationalColumn(schema.relational_columns, source.field) orelse return error.InvalidRowsRequest;
        break :pred_blk try lakeRowsPredicateFromRowsPredicateAlloc(alloc, column, source.field, value_json, &predicate_bytes_value);
    };

    const scan = lake_rows.ScanRequest{
        .projected_columns = projected_columns,
        .predicate = predicate,
        .limit = if (request.order_by.len == 0 and request.distinct_on.len == 0 and request.distinct_on_expressions.len == 0 and request.doc_key_range == null and !lakeRowsQueryHasResidualPredicates(request)) if (request.limit) |limit| std.math.add(usize, @as(usize, request.offset), @as(usize, limit)) catch return error.InvalidRowsRequest else null else null,
    };
    return .{
        .request = scan,
        .projected_columns = projected_columns,
        .predicate_bytes_value = predicate_bytes_value,
    };
}

pub fn buildRowsQueryResultFromLakeRowsAlloc(
    alloc: std.mem.Allocator,
    request: OwnedRowsQueryRequest,
    result: lake_rows.ScanResult,
) !OwnedRowsQueryResult {
    return try buildRowsQueryResultFromLakeRowsWithSchemaAlloc(alloc, null, request, result);
}

pub fn buildRowsQueryResultFromLakeRowsWithSchemaAlloc(
    alloc: std.mem.Allocator,
    maybe_schema: ?runtime_schema.TableSchema,
    request: OwnedRowsQueryRequest,
    result: lake_rows.ScanResult,
) !OwnedRowsQueryResult {
    var filtered_rows: []lake_rows.ProjectedRow = result.rows;
    var owns_filtered_rows = false;
    const has_residual_predicates = lakeRowsQueryHasResidualPredicates(request);
    const has_doc_key_range = request.doc_key_range != null;
    if (has_residual_predicates or has_doc_key_range) {
        var filtered = std.ArrayListUnmanaged(lake_rows.ProjectedRow).empty;
        errdefer filtered.deinit(alloc);
        for (result.rows) |row| {
            if (!try lakeProjectedRowInDocKeyRangeAlloc(alloc, maybe_schema, row, request.doc_key_range)) continue;
            if (try lakeRowsQueryResidualPredicatesMatchAlloc(alloc, request, row)) {
                try filtered.append(alloc, row);
            }
        }
        filtered_rows = try filtered.toOwnedSlice(alloc);
        owns_filtered_rows = true;
    }
    defer if (owns_filtered_rows) alloc.free(filtered_rows);

    var rows = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (rows.items) |row| alloc.free(@constCast(row));
        rows.deinit(alloc);
    }

    var candidates = std.ArrayListUnmanaged(LakeRowsQueryOrderCandidate).empty;
    defer {
        for (candidates.items) |candidate| freeQueryOrderKeySlice(alloc, candidate.order_keys);
        candidates.deinit(alloc);
    }
    try candidates.ensureUnusedCapacity(alloc, filtered_rows.len);
    for (filtered_rows, 0..) |row, ordinal| {
        const keys = try lakeRowsQueryOrderKeysAlloc(alloc, row, request.order_by);
        var keys_transferred = false;
        errdefer if (!keys_transferred) freeQueryOrderKeySlice(alloc, keys);
        candidates.appendAssumeCapacity(.{
            .row = row,
            .order_keys = keys,
            .ordinal = ordinal,
        });
        keys_transferred = true;
    }

    if (request.order_by.len > 0) {
        std.sort.pdq(LakeRowsQueryOrderCandidate, candidates.items, QuerySortContext{ .order_by = request.order_by }, lakeRowsQueryOrderCandidateLessThan);
    }

    var candidate_indexes = std.ArrayListUnmanaged(usize).empty;
    defer candidate_indexes.deinit(alloc);
    if (request.distinct_on.len > 0 or request.distinct_on_expressions.len > 0) {
        const distinct_columns = if (maybe_schema) |schema| schema.relational_columns else &.{};
        try appendLakeRowsQueryDistinctOnIndexesAlloc(alloc, candidates.items, distinct_columns, request.distinct_on, request.distinct_on_expressions, &candidate_indexes);
    } else {
        try candidate_indexes.ensureUnusedCapacity(alloc, candidates.items.len);
        for (0..candidates.items.len) |i| candidate_indexes.appendAssumeCapacity(i);
    }

    const start = @min(@as(usize, request.offset), candidate_indexes.items.len);
    const limited_len: usize = if (request.limit) |limit|
        @min(@as(usize, limit), candidate_indexes.items.len - start)
    else
        candidate_indexes.items.len - start;
    try rows.ensureUnusedCapacity(alloc, limited_len);
    for (candidate_indexes.items[start .. start + limited_len]) |candidate_index| {
        const encoded = try lakeProjectedRowQueryJsonAlloc(alloc, request, candidates.items[candidate_index].row);
        rows.appendAssumeCapacity(encoded);
    }

    const exact_total: u32 = if (request.distinct_on.len > 0 or request.distinct_on_expressions.len > 0)
        @intCast(candidate_indexes.items.len)
    else if (!has_residual_predicates and !has_doc_key_range) result.total else @intCast(filtered_rows.len);
    const total_shape = rowsQueryTotalShape(exact_total, rows.items.len, request.offset, request.limit, request.total_mode);
    return .{
        .rows = try rows.toOwnedSlice(alloc),
        .total = total_shape.total,
        .total_exact = total_shape.total_exact,
        .include_profile = request.profile,
    };
}

pub fn buildLakeRowsScanRequestForRowsAggregateAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    request: OwnedRowsAggregateRequest,
) !OwnedRowsLakeScanRequest {
    try validateLakeRowsAggregateRequestSupported(alloc, schema, request);

    const projected_columns = try lakeRowsAggregateProjectedColumnsAlloc(alloc, schema, request);
    errdefer freeLakeProjectedColumns(alloc, projected_columns);

    var predicate_bytes_value: ?[]const u8 = null;
    errdefer if (predicate_bytes_value) |value| alloc.free(@constCast(value));
    const predicate: ?lake_rows.Predicate = if (request.source.predicates.len == 0) null else pred_blk: {
        const source = request.source.predicates[0];
        if (source.op != .eq) return error.UnsupportedRowsQuery;
        const value_json = source.value_json orelse return error.InvalidRowsRequest;
        const column = findRelationalColumn(schema.relational_columns, source.field) orelse return error.InvalidRowsRequest;
        break :pred_blk try lakeRowsPredicateFromRowsPredicateAlloc(alloc, column, source.field, value_json, &predicate_bytes_value);
    };

    return .{
        .request = .{
            .projected_columns = projected_columns,
            .predicate = predicate,
            .limit = null,
        },
        .projected_columns = projected_columns,
        .predicate_bytes_value = predicate_bytes_value,
    };
}

pub fn buildLakeRowsExpressionAggregateRequestForRowsAggregateAlloc(
    alloc: std.mem.Allocator,
    request: OwnedRowsAggregateRequest,
) !?OwnedRowsLakeExpressionAggregateRequest {
    if (!lakeRowsExpressionAggregateFastPathSupported(request)) return null;

    const expressions = try alloc.alloc(algebraic_segment.ExpressionSpec, request.aggregations.len);
    errdefer alloc.free(expressions);
    var initialized: usize = 0;
    errdefer {
        for (expressions[0..initialized]) |expression| {
            alloc.free(expression.name);
            if (expression.value_column.len != 0) alloc.free(expression.value_column);
        }
    }

    for (request.aggregations, expressions) |aggregation, *out| {
        out.* = .{
            .name = try alloc.dupe(u8, aggregation.name),
            .value_column = if (aggregation.field) |field| try alloc.dupe(u8, field) else &.{},
            .op = try lakeRowsAggregateOpToAlgebraicOp(aggregation),
        };
        initialized += 1;
    }

    return .{
        .request = .{ .expressions = expressions },
        .expressions = expressions,
    };
}

pub fn buildRowsAggregateResultFromLakeRowsExpressionAggregatesAlloc(
    alloc: std.mem.Allocator,
    request: OwnedRowsAggregateRequest,
    result: lake_rows.ExpressionAggregateResult,
) !OwnedRowsAggregateResult {
    if (!lakeRowsExpressionAggregateFastPathSupported(request)) return error.UnsupportedRowsQuery;

    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.writeByte('{');
    for (request.aggregations, 0..) |aggregation, i| {
        if (i != 0) try writer.writeByte(',');
        try writer.print("{f}:", .{std.json.fmt(aggregation.name, .{})});
        const value = result.find(aggregation.name) orelse return error.InvalidRowsRequest;
        try writeLakeExpressionAggregateValueJson(writer, aggregation, value);
    }
    try writer.writeByte('}');

    const rows = try alloc.alloc([]const u8, 1);
    errdefer alloc.free(rows);
    rows[0] = try out.toOwnedSlice();
    return .{ .rows = rows, .total_groups = 1 };
}

pub fn buildRowsAggregateResultFromLakeRowsAlloc(
    alloc: std.mem.Allocator,
    request: OwnedRowsAggregateRequest,
    result: lake_rows.ScanResult,
) !OwnedRowsAggregateResult {
    try validateLakeRowsAggregateShapeSupported(request);

    const groups = try lakeRowsAggregateGroupsAlloc(alloc, request, result.rows);
    defer freeLakeRowsAggregateGroups(alloc, groups, request.aggregations.len);

    var rows = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (rows.items) |row| alloc.free(@constCast(row));
        rows.deinit(alloc);
    }
    try rows.ensureUnusedCapacity(alloc, groups.len);
    for (groups) |group| {
        const encoded = try lakeRowsAggregateGroupJsonAlloc(alloc, request, group);
        var encoded_transferred = false;
        errdefer if (!encoded_transferred) alloc.free(encoded);
        if (!try lakeRowsAggregateHavingPassesAlloc(alloc, request, encoded)) {
            alloc.free(encoded);
            encoded_transferred = true;
            continue;
        }
        rows.appendAssumeCapacity(encoded);
        encoded_transferred = true;
    }
    if (request.order_by.len > 0) {
        try sortLakeRowsAggregateOutputRowsAlloc(alloc, rows.items, request.order_by);
    } else {
        std.sort.pdq([]const u8, rows.items, {}, lakeRowsAggregateOutputLessThan);
    }

    const total_groups: u32 = @intCast(rows.items.len);
    const start = @min(@as(usize, request.offset), rows.items.len);
    const limited_len: usize = if (request.limit) |limit|
        @min(@as(usize, limit), rows.items.len - start)
    else
        rows.items.len - start;
    if (start > 0 or limited_len < rows.items.len) {
        const kept = try alloc.alloc([]const u8, limited_len);
        @memcpy(kept, rows.items[start .. start + limited_len]);
        for (rows.items[0..start]) |row| alloc.free(@constCast(row));
        for (rows.items[start + limited_len ..]) |row| alloc.free(@constCast(row));
        rows.deinit(alloc);
        return .{
            .rows = kept,
            .total_groups = total_groups,
        };
    }
    return .{
        .rows = try rows.toOwnedSlice(alloc),
        .total_groups = total_groups,
    };
}

fn lakeRowsExpressionAggregateFastPathSupported(request: OwnedRowsAggregateRequest) bool {
    if (request.group_by.len != 0 or request.group_expressions.len != 0) return false;
    if (request.having_predicates.len != 0 or request.having_expressions.len != 0 or request.having_any.len != 0 or request.having_not.len != 0) return false;
    if (request.order_by.len != 0 or request.offset != 0) return false;
    if (request.limit != null and request.limit.? == 0) return false;
    if (!lakeRowsExpressionAggregateSourceFastPathSupported(request.source)) return false;
    if (request.aggregations.len == 0) return false;

    var has_value_aggregate = false;
    for (request.aggregations) |aggregation| {
        if (aggregation.name.len == 0) return false;
        if (aggregation.distinct) return false;
        if (aggregation.expression != null) return false;
        if (aggregation.array_order_by.len != 0 or aggregation.string_delimiter != null) return false;
        if (aggregation.filter_predicates.len != 0 or
            aggregation.filter_array_any.len != 0 or
            aggregation.filter_array_contains.len != 0 or
            aggregation.filter_array_eq.len != 0 or
            aggregation.filter_in_predicates.len != 0 or
            aggregation.filter_json_contains.len != 0 or
            aggregation.filter_json_path_eq.len != 0 or
            aggregation.filter_json_path_exists.len != 0 or
            aggregation.filter_text_patterns.len != 0 or
            aggregation.filter_expressions.len != 0 or
            aggregation.filter_expression_array_contains.len != 0 or
            aggregation.filter_any.len != 0 or
            aggregation.filter_not.len != 0) return false;
        switch (aggregation.op) {
            .count => if (aggregation.field != null) return false,
            .sum, .min, .max, .avg => {
                if (aggregation.field == null) return false;
                has_value_aggregate = true;
            },
            else => return false,
        }
    }
    return has_value_aggregate;
}

fn lakeRowsExpressionAggregateSourceFastPathSupported(source: db_mod.types.RelationalRowsQueryRequest) bool {
    return source.source_cte.len == 0 and
        source.row_claim == null and
        source.doc_key_range == null and
        source.limit == null and
        source.offset == 0 and
        source.select_all and
        source.select.len == 0 and
        source.order_by.len == 0 and
        source.distinct_on.len == 0 and
        source.distinct_on_expressions.len == 0 and
        source.json_extract.len == 0 and
        source.array_length.len == 0 and
        source.coalesce.len == 0 and
        source.field_aliases.len == 0 and
        source.expressions.len == 0 and
        source.predicates.len == 0 and
        source.array_any.len == 0 and
        source.array_contains.len == 0 and
        source.array_eq.len == 0 and
        source.in_predicates.len == 0 and
        source.json_contains.len == 0 and
        source.json_path_eq.len == 0 and
        source.json_path_exists.len == 0 and
        source.or_predicates.len == 0 and
        source.not_predicates.len == 0 and
        source.access_or_predicates.len == 0 and
        source.access_not_predicates.len == 0 and
        source.text_patterns.len == 0 and
        source.expression_predicates.len == 0 and
        source.expression_or_predicates.len == 0 and
        source.expression_not_predicates.len == 0 and
        source.expression_array_contains.len == 0;
}

fn lakeRowsAggregateOpToAlgebraicOp(aggregation: db_mod.types.RelationalRowsAggregateSpec) !algebraic_segment.AggregateOp {
    return switch (aggregation.op) {
        .count => .count,
        .sum => .sum_i64,
        .min => .min_i64,
        .max => .max_i64,
        .avg => .avg_i64,
        else => error.UnsupportedRowsQuery,
    };
}

fn writeLakeExpressionAggregateValueJson(
    writer: *std.Io.Writer,
    aggregation: db_mod.types.RelationalRowsAggregateSpec,
    value: algebraic_segment.AggregateValue,
) !void {
    switch (aggregation.op) {
        .count => try writer.print("{d}", .{value.count}),
        .sum => try writer.print("{d}", .{value.sum_i64}),
        .min => try writer.print("{d}", .{value.min_i64}),
        .max => try writer.print("{d}", .{value.max_i64}),
        .avg => {
            if (value.avg_i64.count == 0) {
                try writer.writeAll("null");
            } else {
                try std.json.Stringify.value(@as(f64, @floatFromInt(value.avg_i64.sum_i64)) / @as(f64, @floatFromInt(value.avg_i64.count)), .{}, writer);
            }
        },
        else => return error.UnsupportedRowsQuery,
    }
}

fn lakeRowsAggregateHavingPassesAlloc(
    alloc: std.mem.Allocator,
    request: OwnedRowsAggregateRequest,
    row_json: []const u8,
) !bool {
    if (request.having_predicates.len == 0 and
        request.having_expressions.len == 0 and
        request.having_any.len == 0 and
        request.having_not.len == 0) return true;
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidRowsRequest;
    for (request.having_predicates) |predicate| {
        if (!try relationalCheckPasses(alloc, parsed.value, predicate)) return false;
    }
    for (request.having_expressions) |condition| {
        if (!try expressionConditionMatches(alloc, parsed.value, condition)) return false;
    }
    if (!try queryExpressionOrPredicateGroupsPass(alloc, parsed.value, request.having_any)) return false;
    if (!try queryExpressionNotPredicateGroupsPass(alloc, parsed.value, request.having_not)) return false;
    return true;
}

const LakeAggregateOutputOrderCandidate = struct {
    index: usize,
    order_keys: []QueryOrderKey = &.{},
    ordinal: usize,

    fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        freeQueryOrderKeySlice(alloc, self.order_keys);
        self.* = undefined;
    }
};

fn sortLakeRowsAggregateOutputRowsAlloc(
    alloc: std.mem.Allocator,
    rows: [][]const u8,
    order_by: []const RowsQueryOrder,
) !void {
    if (order_by.len == 0 or rows.len <= 1) return;

    const candidates = try alloc.alloc(LakeAggregateOutputOrderCandidate, rows.len);
    var initialized: usize = 0;
    defer {
        for (candidates[0..initialized]) |*candidate| candidate.deinit(alloc);
        alloc.free(candidates);
    }
    for (rows, 0..) |row_json, i| {
        var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidRowsRequest;
        defer parsed.deinit();
        if (parsed.value != .object) return error.InvalidRowsRequest;
        candidates[i] = .{
            .index = i,
            .order_keys = try queryOrderKeysAlloc(alloc, parsed.value, order_by),
            .ordinal = i,
        };
        initialized += 1;
    }
    std.sort.pdq(LakeAggregateOutputOrderCandidate, candidates, QuerySortContext{ .order_by = order_by }, lakeRowsAggregateOutputOrderCandidateLessThan);

    const ordered = try alloc.alloc([]const u8, rows.len);
    defer alloc.free(ordered);
    for (candidates, 0..) |candidate, i| ordered[i] = rows[candidate.index];
    @memcpy(rows, ordered);
}

fn lakeRowsAggregateOutputOrderCandidateLessThan(
    ctx: QuerySortContext,
    lhs: LakeAggregateOutputOrderCandidate,
    rhs: LakeAggregateOutputOrderCandidate,
) bool {
    for (ctx.order_by, 0..) |order, i| {
        const comparison = compareQueryOrderKeysWithCollation(lhs.order_keys[i], rhs.order_keys[i], order.collation);
        if (comparison == .eq) continue;
        return switch (order.direction) {
            .asc => comparison == .lt,
            .desc => comparison == .gt,
        };
    }
    return lhs.ordinal < rhs.ordinal;
}

fn lakeRowsAggregateOutputLessThan(_: void, lhs: []const u8, rhs: []const u8) bool {
    return std.mem.order(u8, lhs, rhs) == .lt;
}

fn lakeRowsProjectedColumnsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    request: OwnedRowsQueryRequest,
) ![]const []const u8 {
    if (request.select_all) {
        if (schema.relational_columns.len == 0) return error.InvalidRowsRequest;
        var columns = std.ArrayListUnmanaged([]const u8).empty;
        errdefer freeLakeProjectedColumnList(alloc, &columns);
        for (schema.relational_columns) |column| {
            try appendLakeProjectedColumnAlloc(alloc, &columns, column.name);
        }
        return try columns.toOwnedSlice(alloc);
    }
    if (request.select.len == 0 and request.json_extract.len == 0 and request.array_length.len == 0 and request.coalesce.len == 0 and request.field_aliases.len == 0 and request.expressions.len == 0) return error.InvalidRowsRequest;
    var columns = std.ArrayListUnmanaged([]const u8).empty;
    errdefer freeLakeProjectedColumnList(alloc, &columns);
    for (request.select) |field| {
        const column = findRelationalColumn(schema.relational_columns, field) orelse return error.InvalidRowsRequest;
        try appendLakeProjectedColumnAlloc(alloc, &columns, column.name);
    }
    for (request.order_by) |order| {
        if (order.expression) |expression| {
            try appendLakeRowsExpressionProjectedColumnsAlloc(alloc, &columns, expression);
        } else {
            const column = findRelationalColumn(schema.relational_columns, order.field) orelse return error.InvalidRowsRequest;
            try appendLakeProjectedColumnAlloc(alloc, &columns, column.name);
        }
    }
    if (request.doc_key_range != null) {
        if (schema.primary_key) |primary_key| {
            for (primary_key.columns) |column_name| {
                const column = findRelationalColumn(schema.relational_columns, column_name) orelse return error.InvalidRowsRequest;
                try appendLakeProjectedColumnAlloc(alloc, &columns, column.name);
            }
            if (primary_key.without_overlaps_period) |period_name| {
                const period = findRelationalPeriod(schema.periods, period_name) orelse return error.InvalidRowsRequest;
                try appendLakeProjectedColumnAlloc(alloc, &columns, period.start_column);
                try appendLakeProjectedColumnAlloc(alloc, &columns, period.end_column);
            }
        }
    }
    for (request.distinct_on) |field| {
        const column = findRelationalColumn(schema.relational_columns, field) orelse return error.InvalidRowsRequest;
        try appendLakeProjectedColumnAlloc(alloc, &columns, column.name);
    }
    for (request.distinct_on_expressions) |expression| {
        try appendLakeRowsExpressionProjectedColumnsAlloc(alloc, &columns, expression);
    }
    if (lakeRowsQueryHasResidualPredicates(request)) {
        for (request.predicates) |predicate| {
            try appendLakeProjectedColumnAlloc(alloc, &columns, predicate.field);
        }
    }
    try appendLakeRowsQueryPredicateGroupsProjectedColumnsAlloc(alloc, &columns, request);
    for (request.array_any) |predicate| {
        try appendLakeProjectedColumnAlloc(alloc, &columns, predicate.field);
    }
    for (request.array_contains) |predicate| {
        try appendLakeProjectedColumnAlloc(alloc, &columns, predicate.field);
    }
    for (request.array_eq) |predicate| {
        try appendLakeProjectedColumnAlloc(alloc, &columns, predicate.field);
    }
    for (request.in_predicates) |predicate| {
        try appendLakeProjectedColumnAlloc(alloc, &columns, predicate.field);
    }
    for (request.json_contains) |predicate| {
        try appendLakeProjectedColumnAlloc(alloc, &columns, predicate.field);
    }
    for (request.json_path_eq) |predicate| {
        try appendLakeProjectedColumnAlloc(alloc, &columns, predicate.field);
    }
    for (request.json_path_exists) |predicate| {
        try appendLakeProjectedColumnAlloc(alloc, &columns, predicate.field);
    }
    for (request.text_patterns) |predicate| {
        try appendLakeProjectedColumnAlloc(alloc, &columns, predicate.field);
    }
    for (request.json_extract) |projection| {
        try appendLakeProjectedColumnAlloc(alloc, &columns, projection.field);
    }
    for (request.array_length) |projection| {
        try appendLakeProjectedColumnAlloc(alloc, &columns, projection.field);
    }
    for (request.field_aliases) |projection| {
        try appendLakeProjectedColumnAlloc(alloc, &columns, projection.field);
    }
    for (request.coalesce) |projection| {
        for (projection.operands) |operand| {
            if (operand.kind == .field) try appendLakeProjectedColumnAlloc(alloc, &columns, operand.field);
        }
    }
    for (request.expression_predicates) |condition| {
        try appendLakeRowsExpressionConditionProjectedColumnsAlloc(alloc, &columns, condition);
    }
    for (request.expression_array_contains) |predicate| {
        try appendLakeRowsExpressionProjectedColumnsAlloc(alloc, &columns, predicate.expression);
    }
    for (request.expressions) |projection| {
        try appendLakeRowsExpressionProjectedColumnsAlloc(alloc, &columns, projection.expression);
    }
    return try columns.toOwnedSlice(alloc);
}

fn validateLakeRowsQueryPredicateGroupsSupported(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    request: OwnedRowsQueryRequest,
) !void {
    for (request.or_predicates) |group| try validateLakeRowsQueryPredicateGroupSupported(schema, group);
    for (request.not_predicates) |group| try validateLakeRowsQueryPredicateGroupSupported(schema, group);
    for (request.access_or_predicates) |group| try validateLakeRowsQueryAccessPredicateGroupSupported(schema, group);
    for (request.access_not_predicates) |group| try validateLakeRowsQueryAccessPredicateGroupSupported(schema, group);
    for (request.expression_or_predicates) |group| try validateLakeRowsQueryExpressionPredicateGroupSupported(alloc, schema, group);
    for (request.expression_not_predicates) |group| try validateLakeRowsQueryExpressionPredicateGroupSupported(alloc, schema, group);
}

