fn validateLakeRowsAggregateRequestSupported(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    request: OwnedRowsAggregateRequest,
) !void {
    if (schema.storage_mode != .relational) return error.InvalidRowsRequest;
    try validateLakeRowsAggregateShapeSupported(request);
    for (request.group_by) |field| {
        const column = findRelationalColumn(schema.relational_columns, field) orelse return error.InvalidRowsRequest;
        switch (column.field_type) {
            .embedding => return error.UnsupportedRowsQuery,
            else => {},
        }
    }
    for (request.group_expressions) |projection| {
        if (projection.output.len == 0) return error.InvalidRowsRequest;
        const output_type = try rowsExpressionOutputType(alloc, schema, projection.expression);
        if (output_type == .embedding) return error.UnsupportedRowsQuery;
    }
    for (request.aggregations) |aggregation| {
        switch (aggregation.op) {
            .count => {
                if (aggregation.field) |field| {
                    _ = findRelationalColumn(schema.relational_columns, field) orelse return error.InvalidRowsRequest;
                }
                if (aggregation.expression) |expression| {
                    _ = try rowsExpressionOutputType(alloc, schema, expression);
                }
            },
            .sum, .avg => {
                if (aggregation.field) |field| {
                    const column = findRelationalColumn(schema.relational_columns, field) orelse return error.InvalidRowsRequest;
                    if (column.field_type != .numeric) return error.InvalidRowsRequest;
                } else if (aggregation.expression) |expression| {
                    try validateRowsQueryNumericExpression(alloc, schema, expression);
                } else return error.InvalidRowsRequest;
            },
            .min, .max => {
                if (aggregation.field) |field| {
                    const column = findRelationalColumn(schema.relational_columns, field) orelse return error.InvalidRowsRequest;
                    if (column.field_type != .numeric and column.field_type != .datetime) return error.InvalidRowsRequest;
                } else if (aggregation.expression) |expression| {
                    try validateRowsAggregateMinMaxExpressionInput(alloc, schema, expression);
                } else return error.InvalidRowsRequest;
            },
            else => return error.UnsupportedRowsQuery,
        }
        for (aggregation.filter_predicates) |predicate| {
            const column = findRelationalColumn(schema.relational_columns, predicate.field) orelse return error.InvalidRowsRequest;
            switch (column.field_type) {
                .embedding, .json, .array => return error.UnsupportedRowsQuery,
                else => {},
            }
        }
        for (aggregation.filter_in_predicates) |predicate| {
            const column = findRelationalColumn(schema.relational_columns, predicate.field) orelse return error.InvalidRowsRequest;
            switch (column.field_type) {
                .embedding, .json, .array => return error.UnsupportedRowsQuery,
                else => {},
            }
            var values = std.json.parseFromSlice(std.json.Value, alloc, predicate.values_json, .{}) catch return error.InvalidRowsRequest;
            defer values.deinit();
            if (values.value != .array) return error.InvalidRowsRequest;
            for (values.value.array.items) |item| {
                if (!rowsScalarValueMatches(column.field_type, item)) return error.InvalidRowsRequest;
            }
        }
        for (aggregation.filter_array_any) |predicate| {
            const column = findRelationalColumn(schema.relational_columns, predicate.field) orelse return error.InvalidRowsRequest;
            if (column.field_type != .array) return error.InvalidRowsRequest;
        }
        for (aggregation.filter_array_contains) |predicate| {
            const column = findRelationalColumn(schema.relational_columns, predicate.field) orelse return error.InvalidRowsRequest;
            if (column.field_type != .array) return error.InvalidRowsRequest;
        }
        for (aggregation.filter_array_eq) |predicate| {
            const column = findRelationalColumn(schema.relational_columns, predicate.field) orelse return error.InvalidRowsRequest;
            if (column.field_type != .array) return error.InvalidRowsRequest;
        }
        for (aggregation.filter_text_patterns) |predicate| {
            const column = findRelationalColumn(schema.relational_columns, predicate.field) orelse return error.InvalidRowsRequest;
            if (column.field_type != .keyword and column.field_type != .text and column.field_type != .link) return error.InvalidRowsRequest;
        }
        for (aggregation.filter_json_contains) |predicate| {
            const column = findRelationalColumn(schema.relational_columns, predicate.field) orelse return error.InvalidRowsRequest;
            if (column.field_type != .json) return error.InvalidRowsRequest;
        }
        for (aggregation.filter_json_path_eq) |predicate| {
            const column = findRelationalColumn(schema.relational_columns, predicate.field) orelse return error.InvalidRowsRequest;
            if (column.field_type != .json) return error.InvalidRowsRequest;
        }
        for (aggregation.filter_json_path_exists) |predicate| {
            const column = findRelationalColumn(schema.relational_columns, predicate.field) orelse return error.InvalidRowsRequest;
            if (column.field_type != .json) return error.InvalidRowsRequest;
        }
        for (aggregation.filter_expressions) |condition| {
            try validateRowsExpressionConditionTypes(alloc, schema, condition.lhs, condition.op, condition.rhs);
        }
        for (aggregation.filter_expression_array_contains) |predicate| {
            if ((try rowsExpressionOutputType(alloc, schema, predicate.expression)) != .array) return error.InvalidRowsRequest;
            var values = std.json.parseFromSlice(std.json.Value, alloc, predicate.value_json, .{}) catch return error.InvalidRowsRequest;
            defer values.deinit();
            if (values.value != .array) return error.InvalidRowsRequest;
            try validateRowsStringArrayValue(values.value);
        }
    }
    if (request.source.predicates.len == 1) {
        const predicate = request.source.predicates[0];
        _ = findRelationalColumn(schema.relational_columns, predicate.field) orelse return error.InvalidRowsRequest;
    }
}

fn validateLakeRowsAggregateShapeSupported(request: OwnedRowsAggregateRequest) !void {
    try validateLakeRowsAggregateSourceSupported(request.source);
    if (request.aggregations.len == 0 and request.group_by.len == 0 and request.group_expressions.len == 0) return error.InvalidRowsRequest;
    for (request.aggregations) |aggregation| {
        if (aggregation.name.len == 0) return error.InvalidRowsRequest;
        if (aggregation.distinct) return error.UnsupportedRowsQuery;
        if (aggregation.field != null and aggregation.expression != null) return error.InvalidRowsRequest;
        if (aggregation.array_order_by.len != 0 or aggregation.string_delimiter != null) return error.UnsupportedRowsQuery;
        if (aggregation.filter_any.len != 0 or aggregation.filter_not.len != 0) return error.UnsupportedRowsQuery;
        switch (aggregation.op) {
            .count => {},
            .sum, .min, .max, .avg => if (aggregation.field == null and aggregation.expression == null) return error.InvalidRowsRequest,
            else => return error.UnsupportedRowsQuery,
        }
    }
}

fn validateLakeRowsAggregateSourceSupported(source: OwnedRowsQueryRequest) !void {
    if (source.source_cte.len != 0) return error.UnsupportedRowsQuery;
    if (source.row_claim != null) return error.UnsupportedRowsQuery;
    if (source.doc_key_range != null) return error.UnsupportedRowsQuery;
    if (source.limit != null or source.offset != 0) return error.UnsupportedRowsQuery;
    if (!source.select_all or source.select.len != 0) return error.UnsupportedRowsQuery;
    if (source.order_by.len != 0) return error.UnsupportedRowsQuery;
    if (source.distinct_on.len != 0 or source.distinct_on_expressions.len != 0) return error.UnsupportedRowsQuery;
    if (source.json_extract.len != 0 or source.array_length.len != 0 or source.coalesce.len != 0 or source.field_aliases.len != 0 or source.expressions.len != 0) return error.UnsupportedRowsQuery;
    if (source.array_any.len != 0 or source.array_contains.len != 0 or source.array_eq.len != 0 or source.in_predicates.len != 0) return error.UnsupportedRowsQuery;
    if (source.json_contains.len != 0 or source.json_path_eq.len != 0 or source.json_path_exists.len != 0) return error.UnsupportedRowsQuery;
    if (source.or_predicates.len != 0 or source.not_predicates.len != 0 or source.access_or_predicates.len != 0 or source.access_not_predicates.len != 0) return error.UnsupportedRowsQuery;
    if (source.expression_predicates.len != 0 or source.expression_or_predicates.len != 0 or source.expression_not_predicates.len != 0 or source.expression_array_contains.len != 0) return error.UnsupportedRowsQuery;
    if (source.predicates.len > 1) return error.UnsupportedRowsQuery;
    if (source.predicates.len == 1 and source.predicates[0].op != .eq) return error.UnsupportedRowsQuery;
}

fn lakeRowsAggregateProjectedColumnsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    request: OwnedRowsAggregateRequest,
) ![]const []const u8 {
    var columns = std.ArrayListUnmanaged([]const u8).empty;
    errdefer freeLakeProjectedColumnList(alloc, &columns);

    if (lakeRowsQueryHasResidualPredicates(request.source)) {
        for (request.source.predicates) |predicate| {
            try appendLakeProjectedColumnAlloc(alloc, &columns, predicate.field);
        }
    }
    for (request.source.text_patterns) |predicate| {
        try appendLakeProjectedColumnAlloc(alloc, &columns, predicate.field);
    }
    for (request.group_by) |field| {
        try appendLakeProjectedColumnAlloc(alloc, &columns, field);
    }
    for (request.group_expressions) |projection| {
        try appendLakeRowsExpressionProjectedColumnsAlloc(alloc, &columns, projection.expression);
    }
    for (request.aggregations) |aggregation| {
        if (aggregation.field) |field| try appendLakeProjectedColumnAlloc(alloc, &columns, field);
        if (aggregation.expression) |expression| try appendLakeRowsExpressionProjectedColumnsAlloc(alloc, &columns, expression);
        for (aggregation.filter_predicates) |predicate| {
            try appendLakeProjectedColumnAlloc(alloc, &columns, predicate.field);
        }
        for (aggregation.filter_in_predicates) |predicate| {
            try appendLakeProjectedColumnAlloc(alloc, &columns, predicate.field);
        }
        for (aggregation.filter_array_any) |predicate| {
            try appendLakeProjectedColumnAlloc(alloc, &columns, predicate.field);
        }
        for (aggregation.filter_array_contains) |predicate| {
            try appendLakeProjectedColumnAlloc(alloc, &columns, predicate.field);
        }
        for (aggregation.filter_array_eq) |predicate| {
            try appendLakeProjectedColumnAlloc(alloc, &columns, predicate.field);
        }
        for (aggregation.filter_text_patterns) |predicate| {
            try appendLakeProjectedColumnAlloc(alloc, &columns, predicate.field);
        }
        for (aggregation.filter_json_contains) |predicate| {
            try appendLakeProjectedColumnAlloc(alloc, &columns, predicate.field);
        }
        for (aggregation.filter_json_path_eq) |predicate| {
            try appendLakeProjectedColumnAlloc(alloc, &columns, predicate.field);
        }
        for (aggregation.filter_json_path_exists) |predicate| {
            try appendLakeProjectedColumnAlloc(alloc, &columns, predicate.field);
        }
        for (aggregation.filter_expressions) |condition| {
            try appendLakeRowsExpressionConditionProjectedColumnsAlloc(alloc, &columns, condition);
        }
        for (aggregation.filter_expression_array_contains) |predicate| {
            try appendLakeRowsExpressionProjectedColumnsAlloc(alloc, &columns, predicate.expression);
        }
    }
    if (request.source.predicates.len == 1) {
        try appendLakeProjectedColumnAlloc(alloc, &columns, request.source.predicates[0].field);
    }
    if (columns.items.len == 0) {
        if (schema.relational_columns.len == 0) return error.InvalidRowsRequest;
        try appendLakeProjectedColumnAlloc(alloc, &columns, schema.relational_columns[0].name);
    }
    return try columns.toOwnedSlice(alloc);
}

fn appendLakeRowsExpressionProjectedColumnsAlloc(
    alloc: std.mem.Allocator,
    columns: *std.ArrayListUnmanaged([]const u8),
    expression: db_mod.types.RelationalRowsExpression,
) anyerror!void {
    if (expression.kind == .field) {
        if (expression.field_source != .row and expression.field_source != .existing) return error.UnsupportedRowsQuery;
        try appendLakeProjectedColumnAlloc(alloc, columns, expression.field);
    }
    for (expression.operands) |operand| {
        try appendLakeRowsExpressionProjectedColumnsAlloc(alloc, columns, operand);
    }
    for (expression.case_branches) |branch| {
        try appendLakeRowsExpressionConditionProjectedColumnsAlloc(alloc, columns, branch.when);
        try appendLakeRowsExpressionProjectedColumnsAlloc(alloc, columns, branch.then);
    }
    for (expression.case_else) |fallback| {
        try appendLakeRowsExpressionProjectedColumnsAlloc(alloc, columns, fallback);
    }
}

fn appendLakeRowsExpressionConditionProjectedColumnsAlloc(
    alloc: std.mem.Allocator,
    columns: *std.ArrayListUnmanaged([]const u8),
    condition: db_mod.types.RelationalRowsExpressionCondition,
) anyerror!void {
    try appendLakeRowsExpressionProjectedColumnsAlloc(alloc, columns, condition.lhs);
    for (condition.rhs) |rhs| {
        try appendLakeRowsExpressionProjectedColumnsAlloc(alloc, columns, rhs);
    }
}

fn appendLakeProjectedColumnAlloc(
    alloc: std.mem.Allocator,
    columns: *std.ArrayListUnmanaged([]const u8),
    field: []const u8,
) !void {
    if (field.len == 0) return error.InvalidRowsRequest;
    for (columns.items) |existing| {
        if (std.mem.eql(u8, existing, field)) return;
    }
    const owned = try alloc.dupe(u8, field);
    errdefer alloc.free(owned);
    try columns.append(alloc, owned);
}

fn freeLakeProjectedColumns(alloc: std.mem.Allocator, columns: []const []const u8) void {
    for (columns) |column| alloc.free(@constCast(column));
    if (columns.len > 0) alloc.free(columns);
}

fn freeLakeProjectedColumnList(
    alloc: std.mem.Allocator,
    columns: *std.ArrayListUnmanaged([]const u8),
) void {
    for (columns.items) |column| alloc.free(@constCast(column));
    columns.deinit(alloc);
}

fn lakeRowsPredicateFromRowsPredicateAlloc(
    alloc: std.mem.Allocator,
    column: runtime_schema.RelationalColumn,
    field: []const u8,
    value_json: []const u8,
    predicate_bytes_value: *?[]const u8,
) !lake_rows.Predicate {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, value_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    return switch (column.field_type) {
        .numeric => try lakeRowsNumericPredicateFromJson(column, field, parsed.value),
        .datetime => .{
            .column = field,
            .op = .eq_i64,
            .i64_value = try jsonValueAsI64(parsed.value),
        },
        .boolean => .{
            .column = field,
            .op = .eq_bool,
            .bool_value = switch (parsed.value) {
                .bool => |value| value,
                else => return error.InvalidRowsRequest,
            },
        },
        .keyword, .text, .blob, .html, .search_as_you_type => pred_blk: {
            const value = switch (parsed.value) {
                .string => |text| try alloc.dupe(u8, text),
                else => return error.InvalidRowsRequest,
            };
            predicate_bytes_value.* = value;
            break :pred_blk .{
                .column = field,
                .op = .eq_bytes,
                .bytes_value = value,
            };
        },
        .json => pred_blk: {
            const value = try alloc.dupe(u8, value_json);
            predicate_bytes_value.* = value;
            break :pred_blk .{
                .column = field,
                .op = .eq_bytes,
                .bytes_value = value,
            };
        },
        else => return error.UnsupportedRowsQuery,
    };
}

fn lakeRowsNumericPredicateFromJson(
    column: runtime_schema.RelationalColumn,
    field: []const u8,
    value: std.json.Value,
) !lake_rows.Predicate {
    return switch (value) {
        .integer => |number| .{
            .column = field,
            .op = .eq_i64,
            .i64_value = number,
        },
        .float => |number| {
            if (!std.math.isFinite(number)) return error.InvalidRowsRequest;
            return .{
                .column = field,
                .op = .eq_f64,
                .f64_value = number,
            };
        },
        else => switch (column.field_type) {
            .numeric => error.InvalidRowsRequest,
            else => error.UnsupportedRowsQuery,
        },
    };
}

fn jsonValueAsI64(value: std.json.Value) !i64 {
    return switch (value) {
        .integer => |number| number,
        .float => |number| if (@trunc(number) == number and number >= @as(f64, @floatFromInt(std.math.minInt(i64))) and number <= @as(f64, @floatFromInt(std.math.maxInt(i64))))
            @intFromFloat(number)
        else
            error.InvalidRowsRequest,
        else => error.InvalidRowsRequest,
    };
}

fn lakeProjectedRowJsonAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
) ![]u8 {
    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.writeByte('{');
    for (row.cells, 0..) |cell, i| {
        if (i != 0) try writer.writeByte(',');
        try writer.print("{f}:", .{std.json.fmt(cell.name, .{})});
        try writeLakeRowsCellJson(writer, cell.value);
    }
    try writer.writeByte('}');
    return try out.toOwnedSlice();
}

fn lakeProjectedRowQueryJsonAlloc(
    alloc: std.mem.Allocator,
    request: OwnedRowsQueryRequest,
    row: lake_rows.ProjectedRow,
) ![]u8 {
    if (request.select_all and request.json_extract.len == 0 and request.array_length.len == 0 and request.coalesce.len == 0 and request.field_aliases.len == 0 and request.expressions.len == 0) return try lakeProjectedRowJsonAlloc(alloc, row);
    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.writeByte('{');
    var first = true;
    if (request.select_all) {
        for (row.cells) |cell| {
            if (!first) try writer.writeByte(',');
            first = false;
            try writer.print("{f}:", .{std.json.fmt(cell.name, .{})});
            try writeLakeRowsCellJson(writer, cell.value);
        }
    } else {
        for (request.select) |field| {
            if (!first) try writer.writeByte(',');
            first = false;
            const cell = row.find(field) orelse return error.InvalidLakeRowsQuery;
            try writer.print("{f}:", .{std.json.fmt(field, .{})});
            try writeLakeRowsCellJson(writer, cell.value);
        }
    }
    for (request.json_extract) |projection| {
        if (!first) try writer.writeByte(',');
        first = false;
        try writer.print("{f}:", .{std.json.fmt(projection.output, .{})});
        try writeLakeRowsJsonExtractProjectionValueAlloc(alloc, writer, row, projection);
    }
    for (request.array_length) |projection| {
        if (!first) try writer.writeByte(',');
        first = false;
        try writer.print("{f}:", .{std.json.fmt(projection.output, .{})});
        try writeLakeRowsArrayLengthProjectionValueAlloc(alloc, writer, row, projection);
    }
    for (request.coalesce) |projection| {
        if (!first) try writer.writeByte(',');
        first = false;
        try writer.print("{f}:", .{std.json.fmt(projection.output, .{})});
        try writeLakeRowsCoalesceProjectionValueAlloc(alloc, writer, row, projection);
    }
    for (request.field_aliases) |projection| {
        if (!first) try writer.writeByte(',');
        first = false;
        try writer.print("{f}:", .{std.json.fmt(projection.output, .{})});
        const cell = row.find(projection.field) orelse return error.RowSourceColumnNotFound;
        try writeLakeRowsCellJson(writer, cell.value);
    }
    for (request.expressions) |projection| {
        if (queryProjectionOutputAlreadyRendered(request, projection.output)) continue;
        if (!first) try writer.writeByte(',');
        first = false;
        try writer.print("{f}:", .{std.json.fmt(projection.output, .{})});
        try writeLakeRowsExpressionProjectionValueJsonAlloc(alloc, writer, row, projection.expression);
    }
    try writer.writeByte('}');
    return try out.toOwnedSlice();
}

fn lakeProjectedRowInDocKeyRangeAlloc(
    alloc: std.mem.Allocator,
    maybe_schema: ?runtime_schema.TableSchema,
    row: lake_rows.ProjectedRow,
    maybe_range: ?db_mod.types.RelationalRowsDocKeyRange,
) !bool {
    const range = maybe_range orelse return true;
    const key = try lakeProjectedRowDocKeyAlloc(alloc, maybe_schema, row);
    defer alloc.free(key);
    if (range.start.len > 0 and std.mem.order(u8, key, range.start) == .lt) return false;
    if (range.end.len > 0 and std.mem.order(u8, key, range.end) != .lt) return false;
    return true;
}

fn lakeProjectedRowDocKeyAlloc(
    alloc: std.mem.Allocator,
    maybe_schema: ?runtime_schema.TableSchema,
    row: lake_rows.ProjectedRow,
) ![]u8 {
    if (maybe_schema) |schema| {
        if (schema.primary_key != null) {
            const row_json = try lakeProjectedRowJsonAlloc(alloc, row);
            defer alloc.free(row_json);
            return try physicalPrimaryKeyFromRowJsonAlloc(alloc, schema, row_json);
        }
    }
    return switch (row.row_ref) {
        .relational_key => |key| try alloc.dupe(u8, key),
        .serverless, .external => error.InvalidRowsRequest,
    };
}

fn writeLakeRowsExpressionProjectionValueJsonAlloc(
    alloc: std.mem.Allocator,
    writer: *std.Io.Writer,
    row: lake_rows.ProjectedRow,
    expression: db_mod.types.RelationalRowsExpression,
) !void {
    const value_json = try lakeRowsExpressionValueJsonAlloc(alloc, row, expression);
    defer alloc.free(value_json);
    try writer.writeAll(value_json);
}

fn lakeRowsExpressionValueJsonAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    expression: db_mod.types.RelationalRowsExpression,
) ![]u8 {
    switch (try lakeRowsTypedNumericExpressionAlloc(alloc, row, expression)) {
        .unsupported => {},
        .null => return try alloc.dupe(u8, "null"),
        .i64 => |number| return try std.fmt.allocPrint(alloc, "{d}", .{number}),
        .f64 => |number| return try std.json.Stringify.valueAlloc(alloc, number, .{}),
    }
    if (try lakeRowsJsonExtractExpressionValueJsonAlloc(alloc, row, expression)) |value_json| return value_json;
    const row_json = try lakeProjectedRowJsonAlloc(alloc, row);
    defer alloc.free(row_json);
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    return try expressionValueJsonAlloc(alloc, parsed.value, expression);
}

fn writeLakeRowsJsonExtractProjectionValueAlloc(
    alloc: std.mem.Allocator,
    writer: *std.Io.Writer,
    row: lake_rows.ProjectedRow,
    projection: db_mod.types.RelationalRowsJsonExtractProjection,
) !void {
    const maybe_cell = row.find(projection.field) orelse return error.RowSourceColumnNotFound;
    try writeLakeRowsJsonCellExtractValueAlloc(alloc, writer, maybe_cell.value, projection.path, projection.as_text);
}

fn lakeRowsJsonExtractExpressionValueJsonAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    expression: db_mod.types.RelationalRowsExpression,
) !?[]u8 {
    if (expression.kind != .json_extract) return null;
    if (expression.operands.len != 1 or expression.json_path.len == 0) return error.InvalidRowsRequest;
    const source = expression.operands[0];
    if (source.kind != .field) return null;
    if (source.field_source != .row and source.field_source != .existing) return error.UnsupportedRowsQuery;
    const maybe_cell = row.find(source.field) orelse return error.RowSourceColumnNotFound;
    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    try writeLakeRowsJsonCellExtractValueAlloc(alloc, &out.writer, maybe_cell.value, expression.json_path, expression.json_as_text);
    return try out.toOwnedSlice();
}

fn writeLakeRowsJsonCellExtractValueAlloc(
    alloc: std.mem.Allocator,
    writer: *std.Io.Writer,
    maybe_value: ?lake_rows.CellValue,
    path: []const u8,
    as_text: bool,
) !void {
    const value = maybe_value orelse {
        try writer.writeAll("null");
        return;
    };
    const json = switch (value) {
        .json => |bytes| bytes,
        .bytes => |bytes| bytes,
        else => {
            try writer.writeAll("null");
            return;
        },
    };
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    const selected = jsonValueAtPath(parsed.value, path) orelse {
        try writer.writeAll("null");
        return;
    };
    if (!as_text) {
        try std.json.Stringify.value(selected.*, .{}, writer);
        return;
    }
    try writeJsonExtractTextValue(alloc, writer, selected.*);
}

fn writeLakeRowsArrayLengthProjectionValueAlloc(
    alloc: std.mem.Allocator,
    writer: *std.Io.Writer,
    row: lake_rows.ProjectedRow,
    projection: db_mod.types.RelationalRowsArrayLengthProjection,
) !void {
    const maybe_cell = row.find(projection.field) orelse return error.RowSourceColumnNotFound;
    const value = maybe_cell.value orelse {
        try writer.writeAll("null");
        return;
    };
    switch (value) {
        .json => |json| {
            var parsed = std.json.parseFromSlice(std.json.Value, alloc, json, .{}) catch return error.InvalidRowsRequest;
            defer parsed.deinit();
            switch (parsed.value) {
                .null => try writer.writeAll("null"),
                .array => |array| try writer.print("{d}", .{array.items.len}),
                else => return error.InvalidRowsRequest,
            }
        },
        .bytes => |json| {
            var parsed = std.json.parseFromSlice(std.json.Value, alloc, json, .{}) catch return error.InvalidRowsRequest;
            defer parsed.deinit();
            switch (parsed.value) {
                .null => try writer.writeAll("null"),
                .array => |array| try writer.print("{d}", .{array.items.len}),
                else => return error.InvalidRowsRequest,
            }
        },
        .vector_f32 => |values| try writer.print("{d}", .{values.len}),
        else => return error.InvalidRowsRequest,
    }
}

fn writeLakeRowsCoalesceProjectionValueAlloc(
    alloc: std.mem.Allocator,
    writer: *std.Io.Writer,
    row: lake_rows.ProjectedRow,
    projection: db_mod.types.RelationalRowsCoalesceProjection,
) !void {
    for (projection.operands) |operand| {
        switch (operand.kind) {
            .field => {
                const cell = row.find(operand.field) orelse return error.RowSourceColumnNotFound;
                if (cell.value == null) continue;
                try writeLakeRowsCellJson(writer, cell.value);
                return;
            },
            .value => {
                var parsed = std.json.parseFromSlice(std.json.Value, alloc, operand.value_json, .{}) catch return error.InvalidRowsRequest;
                defer parsed.deinit();
                if (parsed.value == .null) continue;
                try std.json.Stringify.value(parsed.value, .{}, writer);
                return;
            },
        }
    }
    try writer.writeAll("null");
}

fn writeLakeRowsCellJson(
    writer: *std.Io.Writer,
    maybe_value: ?lake_rows.CellValue,
) !void {
    const value = maybe_value orelse {
        try writer.writeAll("null");
        return;
    };
    switch (value) {
        .bytes => |bytes| try writer.print("{f}", .{std.json.fmt(bytes, .{})}),
        .json => |json| try writer.writeAll(json),
        .i64 => |number| try writer.print("{d}", .{number}),
        .f64 => |number| try std.json.Stringify.value(number, .{}, writer),
        .bool => |value_bool| try writer.writeAll(if (value_bool) "true" else "false"),
        .vector_f32 => |values| {
            try writer.writeByte('[');
            for (values, 0..) |number, i| {
                if (i != 0) try writer.writeByte(',');
                try std.json.Stringify.value(number, .{}, writer);
            }
            try writer.writeByte(']');
        },
    }
}

const LakeRowsQueryOrderCandidate = struct {
    row: lake_rows.ProjectedRow,
    order_keys: []QueryOrderKey,
    ordinal: usize,
};

fn lakeRowsQueryOrderKeysAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    order_by: []const RowsQueryOrder,
) ![]QueryOrderKey {
    if (order_by.len == 0) return &.{};
    const keys = try alloc.alloc(QueryOrderKey, order_by.len);
    var initialized: usize = 0;
    errdefer {
        freeQueryOrderKeys(alloc, keys[0..initialized]);
        alloc.free(keys);
    }
    for (order_by) |order| {
        keys[initialized] = try lakeRowsQueryOrderKeyAlloc(alloc, row, order);
        initialized += 1;
    }
    return keys;
}

fn lakeRowsQueryOrderKeyAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    order: RowsQueryOrder,
) !QueryOrderKey {
    if (order.expression) |expression| {
        const value_json = try lakeRowsExpressionValueJsonAlloc(alloc, row, expression);
        defer alloc.free(value_json);
        var parsed = std.json.parseFromSlice(std.json.Value, alloc, value_json, .{}) catch return error.InvalidRowsRequest;
        defer parsed.deinit();
        return try queryOrderKeyFromJsonValueAlloc(alloc, parsed.value, order.null_test);
    }
    if (order.field.len == 0) return error.InvalidRowsRequest;
    return try lakeRowsQueryOrderKeyFromCellAlloc(alloc, row.find(order.field), order.null_test);
}

fn lakeRowsQueryOrderKeyFromCellAlloc(
    alloc: std.mem.Allocator,
    maybe_cell: ?lake_rows.ProjectedCell,
    null_test: ?RowsQueryOrderNullTest,
) !QueryOrderKey {
    if (null_test) |test_value| {
        const is_null = if (maybe_cell) |cell| cell.value == null else true;
        return .{ .bool = switch (test_value) {
            .is_null => is_null,
            .is_not_null => !is_null,
        } };
    }
    const cell = maybe_cell orelse return .missing;
    const value = cell.value orelse return .null;
    return switch (value) {
        .bytes => |bytes| .{ .string = try alloc.dupe(u8, bytes) },
        .json => |json| .{ .json = try alloc.dupe(u8, json) },
        .i64 => |number| .{ .number = @floatFromInt(number) },
        .f64 => |number| .{ .number = number },
        .bool => |value_bool| .{ .bool = value_bool },
        .vector_f32 => .missing,
    };
}

fn lakeRowsQueryOrderCandidateLessThan(ctx: QuerySortContext, lhs: LakeRowsQueryOrderCandidate, rhs: LakeRowsQueryOrderCandidate) bool {
    for (ctx.order_by, 0..) |order, i| {
        const comparison = compareQueryOrderKeysWithCollation(lhs.order_keys[i], rhs.order_keys[i], order.collation);
        if (comparison == .eq) continue;
        return switch (order.direction) {
            .asc => comparison == .lt,
            .desc => comparison == .gt,
        };
    }
    return lhs.ordinal < rhs.ordinal;
}

const LakeNumericFold = struct {
    count: u64 = 0,
    sum_i128: i128 = 0,
    sum_f64: f64 = 0,
    min_i64: i64 = 0,
    max_i64: i64 = 0,
    min_f64: f64 = 0,
    max_f64: f64 = 0,
    all_integral: bool = true,

    fn addI64(self: *@This(), value: i64) !void {
        if (self.count == 0) {
            self.min_i64 = value;
            self.max_i64 = value;
            self.min_f64 = @floatFromInt(value);
            self.max_f64 = @floatFromInt(value);
        } else {
            self.min_i64 = @min(self.min_i64, value);
            self.max_i64 = @max(self.max_i64, value);
            const as_float: f64 = @floatFromInt(value);
            self.min_f64 = @min(self.min_f64, as_float);
            self.max_f64 = @max(self.max_f64, as_float);
        }
        self.sum_i128 = try std.math.add(i128, self.sum_i128, @as(i128, value));
        self.sum_f64 += @floatFromInt(value);
        self.count += 1;
    }

    fn addF64(self: *@This(), value: f64) void {
        if (self.count == 0) {
            self.min_f64 = value;
            self.max_f64 = value;
        } else {
            self.min_f64 = @min(self.min_f64, value);
            self.max_f64 = @max(self.max_f64, value);
        }
        self.sum_f64 += value;
        self.count += 1;
        self.all_integral = false;
    }
};

const LakeAggregateFold = struct {
    row_count: u64 = 0,
    non_null_count: u64 = 0,
    numeric: LakeNumericFold = .{},
};

const LakeAggregateGroup = struct {
    key_json: []u8,
    fields_json: []u8,
    folds: []LakeAggregateFold,
};

fn lakeRowsAggregateGroupsAlloc(
    alloc: std.mem.Allocator,
    request: OwnedRowsAggregateRequest,
    rows: []const lake_rows.ProjectedRow,
) ![]LakeAggregateGroup {
    var groups = std.ArrayListUnmanaged(LakeAggregateGroup).empty;
    errdefer freeLakeRowsAggregateGroupList(alloc, &groups, request.aggregations.len);

    const grouped = request.group_by.len != 0 or request.group_expressions.len != 0;
    if (!grouped) {
        try appendLakeRowsAggregateGroupAlloc(alloc, request, &groups, null);
    }

    for (rows) |row| {
        if (lakeRowsQueryHasResidualPredicates(request.source) and !try lakeRowsQueryResidualPredicatesMatchAlloc(alloc, request.source, row)) continue;
        const group_index = if (!grouped)
            @as(usize, 0)
        else
            try findOrAppendLakeRowsAggregateGroupAlloc(alloc, request, &groups, row);
        try addLakeRowsAggregateRow(alloc, request.aggregations, &groups.items[group_index], row);
    }

    return try groups.toOwnedSlice(alloc);
}

fn findOrAppendLakeRowsAggregateGroupAlloc(
    alloc: std.mem.Allocator,
    request: OwnedRowsAggregateRequest,
    groups: *std.ArrayListUnmanaged(LakeAggregateGroup),
    row: lake_rows.ProjectedRow,
) !usize {
    const key_json = try lakeRowsGroupKeyJsonAlloc(alloc, request, row);
    errdefer alloc.free(key_json);
    for (groups.items, 0..) |group, i| {
        if (std.mem.eql(u8, group.key_json, key_json)) {
            alloc.free(key_json);
            return i;
        }
    }
    const fields_json = try lakeRowsGroupFieldsJsonAlloc(alloc, request, row);
    errdefer alloc.free(fields_json);
    const folds = try alloc.alloc(LakeAggregateFold, request.aggregations.len);
    @memset(folds, .{});
    errdefer alloc.free(folds);
    try groups.append(alloc, .{
        .key_json = key_json,
        .fields_json = fields_json,
        .folds = folds,
    });
    return groups.items.len - 1;
}

fn appendLakeRowsAggregateGroupAlloc(
    alloc: std.mem.Allocator,
    request: OwnedRowsAggregateRequest,
    groups: *std.ArrayListUnmanaged(LakeAggregateGroup),
    maybe_row: ?lake_rows.ProjectedRow,
) !void {
    const key_json = if (maybe_row) |row|
        try lakeRowsGroupKeyJsonAlloc(alloc, request, row)
    else
        try alloc.dupe(u8, "[]");
    errdefer alloc.free(key_json);
    const fields_json = if (maybe_row) |row|
        try lakeRowsGroupFieldsJsonAlloc(alloc, request, row)
    else
        try alloc.dupe(u8, "");
    errdefer alloc.free(fields_json);
    const folds = try alloc.alloc(LakeAggregateFold, request.aggregations.len);
    @memset(folds, .{});
    errdefer alloc.free(folds);
    try groups.append(alloc, .{
        .key_json = key_json,
        .fields_json = fields_json,
        .folds = folds,
    });
}

fn addLakeRowsAggregateRow(
    alloc: std.mem.Allocator,
    aggregations: []const db_mod.types.RelationalRowsAggregateSpec,
    group: *LakeAggregateGroup,
    row: lake_rows.ProjectedRow,
) !void {
    for (aggregations, 0..) |aggregation, i| {
        if (!try lakeRowsAggregateFilterMatchesAlloc(alloc, aggregation, row)) continue;
        switch (aggregation.op) {
            .count => {
                if (aggregation.field) |field| {
                    if ((try lakeRowsAggregateCellValue(row, field)) != null) group.folds[i].non_null_count += 1;
                } else if (aggregation.expression) |expression| {
                    if (try lakeRowsAggregateExpressionNonNullAlloc(alloc, row, expression)) {
                        group.folds[i].non_null_count += 1;
                    }
                } else {
                    group.folds[i].row_count += 1;
                }
            },
            .sum, .min, .max, .avg => {
                if (aggregation.field) |field| {
                    const value = (try lakeRowsAggregateCellValue(row, field)) orelse continue;
                    switch (value) {
                        .i64 => |number| try group.folds[i].numeric.addI64(number),
                        .f64 => |number| group.folds[i].numeric.addF64(number),
                        else => return error.UnsupportedRowsQuery,
                    }
                } else if (aggregation.expression) |expression| {
                    try addLakeRowsAggregateExpressionNumericAlloc(alloc, &group.folds[i].numeric, row, expression);
                } else {
                    return error.InvalidRowsRequest;
                }
            },
            else => return error.UnsupportedRowsQuery,
        }
    }
}

fn lakeRowsAggregateExpressionNonNullAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    expression: db_mod.types.RelationalRowsExpression,
) !bool {
    switch (try lakeRowsTypedNumericExpressionAlloc(alloc, row, expression)) {
        .unsupported => {},
        .null => return false,
        .i64, .f64 => return true,
    }
    const value_json = try lakeRowsAggregateExpressionJsonAlloc(alloc, row, expression);
    defer alloc.free(value_json);
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, value_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    return parsed.value != .null;
}

fn addLakeRowsAggregateExpressionNumericAlloc(
    alloc: std.mem.Allocator,
    fold: *LakeNumericFold,
    row: lake_rows.ProjectedRow,
    expression: db_mod.types.RelationalRowsExpression,
) !void {
    switch (try lakeRowsTypedNumericExpressionAlloc(alloc, row, expression)) {
        .unsupported => {},
        .null => return,
        .i64 => |number| {
            try fold.addI64(number);
            return;
        },
        .f64 => |number| {
            fold.addF64(number);
            return;
        },
    }
    const value_json = try lakeRowsAggregateExpressionJsonAlloc(alloc, row, expression);
    defer alloc.free(value_json);
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, value_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    switch (parsed.value) {
        .null => {},
        .integer => |number| try fold.addI64(number),
        .float => |number| fold.addF64(number),
        .number_string => |text| {
            if (std.fmt.parseInt(i64, text, 10)) |number| {
                try fold.addI64(number);
            } else |_| {
                fold.addF64(std.fmt.parseFloat(f64, text) catch return error.InvalidRowsRequest);
            }
        },
        else => return error.UnsupportedRowsQuery,
    }
}

const LakeTypedNumericExpression = union(enum) {
    unsupported,
    null,
    i64: i64,
    f64: f64,

    fn asF64(self: @This()) f64 {
        return switch (self) {
            .i64 => |number| @floatFromInt(number),
            .f64 => |number| number,
            else => unreachable,
        };
    }

    fn isUnsupported(self: @This()) bool {
        return switch (self) {
            .unsupported => true,
            else => false,
        };
    }

    fn isNull(self: @This()) bool {
        return switch (self) {
            .null => true,
            else => false,
        };
    }
};

fn lakeRowsTypedNumericExpressionAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    expression: db_mod.types.RelationalRowsExpression,
) anyerror!LakeTypedNumericExpression {
    return switch (expression.kind) {
        .field => blk: {
            switch (expression.field_source) {
                .row, .existing, .source => {},
                .proposed => break :blk .unsupported,
            }
            const cell = row.find(expression.field) orelse return error.RowSourceColumnNotFound;
            const value = cell.value orelse break :blk .null;
            break :blk switch (value) {
                .i64 => |number| .{ .i64 = number },
                .f64 => |number| .{ .f64 = number },
                else => .unsupported,
            };
        },
        .value => try lakeRowsTypedNumericValueJsonAlloc(alloc, expression.value_json),
        .add, .sub, .mul, .div, .mod, .power => try lakeRowsTypedNumericArithmeticAlloc(alloc, row, expression),
        .abs, .round, .trunc, .floor, .ceil, .sqrt, .sign => try lakeRowsTypedNumericUnaryAlloc(alloc, row, expression),
        else => .unsupported,
    };
}

fn lakeRowsTypedNumericValueJsonAlloc(
    alloc: std.mem.Allocator,
    value_json: []const u8,
) anyerror!LakeTypedNumericExpression {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, value_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    return switch (parsed.value) {
        .null => .null,
        .integer => |number| .{ .i64 = number },
        .float => |number| .{ .f64 = number },
        .number_string => |text| blk: {
            if (std.fmt.parseInt(i64, text, 10)) |number| {
                break :blk .{ .i64 = number };
            } else |_| {
                break :blk .{ .f64 = std.fmt.parseFloat(f64, text) catch return error.InvalidRowsRequest };
            }
        },
        else => .unsupported,
    };
}

fn lakeRowsTypedNumericArithmeticAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    expression: db_mod.types.RelationalRowsExpression,
) anyerror!LakeTypedNumericExpression {
    if ((expression.kind == .add or expression.kind == .mul) and expression.operands.len < 2) return error.InvalidRowsRequest;
    if ((expression.kind == .sub or expression.kind == .div or expression.kind == .mod or expression.kind == .power) and expression.operands.len != 2) return error.InvalidRowsRequest;
    if ((expression.kind == .add or expression.kind == .sub) and expression.operands.len == 2 and rowsExpressionHasDirectCalendarIntervalOperand(expression)) return .unsupported;

    var result = try lakeRowsTypedNumericExpressionAlloc(alloc, row, expression.operands[0]);
    switch (result) {
        .unsupported, .null => return result,
        .i64, .f64 => {},
    }
    for (expression.operands[1..]) |operand| {
        const rhs = try lakeRowsTypedNumericExpressionAlloc(alloc, row, operand);
        switch (rhs) {
            .unsupported => return .unsupported,
            .null => return .null,
            .i64, .f64 => {},
        }
        result = try lakeRowsTypedNumericApplyArithmetic(expression.kind, result, rhs);
    }
    return result;
}

fn lakeRowsTypedNumericApplyArithmetic(
    kind: db_mod.types.RelationalRowsExpressionKind,
    lhs: LakeTypedNumericExpression,
    rhs: LakeTypedNumericExpression,
) anyerror!LakeTypedNumericExpression {
    if (kind == .add or kind == .sub or kind == .mul) {
        switch (lhs) {
            .i64 => |lhs_i64| switch (rhs) {
                .i64 => |rhs_i64| {
                    const maybe_i64 = switch (kind) {
                        .add => std.math.add(i64, lhs_i64, rhs_i64),
                        .sub => std.math.sub(i64, lhs_i64, rhs_i64),
                        .mul => std.math.mul(i64, lhs_i64, rhs_i64),
                        else => unreachable,
                    };
                    if (maybe_i64) |number| return .{ .i64 = number } else |_| {}
                },
                else => {},
            },
            else => {},
        }
    }

    const lhs_f64 = lhs.asF64();
    const rhs_f64 = rhs.asF64();
    const result = switch (kind) {
        .add => lhs_f64 + rhs_f64,
        .sub => lhs_f64 - rhs_f64,
        .mul => lhs_f64 * rhs_f64,
        .div => if (rhs_f64 == 0) return error.InvalidRowsRequest else lhs_f64 / rhs_f64,
        .mod => if (rhs_f64 == 0) return error.InvalidRowsRequest else lhs_f64 - @trunc(lhs_f64 / rhs_f64) * rhs_f64,
        .power => std.math.pow(f64, lhs_f64, rhs_f64),
        else => return error.InvalidRowsRequest,
    };
    if (!std.math.isFinite(result)) return error.InvalidRowsRequest;
    return .{ .f64 = result };
}

fn lakeRowsTypedNumericUnaryAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    expression: db_mod.types.RelationalRowsExpression,
) anyerror!LakeTypedNumericExpression {
    if (expression.operands.len != 1) return error.InvalidRowsRequest;
    const value = try lakeRowsTypedNumericExpressionAlloc(alloc, row, expression.operands[0]);
    switch (value) {
        .unsupported, .null => return value,
        .i64, .f64 => {},
    }
    if (expression.kind == .abs) {
        switch (value) {
            .i64 => |number| {
                if (number >= 0) return .{ .i64 = number };
                return .{ .i64 = std.math.negate(number) catch return .{ .f64 = -value.asF64() } };
            },
            else => {},
        }
    }
    const number = value.asF64();
    const result = switch (expression.kind) {
        .abs => if (number < 0) -number else number,
        .round => @round(number),
        .trunc => @trunc(number),
        .floor => @floor(number),
        .ceil => @ceil(number),
        .sqrt => if (number < 0) return error.InvalidRowsRequest else @sqrt(number),
        .sign => if (number < 0) @as(f64, -1) else if (number > 0) @as(f64, 1) else @as(f64, 0),
        else => return error.InvalidRowsRequest,
    };
    if (!std.math.isFinite(result)) return error.InvalidRowsRequest;
    return .{ .f64 = result };
}

fn lakeRowsAggregateExpressionJsonAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    expression: db_mod.types.RelationalRowsExpression,
) ![]u8 {
    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    try writeLakeRowsExpressionProjectionValueJsonAlloc(alloc, &out.writer, row, expression);
    return try out.toOwnedSlice();
}

fn lakeRowsAggregateFilterMatchesAlloc(
    alloc: std.mem.Allocator,
    aggregation: db_mod.types.RelationalRowsAggregateSpec,
    row: lake_rows.ProjectedRow,
) !bool {
    for (aggregation.filter_predicates) |predicate| {
        if (!try lakeRowsRelationalCheckMatchesAlloc(alloc, row, predicate)) return false;
    }
    for (aggregation.filter_in_predicates) |predicate| {
        if (!try lakeRowsInPredicateMatchesAlloc(alloc, row, predicate)) return false;
    }
    for (aggregation.filter_array_any) |predicate| {
        if (!try lakeRowsArrayAnyPredicateMatchesAlloc(alloc, row, predicate)) return false;
    }
    for (aggregation.filter_array_contains) |predicate| {
        if (!try lakeRowsArrayContainsPredicateMatchesAlloc(alloc, row, predicate)) return false;
    }
    for (aggregation.filter_array_eq) |predicate| {
        if (!try lakeRowsArrayEqPredicateMatchesAlloc(alloc, row, predicate)) return false;
    }
    for (aggregation.filter_text_patterns) |predicate| {
        if (!try lakeRowsTextPatternPredicateMatchesAlloc(alloc, row, predicate)) return false;
    }
    for (aggregation.filter_json_contains) |predicate| {
        if (!try lakeRowsJsonContainsPredicateMatchesAlloc(alloc, row, predicate)) return false;
    }
    for (aggregation.filter_json_path_eq) |predicate| {
        if (!try lakeRowsJsonPathEqPredicateMatchesAlloc(alloc, row, predicate)) return false;
    }
    for (aggregation.filter_json_path_exists) |predicate| {
        if (!try lakeRowsJsonPathExistsPredicateMatchesAlloc(alloc, row, predicate)) return false;
    }
    for (aggregation.filter_expressions) |condition| {
        if (!try lakeRowsExpressionConditionMatchesAlloc(alloc, row, condition)) return false;
    }
    for (aggregation.filter_expression_array_contains) |predicate| {
        if (!try lakeRowsExpressionArrayContainsPredicateMatchesAlloc(alloc, row, predicate)) return false;
    }
    return true;
}

fn lakeRowsArrayAnyPredicateMatchesAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    predicate: db_mod.types.RelationalRowsArrayAnyPredicate,
) !bool {
    const row_json = try lakeProjectedRowJsonAlloc(alloc, row);
    defer alloc.free(row_json);
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    return try queryArrayAnyPredicatePasses(alloc, parsed.value, predicate);
}

fn lakeRowsArrayContainsPredicateMatchesAlloc(
