fn lakeRowsExpressionArrayContainsPredicateMatchesAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    predicate: db_mod.types.RelationalRowsExpressionArrayContainsPredicate,
) !bool {
