}

fn lakeRowsInPredicateMatchesAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    predicate: db_mod.types.RelationalRowsInPredicate,
) !bool {
    const maybe_cell = row.find(predicate.field) orelse return error.RowSourceColumnNotFound;
    const maybe_value = maybe_cell.value;
    const value = maybe_value orelse return predicate.negated;
    var values = std.json.parseFromSlice(std.json.Value, alloc, predicate.values_json, .{}) catch return error.InvalidRowsRequest;
    defer values.deinit();
    if (values.value != .array) return error.InvalidRowsRequest;
    var found = false;
    for (values.value.array.items) |item| {
        const comparison = try compareLakeRowsCellValueToJsonAlloc(alloc, value, item);
        if (comparison == .eq) {
            found = true;
            break;
        }
    }
    return if (predicate.negated) !found else found;
}

fn lakeRowsTextPatternPredicateMatchesAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    predicate: db_mod.types.RelationalRowsTextPatternPredicate,
) !bool {
    const maybe_cell = row.find(predicate.field) orelse return error.RowSourceColumnNotFound;
    const maybe_value = maybe_cell.value;
    const value = maybe_value orelse return predicate.negated;
    const matched = switch (value) {
        .bytes => |text| sqlLikePatternMatches(text, predicate.pattern, predicate.case_insensitive),
        .json => |json| blk: {
            var parsed = std.json.parseFromSlice(std.json.Value, alloc, json, .{}) catch return error.InvalidRowsRequest;
            defer parsed.deinit();
            break :blk switch (parsed.value) {
                .string => |text| sqlLikePatternMatches(text, predicate.pattern, predicate.case_insensitive),
                else => return predicate.negated,
            };
        },
        else => return predicate.negated,
    };
    return if (predicate.negated) !matched else matched;
}

fn lakeRowsQueryHasResidualPredicates(request: OwnedRowsQueryRequest) bool {
    return request.predicates.len > 1 or
        (request.predicates.len == 1 and request.predicates[0].op != .eq) or
        request.or_predicates.len != 0 or
        request.not_predicates.len != 0 or
        request.access_or_predicates.len != 0 or
        request.access_not_predicates.len != 0 or
        request.expression_or_predicates.len != 0 or
        request.expression_not_predicates.len != 0 or
        request.array_any.len != 0 or
        request.array_contains.len != 0 or
        request.array_eq.len != 0 or
        request.in_predicates.len != 0 or
        request.json_contains.len != 0 or
        request.json_path_eq.len != 0 or
        request.json_path_exists.len != 0 or
        request.text_patterns.len != 0 or
        request.expression_predicates.len != 0 or
        request.expression_array_contains.len != 0;
}

fn lakeRowsQueryResidualPredicatesMatchAlloc(
    alloc: std.mem.Allocator,
    request: OwnedRowsQueryRequest,
    row: lake_rows.ProjectedRow,
) !bool {
    if (!try lakeRowsRelationalChecksPassAlloc(alloc, row, request.predicates)) return false;
    if (!try lakeRowsPredicateGroupsPassAlloc(alloc, row, request.or_predicates)) return false;
    if (!try lakeRowsNotPredicateGroupsPassAlloc(alloc, row, request.not_predicates)) return false;
    for (request.in_predicates) |predicate| {
        if (!try lakeRowsInPredicateMatchesAlloc(alloc, row, predicate)) return false;
    }
    for (request.text_patterns) |predicate| {
        if (!try lakeRowsTextPatternPredicateMatchesAlloc(alloc, row, predicate)) return false;
    }
    for (request.json_contains) |predicate| {
        if (!try lakeRowsJsonContainsPredicateMatchesAlloc(alloc, row, predicate)) return false;
    }
    for (request.json_path_eq) |predicate| {
        if (!try lakeRowsJsonPathEqPredicateMatchesAlloc(alloc, row, predicate)) return false;
    }
    for (request.json_path_exists) |predicate| {
        if (!try lakeRowsJsonPathExistsPredicateMatchesAlloc(alloc, row, predicate)) return false;
    }
    for (request.expression_predicates) |condition| {
        if (!try lakeRowsExpressionConditionMatchesAlloc(alloc, row, condition)) return false;
    }
    if (!try lakeRowsExpressionOrPredicateGroupsPassAlloc(alloc, row, request.expression_or_predicates)) return false;
    if (!try lakeRowsExpressionNotPredicateGroupsPassAlloc(alloc, row, request.expression_not_predicates)) return false;
    if (!lakeRowsQueryResidualNeedsJson(request)) return true;

    const row_json = try lakeProjectedRowJsonAlloc(alloc, row);
    defer alloc.free(row_json);
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    if (!try queryAccessOrPredicateGroupsPass(alloc, parsed.value, request.access_or_predicates)) return false;
    if (!try queryAccessNotPredicateGroupsPass(alloc, parsed.value, request.access_not_predicates)) return false;
    for (request.array_any) |predicate| {
        if (!try queryArrayAnyPredicatePasses(alloc, parsed.value, predicate)) return false;
    }
    for (request.array_contains) |predicate| {
        if (!try queryArrayContainsPredicatePasses(alloc, parsed.value, predicate)) return false;
    }
    for (request.array_eq) |predicate| {
        if (!try queryArrayEqPredicatePasses(alloc, parsed.value, predicate)) return false;
    }
    for (request.expression_array_contains) |predicate| {
        if (!try queryExpressionArrayContainsPredicatePasses(alloc, parsed.value, predicate)) return false;
    }
    return true;
}

fn lakeRowsQueryResidualNeedsJson(request: OwnedRowsQueryRequest) bool {
    return request.access_or_predicates.len != 0 or
        request.access_not_predicates.len != 0 or
        request.array_any.len != 0 or
        request.array_contains.len != 0 or
        request.array_eq.len != 0 or
        request.expression_array_contains.len != 0;
}

fn lakeRowsRelationalChecksPassAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    checks: []const runtime_schema.RelationalCheck,
) !bool {
    for (checks) |check| {
        if (!try lakeRowsRelationalCheckMatchesAlloc(alloc, row, check)) return false;
    }
    return true;
}

fn lakeRowsPredicateGroupsPassAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    groups: []const db_mod.types.RelationalRowsPredicateGroup,
) !bool {
    if (groups.len == 0) return true;
    for (groups) |group| {
        if (try lakeRowsRelationalChecksPassAlloc(alloc, row, group.predicates)) return true;
    }
    return false;
}

fn lakeRowsNotPredicateGroupsPassAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    groups: []const db_mod.types.RelationalRowsPredicateGroup,
) !bool {
    for (groups) |group| {
        if (try lakeRowsRelationalChecksPassAlloc(alloc, row, group.predicates)) return false;
    }
    return true;
}

fn lakeRowsExpressionOrPredicateGroupsPassAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    groups: []const db_mod.types.RelationalRowsExpressionPredicateGroup,
) !bool {
    if (groups.len == 0) return true;
    for (groups) |group| {
        if (try lakeRowsExpressionPredicateGroupPassesAlloc(alloc, row, group)) return true;
    }
    return false;
}

fn lakeRowsExpressionNotPredicateGroupsPassAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    groups: []const db_mod.types.RelationalRowsExpressionPredicateGroup,
) !bool {
    for (groups) |group| {
        if (try lakeRowsExpressionPredicateGroupPassesAlloc(alloc, row, group)) return false;
    }
    return true;
}

fn lakeRowsExpressionPredicateGroupPassesAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    group: db_mod.types.RelationalRowsExpressionPredicateGroup,
) !bool {
    for (group.conditions) |condition| {
        if (!try lakeRowsExpressionConditionMatchesAlloc(alloc, row, condition)) return false;
    }
    return true;
}

fn lakeRowsExpressionConditionMatchesAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    condition: db_mod.types.RelationalRowsExpressionCondition,
) !bool {
    if (try lakeRowsTypedNumericExpressionConditionMatchesAlloc(alloc, row, condition)) |matched| return matched;
    const row_json = try lakeProjectedRowJsonAlloc(alloc, row);
    defer alloc.free(row_json);
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    return try expressionConditionMatches(alloc, parsed.value, condition);
}

fn lakeRowsTypedNumericExpressionConditionMatchesAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    condition: db_mod.types.RelationalRowsExpressionCondition,
) !?bool {
    const lhs = try lakeRowsTypedNumericExpressionAlloc(alloc, row, condition.lhs);
    if (lhs.isUnsupported()) return null;
    return switch (condition.op) {
        .is_null => lhs.isNull(),
        .is_not_null => !lhs.isNull(),
        .eq, .ne, .gt, .gte, .lt, .lte, .is_distinct, .is_not_distinct => blk: {
            if (condition.rhs.len != 1) return error.InvalidRowsRequest;
            const rhs = try lakeRowsTypedNumericExpressionAlloc(alloc, row, condition.rhs[0]);
            if (rhs.isUnsupported()) return null;
            if (condition.op == .is_distinct or condition.op == .is_not_distinct) {
                const not_distinct = lakeRowsTypedNumericValuesNotDistinct(lhs, rhs);
                break :blk if (condition.op == .is_not_distinct) not_distinct else !not_distinct;
            }
            if (condition.op == .eq or condition.op == .ne) {
                const equal = lakeRowsTypedNumericValuesEqual(lhs, rhs);
                break :blk if (condition.op == .eq) equal else !equal;
            }
            if (lhs.isNull() or rhs.isNull()) return error.InvalidRowsRequest;
            const comparison = compareLakeRowsTypedNumericValues(lhs, rhs);
            break :blk switch (condition.op) {
                .gt => comparison == .gt,
                .gte => comparison == .gt or comparison == .eq,
                .lt => comparison == .lt,
                .lte => comparison == .lt or comparison == .eq,
                else => unreachable,
            };
        },
    };
}

fn lakeRowsTypedNumericValuesNotDistinct(lhs: LakeTypedNumericExpression, rhs: LakeTypedNumericExpression) bool {
    if (lhs.isNull() or rhs.isNull()) return lhs.isNull() and rhs.isNull();
    return compareLakeRowsTypedNumericValues(lhs, rhs) == .eq;
}

fn lakeRowsTypedNumericValuesEqual(lhs: LakeTypedNumericExpression, rhs: LakeTypedNumericExpression) bool {
    if (lhs.isNull() or rhs.isNull()) return lhs.isNull() and rhs.isNull();
    return compareLakeRowsTypedNumericValues(lhs, rhs) == .eq;
}

fn compareLakeRowsTypedNumericValues(lhs: LakeTypedNumericExpression, rhs: LakeTypedNumericExpression) ScalarComparison {
    if (lhs == .i64 and rhs == .i64) {
        if (lhs.i64 < rhs.i64) return .lt;
        if (lhs.i64 > rhs.i64) return .gt;
        return .eq;
    }
    const lhs_number = lhs.asF64();
    const rhs_number = rhs.asF64();
    if (lhs_number < rhs_number) return .lt;
    if (lhs_number > rhs_number) return .gt;
    return .eq;
}

fn lakeRowsJsonContainsPredicateMatchesAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    predicate: db_mod.types.RelationalRowsJsonContainsPredicate,
) !bool {
    const maybe_cell = row.find(predicate.field) orelse return error.RowSourceColumnNotFound;
    const maybe_value = maybe_cell.value;
    const value = maybe_value orelse return false;
    const json = switch (value) {
        .json => |bytes| bytes,
        .bytes => |bytes| bytes,
        else => return false,
    };
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    var wanted = std.json.parseFromSlice(std.json.Value, alloc, predicate.value_json, .{}) catch return error.InvalidRowsRequest;
    defer wanted.deinit();
    return jsonValueContains(parsed.value, wanted.value);
}

fn lakeRowsJsonPathEqPredicateMatchesAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    predicate: db_mod.types.RelationalRowsJsonPathEqPredicate,
) !bool {
    const maybe_cell = row.find(predicate.field) orelse return error.RowSourceColumnNotFound;
    const maybe_value = maybe_cell.value;
    const value = maybe_value orelse return false;
    const json = switch (value) {
        .json => |bytes| bytes,
        .bytes => |bytes| bytes,
        else => return false,
    };
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    const actual = jsonValueAtPath(parsed.value, predicate.path) orelse return false;
    var wanted = std.json.parseFromSlice(std.json.Value, alloc, predicate.value_json, .{}) catch return error.InvalidRowsRequest;
    defer wanted.deinit();
    return jsonValuesEqual(actual.*, wanted.value);
}

fn lakeRowsJsonPathExistsPredicateMatchesAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    predicate: db_mod.types.RelationalRowsJsonPathExistsPredicate,
) !bool {
    const maybe_cell = row.find(predicate.field) orelse return error.RowSourceColumnNotFound;
    const maybe_value = maybe_cell.value;
    const value = maybe_value orelse return false;
    const json = switch (value) {
        .json => |bytes| bytes,
        .bytes => |bytes| bytes,
        else => return false,
    };
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    return jsonValueAtPath(parsed.value, predicate.path) != null;
}

fn lakeRowsRelationalCheckMatchesAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    check: runtime_schema.RelationalCheck,
) !bool {
    if (check.expression != null) return error.UnsupportedRowsQuery;
    const maybe_cell = row.find(check.field) orelse return error.RowSourceColumnNotFound;
    const maybe_value = maybe_cell.value;
    return switch (check.op) {
        .is_null => maybe_value == null,
        .is_not_null => maybe_value != null,
        .eq, .ne, .gt, .gte, .lt, .lte, .is_distinct, .is_not_distinct => blk: {
            const expected_json = check.value_json orelse return error.InvalidRowsRequest;
            var expected = std.json.parseFromSlice(std.json.Value, alloc, expected_json, .{}) catch return error.InvalidRowsRequest;
            defer expected.deinit();
            const comparison = if (maybe_value) |value|
                try compareLakeRowsCellValueToJsonAlloc(alloc, value, expected.value)
            else
                compareLakeRowsNullToJson(expected.value);
            const not_distinct = if (comparison) |actual_comparison| actual_comparison == .eq else false;
            break :blk switch (check.op) {
                .eq => if (comparison) |actual_comparison| actual_comparison == .eq else false,
                .ne => if (comparison) |actual_comparison| actual_comparison != .eq else false,
                .gt => if (comparison) |actual_comparison| actual_comparison == .gt else false,
                .gte => if (comparison) |actual_comparison| actual_comparison == .gt or actual_comparison == .eq else false,
                .lt => if (comparison) |actual_comparison| actual_comparison == .lt else false,
                .lte => if (comparison) |actual_comparison| actual_comparison == .lt or actual_comparison == .eq else false,
                .is_distinct => !not_distinct,
                .is_not_distinct => not_distinct,
                else => unreachable,
            };
        },
    };
}

fn compareLakeRowsCellValueToJsonAlloc(
    alloc: std.mem.Allocator,
    value: lake_rows.CellValue,
    expected: std.json.Value,
) !?ScalarComparison {
    return switch (value) {
        .i64 => |number| compareLakeRowsNumericToJson(@floatFromInt(number), expected),
        .f64 => |number| compareLakeRowsNumericToJson(number, expected),
        .bool => |actual| switch (expected) {
            .bool => |wanted| if (actual == wanted) .eq else if (!actual and wanted) .lt else .gt,
            else => null,
        },
        .bytes => |actual| switch (expected) {
            .string => |wanted| scalarComparisonFromOrder(std.mem.order(u8, actual, wanted)),
            else => null,
        },
        .json => |json| blk: {
            var parsed = std.json.parseFromSlice(std.json.Value, alloc, json, .{}) catch return error.InvalidRowsRequest;
            defer parsed.deinit();
            break :blk compareJsonScalars(parsed.value, expected);
        },
        .vector_f32 => null,
    };
}

fn compareLakeRowsNumericToJson(actual: f64, expected: std.json.Value) ?ScalarComparison {
    const wanted = switch (expected) {
        .integer => |number| @as(f64, @floatFromInt(number)),
        .float => |number| number,
        .number_string => |text| std.fmt.parseFloat(f64, text) catch return null,
        else => return null,
    };
    if (actual < wanted) return .lt;
    if (actual > wanted) return .gt;
    return .eq;
}

fn compareLakeRowsNullToJson(expected: std.json.Value) ?ScalarComparison {
    return switch (expected) {
        .null => .eq,
        else => null,
    };
}

fn scalarComparisonFromOrder(order: std.math.Order) ScalarComparison {
    return switch (order) {
        .lt => .lt,
        .eq => .eq,
        .gt => .gt,
    };
}

fn lakeRowsAggregateGroupJsonAlloc(
    alloc: std.mem.Allocator,
    request: OwnedRowsAggregateRequest,
    group: LakeAggregateGroup,
) ![]u8 {
    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.writeByte('{');
    var first = true;
    if (group.fields_json.len != 0) {
        try writer.writeAll(group.fields_json);
        first = false;
    }
    for (request.aggregations, 0..) |aggregation, i| {
        if (!first) try writer.writeByte(',');
        first = false;
        try writer.print("{f}:", .{std.json.fmt(aggregation.name, .{})});
        try writeLakeAggregateFoldValueJson(writer, aggregation, group.folds[i]);
    }
    try writer.writeByte('}');
    return try out.toOwnedSlice();
}

fn writeLakeAggregateFoldValueJson(
    writer: *std.Io.Writer,
    aggregation: db_mod.types.RelationalRowsAggregateSpec,
    fold: LakeAggregateFold,
) !void {
    switch (aggregation.op) {
        .count => try writer.print("{d}", .{if (aggregation.field == null and aggregation.expression == null) fold.row_count else fold.non_null_count}),
        .sum => {
            if (fold.numeric.all_integral) {
                try writer.print("{d}", .{fold.numeric.sum_i128});
            } else {
                try std.json.Stringify.value(fold.numeric.sum_f64, .{}, writer);
            }
        },
        .min => try writeLakeNumericExtremumJson(writer, fold.numeric, .min),
        .max => try writeLakeNumericExtremumJson(writer, fold.numeric, .max),
        .avg => {
            if (fold.numeric.count == 0) {
                try writer.writeAll("null");
            } else {
                try std.json.Stringify.value(fold.numeric.sum_f64 / @as(f64, @floatFromInt(fold.numeric.count)), .{}, writer);
            }
        },
        else => return error.UnsupportedRowsQuery,
    }
}

fn lakeRowsGroupKeyJsonAlloc(
    alloc: std.mem.Allocator,
    request: OwnedRowsAggregateRequest,
    row: lake_rows.ProjectedRow,
) ![]u8 {
    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.writeByte('[');
    var first = true;
    for (request.group_by) |field| {
        if (!first) try writer.writeByte(',');
        first = false;
        try writeLakeRowsCellJson(writer, (row.find(field) orelse return error.RowSourceColumnNotFound).value);
    }
    if (request.group_expressions.len != 0) {
        const row_json = try lakeProjectedRowJsonAlloc(alloc, row);
        defer alloc.free(row_json);
        var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidRowsRequest;
        defer parsed.deinit();
        for (request.group_expressions) |projection| {
            if (!first) try writer.writeByte(',');
            first = false;
            const value_json = try expressionValueJsonAlloc(alloc, parsed.value, projection.expression);
            defer alloc.free(value_json);
            try writer.writeAll(value_json);
        }
    }
    try writer.writeByte(']');
    return try out.toOwnedSlice();
}

fn lakeRowsGroupFieldsJsonAlloc(
    alloc: std.mem.Allocator,
    request: OwnedRowsAggregateRequest,
    row: lake_rows.ProjectedRow,
) ![]u8 {
    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    var first = true;
    for (request.group_by) |field| {
        if (!first) try writer.writeByte(',');
        first = false;
        try writer.print("{f}:", .{std.json.fmt(field, .{})});
        try writeLakeRowsCellJson(writer, (row.find(field) orelse return error.RowSourceColumnNotFound).value);
    }
    if (request.group_expressions.len != 0) {
        const row_json = try lakeProjectedRowJsonAlloc(alloc, row);
        defer alloc.free(row_json);
        var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidRowsRequest;
        defer parsed.deinit();
        for (request.group_expressions) |projection| {
            if (!first) try writer.writeByte(',');
            first = false;
            try writer.print("{f}:", .{std.json.fmt(projection.output, .{})});
            const value_json = try expressionValueJsonAlloc(alloc, parsed.value, projection.expression);
            defer alloc.free(value_json);
            try writer.writeAll(value_json);
        }
    }
    return try out.toOwnedSlice();
}

fn freeLakeRowsAggregateGroups(
    alloc: std.mem.Allocator,
    groups: []LakeAggregateGroup,
    aggregation_count: usize,
) void {
    for (groups) |group| freeLakeRowsAggregateGroup(alloc, group, aggregation_count);
    if (groups.len > 0) alloc.free(groups);
}

fn freeLakeRowsAggregateGroupList(
    alloc: std.mem.Allocator,
    groups: *std.ArrayListUnmanaged(LakeAggregateGroup),
    aggregation_count: usize,
) void {
    for (groups.items) |group| freeLakeRowsAggregateGroup(alloc, group, aggregation_count);
    groups.deinit(alloc);
}

fn freeLakeRowsAggregateGroup(
    alloc: std.mem.Allocator,
    group: LakeAggregateGroup,
    aggregation_count: usize,
) void {
    alloc.free(group.key_json);
    alloc.free(group.fields_json);
    if (aggregation_count > 0) alloc.free(group.folds);
}

fn writeLakeRowsAggregateValueJson(
    writer: *std.Io.Writer,
    aggregation: db_mod.types.RelationalRowsAggregateSpec,
    result: lake_rows.ScanResult,
) !void {
    switch (aggregation.op) {
        .count => {
            const field = aggregation.field orelse {
                const total = if (result.total == 0 and result.rows.len != 0) @as(u32, @intCast(result.rows.len)) else result.total;
                try writer.print("{d}", .{total});
                return;
            };
            var count: u64 = 0;
            for (result.rows) |row| {
                if ((try lakeRowsAggregateCellValue(row, field)) != null) count += 1;
            }
            try writer.print("{d}", .{count});
        },
        .sum, .min, .max, .avg => {
            const field = aggregation.field orelse return error.InvalidRowsRequest;
            const fold = try lakeRowsNumericFold(result.rows, field);
            switch (aggregation.op) {
                .sum => {
                    if (fold.all_integral) {
                        try writer.print("{d}", .{fold.sum_i128});
                    } else {
                        try std.json.Stringify.value(fold.sum_f64, .{}, writer);
                    }
                },
                .min => try writeLakeNumericExtremumJson(writer, fold, .min),
                .max => try writeLakeNumericExtremumJson(writer, fold, .max),
                .avg => {
                    if (fold.count == 0) {
                        try writer.writeAll("null");
                    } else {
                        const average = fold.sum_f64 / @as(f64, @floatFromInt(fold.count));
                        try std.json.Stringify.value(average, .{}, writer);
                    }
                },
                else => unreachable,
            }
        },
        else => return error.UnsupportedRowsQuery,
    }
}

const LakeExtremum = enum { min, max };

fn writeLakeNumericExtremumJson(
    writer: *std.Io.Writer,
    fold: LakeNumericFold,
    extremum: LakeExtremum,
) !void {
    if (fold.count == 0) {
        try writer.writeAll("null");
        return;
    }
    if (fold.all_integral) {
        const value = switch (extremum) {
            .min => fold.min_i64,
            .max => fold.max_i64,
        };
        try writer.print("{d}", .{value});
    } else {
        const value = switch (extremum) {
            .min => fold.min_f64,
            .max => fold.max_f64,
        };
        try std.json.Stringify.value(value, .{}, writer);
    }
}

fn lakeRowsNumericFold(
    rows: []const lake_rows.ProjectedRow,
    field: []const u8,
) !LakeNumericFold {
    var fold = LakeNumericFold{};
    for (rows) |row| {
        const value = (try lakeRowsAggregateCellValue(row, field)) orelse continue;
        switch (value) {
            .i64 => |number| try fold.addI64(number),
            .f64 => |number| fold.addF64(number),
            else => return error.UnsupportedRowsQuery,
        }
    }
    return fold;
}

fn lakeRowsAggregateCellValue(
    row: lake_rows.ProjectedRow,
    field: []const u8,
) !?lake_rows.CellValue {
    const cell = row.find(field) orelse return error.RowSourceColumnNotFound;
    return cell.value;
}

fn executeRowsQueryOnJsonRowsAcrossRangesAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    request: OwnedRowsQueryRequest,
    rows: []const []const u8,
    ranges: []const db_mod.types.RelationalRowsDocKeyRange,
) !OwnedRowsQueryResult {
    if (ranges.len == 0) return try executeRowsQueryOnJsonRowsAlloc(alloc, schema, request, rows);
    if (request.doc_key_range != null) return error.InvalidRowsRequest;
    try validateRowsPlanRanges(ranges);

    var filtered_rows = std.ArrayListUnmanaged([]const u8).empty;
    defer filtered_rows.deinit(alloc);
    const source_rows = try rowsJsonSourceRowsForRangesAlloc(alloc, schema, rows, ranges, &filtered_rows);

    var local_request = request;
    local_request.offset = request.offset;
    local_request.limit = request.limit;
    local_request.doc_key_range = null;
    return try executeRowsQueryOnJsonRowsAlloc(alloc, schema, local_request, source_rows);
}

fn rowsJsonSourceRowsForRangesAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    rows: []const []const u8,
    ranges: []const db_mod.types.RelationalRowsDocKeyRange,
    out: *std.ArrayListUnmanaged([]const u8),
) ![]const []const u8 {
    if (ranges.len == 0) return rows;
    try validateRowsPlanRanges(ranges);
    try out.ensureUnusedCapacity(alloc, rows.len);
    for (rows) |row_json| {
        if (try rowJsonInDocKeyRangesAlloc(alloc, schema, row_json, ranges)) out.appendAssumeCapacity(row_json);
    }
    return out.items;
}

fn rowsJsonSourceRowsForDocKeyRangeAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    rows: []const []const u8,
    maybe_range: ?db_mod.types.RelationalRowsDocKeyRange,
    out: *std.ArrayListUnmanaged([]const u8),
) ![]const []const u8 {
    if (maybe_range == null) return rows;
    try out.ensureUnusedCapacity(alloc, rows.len);
    for (rows) |row_json| {
        if (try rowJsonInDocKeyRangeAlloc(alloc, schema, row_json, maybe_range)) out.appendAssumeCapacity(row_json);
    }
    return out.items;
}

fn rowJsonInDocKeyRangeAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    row_json: []const u8,
    maybe_range: ?db_mod.types.RelationalRowsDocKeyRange,
) !bool {
    const range = maybe_range orelse return true;
    const key = try physicalPrimaryKeyFromRowJsonAlloc(alloc, schema, row_json);
    defer alloc.free(key);
    if (range.start.len > 0 and std.mem.order(u8, key, range.start) == .lt) return false;
    if (range.end.len > 0 and std.mem.order(u8, key, range.end) != .lt) return false;
    return true;
}

fn rowJsonInDocKeyRangesAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    row_json: []const u8,
    ranges: []const db_mod.types.RelationalRowsDocKeyRange,
) !bool {
    if (ranges.len == 0) return true;
    const key = try physicalPrimaryKeyFromRowJsonAlloc(alloc, schema, row_json);
    defer alloc.free(key);
    for (ranges) |range| {
        if (range.start.len > 0 and std.mem.order(u8, key, range.start) == .lt) return false;
        if (range.end.len == 0 or std.mem.order(u8, key, range.end) == .lt) return true;
    }
    return false;
}

fn singleRowsDocKeyRangeFromRowsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    start_row_json: []const u8,
    end_row_json: []const u8,
) ![]const db_mod.types.RelationalRowsDocKeyRange {
    const ranges = try alloc.alloc(db_mod.types.RelationalRowsDocKeyRange, 1);
    errdefer alloc.free(ranges);
    const start = try physicalPrimaryKeyFromRowJsonAlloc(alloc, schema, start_row_json);
    var start_transferred = false;
    errdefer if (!start_transferred) alloc.free(start);
    const end = try physicalPrimaryKeyFromRowJsonAlloc(alloc, schema, end_row_json);
    var end_transferred = false;
    errdefer if (!end_transferred) alloc.free(end);
    ranges[0] = .{ .start = start, .end = end };
    start_transferred = true;
    end_transferred = true;
    return ranges;
}

fn appendRowsQueryDistinctOnIndexesAlloc(
    alloc: std.mem.Allocator,
    candidates: []const QueryCandidate,
    distinct_columns: []const runtime_schema.RelationalColumn,
    distinct_on: []const []const u8,
    distinct_on_expressions: []const db_mod.types.RelationalRowsExpression,
    out: *std.ArrayListUnmanaged(usize),
) !void {
    var seen = std.StringHashMapUnmanaged(void).empty;
    defer {
        var keys = seen.keyIterator();
        while (keys.next()) |key| alloc.free(@constCast(key.*));
        seen.deinit(alloc);
    }

    for (candidates, 0..) |candidate, i| {
        const key = try rowsQueryDistinctOnKeyJsonAlloc(alloc, candidate.row_json, distinct_columns, distinct_on, distinct_on_expressions);
        var key_transferred = false;
        errdefer if (!key_transferred) alloc.free(key);
        if (seen.contains(key)) {
            alloc.free(key);
            continue;
        }
        const gop = try seen.getOrPut(alloc, key);
        if (gop.found_existing) {
            alloc.free(key);
            continue;
        }
        key_transferred = true;
        try out.append(alloc, i);
    }
}

fn rowsQueryDistinctOnKeyJsonAlloc(
    alloc: std.mem.Allocator,
    row_json: []const u8,
    distinct_columns: []const runtime_schema.RelationalColumn,
    distinct_on: []const []const u8,
    distinct_on_expressions: []const db_mod.types.RelationalRowsExpression,
) ![]u8 {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidRowsRequest;
    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.writeByte('[');
    var wrote_key = false;
    for (distinct_on, 0..) |field, i| {
        if (i > 0) try writer.writeByte(',');
        const selected = jsonValueAtPath(parsed.value, field) orelse {
            try writer.writeAll("null");
            wrote_key = true;
            continue;
        };
        try writeDistinctOnJsonValueWithCollation(alloc, writer, selected.*, distinctFieldCollation(distinct_columns, field));
        wrote_key = true;
    }
    for (distinct_on_expressions) |expression| {
        if (wrote_key) try writer.writeByte(',');
        const value_json = try expressionValueJsonAlloc(alloc, parsed.value, expression);
        defer alloc.free(value_json);
        if (expressionDirectRowFieldCollation(distinct_columns, expression)) |collation| {
            var parsed_value = std.json.parseFromSlice(std.json.Value, alloc, value_json, .{}) catch return error.InvalidRowsRequest;
            defer parsed_value.deinit();
            try writeDistinctOnJsonValueWithCollation(alloc, writer, parsed_value.value, collation);
        } else {
            try writer.writeAll(value_json);
        }
        wrote_key = true;
    }
    try writer.writeByte(']');
    return try out.toOwnedSlice();
}

fn appendLakeRowsQueryDistinctOnIndexesAlloc(
    alloc: std.mem.Allocator,
    candidates: []const LakeRowsQueryOrderCandidate,
    distinct_columns: []const runtime_schema.RelationalColumn,
    distinct_on: []const []const u8,
    distinct_on_expressions: []const db_mod.types.RelationalRowsExpression,
    out: *std.ArrayListUnmanaged(usize),
) !void {
    var seen = std.StringHashMapUnmanaged(void).empty;
    defer {
        var keys = seen.keyIterator();
        while (keys.next()) |key| alloc.free(@constCast(key.*));
        seen.deinit(alloc);
    }

    for (candidates, 0..) |candidate, i| {
        const key = try lakeRowsQueryDistinctOnKeyJsonAlloc(alloc, candidate.row, distinct_columns, distinct_on, distinct_on_expressions);
        var key_transferred = false;
        errdefer if (!key_transferred) alloc.free(key);
        if (seen.contains(key)) {
            alloc.free(key);
            continue;
        }
        const gop = try seen.getOrPut(alloc, key);
        if (gop.found_existing) {
            alloc.free(key);
            continue;
        }
        key_transferred = true;
        try out.append(alloc, i);
    }
}

fn lakeRowsQueryDistinctOnKeyJsonAlloc(
    alloc: std.mem.Allocator,
    row: lake_rows.ProjectedRow,
    distinct_columns: []const runtime_schema.RelationalColumn,
    distinct_on: []const []const u8,
    distinct_on_expressions: []const db_mod.types.RelationalRowsExpression,
) ![]u8 {
    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.writeByte('[');
    var wrote_key = false;
    for (distinct_on, 0..) |field, i| {
        if (i > 0) try writer.writeByte(',');
        const maybe_cell = row.find(field);
        if (maybe_cell) |cell| {
            try writeLakeRowsCellJsonWithCollation(alloc, writer, cell.value, distinctFieldCollation(distinct_columns, field));
        } else {
            try writer.writeAll("null");
        }
        wrote_key = true;
    }
    for (distinct_on_expressions) |expression| {
        if (wrote_key) try writer.writeByte(',');
        if (expressionDirectRowFieldCollation(distinct_columns, expression)) |collation| {
            const maybe_cell = row.find(expression.field);
            if (maybe_cell) |cell| {
                try writeLakeRowsCellJsonWithCollation(alloc, writer, cell.value, collation);
            } else {
                try writer.writeAll("null");
            }
        } else {
            const value_json = try lakeRowsExpressionValueJsonAlloc(alloc, row, expression);
            defer alloc.free(value_json);
            try writer.writeAll(value_json);
        }
        wrote_key = true;
    }
    try writer.writeByte(']');
    return try out.toOwnedSlice();
}

fn distinctFieldCollation(columns: []const runtime_schema.RelationalColumn, field: []const u8) ?[]const u8 {
    for (columns) |column| {
        if (std.mem.eql(u8, column.path, field) or std.mem.eql(u8, column.name, field)) return column.collation;
    }
    return null;
}

fn expressionDirectRowFieldCollation(
    columns: []const runtime_schema.RelationalColumn,
    expression: db_mod.types.RelationalRowsExpression,
) ?[]const u8 {
    if (expression.kind != .field or expression.field_source != .row) return null;
    return distinctFieldCollation(columns, expression.field);
}

fn writeDistinctOnJsonValueWithCollation(
    alloc: std.mem.Allocator,
    writer: *std.Io.Writer,
    value: std.json.Value,
    collation: ?[]const u8,
) !void {
    if (value == .string) {
        if (collation) |name| {
            if (relational_collation.isCaseInsensitive(name)) {
                const folded = try asciiLowerAlloc(alloc, value.string);
                defer alloc.free(folded);
                try writer.print("{f}", .{std.json.fmt(folded, .{})});
                return;
            }
        }
    }
    try std.json.Stringify.value(value, .{}, writer);
}

fn writeLakeRowsCellJsonWithCollation(
    alloc: std.mem.Allocator,
    writer: *std.Io.Writer,
    maybe_value: ?lake_rows.CellValue,
    collation: ?[]const u8,
) !void {
    const value = maybe_value orelse {
        try writer.writeAll("null");
        return;
    };
    if (value == .bytes) {
        if (collation) |name| {
            if (relational_collation.isCaseInsensitive(name)) {
                const folded = try asciiLowerAlloc(alloc, value.bytes);
                defer alloc.free(folded);
                try writer.print("{f}", .{std.json.fmt(folded, .{})});
                return;
            }
        }
    }
    try writeLakeRowsCellJson(writer, maybe_value);
}

fn asciiLowerAlloc(alloc: std.mem.Allocator, value: []const u8) ![]u8 {
    const folded = try alloc.dupe(u8, value);
    for (folded) |*byte| byte.* = std.ascii.toLower(byte.*);
    return folded;
}

