    }
    if (std.mem.eql(u8, op.string, "now")) {
        try requireJsonObjectOnlyKeys(value.object, &.{ "op", "args" });
        if (value.object.get("args")) |args_value| {
            if (args_value != .array or args_value.array.items.len != 0) return error.InvalidRowsRequest;
        }
