    }
    if (std.mem.eql(u8, op.string, "uuid_v4") or std.mem.eql(u8, op.string, "gen_random_uuid") or std.mem.eql(u8, op.string, "uuid_generate_v4")) {
        try requireJsonObjectOnlyKeys(value.object, &.{ "op", "args" });
