const ConflictAction = enum {
    update,
    nothing,
};

fn plannedRelationalRowJsonAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    row_value: std.json.Value,
) ![]u8 {
    return try plannedRelationalRowJsonWithDefaultContextAlloc(alloc, schema, row_value, .{});
}

fn plannedRelationalRowJsonWithDefaultContextAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    row_value: std.json.Value,
    default_context: DefaultValueContext,
) ![]u8 {
    return try plannedRelationalRowJsonWithOptionsAlloc(alloc, schema, row_value, true, default_context);
}

fn plannedExistingRelationalRowJsonAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    row_json: []const u8,
) ![]u8 {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    return try plannedRelationalRowJsonWithOptionsAlloc(alloc, schema, parsed.value, false, .{});
}

fn insertSourceAssignedRowJsonAlloc(
    alloc: std.mem.Allocator,
    req: db_mod.types.RelationalRowsInsertSourceRequest,
    source_row_json: []const u8,
) ![]u8 {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, source_row_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidRowsRequest;

    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.writeByte('{');
    var first = true;
    for (req.assignments) |assignment| {
        const value_json = try expressionValueJsonAlloc(alloc, parsed.value, assignment.expression);
        defer alloc.free(value_json);
        try appendRawJsonFieldValue(alloc, writer, &first, assignment.field, value_json);
    }
    try writer.writeByte('}');
    return try out.toOwnedSlice();
}

fn insertSourceReturningProjectionAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    req: db_mod.types.RelationalRowsInsertSourceRequest,
    row_json: []const u8,
) ![]u8 {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidRowsRequest;

    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.writeByte('{');
    var first = true;
    if (req.returning_all) {
        for (parsed.value.object.keys(), parsed.value.object.values()) |field, value| {
            try appendJsonFieldValue(alloc, writer, &first, field, value);
        }
    }
    for (req.returning) |field| {
        if (field.len == 0) return error.InvalidRowsRequest;
        if (!first) try writer.writeByte(',');
        first = false;
        try writer.print("{f}:", .{std.json.fmt(field, .{})});
        if (jsonValueAtPath(parsed.value, field)) |selected| {
            try std.json.Stringify.value(selected.*, .{}, writer);
        } else {
            try writer.writeAll("null");
        }
    }
    for (req.returning_expressions) |projection| {
        if (projection.output.len == 0) return error.InvalidRowsRequest;
        if (!first) try writer.writeByte(',');
        first = false;
        try writer.print("{f}:", .{std.json.fmt(projection.output, .{})});
        const value_json = try expressionValueJsonAlloc(alloc, parsed.value, projection.expression);
        defer alloc.free(value_json);
        try writer.writeAll(value_json);
    }
    _ = schema;
    try writer.writeByte('}');
    return try out.toOwnedSlice();
}

fn plannedRelationalRowJsonWithOptionsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    row_value: std.json.Value,
    reject_generated_input: bool,
    default_context: DefaultValueContext,
) ![]u8 {
    if (row_value != .object) return error.InvalidRowsRequest;
    const resolved_defaults = try alloc.alloc(?[]u8, schema.relational_columns.len);
    defer {
        for (resolved_defaults) |value| if (value) |owned| alloc.free(owned);
        alloc.free(resolved_defaults);
    }
    @memset(resolved_defaults, null);

    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.writeByte('{');
    var first = true;

    var it = row_value.object.iterator();
    while (it.next()) |entry| {
        const column = findRelationalColumn(schema.relational_columns, entry.key_ptr.*) orelse return error.InvalidRowsRequest;
        if (column.generated != null) {
            if (reject_generated_input) return error.InvalidRowsRequest;
            continue;
        }
        try appendJsonFieldValue(alloc, writer, &first, entry.key_ptr.*, entry.value_ptr.*);
    }

    for (schema.relational_columns, 0..) |column, column_index| {
        if (row_value.object.get(column.path) != null) continue;
        if (column.default_value) |default_value| {
            const value_json = try relationalDefaultValueJsonWithContextAlloc(alloc, default_value, default_context);
            resolved_defaults[column_index] = value_json;
            try appendRawJsonFieldValue(alloc, writer, &first, column.path, value_json);
        }
    }

    for (schema.relational_columns) |column| {
        const generated = column.generated orelse continue;
        const value_json = try generatedColumnValueJsonAlloc(alloc, schema, row_value, resolved_defaults, generated);
        defer alloc.free(value_json);
        try appendRawJsonFieldValue(alloc, writer, &first, column.path, value_json);
    }

    try writer.writeByte('}');
    const planned = try out.toOwnedSlice();
    errdefer alloc.free(planned);
    try validateRelationalChecks(alloc, schema, planned);
    return planned;
}

pub fn relationalDefaultValueJsonAlloc(alloc: std.mem.Allocator, default_value: runtime_schema.RelationalDefaultValue) ![]u8 {
    return try relationalDefaultValueJsonWithContextAlloc(alloc, default_value, .{});
}

pub fn relationalDefaultValueJsonWithContextAlloc(
    alloc: std.mem.Allocator,
    default_value: runtime_schema.RelationalDefaultValue,
    default_context: DefaultValueContext,
) ![]u8 {
    return switch (default_value.kind) {
        .literal => try alloc.dupe(u8, default_value.value_json),
        .now_ns => try std.fmt.allocPrint(alloc, "{d}", .{platform_time.realtimeNs()}),
        .current_date_ns => try std.fmt.allocPrint(alloc, "{d}", .{currentUtcDateStartNs()}),
        .sequence_next => try sequenceDefaultValueJsonAlloc(alloc, default_value.value_json, default_context.sequence_resolver orelse return error.UnsupportedSqlShape),
        .scalar_subquery => try scalarSubqueryDefaultValueJsonAlloc(alloc, default_value.value_json, default_context.scalar_subquery_resolver orelse return error.UnsupportedSqlShape),
        .uuid_v4 => blk: {
            const uuid = try randomUuidV4String();
            break :blk try std.fmt.allocPrint(alloc, "{f}", .{std.json.fmt(uuid[0..], .{})});
        },
    };
}

fn scalarSubqueryDefaultValueJsonAlloc(
    alloc: std.mem.Allocator,
    value_json: []const u8,
    resolver: ScalarSubqueryDefaultResolver,
) ![]u8 {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, value_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidRowsRequest;
    const query_value = parsed.value.object.get("query") orelse return error.InvalidRowsRequest;
    if (query_value != .object) return error.InvalidRowsRequest;
    if (query_value.object.get("kind") != null) return error.UnsupportedSqlShape;
    const query_json = try jsonValueStringifyAlloc(alloc, query_value);
    defer alloc.free(query_json);
    const value = try resolver.valueJsonAlloc(alloc, .{ .query_json = query_json });
    errdefer alloc.free(value);
    try validateScalarSubqueryDefaultJsonValue(alloc, value);
    return value;
}

pub fn normalizeScalarSubqueryDefaultValueJsonAlloc(
    alloc: std.mem.Allocator,
    value_json: []const u8,
) ![]u8 {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, value_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(parsed.value.object, &.{"query"});
    const query_value = parsed.value.object.get("query") orelse return error.InvalidRowsRequest;
    if (query_value != .object) return error.InvalidRowsRequest;
    var plan = if (query_value.object.get("kind")) |kind| blk: {
        if (kind != .string) return error.InvalidRowsRequest;
        if (!std.mem.eql(u8, kind.string, "tokenized_sql")) return error.UnsupportedSqlShape;
        break :blk try legacyTokenizedScalarDefaultPlanAlloc(alloc, query_value);
    } else try scalarSubqueryDefaultPlanFromStructuredPayloadAlloc(alloc, query_value);
    defer plan.deinit(alloc);
    const query_json = try scalarSubqueryDefaultNormalizedQueryJsonAlloc(alloc, plan);
    defer alloc.free(query_json);
    return try std.fmt.allocPrint(alloc, "{{\"query\":{s}}}", .{query_json});
}

fn validateScalarSubqueryDefaultJsonValue(alloc: std.mem.Allocator, value_json: []const u8) !void {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, value_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
}

pub fn scalarSubqueryDefaultPlanFromQueryJsonAlloc(
    alloc: std.mem.Allocator,
    query_json: []const u8,
) !ScalarSubqueryDefaultPlan {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, query_json, .{ .allocate = .alloc_always }) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidRowsRequest;
    if (parsed.value.object.get("kind") != null) return error.UnsupportedSqlShape;
    return try scalarSubqueryDefaultPlanFromStructuredPayloadAlloc(alloc, parsed.value);
}

fn legacyScalarDefaultPlanFromQueryJsonAlloc(
    alloc: std.mem.Allocator,
    query_json: []const u8,
) !ScalarSubqueryDefaultPlan {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, query_json, .{ .allocate = .alloc_always }) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidRowsRequest;
    return try legacyTokenizedScalarDefaultPlanAlloc(alloc, parsed.value);
}

fn scalarSubqueryDefaultPlanFromStructuredPayloadAlloc(
    alloc: std.mem.Allocator,
    value: std.json.Value,
) !ScalarSubqueryDefaultPlan {
    if (value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(value.object, &.{ "table", "alias", "select", "expressions", "where", "limit", "offset", "order_by", "distinct_on" });
    const table_value = value.object.get("table") orelse return error.InvalidRowsRequest;
    if (table_value != .string or table_value.string.len == 0) return error.InvalidRowsRequest;
    const table_name = scalarDefaultNormalizeTableName(table_value.string);
    const source_binding: ScalarDefaultSourceBinding = .{
        .table_name = table_name,
        .alias = try scalarDefaultStructuredAlias(value.object.get("alias")),
    };
    const select_value = value.object.get("select");
    const expressions_value = value.object.get("expressions");
    if ((select_value == null) == (expressions_value == null)) return error.UnsupportedSqlShape;

    const where_plan = try scalarDefaultStructuredWhereAlloc(alloc, value.object.get("where"), source_binding);
    var where_transferred = false;
    errdefer if (!where_transferred) freeScalarDefaultWherePlan(alloc, where_plan);

    const order_by = try scalarDefaultStructuredOrderByAlloc(alloc, value.object.get("order_by"), source_binding);
    var order_transferred = false;
    errdefer if (!order_transferred) freeScalarDefaultOrderBy(alloc, order_by);

    const limit = try parseOptionalU32(value.object.get("limit"));
    const offset = (try parseOptionalU32(value.object.get("offset"))) orelse 0;
    const plan = if (select_value) |selected_value| blk: {
        if (selected_value != .array or selected_value.array.items.len != 1) return error.UnsupportedSqlShape;
        const selected = selected_value.array.items[0];
        if (selected != .string or selected.string.len == 0) return error.InvalidRowsRequest;
        const selected_field = scalarDefaultNormalizeFieldNameForBinding(selected.string, source_binding);
        const distinct_on_value = value.object.get("distinct_on");
        const distinct = try scalarDefaultStructuredDistinctOnMatchesSelected(distinct_on_value, selected_field);
        break :blk try ownedScalarSubqueryDefaultPlanAlloc(
            alloc,
            table_name,
            selected_field,
            limit,
            offset,
            where_plan.predicates,
            where_plan.in_predicates,
            where_plan.or_predicates,
            where_plan.not_predicates,
            distinct,
            order_by,
        );
    } else blk: {
        if (value.object.get("distinct_on") != null) return error.UnsupportedSqlShape;
        const projection = try scalarDefaultStructuredExpressionProjection(alloc, expressions_value orelse return error.UnsupportedSqlShape, source_binding);
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeRowsQueryExpression(alloc, projection.expression);
        const expression_plan = try ownedScalarSubqueryDefaultExpressionTreePlanAlloc(
            alloc,
            table_name,
            projection.output,
            projection.expression,
            limit,
            offset,
            where_plan.predicates,
            where_plan.in_predicates,
            where_plan.or_predicates,
            where_plan.not_predicates,
            order_by,
        );
        expression_transferred = true;
        break :blk expression_plan;
    };
    where_transferred = true;
    order_transferred = true;
    return plan;
}

fn scalarDefaultStructuredDistinctOnMatchesSelected(
    maybe_value: ?std.json.Value,
    selected_field: []const u8,
) !bool {
    const value = maybe_value orelse return false;
    if (value != .array or value.array.items.len != 1) return error.UnsupportedSqlShape;
    const field = value.array.items[0];
    if (field != .string or field.string.len == 0) return error.InvalidRowsRequest;
    if (!std.mem.eql(u8, field.string, selected_field)) return error.UnsupportedSqlShape;
    return true;
}

fn scalarDefaultStructuredExpressionProjection(
    alloc: std.mem.Allocator,
    value: std.json.Value,
    source_binding: ScalarDefaultSourceBinding,
) !struct { output: []const u8, expression: db_mod.types.RelationalRowsExpression } {
    if (value != .array or value.array.items.len != 1) return error.UnsupportedSqlShape;
    const item = value.array.items[0];
    if (item != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(item.object, &.{ "as", "expr" });
    const output_value = item.object.get("as") orelse return error.InvalidRowsRequest;
    const expression_value = item.object.get("expr") orelse return error.InvalidRowsRequest;
    if (output_value != .string or output_value.string.len == 0) return error.InvalidRowsRequest;
    const expression = try scalarDefaultStructuredExpressionAlloc(alloc, expression_value, source_binding);
    return .{
        .output = output_value.string,
        .expression = expression,
    };
}

fn scalarDefaultSimpleExpressionKind(op: []const u8) ?db_mod.types.RelationalRowsExpressionKind {
    if (std.ascii.eqlIgnoreCase(op, "lower")) return .lower;
    if (std.ascii.eqlIgnoreCase(op, "upper")) return .upper;
    if (std.ascii.eqlIgnoreCase(op, "length")) return .length;
    if (std.ascii.eqlIgnoreCase(op, "md5")) return .md5;
    if (std.ascii.eqlIgnoreCase(op, "concat")) return .concat;
    return null;
}

fn scalarDefaultStructuredSimpleExpressionKind(op: []const u8) ?db_mod.types.RelationalRowsExpressionKind {
    if (std.ascii.eqlIgnoreCase(op, "reverse")) return .reverse;
    return scalarDefaultSimpleExpressionKind(op);
}

fn scalarDefaultStructuredExpressionKind(op: []const u8) ?db_mod.types.RelationalRowsExpressionKind {
    if (std.ascii.eqlIgnoreCase(op, "cast")) return .cast;
    if (std.ascii.eqlIgnoreCase(op, "add")) return .add;
    if (std.ascii.eqlIgnoreCase(op, "sub")) return .sub;
    if (std.ascii.eqlIgnoreCase(op, "mul")) return .mul;
    if (std.ascii.eqlIgnoreCase(op, "div")) return .div;
    if (std.ascii.eqlIgnoreCase(op, "mod")) return .mod;
    return scalarDefaultStructuredSimpleExpressionKind(op);
}

fn scalarDefaultStructuredExpressionArityValid(
    kind: db_mod.types.RelationalRowsExpressionKind,
    len: usize,
) bool {
    return switch (kind) {
        .concat, .sub, .div, .mod => len == 2,
        .add, .mul => len >= 2,
        .cast => len == 1,
        else => len == 1,
    };
}

fn scalarDefaultStructuredExpressionAlloc(
    alloc: std.mem.Allocator,
    value: std.json.Value,
    source_binding: ScalarDefaultSourceBinding,
) !db_mod.types.RelationalRowsExpression {
    if (value != .object) return error.InvalidRowsRequest;
    if (value.object.get("field")) |field_value| {
        try requireJsonObjectOnlyKeys(value.object, &.{"field"});
        if (field_value != .string or field_value.string.len == 0) return error.InvalidRowsRequest;
        return .{
            .kind = .field,
            .field = try alloc.dupe(u8, scalarDefaultNormalizeFieldNameForBinding(field_value.string, source_binding)),
        };
    }
    if (value.object.get("value")) |literal_value| {
        try requireJsonObjectOnlyKeys(value.object, &.{"value"});
        return .{
            .kind = .value,
            .value_json = try jsonValueStringifyAlloc(alloc, literal_value),
        };
    }
    const op_value = value.object.get("op") orelse return error.InvalidRowsRequest;
    const args_value = value.object.get("args") orelse return error.InvalidRowsRequest;
    if (op_value != .string) return error.InvalidRowsRequest;
    if (args_value != .array) return error.InvalidRowsRequest;
    const kind = scalarDefaultStructuredExpressionKind(op_value.string) orelse return error.UnsupportedSqlShape;
    if (kind == .cast) {
        try requireJsonObjectOnlyKeys(value.object, &.{ "op", "args", "to" });
    } else {
        try requireJsonObjectOnlyKeys(value.object, &.{ "op", "args" });
    }
    if (!scalarDefaultStructuredExpressionArityValid(kind, args_value.array.items.len)) return error.UnsupportedSqlShape;
    const operands = try alloc.alloc(db_mod.types.RelationalRowsExpression, args_value.array.items.len);
    var initialized: usize = 0;
    errdefer {
        for (operands[0..initialized]) |operand| freeRowsQueryExpression(alloc, operand);
        alloc.free(operands);
    }
    for (args_value.array.items) |arg| {
        operands[initialized] = try scalarDefaultStructuredExpressionAlloc(alloc, arg, source_binding);
        initialized += 1;
    }
    const cast_type: ?db_mod.types.RelationalRowsExpressionCastType = if (kind == .cast) blk: {
        const target_value = value.object.get("to") orelse return error.InvalidRowsRequest;
        if (target_value != .string) return error.InvalidRowsRequest;
        break :blk parseRowsQueryExpressionCastType(target_value.string) orelse return error.InvalidRowsRequest;
    } else null;
    return .{ .kind = kind, .operands = operands, .cast_type = cast_type };
}

fn scalarDefaultStructuredWhereAlloc(
    alloc: std.mem.Allocator,
    maybe_value: ?std.json.Value,
    source_binding: ScalarDefaultSourceBinding,
) !ScalarDefaultWherePlan {
    const value = maybe_value orelse return .{};
    if (value != .object) return error.InvalidRowsRequest;
    if (value.object.get("any") != null or value.object.get("not") != null) {
        try requireJsonObjectOnlyKeys(value.object, &.{ "all", "any", "not" });
        const predicates = if (value.object.get("all")) |all_value|
            try scalarDefaultStructuredPredicateArrayAlloc(alloc, all_value, source_binding)
        else
            &.{};
        var predicates_transferred = false;
        errdefer if (!predicates_transferred) freeScalarDefaultPredicates(alloc, predicates);
        const or_predicates = if (value.object.get("any")) |any_value|
            try scalarDefaultStructuredPredicateGroupsAlloc(alloc, any_value, source_binding)
        else
            &.{};
        var or_transferred = false;
        errdefer if (!or_transferred) freeScalarDefaultPredicateGroups(alloc, or_predicates);
        const not_predicates = if (value.object.get("not")) |not_value|
            try scalarDefaultStructuredPredicateGroupsAlloc(alloc, not_value, source_binding)
        else
            &.{};
        var not_transferred = false;
        errdefer if (!not_transferred) freeScalarDefaultPredicateGroups(alloc, not_predicates);
        predicates_transferred = true;
        or_transferred = true;
        not_transferred = true;
        return .{ .predicates = predicates, .or_predicates = or_predicates, .not_predicates = not_predicates };
    }
    if (value.object.get("all")) |all_value| {
        try requireJsonObjectOnlyKeys(value.object, &.{"all"});
        return try scalarDefaultStructuredPredicateAllPlanAlloc(alloc, all_value, source_binding);
    }
    if (try scalarDefaultStructuredPredicateIsIn(value)) {
        const out = try alloc.alloc(db_mod.types.RelationalRowsInPredicate, 1);
        errdefer alloc.free(out);
        out[0] = try scalarDefaultStructuredInPredicateAlloc(alloc, value, source_binding);
        return .{ .in_predicates = out };
    }
    const out = try alloc.alloc(runtime_schema.RelationalCheck, 1);
    errdefer alloc.free(out);
    out[0] = try scalarDefaultStructuredPredicateAlloc(alloc, value, source_binding);
    return .{ .predicates = out };
}

fn scalarDefaultStructuredPredicateAllPlanAlloc(
    alloc: std.mem.Allocator,
    value: std.json.Value,
    source_binding: ScalarDefaultSourceBinding,
) !ScalarDefaultWherePlan {
    if (value != .array) return error.InvalidRowsRequest;
    var predicates = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    defer predicates.deinit(alloc);
    var in_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate).empty;
    defer in_predicates.deinit(alloc);
    var or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup).empty;
    defer or_predicates.deinit(alloc);
    var not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup).empty;
    defer not_predicates.deinit(alloc);
    errdefer {
        freeScalarDefaultPredicateValues(alloc, predicates.items);
        freeRowsQueryInPredicatesNoSlice(alloc, in_predicates.items);
        freeScalarDefaultPredicateGroupValues(alloc, or_predicates.items);
        freeScalarDefaultPredicateGroupValues(alloc, not_predicates.items);
    }
    for (value.array.items) |item| {
        if (item == .object and item.object.get("any") != null) {
            try requireJsonObjectOnlyKeys(item.object, &.{"any"});
            try scalarDefaultStructuredAppendPredicateGroupsAlloc(alloc, &or_predicates, item.object.get("any").?, source_binding);
        } else if (item == .object and item.object.get("not") != null) {
            try requireJsonObjectOnlyKeys(item.object, &.{"not"});
            try scalarDefaultStructuredAppendPredicateGroupsAlloc(alloc, &not_predicates, item.object.get("not").?, source_binding);
        } else if (item == .object and item.object.get("all") != null) {
            try requireJsonObjectOnlyKeys(item.object, &.{"all"});
            var nested = try scalarDefaultStructuredPredicateAllPlanAlloc(alloc, item.object.get("all").?, source_binding);
            try scalarDefaultStructuredAppendWherePlanAlloc(alloc, &predicates, &in_predicates, &or_predicates, &not_predicates, &nested);
        } else if (try scalarDefaultStructuredPredicateIsIn(item)) {
            try in_predicates.append(alloc, try scalarDefaultStructuredInPredicateAlloc(alloc, item, source_binding));
        } else {
            try predicates.append(alloc, try scalarDefaultStructuredPredicateAlloc(alloc, item, source_binding));
        }
    }
    const owned_predicates = try predicates.toOwnedSlice(alloc);
    predicates = .empty;
    var predicates_transferred = false;
    errdefer if (!predicates_transferred) freeScalarDefaultPredicates(alloc, owned_predicates);
    const owned_in_predicates = try in_predicates.toOwnedSlice(alloc);
    in_predicates = .empty;
    var in_predicates_transferred = false;
    errdefer if (!in_predicates_transferred) freeRowsQueryInPredicates(alloc, owned_in_predicates);
    const owned_or_predicates = try or_predicates.toOwnedSlice(alloc);
    or_predicates = .empty;
    var or_predicates_transferred = false;
    errdefer if (!or_predicates_transferred) freeScalarDefaultPredicateGroups(alloc, owned_or_predicates);
    const owned_not_predicates = try not_predicates.toOwnedSlice(alloc);
    not_predicates = .empty;
    var not_predicates_transferred = false;
    errdefer if (!not_predicates_transferred) freeScalarDefaultPredicateGroups(alloc, owned_not_predicates);
    predicates_transferred = true;
    in_predicates_transferred = true;
    or_predicates_transferred = true;
    not_predicates_transferred = true;
    return .{ .predicates = owned_predicates, .in_predicates = owned_in_predicates, .or_predicates = owned_or_predicates, .not_predicates = owned_not_predicates };
}

fn scalarDefaultStructuredAppendWherePlanAlloc(
    alloc: std.mem.Allocator,
    predicates: *std.ArrayListUnmanaged(runtime_schema.RelationalCheck),
    in_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate),
    or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
    not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
    nested: *ScalarDefaultWherePlan,
) !void {
    errdefer freeScalarDefaultWherePlan(alloc, nested.*);
    try predicates.appendSlice(alloc, nested.predicates);
    try in_predicates.appendSlice(alloc, nested.in_predicates);
    try or_predicates.appendSlice(alloc, nested.or_predicates);
    try not_predicates.appendSlice(alloc, nested.not_predicates);
    if (nested.predicates.len > 0) alloc.free(@constCast(nested.predicates.ptr)[0..nested.predicates.len]);
    if (nested.in_predicates.len > 0) alloc.free(@constCast(nested.in_predicates.ptr)[0..nested.in_predicates.len]);
    if (nested.or_predicates.len > 0) alloc.free(@constCast(nested.or_predicates.ptr)[0..nested.or_predicates.len]);
    if (nested.not_predicates.len > 0) alloc.free(@constCast(nested.not_predicates.ptr)[0..nested.not_predicates.len]);
    nested.* = .{};
}

fn scalarDefaultStructuredPredicateIsIn(value: std.json.Value) !bool {
    if (value != .object) return false;
    const op_value = value.object.get("op") orelse return false;
    if (op_value != .string) return error.InvalidRowsRequest;
    return std.mem.eql(u8, op_value.string, "in") or std.mem.eql(u8, op_value.string, "not_in");
}

fn scalarDefaultStructuredInPredicateAlloc(
    alloc: std.mem.Allocator,
    value: std.json.Value,
    source_binding: ScalarDefaultSourceBinding,
) !db_mod.types.RelationalRowsInPredicate {
    if (value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(value.object, &.{ "field", "op", "value" });
    const field_value = value.object.get("field") orelse return error.InvalidRowsRequest;
    const op_value = value.object.get("op") orelse return error.InvalidRowsRequest;
    const list_value = value.object.get("value") orelse return error.InvalidRowsRequest;
    if (field_value != .string or field_value.string.len == 0) return error.InvalidRowsRequest;
    if (op_value != .string) return error.InvalidRowsRequest;
    if (list_value != .array or list_value.array.items.len == 0) return error.InvalidRowsRequest;
    const field = try alloc.dupe(u8, scalarDefaultNormalizeFieldNameForBinding(field_value.string, source_binding));
    var field_transferred = false;
    errdefer if (!field_transferred) alloc.free(field);
    const values_json = try jsonValueStringifyAlloc(alloc, list_value);
    var values_transferred = false;
    errdefer if (!values_transferred) alloc.free(values_json);
    field_transferred = true;
    values_transferred = true;
    return .{
        .field = field,
        .values_json = values_json,
        .negated = std.mem.eql(u8, op_value.string, "not_in"),
    };
}

fn scalarDefaultStructuredPredicateArrayAlloc(
    alloc: std.mem.Allocator,
    value: std.json.Value,
    source_binding: ScalarDefaultSourceBinding,
) ![]const runtime_schema.RelationalCheck {
    if (value != .array) return error.InvalidRowsRequest;
    const out = try alloc.alloc(runtime_schema.RelationalCheck, value.array.items.len);
    var initialized: usize = 0;
    errdefer {
        freeScalarDefaultPredicateValues(alloc, out[0..initialized]);
        alloc.free(out);
    }
    for (value.array.items) |item| {
        out[initialized] = try scalarDefaultStructuredPredicateAlloc(alloc, item, source_binding);
        initialized += 1;
    }
    return out;
}

fn scalarDefaultStructuredPredicateGroupsAlloc(
    alloc: std.mem.Allocator,
    value: std.json.Value,
    source_binding: ScalarDefaultSourceBinding,
) ![]const db_mod.types.RelationalRowsPredicateGroup {
    if (value != .array or value.array.items.len == 0) return error.InvalidRowsRequest;
    const groups = try alloc.alloc(db_mod.types.RelationalRowsPredicateGroup, value.array.items.len);
    var initialized: usize = 0;
    errdefer {
        freeScalarDefaultPredicateGroupValues(alloc, groups[0..initialized]);
        alloc.free(groups);
    }
    for (value.array.items) |item| {
        groups[initialized] = .{ .predicates = try scalarDefaultStructuredPredicateGroupAlloc(alloc, item, source_binding) };
        initialized += 1;
    }
    return groups;
}

fn scalarDefaultStructuredAppendPredicateGroupsAlloc(
    alloc: std.mem.Allocator,
    groups: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
    value: std.json.Value,
    source_binding: ScalarDefaultSourceBinding,
) !void {
    const parsed_groups = try scalarDefaultStructuredPredicateGroupsAlloc(alloc, value, source_binding);
    var groups_transferred = false;
    errdefer if (!groups_transferred) freeScalarDefaultPredicateGroups(alloc, parsed_groups);
    try groups.appendSlice(alloc, parsed_groups);
    groups_transferred = true;
    if (parsed_groups.len > 0) alloc.free(@constCast(parsed_groups.ptr)[0..parsed_groups.len]);
}

fn scalarDefaultStructuredPredicateGroupAlloc(
    alloc: std.mem.Allocator,
    value: std.json.Value,
    source_binding: ScalarDefaultSourceBinding,
) ![]const runtime_schema.RelationalCheck {
    if (value != .object) return error.InvalidRowsRequest;
    if (value.object.get("all")) |all_value| {
        try requireJsonObjectOnlyKeys(value.object, &.{"all"});
        const predicates = try scalarDefaultStructuredPredicateArrayAlloc(alloc, all_value, source_binding);
        errdefer freeScalarDefaultPredicates(alloc, predicates);
        if (predicates.len == 0) return error.InvalidRowsRequest;
        return predicates;
    }
    const out = try alloc.alloc(runtime_schema.RelationalCheck, 1);
    errdefer alloc.free(out);
    out[0] = try scalarDefaultStructuredPredicateAlloc(alloc, value, source_binding);
    return out;
}

fn scalarDefaultStructuredPredicateAlloc(
    alloc: std.mem.Allocator,
    value: std.json.Value,
    source_binding: ScalarDefaultSourceBinding,
) !runtime_schema.RelationalCheck {
    if (value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(value.object, &.{ "field", "op", "value" });
    const field_value = value.object.get("field") orelse return error.InvalidRowsRequest;
    const op_value = value.object.get("op") orelse return error.InvalidRowsRequest;
    if (field_value != .string or field_value.string.len == 0) return error.InvalidRowsRequest;
    if (op_value != .string or op_value.string.len == 0) return error.InvalidRowsRequest;
    const op = try parseRowsQueryPredicateOp(op_value.string);
    if (!rowsQueryPredicateNeedsValue(op)) {
        if (value.object.get("value") != null) return error.InvalidRowsRequest;
    }
    const value_json = if (rowsQueryPredicateNeedsValue(op)) blk: {
        const predicate_value = value.object.get("value") orelse return error.InvalidRowsRequest;
        break :blk try jsonValueStringifyAlloc(alloc, predicate_value);
    } else null;
    var value_transferred = false;
    errdefer if (!value_transferred) if (value_json) |json| alloc.free(json);
    const field = try alloc.dupe(u8, scalarDefaultNormalizeFieldNameForBinding(field_value.string, source_binding));
    var field_transferred = false;
    errdefer if (!field_transferred) alloc.free(field);
    value_transferred = true;
    field_transferred = true;
    return .{
        .name = "",
        .field = field,
        .op = op,
        .value_json = value_json,
    };
}

fn scalarDefaultStructuredOrderByAlloc(
    alloc: std.mem.Allocator,
    maybe_value: ?std.json.Value,
    source_binding: ScalarDefaultSourceBinding,
) ![]const db_mod.types.RelationalRowsQueryOrder {
    const value = maybe_value orelse return &.{};
    if (value != .array) return error.InvalidRowsRequest;
    const orders = try alloc.alloc(db_mod.types.RelationalRowsQueryOrder, value.array.items.len);
    var initialized: usize = 0;
    errdefer {
        freeScalarDefaultOrderBy(alloc, orders[0..initialized]);
        alloc.free(orders);
    }
    for (value.array.items) |item| {
        if (item != .object) return error.InvalidRowsRequest;
        try requireJsonObjectOnlyKeys(item.object, &.{ "field", "direction", "null_test" });
        const field_value = item.object.get("field") orelse return error.InvalidRowsRequest;
        if (field_value != .string or field_value.string.len == 0) return error.InvalidRowsRequest;
        const direction: db_mod.types.RelationalRowsQueryOrderDirection = if (item.object.get("direction")) |direction_value| blk: {
            if (direction_value != .string) return error.InvalidRowsRequest;
            if (std.ascii.eqlIgnoreCase(direction_value.string, "asc")) break :blk .asc;
            if (std.ascii.eqlIgnoreCase(direction_value.string, "desc")) break :blk .desc;
            return error.InvalidRowsRequest;
        } else .asc;
        const null_test: ?db_mod.types.RelationalRowsQueryOrderNullTest = if (item.object.get("null_test")) |null_test_value| blk: {
            if (null_test_value != .string) return error.InvalidRowsRequest;
            if (std.mem.eql(u8, null_test_value.string, "is_null")) break :blk .is_null;
            if (std.mem.eql(u8, null_test_value.string, "is_not_null")) break :blk .is_not_null;
            return error.InvalidRowsRequest;
        } else null;
        orders[initialized] = .{
            .field = try alloc.dupe(u8, scalarDefaultNormalizeFieldNameForBinding(field_value.string, source_binding)),
            .direction = direction,
            .null_test = null_test,
        };
        initialized += 1;
    }
    return orders;
}

fn legacyTokenizedScalarDefaultPlanAlloc(
    alloc: std.mem.Allocator,
    value: std.json.Value,
) !ScalarSubqueryDefaultPlan {
    if (value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(value.object, &.{ "kind", "tokens" });
    const tokens_value = value.object.get("tokens") orelse return error.InvalidRowsRequest;
    if (tokens_value != .array) return error.InvalidRowsRequest;
    const tokens = tokens_value.array.items;
    var pos: usize = 0;

    try expectScalarDefaultKeyword(tokens, &pos, "select");
    const distinct = if (pos < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos], "distinct")) distinct: {
        pos += 1;
        if (pos < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos], "on")) return error.UnsupportedSqlShape;
        break :distinct true;
    } else false;
    const projection = try scalarDefaultTokenizedProjection(alloc, tokens, &pos);
    defer scalarDefaultFreeTokenizedProjection(alloc, projection);
    if (pos < tokens.len and scalarDefaultTokenKindEql(tokens[pos], "comma")) return error.UnsupportedSqlShape;
    try expectScalarDefaultKeyword(tokens, &pos, "from");
    const table_name = scalarDefaultNormalizeTableName(try scalarDefaultIdentifierTokenText(tokens, pos));
    pos += 1;
    const source_binding: ScalarDefaultSourceBinding = .{
        .table_name = table_name,
        .alias = try scalarDefaultConsumeOptionalSourceAlias(tokens, &pos),
    };
    const output_field = switch (projection) {
        .field => |field| scalarDefaultNormalizeFieldNameForBinding(field.raw_field, source_binding),
        .simple_expression => |projection_expression| projection_expression.output,
    };
    const projection_alias = switch (projection) {
        .field => |field| field.alias,
        .simple_expression => "",
    };
    if (distinct and projection != .field) return error.UnsupportedSqlShape;

    var order_by = std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder).empty;
    defer order_by.deinit(alloc);
    var where_plan: ScalarDefaultWherePlan = .{};
    var where_transferred = false;
    errdefer if (!where_transferred) freeScalarDefaultWherePlan(alloc, where_plan);
    var limit: ?u32 = null;
    var offset: u32 = 0;
    var consumed_where = false;

    while (pos < tokens.len) {
        if (scalarDefaultTokenKindEql(tokens[pos], "semicolon")) {
            pos += 1;
            break;
        }
        if (scalarDefaultTokenMatchesKeyword(tokens[pos], "where")) {
            if (consumed_where) return error.UnsupportedSqlShape;
            consumed_where = true;
            pos += 1;
            where_plan = try scalarDefaultTokenizedWhereAlloc(alloc, tokens, &pos, source_binding);
            continue;
        }
        if (scalarDefaultTokenMatchesKeyword(tokens[pos], "order")) {
            pos += 1;
            try expectScalarDefaultKeyword(tokens, &pos, "by");
            while (true) {
                const field = try alloc.dupe(u8, try scalarDefaultOrderFieldName(tokens, pos, source_binding, output_field, projection_alias));
                var field_transferred = false;
                errdefer if (!field_transferred) alloc.free(field);
                pos += 1;
                const direction: db_mod.types.RelationalRowsQueryOrderDirection = if (pos < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos], "desc")) blk: {
                    pos += 1;
                    break :blk .desc;
                } else if (pos < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos], "asc")) blk: {
                    pos += 1;
                    break :blk .asc;
                } else .asc;
                const explicit_nulls_first: ?bool = if (pos < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos], "nulls")) blk: {
                    pos += 1;
                    if (pos < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos], "first")) {
                        pos += 1;
                        break :blk true;
                    }
                    try expectScalarDefaultKeyword(tokens, &pos, "last");
                    break :blk false;
                } else null;
                if (explicit_nulls_first) |nulls_first| {
                    const null_field = try alloc.dupe(u8, field);
                    var null_field_transferred = false;
                    errdefer if (!null_field_transferred) alloc.free(null_field);
                    try order_by.append(alloc, .{
                        .field = null_field,
                        .direction = if (nulls_first) .desc else .asc,
                        .null_test = .is_null,
                    });
                    null_field_transferred = true;
                }
                try order_by.append(alloc, .{ .field = field, .direction = direction });
                field_transferred = true;
                if (pos < tokens.len and scalarDefaultTokenKindEql(tokens[pos], "comma")) {
                    pos += 1;
                    continue;
                }
                break;
            }
            continue;
        }
        if (scalarDefaultTokenMatchesKeyword(tokens[pos], "limit")) {
            pos += 1;
            if (pos < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos], "all")) {
                pos += 1;
                limit = null;
            } else {
                limit = try scalarDefaultUnsignedToken(tokens, &pos);
            }
            continue;
        }
        if (scalarDefaultTokenMatchesKeyword(tokens[pos], "offset")) {
            pos += 1;
            offset = try scalarDefaultUnsignedToken(tokens, &pos);
            if (pos < tokens.len and (scalarDefaultTokenMatchesKeyword(tokens[pos], "row") or scalarDefaultTokenMatchesKeyword(tokens[pos], "rows"))) pos += 1;
            continue;
        }
        if (scalarDefaultTokenMatchesKeyword(tokens[pos], "fetch")) {
            pos += 1;
            try expectScalarDefaultFetchDirection(tokens, &pos);
            limit = if (pos < tokens.len and scalarDefaultTokenKindEql(tokens[pos], "number"))
                try scalarDefaultUnsignedToken(tokens, &pos)
            else
                1;
            if (pos < tokens.len and (scalarDefaultTokenMatchesKeyword(tokens[pos], "row") or scalarDefaultTokenMatchesKeyword(tokens[pos], "rows"))) {
                pos += 1;
            } else return error.UnsupportedSqlShape;
            try expectScalarDefaultKeyword(tokens, &pos, "only");
            continue;
        }
        return error.UnsupportedSqlShape;
    }
    if (pos != tokens.len) return error.UnsupportedSqlShape;

    const owned_order_by = try order_by.toOwnedSlice(alloc);
    var order_transferred = false;
    errdefer if (!order_transferred) freeScalarDefaultOrderBy(alloc, owned_order_by);
    if (distinct and (owned_order_by.len == 0 or !std.mem.eql(u8, owned_order_by[0].field, output_field))) return error.UnsupportedSqlShape;
    const plan = switch (projection) {
        .field => try ownedScalarSubqueryDefaultPlanAlloc(
            alloc,
            table_name,
            output_field,
            limit,
            offset,
            where_plan.predicates,
            where_plan.in_predicates,
            where_plan.or_predicates,
            where_plan.not_predicates,
            distinct,
            owned_order_by,
        ),
        .simple_expression => |projection_expression| try ownedScalarSubqueryDefaultExpressionPlanAlloc(
            alloc,
            table_name,
            projection_expression.kind,
            projection_expression.output,
            scalarDefaultNormalizeFieldNameForBinding(projection_expression.raw_field, source_binding),
            projection_expression.value_json,
            limit,
            offset,
            where_plan.predicates,
            where_plan.in_predicates,
            where_plan.or_predicates,
            where_plan.not_predicates,
            owned_order_by,
        ),
    };
    where_transferred = true;
    order_transferred = true;
    return plan;
}

fn scalarSubqueryDefaultNormalizedQueryJsonAlloc(
    alloc: std.mem.Allocator,
    plan: ScalarSubqueryDefaultPlan,
) ![]u8 {
    if (plan.table_name.len == 0 or plan.query.select_all) return error.UnsupportedSqlShape;
    if ((plan.query.select.len == 0) == (plan.query.expressions.len == 0)) return error.UnsupportedSqlShape;
    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.writeByte('{');
    try writer.print("\"table\":{f}", .{std.json.fmt(plan.table_name, .{})});
    if (plan.query.select.len != 0) {
        try writer.writeAll(",\"select\":[");
        for (plan.query.select, 0..) |field, i| {
            if (field.len == 0) return error.UnsupportedSqlShape;
            if (i > 0) try writer.writeByte(',');
            try writer.print("{f}", .{std.json.fmt(field, .{})});
        }
        try writer.writeByte(']');
    }
    if (plan.query.expressions.len != 0) {
        try writer.writeAll(",\"expressions\":[");
        for (plan.query.expressions, 0..) |projection, i| {
            if (projection.output.len == 0) return error.UnsupportedSqlShape;
            if (i > 0) try writer.writeByte(',');
            try writer.print("{{\"as\":{f},\"expr\":", .{std.json.fmt(projection.output, .{})});
            try expr_type.writeRowExpressionJson(writer, projection.expression);
            try writer.writeByte('}');
        }
        try writer.writeByte(']');
    }
    if (plan.query.distinct_on.len != 0) {
        try writer.writeAll(",\"distinct_on\":[");
        for (plan.query.distinct_on, 0..) |field, i| {
            if (field.len == 0) return error.UnsupportedSqlShape;
            if (i > 0) try writer.writeByte(',');
            try writer.print("{f}", .{std.json.fmt(field, .{})});
        }
        try writer.writeByte(']');
    }
    if (plan.query.predicates.len != 0 or plan.query.in_predicates.len != 0 or plan.query.or_predicates.len != 0 or plan.query.not_predicates.len != 0) {
        try writer.writeAll(",\"where\":");
        try encodeRowsMutationSourceWhere(writer, plan.query);
    }
    if (plan.query.order_by.len != 0) {
        try writer.writeAll(",\"order_by\":[");
        for (plan.query.order_by, 0..) |order, i| {
            if (order.expression != null or order.field.len == 0) return error.UnsupportedSqlShape;
            if (i > 0) try writer.writeByte(',');
            try writer.writeByte('{');
            try writer.print("\"field\":{f}", .{std.json.fmt(order.field, .{})});
            if (order.direction == .desc) try writer.writeAll(",\"direction\":\"desc\"");
            if (order.null_test) |null_test| {
                try writer.writeAll(",\"null_test\":");
                try writer.print("{f}", .{std.json.fmt(rowsQueryOrderNullTestText(null_test), .{})});
            }
            try writer.writeByte('}');
        }
        try writer.writeByte(']');
    }
    if (plan.query.limit) |limit| try writer.print(",\"limit\":{d}", .{limit});
    if (plan.query.offset != 0) try writer.print(",\"offset\":{d}", .{plan.query.offset});
    try writer.writeByte('}');
    return try out.toOwnedSlice();
}

fn scalarDefaultTokenizedProjection(alloc: std.mem.Allocator, tokens: []const std.json.Value, pos: *usize) !ScalarDefaultTokenizedProjection {
    const first = try scalarDefaultIdentifierTokenText(tokens, pos.*);
    pos.* += 1;
    if (pos.* < tokens.len and scalarDefaultTokenKindEql(tokens[pos.*], "lparen")) {
        const kind = scalarDefaultSimpleExpressionKind(first) orelse return error.UnsupportedSqlShape;
        pos.* += 1;
        const raw_field = try scalarDefaultIdentifierTokenText(tokens, pos.*);
        pos.* += 1;
        const value_json: ?[]const u8 = if (kind == .concat) blk: {
            if (pos.* >= tokens.len or !scalarDefaultTokenKindEql(tokens[pos.*], "comma")) return error.UnsupportedSqlShape;
            pos.* += 1;
            break :blk try scalarDefaultValueTokenJsonAlloc(alloc, tokens, pos);
        } else null;
        var value_transferred = false;
        errdefer if (!value_transferred) if (value_json) |json| alloc.free(@constCast(json));
        if (pos.* >= tokens.len or !scalarDefaultTokenKindEql(tokens[pos.*], "rparen")) return error.UnsupportedSqlShape;
        pos.* += 1;
        const alias = try scalarDefaultConsumeOptionalProjectionAlias(tokens, pos);
        value_transferred = true;
        return .{ .simple_expression = .{
            .kind = kind,
            .raw_field = raw_field,
            .output = if (alias.len != 0) alias else expr_type.rowExpressionDefaultOutputName(kind),
            .value_json = value_json,
        } };
    }
    return .{ .field = .{
        .raw_field = first,
        .alias = try scalarDefaultConsumeOptionalProjectionAlias(tokens, pos),
    } };
}

fn scalarDefaultFreeTokenizedProjection(alloc: std.mem.Allocator, projection: ScalarDefaultTokenizedProjection) void {
    switch (projection) {
        .field => {},
        .simple_expression => |expression| if (expression.value_json) |value_json| alloc.free(@constCast(value_json)),
    }
}

fn scalarDefaultAppendTokenizedPredicatesAlloc(
    alloc: std.mem.Allocator,
    tokens: []const std.json.Value,
    pos: *usize,
    source_binding: ScalarDefaultSourceBinding,
    predicates: *std.ArrayListUnmanaged(runtime_schema.RelationalCheck),
    in_predicates: ?*std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate),
    not_groups: ?*std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
) !void {
    if (pos.* < tokens.len and scalarDefaultTokenKindEql(tokens[pos.*], "lparen")) {
        pos.* += 1;
        try scalarDefaultAppendTokenizedPredicatesAlloc(alloc, tokens, pos, source_binding, predicates, in_predicates, not_groups);
        if (pos.* >= tokens.len or !scalarDefaultTokenKindEql(tokens[pos.*], "rparen")) return error.UnsupportedSqlShape;
        pos.* += 1;
        return;
    }
    const field = try alloc.dupe(u8, scalarDefaultNormalizeFieldNameForBinding(try scalarDefaultIdentifierTokenText(tokens, pos.*), source_binding));
    var field_transferred = false;
    errdefer if (!field_transferred) alloc.free(field);
    pos.* += 1;
    if (pos.* < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos.*], "not")) {
        pos.* += 1;
        if (pos.* < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos.*], "between")) {
            pos.* += 1;
            const target_not_groups = not_groups orelse return error.UnsupportedSqlShape;
            field_transferred = true;
            try scalarDefaultAppendTokenizedBetweenNotGroupAlloc(alloc, tokens, pos, field, target_not_groups);
            return;
        }
        if (pos.* < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos.*], "in")) {
            pos.* += 1;
            const target_in_predicates = in_predicates orelse return error.UnsupportedSqlShape;
            field_transferred = true;
            try scalarDefaultAppendTokenizedInPredicateAlloc(alloc, tokens, pos, field, true, target_in_predicates);
            return;
        }
        return error.UnsupportedSqlShape;
    }
    if (pos.* < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos.*], "in")) {
        pos.* += 1;
        const target_in_predicates = in_predicates orelse return error.UnsupportedSqlShape;
        field_transferred = true;
        try scalarDefaultAppendTokenizedInPredicateAlloc(alloc, tokens, pos, field, false, target_in_predicates);
        return;
    }
    if (pos.* < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos.*], "between")) {
        pos.* += 1;
        field_transferred = true;
        try scalarDefaultAppendTokenizedBetweenPredicatesAlloc(alloc, tokens, pos, field, predicates);
        return;
    }
    field_transferred = true;
    const predicate = try scalarDefaultTokenizedPredicateAfterFieldAlloc(alloc, tokens, pos, field);
    var predicate_transferred = false;
    errdefer if (!predicate_transferred) {
        const predicate_slice = [_]runtime_schema.RelationalCheck{predicate};
        freeScalarDefaultPredicateValues(alloc, predicate_slice[0..]);
    };
    try predicates.append(alloc, predicate);
    predicate_transferred = true;
}

fn scalarDefaultAppendTokenizedInPredicateAlloc(
    alloc: std.mem.Allocator,
    tokens: []const std.json.Value,
    pos: *usize,
    field: []const u8,
    negated: bool,
    in_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate),
) !void {
    var field_transferred = false;
    errdefer if (!field_transferred) alloc.free(@constCast(field));
    const values_json = try scalarDefaultTokenizedValueListJsonAlloc(alloc, tokens, pos);
    var values_transferred = false;
    errdefer if (!values_transferred) alloc.free(values_json);
    try in_predicates.append(alloc, .{ .field = field, .values_json = values_json, .negated = negated });
    field_transferred = true;
    values_transferred = true;
}

fn scalarDefaultAppendTokenizedBetweenNotGroupAlloc(
    alloc: std.mem.Allocator,
    tokens: []const std.json.Value,
    pos: *usize,
    field: []const u8,
    groups: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
) !void {
    var current = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    defer current.deinit(alloc);
    errdefer freeScalarDefaultPredicateValues(alloc, current.items);

    var field_transferred = false;
    errdefer if (!field_transferred) alloc.free(@constCast(field));
    field_transferred = true;
    try scalarDefaultAppendTokenizedBetweenPredicatesAlloc(alloc, tokens, pos, field, &current);

    const predicates = try current.toOwnedSlice(alloc);
    current = .empty;
    var predicates_transferred = false;
    errdefer if (!predicates_transferred) freeScalarDefaultPredicates(alloc, predicates);
    try groups.append(alloc, .{ .predicates = predicates });
    predicates_transferred = true;
}

fn scalarDefaultAppendTokenizedBetweenPredicatesAlloc(
    alloc: std.mem.Allocator,
    tokens: []const std.json.Value,
    pos: *usize,
    field: []const u8,
    predicates: *std.ArrayListUnmanaged(runtime_schema.RelationalCheck),
) !void {
    var field_transferred = false;
    errdefer if (!field_transferred) alloc.free(@constCast(field));

    if (pos.* < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos.*], "symmetric")) return error.UnsupportedSqlShape;
    if (pos.* < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos.*], "asymmetric")) pos.* += 1;

    const lower_value_json = try scalarDefaultValueTokenJsonAlloc(alloc, tokens, pos);
    var lower_value_transferred = false;
    errdefer if (!lower_value_transferred) alloc.free(lower_value_json);
    try expectScalarDefaultKeyword(tokens, pos, "and");
    const upper_value_json = try scalarDefaultValueTokenJsonAlloc(alloc, tokens, pos);
    var upper_value_transferred = false;
    errdefer if (!upper_value_transferred) alloc.free(upper_value_json);
    const upper_field = try alloc.dupe(u8, field);
    var upper_field_transferred = false;
    errdefer if (!upper_field_transferred) alloc.free(upper_field);

    try predicates.append(alloc, .{
        .name = "",
        .field = field,
        .op = .gte,
        .value_json = lower_value_json,
    });
    field_transferred = true;
    lower_value_transferred = true;
    try predicates.append(alloc, .{
        .name = "",
        .field = upper_field,
        .op = .lte,
        .value_json = upper_value_json,
    });
    upper_field_transferred = true;
    upper_value_transferred = true;
}

fn scalarDefaultTokenizedPredicateAfterFieldAlloc(
    alloc: std.mem.Allocator,
    tokens: []const std.json.Value,
    pos: *usize,
    field: []const u8,
) !runtime_schema.RelationalCheck {
    var field_transferred = false;
    errdefer if (!field_transferred) alloc.free(@constCast(field));
    var precomputed_value_json: ?[]const u8 = null;
    var precomputed_transferred = false;
    errdefer if (!precomputed_transferred) if (precomputed_value_json) |json| alloc.free(@constCast(json));
    const op: runtime_schema.RelationalCheckOp = if (pos.* < tokens.len and scalarDefaultTokenKindEql(tokens[pos.*], "eq")) blk: {
        pos.* += 1;
        break :blk .eq;
    } else if (pos.* < tokens.len and scalarDefaultTokenKindEql(tokens[pos.*], "neq")) blk: {
        pos.* += 1;
        break :blk .ne;
    } else if (pos.* < tokens.len and scalarDefaultTokenKindEql(tokens[pos.*], "gt")) blk: {
        pos.* += 1;
        break :blk .gt;
    } else if (pos.* < tokens.len and scalarDefaultTokenKindEql(tokens[pos.*], "gte")) blk: {
        pos.* += 1;
        break :blk .gte;
    } else if (pos.* < tokens.len and scalarDefaultTokenKindEql(tokens[pos.*], "lt")) blk: {
        pos.* += 1;
        break :blk .lt;
    } else if (pos.* < tokens.len and scalarDefaultTokenKindEql(tokens[pos.*], "lte")) blk: {
        pos.* += 1;
        break :blk .lte;
    } else if (pos.* < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos.*], "is")) blk: {
        pos.* += 1;
        const negated = if (pos.* < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos.*], "not")) negated: {
            pos.* += 1;
            break :negated true;
        } else false;
        if (pos.* < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos.*], "null")) {
            pos.* += 1;
            break :blk if (negated) .is_not_null else .is_null;
        }
        if (pos.* < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos.*], "unknown")) {
            pos.* += 1;
            break :blk if (negated) .is_not_null else .is_null;
        }
        if (pos.* < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos.*], "distinct")) {
            pos.* += 1;
            try expectScalarDefaultKeyword(tokens, pos, "from");
            break :blk if (negated) .is_not_distinct else .is_distinct;
        }
        if (!negated and pos.* < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos.*], "true")) {
            pos.* += 1;
            precomputed_value_json = try alloc.dupe(u8, "true");
            break :blk .eq;
        }
        if (!negated and pos.* < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos.*], "false")) {
            pos.* += 1;
            precomputed_value_json = try alloc.dupe(u8, "false");
            break :blk .eq;
        }
        return error.UnsupportedSqlShape;
    } else return error.UnsupportedSqlShape;
    const value_json: ?[]const u8 = if (precomputed_value_json) |json| blk: {
        precomputed_transferred = true;
        break :blk json;
    } else if (rowsQueryPredicateNeedsValue(op))
        try scalarDefaultValueTokenJsonAlloc(alloc, tokens, pos)
    else
        null;
    var value_transferred = false;
    errdefer if (!value_transferred) if (value_json) |json| alloc.free(json);
    field_transferred = true;
    value_transferred = true;
    return .{
        .name = "",
        .field = field,
        .op = op,
        .value_json = value_json,
    };
}

fn scalarDefaultTokenizedWhereAlloc(
    alloc: std.mem.Allocator,
    tokens: []const std.json.Value,
    pos: *usize,
    source_binding: ScalarDefaultSourceBinding,
) !ScalarDefaultWherePlan {
    var current = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    defer current.deinit(alloc);
    var current_in = std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate).empty;
    defer current_in.deinit(alloc);
    var groups = std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup).empty;
    defer groups.deinit(alloc);
    var not_groups = std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup).empty;
    defer not_groups.deinit(alloc);
    var saw_or = false;

    errdefer {
        freeScalarDefaultPredicateValues(alloc, current.items);
        freeRowsQueryInPredicatesNoSlice(alloc, current_in.items);
        freeScalarDefaultPredicateGroupValues(alloc, groups.items);
        freeScalarDefaultPredicateGroupValues(alloc, not_groups.items);
    }

    while (true) {
        if (pos.* < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos.*], "not")) {
            if (saw_or) return error.UnsupportedSqlShape;
            pos.* += 1;
            try scalarDefaultAppendTokenizedNotGroup(alloc, tokens, pos, source_binding, &not_groups);
        } else {
            try scalarDefaultAppendTokenizedPredicatesAlloc(alloc, tokens, pos, source_binding, &current, &current_in, if (saw_or) null else &not_groups);
        }
        if (pos.* < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos.*], "and")) {
            pos.* += 1;
            continue;
        }
        if (pos.* < tokens.len and scalarDefaultTokenMatchesKeyword(tokens[pos.*], "or")) {
            if (not_groups.items.len != 0) return error.UnsupportedSqlShape;
            if (current_in.items.len != 0) return error.UnsupportedSqlShape;
            saw_or = true;
            pos.* += 1;
            try scalarDefaultFlushTokenizedWhereGroup(alloc, &current, &groups);
            continue;
        }
        break;
    }

    if (!saw_or) {
        const owned_predicates = try current.toOwnedSlice(alloc);
        current = .empty;
        var predicates_transferred = false;
        errdefer if (!predicates_transferred) freeScalarDefaultPredicates(alloc, owned_predicates);
        const owned_in_predicates = try current_in.toOwnedSlice(alloc);
        current_in = .empty;
        var in_predicates_transferred = false;
        errdefer if (!in_predicates_transferred) freeRowsQueryInPredicates(alloc, owned_in_predicates);
        const owned_not_groups = try not_groups.toOwnedSlice(alloc);
        not_groups = .empty;
        predicates_transferred = true;
        in_predicates_transferred = true;
        return .{ .predicates = owned_predicates, .in_predicates = owned_in_predicates, .not_predicates = owned_not_groups };
    }
    try scalarDefaultFlushTokenizedWhereGroup(alloc, &current, &groups);
    const owned_groups = try groups.toOwnedSlice(alloc);
    groups = .empty;
    return .{ .or_predicates = owned_groups };
}

fn scalarDefaultAppendTokenizedNotGroup(
    alloc: std.mem.Allocator,
    tokens: []const std.json.Value,
    pos: *usize,
    source_binding: ScalarDefaultSourceBinding,
    groups: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
) !void {
    var current = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    defer current.deinit(alloc);
    errdefer freeScalarDefaultPredicateValues(alloc, current.items);
    try scalarDefaultAppendTokenizedPredicatesAlloc(alloc, tokens, pos, source_binding, &current, null, null);
    const predicates = try current.toOwnedSlice(alloc);
    current = .empty;
    var predicates_transferred = false;
    errdefer if (!predicates_transferred) freeScalarDefaultPredicates(alloc, predicates);
    try groups.append(alloc, .{ .predicates = predicates });
    predicates_transferred = true;
}

fn scalarDefaultFlushTokenizedWhereGroup(
    alloc: std.mem.Allocator,
    current: *std.ArrayListUnmanaged(runtime_schema.RelationalCheck),
    groups: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
) !void {
    if (current.items.len == 0) return error.InvalidRowsRequest;
    const predicates = try current.toOwnedSlice(alloc);
    current.* = .empty;
    var predicates_transferred = false;
    errdefer if (!predicates_transferred) freeScalarDefaultPredicates(alloc, predicates);
    try groups.append(alloc, .{ .predicates = predicates });
    predicates_transferred = true;
}

fn ownedScalarSubqueryDefaultPlanAlloc(
    alloc: std.mem.Allocator,
    table_name: []const u8,
    output_field: []const u8,
    limit: ?u32,
    offset: u32,
    predicates: []const runtime_schema.RelationalCheck,
    in_predicates: []const db_mod.types.RelationalRowsInPredicate,
    or_predicates: []const db_mod.types.RelationalRowsPredicateGroup,
    not_predicates: []const db_mod.types.RelationalRowsPredicateGroup,
    distinct: bool,
    order_by: []const db_mod.types.RelationalRowsQueryOrder,
) !ScalarSubqueryDefaultPlan {
    const owned_table = try alloc.dupe(u8, table_name);
    var table_transferred = false;
    errdefer if (!table_transferred) alloc.free(owned_table);
    const owned_output = try alloc.dupe(u8, output_field);
    var output_transferred = false;
    errdefer if (!output_transferred) alloc.free(owned_output);
    const select = try alloc.alloc([]const u8, 1);
    var select_transferred = false;
    errdefer if (!select_transferred) alloc.free(select);
    select[0] = try alloc.dupe(u8, output_field);
    var select_field_transferred = false;
    errdefer if (!select_field_transferred) alloc.free(@constCast(select[0]));
    const distinct_on = if (distinct) distinct_on: {
        const fields = try alloc.alloc([]const u8, 1);
        var fields_transferred = false;
        errdefer if (!fields_transferred) alloc.free(fields);
        fields[0] = try alloc.dupe(u8, output_field);
        fields_transferred = true;
        break :distinct_on fields;
    } else &.{};
    var distinct_slice_transferred = false;
    errdefer if (!distinct_slice_transferred and distinct_on.len != 0) alloc.free(@constCast(distinct_on.ptr)[0..distinct_on.len]);
    var distinct_field_transferred = false;
    errdefer if (!distinct_field_transferred and distinct_on.len != 0) alloc.free(@constCast(distinct_on[0]));

    table_transferred = true;
    output_transferred = true;
    select_transferred = true;
    select_field_transferred = true;
    distinct_slice_transferred = true;
    distinct_field_transferred = true;
    return .{
        .table_name = owned_table,
        .output_field = owned_output,
        .query = .{
            .select = select,
            .select_all = false,
            .predicates = predicates,
            .in_predicates = in_predicates,
            .or_predicates = or_predicates,
            .not_predicates = not_predicates,
            .distinct_on = distinct_on,
            .order_by = order_by,
            .limit = limit,
            .offset = offset,
        },
    };
}

fn ownedScalarSubqueryDefaultExpressionPlanAlloc(
    alloc: std.mem.Allocator,
    table_name: []const u8,
    expression_kind: db_mod.types.RelationalRowsExpressionKind,
    output_field: []const u8,
    source_field: []const u8,
    value_json: ?[]const u8,
    limit: ?u32,
    offset: u32,
    predicates: []const runtime_schema.RelationalCheck,
    in_predicates: []const db_mod.types.RelationalRowsInPredicate,
    or_predicates: []const db_mod.types.RelationalRowsPredicateGroup,
    not_predicates: []const db_mod.types.RelationalRowsPredicateGroup,
    order_by: []const db_mod.types.RelationalRowsQueryOrder,
) !ScalarSubqueryDefaultPlan {
    if (output_field.len == 0 or source_field.len == 0) return error.UnsupportedSqlShape;
    const operands_len: usize = if (value_json != null) 2 else 1;
    const operands = try alloc.alloc(db_mod.types.RelationalRowsExpression, operands_len);
    var operands_transferred = false;
    errdefer if (!operands_transferred) alloc.free(operands);
    const operand_field = try alloc.dupe(u8, source_field);
    var operand_field_transferred = false;
    errdefer if (!operand_field_transferred) alloc.free(operand_field);
    const operand_value_json = if (value_json) |json| try alloc.dupe(u8, json) else "";
    var operand_value_transferred = false;
    errdefer if (!operand_value_transferred and operand_value_json.len != 0) alloc.free(operand_value_json);

    operands[0] = .{ .kind = .field, .field = operand_field };
    operand_field_transferred = true;
    if (value_json != null) {
        operands[1] = .{ .kind = .value, .value_json = operand_value_json };
        operand_value_transferred = true;
    }
    operands_transferred = true;
    const expression: db_mod.types.RelationalRowsExpression = .{ .kind = expression_kind, .operands = operands };
    var expression_transferred = false;
    errdefer if (!expression_transferred) freeRowsQueryExpression(alloc, expression);
    const plan = try ownedScalarSubqueryDefaultExpressionTreePlanAlloc(
        alloc,
        table_name,
        output_field,
        expression,
        limit,
        offset,
        predicates,
        in_predicates,
        or_predicates,
        not_predicates,
        order_by,
    );
    expression_transferred = true;
    return plan;
}

fn ownedScalarSubqueryDefaultExpressionTreePlanAlloc(
    alloc: std.mem.Allocator,
    table_name: []const u8,
    output_field: []const u8,
    expression: db_mod.types.RelationalRowsExpression,
    limit: ?u32,
    offset: u32,
    predicates: []const runtime_schema.RelationalCheck,
    in_predicates: []const db_mod.types.RelationalRowsInPredicate,
    or_predicates: []const db_mod.types.RelationalRowsPredicateGroup,
    not_predicates: []const db_mod.types.RelationalRowsPredicateGroup,
    order_by: []const db_mod.types.RelationalRowsQueryOrder,
) !ScalarSubqueryDefaultPlan {
    if (output_field.len == 0) return error.UnsupportedSqlShape;
    const owned_table = try alloc.dupe(u8, table_name);
    var table_transferred = false;
    errdefer if (!table_transferred) alloc.free(owned_table);
    const owned_output = try alloc.dupe(u8, output_field);
    var output_transferred = false;
    errdefer if (!output_transferred) alloc.free(owned_output);
    const expressions = try alloc.alloc(db_mod.types.RelationalRowsExpressionProjection, 1);
    var expressions_transferred = false;
    errdefer if (!expressions_transferred) alloc.free(expressions);
    const projection_output = try alloc.dupe(u8, output_field);
    var projection_output_transferred = false;
    errdefer if (!projection_output_transferred) alloc.free(projection_output);
    expressions[0] = .{
        .output = projection_output,
        .expression = expression,
    };
    projection_output_transferred = true;
    table_transferred = true;
    output_transferred = true;
    expressions_transferred = true;
    return .{
        .table_name = owned_table,
        .output_field = owned_output,
        .query = .{
            .select = &.{},
            .select_all = false,
            .predicates = predicates,
            .in_predicates = in_predicates,
            .or_predicates = or_predicates,
            .not_predicates = not_predicates,
            .expressions = expressions,
            .order_by = order_by,
            .limit = limit,
            .offset = offset,
        },
    };
}

fn freeScalarDefaultOrderBy(
    alloc: std.mem.Allocator,
    order_by: []const db_mod.types.RelationalRowsQueryOrder,
) void {
    for (order_by) |order| {
        if (order.field.len > 0) alloc.free(@constCast(order.field));
    }
    if (order_by.len > 0) alloc.free(@constCast(order_by.ptr)[0..order_by.len]);
}

fn freeScalarDefaultPredicates(
    alloc: std.mem.Allocator,
    predicates: []const runtime_schema.RelationalCheck,
) void {
    freeScalarDefaultPredicateValues(alloc, predicates);
    if (predicates.len > 0) alloc.free(@constCast(predicates.ptr)[0..predicates.len]);
}

fn freeScalarDefaultPredicateValues(
    alloc: std.mem.Allocator,
    predicates: []const runtime_schema.RelationalCheck,
) void {
    for (predicates) |predicate| {
        if (predicate.field.len > 0) alloc.free(@constCast(predicate.field));
        if (predicate.value_json) |value| alloc.free(@constCast(value));
        if (predicate.collation) |collation| alloc.free(@constCast(collation));
    }
}

fn freeScalarDefaultWherePlan(
    alloc: std.mem.Allocator,
    where_plan: ScalarDefaultWherePlan,
) void {
    freeScalarDefaultPredicates(alloc, where_plan.predicates);
    freeRowsQueryInPredicates(alloc, where_plan.in_predicates);
    freeScalarDefaultPredicateGroups(alloc, where_plan.or_predicates);
    freeScalarDefaultPredicateGroups(alloc, where_plan.not_predicates);
}

fn freeScalarDefaultPredicateGroups(
    alloc: std.mem.Allocator,
    groups: []const db_mod.types.RelationalRowsPredicateGroup,
) void {
    freeScalarDefaultPredicateGroupValues(alloc, groups);
    if (groups.len > 0) alloc.free(@constCast(groups.ptr)[0..groups.len]);
}

fn freeScalarDefaultPredicateGroupValues(
    alloc: std.mem.Allocator,
    groups: []const db_mod.types.RelationalRowsPredicateGroup,
) void {
    for (groups) |group| {
        freeScalarDefaultPredicates(alloc, group.predicates);
    }
}

fn expectScalarDefaultKeyword(tokens: []const std.json.Value, pos: *usize, keyword: []const u8) !void {
    if (pos.* >= tokens.len or !scalarDefaultTokenMatchesKeyword(tokens[pos.*], keyword)) return error.UnsupportedSqlShape;
    pos.* += 1;
}

fn expectScalarDefaultFetchDirection(tokens: []const std.json.Value, pos: *usize) !void {
    if (pos.* >= tokens.len) return error.UnsupportedSqlShape;
    if (scalarDefaultTokenMatchesKeyword(tokens[pos.*], "first") or scalarDefaultTokenMatchesKeyword(tokens[pos.*], "next")) {
        pos.* += 1;
        return;
    }
    return error.UnsupportedSqlShape;
}

fn scalarDefaultTokenMatchesKeyword(token: std.json.Value, keyword: []const u8) bool {
    if (token != .object) return false;
    if (!scalarDefaultTokenKindEql(token, "identifier")) return false;
    const keyword_value = token.object.get("keyword") orelse return false;
    if (keyword_value != .string or !std.mem.eql(u8, keyword_value.string, keyword)) return false;
    return std.ascii.eqlIgnoreCase(scalarDefaultTokenText(token), keyword);
}

fn scalarDefaultTokenKindEql(token: std.json.Value, kind: []const u8) bool {
    if (token != .object) return false;
    const kind_value = token.object.get("kind") orelse return false;
    if (kind_value != .string or !std.mem.eql(u8, kind_value.string, kind)) return false;
    return scalarDefaultTokenTextMatchesKind(kind, scalarDefaultTokenText(token));
}

fn scalarDefaultTokenTextMatchesKind(kind: []const u8, text: []const u8) bool {
    if (std.mem.eql(u8, kind, "identifier") or
        std.mem.eql(u8, kind, "number") or
        std.mem.eql(u8, kind, "string"))
    {
        return text.len != 0;
    }
    if (std.mem.eql(u8, kind, "lparen")) return std.mem.eql(u8, text, "(");
    if (std.mem.eql(u8, kind, "rparen")) return std.mem.eql(u8, text, ")");
    if (std.mem.eql(u8, kind, "comma")) return std.mem.eql(u8, text, ",");
    if (std.mem.eql(u8, kind, "semicolon")) return std.mem.eql(u8, text, ";");
    if (std.mem.eql(u8, kind, "eq")) return std.mem.eql(u8, text, "=");
    if (std.mem.eql(u8, kind, "neq")) return std.mem.eql(u8, text, "!=") or std.mem.eql(u8, text, "<>");
    if (std.mem.eql(u8, kind, "gt")) return std.mem.eql(u8, text, ">");
    if (std.mem.eql(u8, kind, "gte")) return std.mem.eql(u8, text, ">=");
    if (std.mem.eql(u8, kind, "lt")) return std.mem.eql(u8, text, "<");
    if (std.mem.eql(u8, kind, "lte")) return std.mem.eql(u8, text, "<=");
    if (std.mem.eql(u8, kind, "plus")) return std.mem.eql(u8, text, "+");
    if (std.mem.eql(u8, kind, "minus")) return std.mem.eql(u8, text, "-");
    return true;
}

fn scalarDefaultIdentifierTokenText(tokens: []const std.json.Value, pos: usize) ![]const u8 {
    if (pos >= tokens.len) return error.UnsupportedSqlShape;
    const token = tokens[pos];
    if (!scalarDefaultTokenKindEql(token, "identifier")) return error.UnsupportedSqlShape;
    const text = scalarDefaultTokenText(token);
    if (text.len == 0) return error.UnsupportedSqlShape;
    return text;
}

fn scalarDefaultOrderFieldName(
    tokens: []const std.json.Value,
    pos: usize,
    source_binding: ScalarDefaultSourceBinding,
    output_field: []const u8,
    projection_alias: []const u8,
) ![]const u8 {
    if (pos >= tokens.len) return error.UnsupportedSqlShape;
    if (scalarDefaultTokenKindEql(tokens[pos], "number")) {
        const text = scalarDefaultTokenText(tokens[pos]);
        if (!std.mem.eql(u8, text, "1")) return error.UnsupportedSqlShape;
        return output_field;
    }
    const field = try scalarDefaultIdentifierTokenText(tokens, pos);
    if (projection_alias.len != 0 and std.mem.eql(u8, field, projection_alias)) return output_field;
    return scalarDefaultNormalizeFieldNameForBinding(field, source_binding);
}

fn scalarDefaultConsumeOptionalProjectionAlias(tokens: []const std.json.Value, pos: *usize) ![]const u8 {
    if (pos.* >= tokens.len or !scalarDefaultTokenMatchesKeyword(tokens[pos.*], "as")) return "";
    pos.* += 1;
    const alias = try scalarDefaultIdentifierTokenText(tokens, pos.*);
    pos.* += 1;
    return alias;
}

fn scalarDefaultConsumeOptionalSourceAlias(tokens: []const std.json.Value, pos: *usize) ![]const u8 {
    if (pos.* >= tokens.len) return "";
    if (scalarDefaultTokenMatchesKeyword(tokens[pos.*], "as")) {
        pos.* += 1;
        const alias = try scalarDefaultIdentifierTokenText(tokens, pos.*);
        if (!scalarDefaultAliasIsValid(alias) or scalarDefaultTokenKeyword(tokens[pos.*]) != null) return error.UnsupportedSqlShape;
        pos.* += 1;
        return alias;
    }
    if (!scalarDefaultTokenKindEql(tokens[pos.*], "identifier") or scalarDefaultTokenKeyword(tokens[pos.*]) != null) return "";
    const alias = try scalarDefaultIdentifierTokenText(tokens, pos.*);
    if (!scalarDefaultAliasIsValid(alias)) return error.UnsupportedSqlShape;
    pos.* += 1;
    return alias;
}

fn scalarDefaultStructuredAlias(maybe_value: ?std.json.Value) ![]const u8 {
    const value = maybe_value orelse return "";
    if (value != .string or !scalarDefaultAliasIsValid(value.string)) return error.InvalidRowsRequest;
    return value.string;
}

fn scalarDefaultAliasIsValid(alias: []const u8) bool {
    return alias.len != 0 and std.mem.indexOfScalar(u8, alias, '.') == null;
}

fn scalarDefaultTokenKeyword(token: std.json.Value) ?[]const u8 {
    if (token != .object) return null;
    const keyword_value = token.object.get("keyword") orelse return null;
    if (keyword_value != .string) return null;
    return keyword_value.string;
}

fn scalarDefaultNormalizeTableName(name: []const u8) []const u8 {
    const public_member = scalarDefaultStripQualifier(name, "public") orelse return name;
    if (std.mem.indexOfScalar(u8, public_member, '.') != null or public_member.len == 0) return name;
    return public_member;
}

fn scalarDefaultNormalizeFieldNameForBinding(name: []const u8, source_binding: ScalarDefaultSourceBinding) []const u8 {
    if (scalarDefaultStripQualifier(name, source_binding.alias)) |member| {
        if (member.len != 0) return member;
    }
    return scalarDefaultNormalizeFieldName(name, source_binding.table_name);
}

fn scalarDefaultNormalizeFieldName(name: []const u8, table_name: []const u8) []const u8 {
    if (scalarDefaultStripQualifier(name, table_name)) |member| {
        if (member.len != 0) return member;
    }
    if (scalarDefaultStripQualifier(name, "public")) |public_member| {
        if (scalarDefaultStripQualifier(public_member, table_name)) |member| {
            if (member.len != 0) return member;
        }
    }
    return name;
}

fn scalarDefaultStripQualifier(name: []const u8, qualifier: []const u8) ?[]const u8 {
    if (qualifier.len == 0 or name.len <= qualifier.len + 1) return null;
    if (name[qualifier.len] != '.') return null;
    if (!std.ascii.eqlIgnoreCase(name[0..qualifier.len], qualifier)) return null;
    return name[qualifier.len + 1 ..];
}

fn scalarDefaultValueTokenJsonAlloc(
    alloc: std.mem.Allocator,
    tokens: []const std.json.Value,
    pos: *usize,
) ![]const u8 {
    if (pos.* >= tokens.len) return error.UnsupportedSqlShape;
    if (scalarDefaultTokenKindEql(tokens[pos.*], "string")) {
        const text = scalarDefaultTokenText(tokens[pos.*]);
        pos.* += 1;
        return try std.json.Stringify.valueAlloc(alloc, text, .{});
    }
    if (scalarDefaultTokenKindEql(tokens[pos.*], "number")) {
        const text = scalarDefaultTokenText(tokens[pos.*]);
        pos.* += 1;
        return try alloc.dupe(u8, text);
    }
    if (scalarDefaultTokenKindEql(tokens[pos.*], "minus") or scalarDefaultTokenKindEql(tokens[pos.*], "plus")) {
        const negative = scalarDefaultTokenKindEql(tokens[pos.*], "minus");
        pos.* += 1;
        if (pos.* >= tokens.len or !scalarDefaultTokenKindEql(tokens[pos.*], "number")) return error.UnsupportedSqlShape;
        const text = scalarDefaultTokenText(tokens[pos.*]);
        pos.* += 1;
        return if (negative) try std.fmt.allocPrint(alloc, "-{s}", .{text}) else try alloc.dupe(u8, text);
    }
    if (scalarDefaultTokenMatchesKeyword(tokens[pos.*], "true")) {
        pos.* += 1;
        return try alloc.dupe(u8, "true");
    }
    if (scalarDefaultTokenMatchesKeyword(tokens[pos.*], "false")) {
        pos.* += 1;
        return try alloc.dupe(u8, "false");
    }
    if (scalarDefaultTokenMatchesKeyword(tokens[pos.*], "null")) {
        pos.* += 1;
        return try alloc.dupe(u8, "null");
    }
    return error.UnsupportedSqlShape;
}

fn scalarDefaultTokenizedValueListJsonAlloc(
    alloc: std.mem.Allocator,
    tokens: []const std.json.Value,
    pos: *usize,
) ![]const u8 {
    if (pos.* >= tokens.len or !scalarDefaultTokenKindEql(tokens[pos.*], "lparen")) return error.UnsupportedSqlShape;
    pos.* += 1;
    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.writeByte('[');
    var count: usize = 0;
    while (true) {
        if (pos.* >= tokens.len or scalarDefaultTokenKindEql(tokens[pos.*], "rparen")) return error.UnsupportedSqlShape;
        const value_json = try scalarDefaultValueTokenJsonAlloc(alloc, tokens, pos);
        defer alloc.free(value_json);
        if (count > 0) try writer.writeByte(',');
        try writer.writeAll(value_json);
        count += 1;
        if (pos.* < tokens.len and scalarDefaultTokenKindEql(tokens[pos.*], "comma")) {
            pos.* += 1;
            continue;
        }
        break;
    }
    if (pos.* >= tokens.len or !scalarDefaultTokenKindEql(tokens[pos.*], "rparen")) return error.UnsupportedSqlShape;
    pos.* += 1;
    try writer.writeByte(']');
    return try out.toOwnedSlice();
}

fn scalarDefaultUnsignedToken(tokens: []const std.json.Value, pos: *usize) !u32 {
    if (pos.* < tokens.len and scalarDefaultTokenKindEql(tokens[pos.*], "plus")) pos.* += 1;
    if (pos.* >= tokens.len or !scalarDefaultTokenKindEql(tokens[pos.*], "number")) return error.UnsupportedSqlShape;
    const text = scalarDefaultTokenText(tokens[pos.*]);
    pos.* += 1;
    return std.fmt.parseUnsigned(u32, text, 10) catch return error.UnsupportedSqlShape;
}

fn scalarDefaultTokenText(token: std.json.Value) []const u8 {
    if (token != .object) return "";
    const text_value = token.object.get("text") orelse return "";
    return if (text_value == .string) text_value.string else "";
}

fn sequenceDefaultValueJsonAlloc(
    alloc: std.mem.Allocator,
    value_json: []const u8,
    resolver: SequenceDefaultResolver,
) ![]u8 {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, value_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(parsed.value.object, &.{ "sequence", "database", "schema" });
    const sequence_value = parsed.value.object.get("sequence") orelse return error.InvalidRowsRequest;
    if (sequence_value != .string or sequence_value.string.len == 0) return error.InvalidRowsRequest;
    const database = if (parsed.value.object.get("database")) |database_value| blk: {
        if (database_value != .string or database_value.string.len == 0) return error.InvalidRowsRequest;
        break :blk database_value.string;
    } else "";
    const schema = if (parsed.value.object.get("schema")) |schema_value| blk: {
        if (schema_value != .string or schema_value.string.len == 0) return error.InvalidRowsRequest;
        break :blk schema_value.string;
    } else "";
    const value = try resolver.nextValueJsonAlloc(alloc, .{
        .sequence = sequence_value.string,
        .database = database,
        .schema = schema,
    });
    errdefer alloc.free(value);
    try validateSequenceDefaultJsonValue(alloc, value);
    return value;
}

fn validateSequenceDefaultJsonValue(alloc: std.mem.Allocator, value_json: []const u8) !void {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, value_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    switch (parsed.value) {
        .integer, .float => {},
        else => return error.InvalidRowsRequest,
    }
}

fn currentUtcDateStartNs() u64 {
    const now_ns = platform_time.realtimeNs();
    return now_ns - (now_ns % ns_per_day);
}

fn randomUuidV4String() ![36]u8 {
    var bytes: [16]u8 = undefined;
    var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
    defer io_impl.deinit();
    try io_impl.io().randomSecure(&bytes);
    bytes[6] = (bytes[6] & 0x0f) | 0x40;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;

    var out: [36]u8 = undefined;
    const hex = "0123456789abcdef";
    var src: usize = 0;
    var dst: usize = 0;
    while (src < bytes.len) : (src += 1) {
        if (dst == 8 or dst == 13 or dst == 18 or dst == 23) {
            out[dst] = '-';
            dst += 1;
        }
        out[dst] = hex[bytes[src] >> 4];
        out[dst + 1] = hex[bytes[src] & 0x0f];
        dst += 2;
    }
    return out;
}

fn schemaHasGeneratedColumns(schema: runtime_schema.TableSchema) bool {
    for (schema.relational_columns) |column| {
        if (column.generated != null) return true;
    }
    return false;
}

fn extendOperationsWithOnUpdateAlloc(
    alloc: std.mem.Allocator,
    operations: []db_mod.types.TransformOp,
    schema: runtime_schema.TableSchema,
) ![]db_mod.types.TransformOp {
    var update_count: usize = 0;
    for (schema.relational_columns) |column| {
        if (column.on_update_value != null) update_count += 1;
    }
    if (update_count == 0) return operations;

    const extended = try alloc.alloc(db_mod.types.TransformOp, operations.len + update_count);
    @memcpy(extended[0..operations.len], operations);
    alloc.free(operations);
    var index = operations.len;
    errdefer freeTransformOps(alloc, extended[operations.len..index]);

    for (schema.relational_columns) |column| {
        const on_update_value = column.on_update_value orelse continue;
        const value_json = try relationalDefaultValueJsonAlloc(alloc, on_update_value);
        var value_transferred = false;
        errdefer if (!value_transferred) alloc.free(value_json);
        const path = try alloc.dupe(u8, column.path);
        var path_transferred = false;
        errdefer if (!path_transferred) alloc.free(path);
        extended[index] = .{
            .op = .set,
            .path = path,
            .value_json = value_json,
        };
        path_transferred = true;
        value_transferred = true;
        index += 1;
    }
    return extended;
}

fn appendJsonFieldValue(
    alloc: std.mem.Allocator,
    writer: *std.Io.Writer,
    first: *bool,
    field: []const u8,
    value: std.json.Value,
) !void {
    if (!first.*) try writer.writeByte(',');
    first.* = false;
    try writer.print("{f}:", .{std.json.fmt(field, .{})});
    _ = alloc;
    try std.json.Stringify.value(value, .{}, writer);
}

fn appendRawJsonFieldValue(
    alloc: std.mem.Allocator,
    writer: *std.Io.Writer,
    first: *bool,
    field: []const u8,
    value_json: []const u8,
) !void {
    if (!first.*) try writer.writeByte(',');
    first.* = false;
    try writer.print("{f}:", .{std.json.fmt(field, .{})});
    _ = alloc;
    try writer.writeAll(value_json);
}

fn generatedColumnValueJsonAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    row_value: std.json.Value,
    resolved_defaults: []const ?[]u8,
    generated: runtime_schema.RelationalGeneratedValue,
) ![]u8 {
    return switch (generated.op) {
        .lower, .upper, .md5 => blk: {
            const field = generated.field orelse return error.InvalidRowsRequest;
            const source = try plannedStringFieldValueOrNullAlloc(alloc, schema, row_value, resolved_defaults, field) orelse
                break :blk try alloc.dupe(u8, "null");
            defer alloc.free(source);
            const folded = switch (generated.op) {
                .lower => try std.ascii.allocLowerString(alloc, source),
                .upper => try std.ascii.allocUpperString(alloc, source),
                .md5 => try expr_text.md5HexTextAlloc(alloc, source),
                .concat => unreachable,
                .concat_ws => unreachable,
                .expression => unreachable,
            };
            defer alloc.free(folded);
            break :blk try std.fmt.allocPrint(alloc, "{f}", .{std.json.fmt(folded, .{})});
        },
        .concat => blk: {
            var joined = std.ArrayListUnmanaged(u8).empty;
            defer joined.deinit(alloc);
            for (generated.fields, 0..) |field, i| {
                if (i != 0) try joined.appendSlice(alloc, generated.separator);
                const value = try plannedScalarFieldTextAlloc(alloc, schema, row_value, resolved_defaults, field);
                defer alloc.free(value);
                try joined.appendSlice(alloc, value);
            }
            break :blk try std.fmt.allocPrint(alloc, "{f}", .{std.json.fmt(joined.items, .{})});
        },
        .concat_ws => blk: {
            var joined = std.ArrayListUnmanaged(u8).empty;
            defer joined.deinit(alloc);
            var emitted = false;
            for (generated.fields) |field| {
                const value = try plannedStringFieldValueOrNullAlloc(alloc, schema, row_value, resolved_defaults, field) orelse continue;
                defer alloc.free(value);
                if (emitted) try joined.appendSlice(alloc, generated.separator);
                try joined.appendSlice(alloc, value);
                emitted = true;
            }
            break :blk try std.fmt.allocPrint(alloc, "{f}", .{std.json.fmt(joined.items, .{})});
        },
        .expression => blk: {
            const expression = generated.expression orelse return error.InvalidRowsRequest;
            const source_json = try generatedExpressionSourceRowJsonAlloc(alloc, schema, row_value, resolved_defaults);
            defer alloc.free(source_json);
            var parsed = std.json.parseFromSlice(std.json.Value, alloc, source_json, .{}) catch return error.InvalidRowsRequest;
            defer parsed.deinit();
            break :blk try expressionValueJsonAlloc(alloc, parsed.value, expression);
        },
    };
}

fn generatedExpressionSourceRowJsonAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    row_value: std.json.Value,
    resolved_defaults: []const ?[]u8,
) ![]u8 {
    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.writeByte('{');
    var first = true;
    for (schema.relational_columns, 0..) |column, column_index| {
        if (column.generated != null) continue;
        if (jsonValueAtPath(row_value, column.path)) |selected| {
            try appendJsonFieldValue(alloc, writer, &first, column.path, selected.*);
        } else if (resolved_defaults[column_index]) |default_json| {
            try appendRawJsonFieldValue(alloc, writer, &first, column.path, default_json);
        }
    }
    try writer.writeByte('}');
    return try out.toOwnedSlice();
}

fn plannedStringFieldValueAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    row_value: std.json.Value,
    resolved_defaults: []const ?[]u8,
    field: []const u8,
) ![]u8 {
    if (row_value.object.get(field)) |value| {
        if (value != .string) return error.InvalidRowsRequest;
        return try alloc.dupe(u8, value.string);
    }
    const column_index = findRelationalColumnIndex(schema.relational_columns, field) orelse return error.InvalidRowsRequest;
    const default_json = resolved_defaults[column_index] orelse return error.InvalidRowsRequest;
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, default_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    if (parsed.value != .string) return error.InvalidRowsRequest;
    return try alloc.dupe(u8, parsed.value.string);
}

fn plannedStringFieldValueOrNullAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    row_value: std.json.Value,
    resolved_defaults: []const ?[]u8,
    field: []const u8,
) !?[]u8 {
    if (row_value.object.get(field)) |value| {
        if (value == .null) return null;
        if (value != .string) return error.InvalidRowsRequest;
        return try alloc.dupe(u8, value.string);
    }
    const column_index = findRelationalColumnIndex(schema.relational_columns, field) orelse return error.InvalidRowsRequest;
    const default_json = resolved_defaults[column_index] orelse return null;
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, default_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    if (parsed.value == .null) return null;
    if (parsed.value != .string) return error.InvalidRowsRequest;
    return try alloc.dupe(u8, parsed.value.string);
}

fn plannedScalarFieldTextAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    row_value: std.json.Value,
    resolved_defaults: []const ?[]u8,
    field: []const u8,
) ![]u8 {
    if (row_value.object.get(field)) |value| return try scalarJsonValueTextAlloc(alloc, value);
    const column_index = findRelationalColumnIndex(schema.relational_columns, field) orelse return error.InvalidRowsRequest;
    const default_json = resolved_defaults[column_index] orelse return error.InvalidRowsRequest;
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, default_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    return try scalarJsonValueTextAlloc(alloc, parsed.value);
}

fn scalarJsonValueTextAlloc(alloc: std.mem.Allocator, value: std.json.Value) ![]u8 {
    return switch (value) {
        .string => |text| try alloc.dupe(u8, text),
        .integer => |integer| try std.fmt.allocPrint(alloc, "{d}", .{integer}),
        .float => |float| try std.fmt.allocPrint(alloc, "{d}", .{float}),
        .bool => |enabled| try alloc.dupe(u8, if (enabled) "true" else "false"),
        else => error.InvalidRowsRequest,
    };
}

fn replaceTextAlloc(alloc: std.mem.Allocator, source: []const u8, needle: []const u8, replacement: []const u8) ![]u8 {
    if (needle.len == 0) return try alloc.dupe(u8, source);
    var out = std.ArrayListUnmanaged(u8).empty;
    errdefer out.deinit(alloc);
    var start: usize = 0;
    while (std.mem.indexOfPos(u8, source, start, needle)) |index| {
        try out.appendSlice(alloc, source[start..index]);
        try out.appendSlice(alloc, replacement);
        start = index + needle.len;
    }
    try out.appendSlice(alloc, source[start..]);
    return try out.toOwnedSlice(alloc);
}

const RegexpReplaceFlags = struct {
    global: bool = false,
};

const RegexpMatchSpan = struct {
    start: usize,
    end: usize,
};

fn regexpReplaceTextAlloc(
    alloc: std.mem.Allocator,
    source: []const u8,
    pattern: []const u8,
    replacement: []const u8,
    flags: []const u8,
) ![]u8 {
    const parsed_flags = try parseRegexpReplaceFlags(flags);
    if (std.mem.indexOfScalar(u8, replacement, '\\') != null) return error.InvalidRowsRequest;

    var compiled = regex_mod.compile(alloc, pattern) catch return error.InvalidRowsRequest;
    defer compiled.deinit();

    var out = std.ArrayListUnmanaged(u8).empty;
    errdefer out.deinit(alloc);
    var cursor: usize = 0;
    var replaced = false;

    while (cursor <= source.len) {
        const span = regexpFindLeftmostMatch(&compiled, source, cursor) orelse break;
        if (span.end <= span.start) return error.InvalidRowsRequest;
        try out.appendSlice(alloc, source[cursor..span.start]);
        try out.appendSlice(alloc, replacement);
        cursor = span.end;
        replaced = true;
        if (!parsed_flags.global) break;
    }

    if (!replaced) return try alloc.dupe(u8, source);
    try out.appendSlice(alloc, source[cursor..]);
    return try out.toOwnedSlice(alloc);
}

fn regexpMatchTextAlloc(
    alloc: std.mem.Allocator,
    source: []const u8,
    pattern: []const u8,
    case_insensitive: bool,
) !bool {
    var source_lower: ?[]u8 = null;
    defer if (source_lower) |text| alloc.free(text);
    var pattern_lower: ?[]u8 = null;
    defer if (pattern_lower) |text| alloc.free(text);

    const source_text = if (case_insensitive) blk: {
        source_lower = try asciiLowerTextAlloc(alloc, source);
        break :blk source_lower.?;
    } else source;
    const pattern_text = if (case_insensitive) blk: {
        pattern_lower = try asciiLowerTextAlloc(alloc, pattern);
        break :blk pattern_lower.?;
    } else pattern;

    var compiled = regex_mod.compile(alloc, pattern_text) catch return error.InvalidRowsRequest;
    defer compiled.deinit();
    return regexpFindLeftmostMatch(&compiled, source_text, 0) != null;
}

fn regexpCountText(alloc: std.mem.Allocator, source: []const u8, pattern: []const u8) !u64 {
    var compiled = regex_mod.compile(alloc, pattern) catch return error.InvalidRowsRequest;
    defer compiled.deinit();

    var count: u64 = 0;
    var cursor: usize = 0;
    while (cursor <= source.len) {
        const span = regexpFindLeftmostMatch(&compiled, source, cursor) orelse break;
        if (span.end <= span.start) return error.InvalidRowsRequest;
        count += 1;
        cursor = span.end;
    }
    return count;
}

fn regexpInstrText(alloc: std.mem.Allocator, source: []const u8, pattern: []const u8) !usize {
    var compiled = regex_mod.compile(alloc, pattern) catch return error.InvalidRowsRequest;
    defer compiled.deinit();

    const span = regexpFindLeftmostMatch(&compiled, source, 0) orelse return 0;
    if (span.end <= span.start) return error.InvalidRowsRequest;
    const codepoints_before = std.unicode.utf8CountCodepoints(source[0..span.start]) catch return error.InvalidRowsRequest;
    return codepoints_before + 1;
}

fn regexpSubstrTextAlloc(alloc: std.mem.Allocator, source: []const u8, pattern: []const u8) !?[]u8 {
    var compiled = regex_mod.compile(alloc, pattern) catch return error.InvalidRowsRequest;
    defer compiled.deinit();

    const span = regexpFindLeftmostMatch(&compiled, source, 0) orelse return null;
    if (span.end <= span.start) return error.InvalidRowsRequest;
    return try alloc.dupe(u8, source[span.start..span.end]);
}

test "regexp_instr returns one based UTF-8 codepoint positions" {
    const alloc = std.testing.allocator;
    const text = [_]u8{ 'a', 0xc3, 0xa9, '7' };
    try std.testing.expectEqual(@as(usize, 3), try regexpInstrText(alloc, text[0..], "[0-9]"));
    try std.testing.expectEqual(@as(usize, 0), try regexpInstrText(alloc, text[0..], "z+"));
    try std.testing.expectError(error.InvalidRowsRequest, regexpInstrText(alloc, text[0..], ""));
}

test "regexp_substr returns first leftmost non-empty match" {
    const alloc = std.testing.allocator;
    const text = [_]u8{ 'a', 0xc3, 0xa9, '7', 'b', '8' };
    const matched = (try regexpSubstrTextAlloc(alloc, text[0..], "[0-9]+")).?;
    defer alloc.free(matched);
    try std.testing.expectEqualStrings("7", matched);
    try std.testing.expect((try regexpSubstrTextAlloc(alloc, text[0..], "z+")) == null);
    try std.testing.expectError(error.InvalidRowsRequest, regexpSubstrTextAlloc(alloc, text[0..], ""));
}

fn asciiLowerTextAlloc(alloc: std.mem.Allocator, source: []const u8) ![]u8 {
    const out = try alloc.dupe(u8, source);
    for (out) |*byte| byte.* = std.ascii.toLower(byte.*);
    return out;
}

fn parseRegexpReplaceFlags(flags: []const u8) !RegexpReplaceFlags {
    var parsed = RegexpReplaceFlags{};
    for (flags) |flag| switch (flag) {
        'g' => parsed.global = true,
        else => return error.InvalidRowsRequest,
    };
    return parsed;
}

fn regexpFindLeftmostMatch(compiled: *regex_mod.RegexAutomaton, text: []const u8, start_at: usize) ?RegexpMatchSpan {
    if (start_at > text.len) return null;
    const start_limit: usize = if (compiled.anchored_start) 1 else text.len + 1;
    if (start_at >= start_limit) return null;
    var start = start_at;
    while (start < start_limit) : (start += 1) {
        if (regexpMatchEndFrom(compiled, text, start)) |end| {
            return .{ .start = start, .end = end };
        }
    }
    return null;
}

fn regexpMatchEndFrom(compiled: *regex_mod.RegexAutomaton, text: []const u8, start: usize) ?usize {
    const automaton = compiled.automaton();
    var state = automaton.start();
    var latest_match: ?usize = null;
    if (automaton.isMatch(state) and (!compiled.anchored_end or start == text.len)) latest_match = start;
    for (text[start..], 0..) |byte, offset| {
        state = automaton.accept(state, byte);
        if (!automaton.canMatch(state)) break;
        if (automaton.isMatch(state)) {
            const end = start + offset + 1;
            if (!compiled.anchored_end or end == text.len) latest_match = end;
        }
    }
    return latest_match;
}

fn validateRelationalChecks(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    row_json: []const u8,
) !void {
    if (schema.checks.len == 0) return;
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    for (schema.checks) |check| {
        if (check.validation_state != .enforced) continue;
        if (!try relationalCheckPasses(alloc, parsed.value, check)) return error.InvalidRowsRequest;
    }
}

fn extendOperationsWithGeneratedColumnsAlloc(
    alloc: std.mem.Allocator,
    operations: []db_mod.types.TransformOp,
    schema: runtime_schema.TableSchema,
    planned_json: []const u8,
) ![]db_mod.types.TransformOp {
    var generated_count: usize = 0;
    for (schema.relational_columns) |column| {
        if (column.generated != null) generated_count += 1;
    }
    if (generated_count == 0) return operations;

    var parsed = std.json.parseFromSlice(std.json.Value, alloc, planned_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    const extended = try alloc.alloc(db_mod.types.TransformOp, operations.len + generated_count);
    @memcpy(extended[0..operations.len], operations);
    alloc.free(operations);
    var index = operations.len;
    errdefer freeTransformOps(alloc, extended[operations.len..index]);

    for (schema.relational_columns) |column| {
        if (column.generated == null) continue;
        const value = jsonValueAtPath(parsed.value, column.path) orelse return error.InvalidRowsRequest;
        const value_json = try jsonValueStringifyAlloc(alloc, value.*);
        var value_transferred = false;
        errdefer if (!value_transferred) alloc.free(value_json);
        const path = try alloc.dupe(u8, column.path);
        var path_transferred = false;
        errdefer if (!path_transferred) alloc.free(path);
        extended[index] = .{
            .op = .set,
            .path = path,
            .value_json = value_json,
        };
        path_transferred = true;
        value_transferred = true;
        index += 1;
    }
    return extended;
}

fn relationalCheckPasses(
    alloc: std.mem.Allocator,
    row: std.json.Value,
    check: runtime_schema.RelationalCheck,
) !bool {
    if (check.expression) |condition| return try expressionConditionMatches(alloc, row, condition);
    const value = jsonValueAtPath(row, check.field);
    return switch (check.op) {
        .is_null => value == null or value.?.* == .null,
        .is_not_null => value != null and value.?.* != .null,
        .is_distinct, .is_not_distinct => blk: {
            const expected_json = check.value_json orelse return error.InvalidRowsRequest;
            var expected = std.json.parseFromSlice(std.json.Value, alloc, expected_json, .{}) catch return error.InvalidRowsRequest;
            defer expected.deinit();
            const actual: std.json.Value = if (value) |selected| selected.* else .null;
            const not_distinct = jsonValuesNotDistinctWithCollation(actual, expected.value, check.collation) orelse return error.InvalidRowsRequest;
            break :blk if (check.op == .is_not_distinct) not_distinct else !not_distinct;
        },
        .eq, .ne, .gt, .gte, .lt, .lte => blk: {
            const expected_json = check.value_json orelse return error.InvalidRowsRequest;
            var expected = std.json.parseFromSlice(std.json.Value, alloc, expected_json, .{}) catch return error.InvalidRowsRequest;
            defer expected.deinit();
            const actual = value orelse break :blk false;
            const comparison = compareJsonScalarsWithCollation(actual.*, expected.value, check.collation) orelse return error.InvalidRowsRequest;
            break :blk switch (check.op) {
                .eq => comparison == .eq,
                .ne => comparison != .eq,
                .gt => comparison == .gt,
                .gte => comparison == .gt or comparison == .eq,
                .lt => comparison == .lt,
                .lte => comparison == .lt or comparison == .eq,
                else => unreachable,
            };
        },
    };
}

const ScalarComparison = enum { lt, eq, gt };

fn jsonValuesNotDistinct(actual: std.json.Value, expected: std.json.Value) ?bool {
    return jsonValuesNotDistinctWithCollation(actual, expected, null);
}

fn jsonValuesNotDistinctWithCollation(actual: std.json.Value, expected: std.json.Value, collation: ?[]const u8) ?bool {
    if (jsonScalarKind(actual) != null and jsonScalarKind(expected) != null) {
        if (jsonScalarKind(actual) != jsonScalarKind(expected)) return false;
    }
    const comparison = compareJsonScalarsWithCollation(actual, expected, collation) orelse return null;
    return comparison == .eq;
}

const JsonScalarKind = enum { null, bool, numeric, string };

fn jsonScalarKind(value: std.json.Value) ?JsonScalarKind {
    return switch (value) {
        .null => .null,
        .bool => .bool,
        .integer, .float => .numeric,
        .string => .string,
        else => null,
    };
}

fn compareJsonScalars(actual: std.json.Value, expected: std.json.Value) ?ScalarComparison {
    return compareJsonScalarsWithCollation(actual, expected, null);
}

fn compareJsonScalarsWithCollation(actual: std.json.Value, expected: std.json.Value, collation: ?[]const u8) ?ScalarComparison {
    if (jsonNumericValue(actual)) |left| {
        const right = jsonNumericValue(expected) orelse return null;
        if (left < right) return .lt;
        if (left > right) return .gt;
        return .eq;
    }
    if (actual == .string and expected == .string) {
        return compareTextScalars(actual.string, expected.string, collation);
    }
    if (actual == .bool and expected == .bool) {
        if (actual.bool == expected.bool) return .eq;
        return if (!actual.bool and expected.bool) .lt else .gt;
    }
    if (actual == .null and expected == .null) return .eq;
    return null;
}

fn compareTextScalars(lhs: []const u8, rhs: []const u8, collation: ?[]const u8) ScalarComparison {
    return scalarComparisonFromTextComparison(relational_collation.compareTextForScalar(lhs, rhs, collation));
}

fn scalarComparisonFromTextComparison(comparison: relational_collation.TextComparison) ScalarComparison {
    return switch (comparison) {
        .lt => .lt,
        .eq => .eq,
        .gt => .gt,
    };
}

fn jsonNumericValue(value: std.json.Value) ?f64 {
    return switch (value) {
        .integer => |integer| @floatFromInt(integer),
        .float => |float| float,
        else => null,
    };
}

fn appendInsertAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    row_value: std.json.Value,
    require_absent: bool,
    writes: *std.ArrayListUnmanaged(db_mod.types.BatchWrite),
    predicates: *std.ArrayListUnmanaged(db_mod.types.TransactionVersionPredicate),
    default_context: DefaultValueContext,
) !void {
    const row_json = try plannedRelationalRowJsonWithDefaultContextAlloc(alloc, schema, row_value, default_context);
    var row_json_transferred = false;
    errdefer if (!row_json_transferred) alloc.free(row_json);
    const key = try physicalPrimaryKeyFromRowJsonAlloc(alloc, schema, row_json);
    var key_transferred = false;
    errdefer if (!key_transferred) alloc.free(key);
    try writes.append(alloc, .{ .key = key, .value = row_json });
    key_transferred = true;
    row_json_transferred = true;
    if (require_absent) {
        const predicate_key = try alloc.dupe(u8, key);
        var predicate_key_transferred = false;
        errdefer if (!predicate_key_transferred) alloc.free(predicate_key);
        try predicates.append(alloc, .{ .key = predicate_key, .expected_version = 0 });
        predicate_key_transferred = true;
    }
}

fn appendPlannedInsertAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    row_json: []const u8,
    require_absent: bool,
    writes: *std.ArrayListUnmanaged(db_mod.types.BatchWrite),
    predicates: *std.ArrayListUnmanaged(db_mod.types.TransactionVersionPredicate),
) !void {
    const row_json_owned = try alloc.dupe(u8, row_json);
    var row_json_transferred = false;
    errdefer if (!row_json_transferred) alloc.free(row_json_owned);
    const key = try physicalPrimaryKeyFromRowJsonAlloc(alloc, schema, row_json);
    var key_transferred = false;
    errdefer if (!key_transferred) alloc.free(key);
    try writes.append(alloc, .{ .key = key, .value = row_json_owned });
    key_transferred = true;
    row_json_transferred = true;
    if (require_absent) {
        const predicate_key = try alloc.dupe(u8, key);
        var predicate_key_transferred = false;
        errdefer if (!predicate_key_transferred) alloc.free(predicate_key);
        try predicates.append(alloc, .{ .key = predicate_key, .expected_version = 0 });
        predicate_key_transferred = true;
    }
}

fn appendInsertWithConflictAlloc(
    alloc: std.mem.Allocator,
    table_name: []const u8,
    schema: runtime_schema.TableSchema,
    row_value: std.json.Value,
    op_value: std.json.Value,
    conflict_value: std.json.Value,
    resolver: UniqueSelectorResolver,
    writes: *std.ArrayListUnmanaged(db_mod.types.BatchWrite),
    transforms: *std.ArrayListUnmanaged(db_mod.types.DocumentTransform),
    predicates: *std.ArrayListUnmanaged(db_mod.types.TransactionVersionPredicate),
    returning_rows: *std.ArrayListUnmanaged([]const u8),
    proposed_conflict_targets: *std.StringHashMapUnmanaged(void),
    inserted: *u32,
    transformed: *u32,
    default_context: DefaultValueContext,
) !void {
    if (conflict_value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(conflict_value.object, &.{ "target", "action", "patch", "patch_expr", "increment", "increment_expr", "json_set", "array_update", "where_expression", "where_expressions", "where_any", "where_not" });
    const action = try parseConflictAction(conflict_value.object.get("action") orelse return error.InvalidRowsRequest);
    const target_value = conflict_value.object.get("target") orelse return error.InvalidRowsRequest;
    if (target_value != .object) return error.InvalidRowsRequest;

    const row_json = try plannedRelationalRowJsonWithDefaultContextAlloc(alloc, schema, row_value, default_context);
    defer alloc.free(row_json);

    const duplicate_keys = try conflictTargetDuplicateKeysAlloc(alloc, schema, row_json, target_value);
    if (try proposedConflictTargetsContainOrPutAllAlloc(alloc, proposed_conflict_targets, duplicate_keys)) {
        if (action == .update) return error.InvalidRowsRequest;
        if (hasConflictActionCondition(conflict_value)) return error.InvalidRowsRequest;
        return;
    }

    const conflict_key = try conflictTargetPrimaryKeyAlloc(alloc, table_name, schema, row_json, target_value, resolver);
    defer if (conflict_key) |key| alloc.free(key);

    if (conflict_key) |key| {
        const owner_duplicate_key = try std.mem.concat(alloc, u8, &.{ "owner\x00", key });
        var owner_duplicate_key_transferred = false;
        errdefer if (!owner_duplicate_key_transferred) alloc.free(owner_duplicate_key);
        const owner_gop = try proposed_conflict_targets.getOrPut(alloc, owner_duplicate_key);
        if (owner_gop.found_existing) {
            owner_duplicate_key_transferred = true;
            alloc.free(owner_duplicate_key);
            if (action == .update) return error.InvalidRowsRequest;
            if (hasConflictActionCondition(conflict_value)) return error.InvalidRowsRequest;
            return;
        }
        owner_duplicate_key_transferred = true;
        switch (action) {
            .nothing => {
                if (hasConflictActionCondition(conflict_value)) return error.InvalidRowsRequest;
                return;
            },
            .update => {
                const needs_existing_row = hasMutationExpression(conflict_value) or hasConflictActionCondition(conflict_value) or hasReturningProjection(op_value) or schemaHasGeneratedColumns(schema) or schema.checks.len != 0;
                var existing: ?ResolvedPrimaryRow = if (needs_existing_row)
                    (try resolver.lookupPrimary(alloc, table_name, key)) orelse return error.RowSelectorNotFound
                else
                    null;
                defer if (existing) |*row| row.deinit(alloc);
                var parsed_existing: std.json.Parsed(std.json.Value) = undefined;
                var parsed_existing_loaded = false;
                defer if (parsed_existing_loaded) parsed_existing.deinit();
                const existing_row_value: ?std.json.Value = if (existing) |row| blk: {
                    parsed_existing = std.json.parseFromSlice(std.json.Value, alloc, row.json, .{}) catch return error.InvalidRowsRequest;
                    parsed_existing_loaded = true;
                    if (parsed_existing.value != .object) return error.InvalidRowsRequest;
                    break :blk parsed_existing.value;
                } else null;
                var parsed_proposed: std.json.Parsed(std.json.Value) = undefined;
                var parsed_proposed_loaded = false;
                defer if (parsed_proposed_loaded) parsed_proposed.deinit();
                const proposed_row_value: ?std.json.Value = if (hasMutationExpression(conflict_value) or hasConflictActionCondition(conflict_value)) blk: {
                    parsed_proposed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidRowsRequest;
                    parsed_proposed_loaded = true;
                    if (parsed_proposed.value != .object) return error.InvalidRowsRequest;
                    break :blk parsed_proposed.value;
                } else null;
                if (hasConflictActionCondition(conflict_value) and !try conflictActionConditionMatches(alloc, schema, conflict_value, existing_row_value orelse return error.InvalidRowsRequest, proposed_row_value)) return;
                var operations = try updateTransformOperationsAlloc(alloc, schema, conflict_value, existing_row_value, proposed_row_value);
                var operations_transferred = false;
                errdefer if (!operations_transferred) freeTransformOps(alloc, operations);
                operations = try extendOperationsWithOnUpdateAlloc(alloc, operations, schema);
                if (existing) |row| {
                    try appendVersionPredicateAlloc(alloc, predicates, key, row.version);
                }
                if (existing) |row| {
                    const projected_json = (try db_mod.transform.resolveDocumentTransform(alloc, row.json, .{ .key = key, .operations = operations })) orelse return error.RowSelectorNotFound;
                    defer alloc.free(projected_json);
                    const planned_json = try plannedExistingRelationalRowJsonAlloc(alloc, schema, projected_json);
                    defer alloc.free(planned_json);
                    if (schemaHasGeneratedColumns(schema)) operations = try extendOperationsWithGeneratedColumnsAlloc(alloc, operations, schema, planned_json);
                    try appendReturningProjectionFromJsonAlloc(alloc, schema, returning_rows, op_value, planned_json);
                }
                const transform_key = try alloc.dupe(u8, key);
                var key_transferred = false;
                errdefer if (!key_transferred) alloc.free(transform_key);
                try transforms.append(alloc, .{ .key = transform_key, .operations = operations });
                key_transferred = true;
                operations_transferred = true;
                transformed.* += 1;
                return;
            },
        }
    }

    try appendInsertAlloc(alloc, schema, row_value, true, writes, predicates, default_context);
    try appendReturningProjectionAlloc(alloc, schema, returning_rows, op_value, row_json);
    inserted.* += 1;
}

fn parseConflictAction(value: std.json.Value) !ConflictAction {
    if (value != .string) return error.InvalidRowsRequest;
    if (std.mem.eql(u8, value.string, "update")) return .update;
    if (std.mem.eql(u8, value.string, "nothing")) return .nothing;
    return error.InvalidRowsRequest;
}

fn conflictTargetPrimaryKeyAlloc(
    alloc: std.mem.Allocator,
    table_name: []const u8,
    schema: runtime_schema.TableSchema,
    row_json: []const u8,
    target_value: std.json.Value,
    resolver: UniqueSelectorResolver,
) !?[]u8 {
    if (target_value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(target_value.object, &.{ "any", "primary", "unique" });
    try validateConflictTargetObjectShape(target_value);
    if (target_value.object.get("any")) |any_value| {
        if (any_value != .bool or !any_value.bool) return error.InvalidRowsRequest;
        return try anyConflictTargetPrimaryKeyAlloc(alloc, table_name, schema, row_json, resolver);
    }
    if (target_value.object.get("primary")) |primary_value| {
        if (primary_value != .bool or !primary_value.bool) return error.InvalidRowsRequest;
        const primary_key = schema.primary_key orelse return error.InvalidRowsRequest;
        if (primary_key.without_overlaps_period) |period_name| {
            const encoded_value = try primaryKeyValueFromRowJsonAlloc(alloc, schema, primary_key, row_json);
            defer alloc.free(encoded_value);
            var span = try temporalPeriodSpanBytesFromRowAlloc(alloc, schema, row_json, period_name);
            defer span.deinit(alloc);
            return try resolver.resolveTemporalUniqueOverlap(alloc, table_name, db_mod.relational_store.primary_key_constraint_name, encoded_value, span.start, span.end);
        }
        const key = try physicalPrimaryKeyFromRowJsonAlloc(alloc, schema, row_json);
        errdefer alloc.free(key);
        if (try resolver.primaryExists(alloc, table_name, key)) return key;
        alloc.free(key);
        return null;
    }

    if (target_value.object.get("unique")) |unique_value| {
        if (unique_value != .object) return error.InvalidRowsRequest;
        try requireJsonObjectOnlyKeys(unique_value.object, &.{ "name", "where", "where_expressions" });
        const name_value = unique_value.object.get("name") orelse return error.InvalidRowsRequest;
        if (name_value != .string) return error.InvalidRowsRequest;
        const constraint = findUniqueConstraint(schema.unique_constraints, name_value.string) orelse return error.InvalidRowsRequest;
        try validateConflictTargetPredicateMatchesConstraint(alloc, schema, unique_value, constraint);
        const encoded_value = (try uniqueConstraintValueFromRowAlloc(alloc, schema, constraint, row_json)) orelse return null;
        defer alloc.free(encoded_value);
        if (constraint.without_overlaps_period) |period_name| {
            var span = try temporalPeriodSpanBytesFromRowAlloc(alloc, schema, row_json, period_name);
            defer span.deinit(alloc);
            return try resolver.resolveTemporalUniqueOverlap(alloc, table_name, constraint.name, encoded_value, span.start, span.end);
        }
        return try resolver.resolveUnique(alloc, table_name, constraint.name, encoded_value);
    }

    return error.InvalidRowsRequest;
}

fn validateConflictTargetObjectShape(target_value: std.json.Value) !void {
    if (target_value != .object) return error.InvalidRowsRequest;
    var count: usize = 0;
    if (target_value.object.get("any") != null) count += 1;
    if (target_value.object.get("primary") != null) count += 1;
    if (target_value.object.get("unique") != null) count += 1;
    if (count != 1) return error.InvalidRowsRequest;
}

fn conflictTargetDuplicateKeysAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    row_json: []const u8,
    target_value: std.json.Value,
) ![]const []const u8 {
    if (target_value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(target_value.object, &.{ "any", "primary", "unique" });
    try validateConflictTargetObjectShape(target_value);
    var keys = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (keys.items) |key| alloc.free(@constCast(key));
        keys.deinit(alloc);
    }
    if (target_value.object.get("any")) |any_value| {
        if (any_value != .bool or !any_value.bool) return error.InvalidRowsRequest;
        try appendAnyConflictTargetDuplicateKeysAlloc(alloc, schema, row_json, &keys);
        return try keys.toOwnedSlice(alloc);
    }
    if (target_value.object.get("primary")) |primary_value| {
        if (primary_value != .bool or !primary_value.bool) return error.InvalidRowsRequest;
        try appendPrimaryConflictTargetDuplicateKeyAlloc(alloc, schema, row_json, &keys);
        return try keys.toOwnedSlice(alloc);
    }
    if (target_value.object.get("unique")) |unique_value| {
        if (unique_value != .object) return error.InvalidRowsRequest;
        try requireJsonObjectOnlyKeys(unique_value.object, &.{ "name", "where", "where_expressions" });
        const name_value = unique_value.object.get("name") orelse return error.InvalidRowsRequest;
        if (name_value != .string) return error.InvalidRowsRequest;
        const constraint = findUniqueConstraint(schema.unique_constraints, name_value.string) orelse return error.InvalidRowsRequest;
        try validateConflictTargetPredicateMatchesConstraint(alloc, schema, unique_value, constraint);
        try appendUniqueConflictTargetDuplicateKeyAlloc(alloc, schema, row_json, constraint, &keys);
        return try keys.toOwnedSlice(alloc);
    }
    return error.InvalidRowsRequest;
}

fn typedConflictTargetDuplicateKeysAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    row_json: []const u8,
    target: db_mod.types.RelationalRowsConflictTarget,
) ![]const []const u8 {
    var keys = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (keys.items) |key| alloc.free(@constCast(key));
        keys.deinit(alloc);
    }
    switch (target.kind) {
        .any => try appendAnyConflictTargetDuplicateKeysAlloc(alloc, schema, row_json, &keys),
        .primary => try appendPrimaryConflictTargetDuplicateKeyAlloc(alloc, schema, row_json, &keys),
        .unique => {
            if (target.unique_name.len == 0) return error.InvalidRowsRequest;
            const constraint = findUniqueConstraint(schema.unique_constraints, target.unique_name) orelse return error.InvalidRowsRequest;
            try validateTypedConflictTargetMatchesConstraint(target, constraint);
            try appendUniqueConflictTargetDuplicateKeyAlloc(alloc, schema, row_json, constraint, &keys);
        },
    }
    return try keys.toOwnedSlice(alloc);
}

fn appendPrimaryConflictTargetDuplicateKeyAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    row_json: []const u8,
    keys: *std.ArrayListUnmanaged([]const u8),
) !void {
    const key = try physicalPrimaryKeyFromRowJsonAlloc(alloc, schema, row_json);
    errdefer alloc.free(key);
    try keys.append(alloc, key);
}

fn appendUniqueConflictTargetDuplicateKeyAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    row_json: []const u8,
    constraint: runtime_schema.UniqueConstraint,
    keys: *std.ArrayListUnmanaged([]const u8),
) !void {
    const encoded_value = (try uniqueConstraintValueFromRowAlloc(alloc, schema, constraint, row_json)) orelse return;
    defer alloc.free(encoded_value);
    const key = if (constraint.without_overlaps_period) |period_name| blk: {
        var span = try temporalPeriodSpanBytesFromRowAlloc(alloc, schema, row_json, period_name);
        defer span.deinit(alloc);
        break :blk try std.mem.concat(alloc, u8, &.{ "unique\x00", constraint.name, "\x00", encoded_value, "\x00period\x00", span.start, "\x00", span.end });
    } else try std.mem.concat(alloc, u8, &.{ "unique\x00", constraint.name, "\x00", encoded_value });
    errdefer alloc.free(key);
    try keys.append(alloc, key);
}

fn appendAnyConflictTargetDuplicateKeysAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    row_json: []const u8,
    keys: *std.ArrayListUnmanaged([]const u8),
) !void {
    try appendPrimaryConflictTargetDuplicateKeyAlloc(alloc, schema, row_json, keys);
    for (schema.unique_constraints) |constraint| {
        if (constraint.validation_state != .enforced) continue;
        try appendUniqueConflictTargetDuplicateKeyAlloc(alloc, schema, row_json, constraint, keys);
    }
}

fn proposedConflictTargetsContainOrPutAllAlloc(
    alloc: std.mem.Allocator,
    proposed_conflict_targets: *std.StringHashMapUnmanaged(void),
    keys: []const []const u8,
) !bool {
    for (keys) |key| {
        if (proposed_conflict_targets.contains(key)) {
            for (keys) |owned| alloc.free(@constCast(owned));
            if (keys.len > 0) alloc.free(keys);
            return true;
        }
    }
    for (keys) |key| {
        const gop = try proposed_conflict_targets.getOrPut(alloc, key);
        if (gop.found_existing) unreachable;
        gop.value_ptr.* = {};
    }
    if (keys.len > 0) alloc.free(keys);
    return false;
}

fn anyConflictTargetPrimaryKeyAlloc(
    alloc: std.mem.Allocator,
    table_name: []const u8,
    schema: runtime_schema.TableSchema,
    row_json: []const u8,
    resolver: UniqueSelectorResolver,
) !?[]u8 {
    const primary_key = schema.primary_key orelse return error.InvalidRowsRequest;
    if (primary_key.without_overlaps_period) |period_name| {
        const encoded_value = try primaryKeyValueFromRowJsonAlloc(alloc, schema, primary_key, row_json);
        defer alloc.free(encoded_value);
        var span = try temporalPeriodSpanBytesFromRowAlloc(alloc, schema, row_json, period_name);
        defer span.deinit(alloc);
        if (try resolver.resolveTemporalUniqueOverlap(alloc, table_name, db_mod.relational_store.primary_key_constraint_name, encoded_value, span.start, span.end)) |key| return key;
    } else {
        const key = try physicalPrimaryKeyFromRowJsonAlloc(alloc, schema, row_json);
        errdefer alloc.free(key);
        if (try resolver.primaryExists(alloc, table_name, key)) return key;
        alloc.free(key);
    }

    for (schema.unique_constraints) |constraint| {
        if (constraint.validation_state != .enforced) continue;
        const encoded_value = (try uniqueConstraintValueFromRowAlloc(alloc, schema, constraint, row_json)) orelse continue;
        defer alloc.free(encoded_value);
        if (constraint.without_overlaps_period) |period_name| {
            var span = try temporalPeriodSpanBytesFromRowAlloc(alloc, schema, row_json, period_name);
            defer span.deinit(alloc);
            if (try resolver.resolveTemporalUniqueOverlap(alloc, table_name, constraint.name, encoded_value, span.start, span.end)) |key| return key;
        } else {
            if (try resolver.resolveUnique(alloc, table_name, constraint.name, encoded_value)) |key| return key;
        }
    }
    return null;
}

fn typedConflictTargetPrimaryKeyAlloc(
    alloc: std.mem.Allocator,
    table_name: []const u8,
    schema: runtime_schema.TableSchema,
    row_json: []const u8,
    target: db_mod.types.RelationalRowsConflictTarget,
    resolver: UniqueSelectorResolver,
) !?[]u8 {
    switch (target.kind) {
        .any => return try anyConflictTargetPrimaryKeyAlloc(alloc, table_name, schema, row_json, resolver),
        .primary => {
            const primary_key = schema.primary_key orelse return error.InvalidRowsRequest;
            if (primary_key.without_overlaps_period) |period_name| {
                const encoded_value = try primaryKeyValueFromRowJsonAlloc(alloc, schema, primary_key, row_json);
                defer alloc.free(encoded_value);
                var span = try temporalPeriodSpanBytesFromRowAlloc(alloc, schema, row_json, period_name);
                defer span.deinit(alloc);
                return try resolver.resolveTemporalUniqueOverlap(alloc, table_name, db_mod.relational_store.primary_key_constraint_name, encoded_value, span.start, span.end);
            }
            const key = try physicalPrimaryKeyFromRowJsonAlloc(alloc, schema, row_json);
            errdefer alloc.free(key);
            if (try resolver.primaryExists(alloc, table_name, key)) return key;
            alloc.free(key);
            return null;
        },
        .unique => {
            if (target.unique_name.len == 0) return error.InvalidRowsRequest;
            const constraint = findUniqueConstraint(schema.unique_constraints, target.unique_name) orelse return error.InvalidRowsRequest;
            try validateTypedConflictTargetMatchesConstraint(target, constraint);
            const encoded_value = (try uniqueConstraintValueFromRowAlloc(alloc, schema, constraint, row_json)) orelse return null;
            defer alloc.free(encoded_value);
            if (constraint.without_overlaps_period) |period_name| {
                var span = try temporalPeriodSpanBytesFromRowAlloc(alloc, schema, row_json, period_name);
                defer span.deinit(alloc);
                return try resolver.resolveTemporalUniqueOverlap(alloc, table_name, constraint.name, encoded_value, span.start, span.end);
            }
            return try resolver.resolveUnique(alloc, table_name, constraint.name, encoded_value);
        },
    }
}

fn appendTypedConflictUpdateAlloc(
    alloc: std.mem.Allocator,
    table_name: []const u8,
    schema: runtime_schema.TableSchema,
    req: db_mod.types.RelationalRowsInsertSourceRequest,
    source_row_json: []const u8,
    proposed_row_json: []const u8,
    conflict: db_mod.types.RelationalRowsOnConflict,
    key: []const u8,
    resolver: UniqueSelectorResolver,
    transforms: *std.ArrayListUnmanaged(db_mod.types.DocumentTransform),
    predicates: *std.ArrayListUnmanaged(db_mod.types.TransactionVersionPredicate),
    returning_rows: *std.ArrayListUnmanaged([]const u8),
) !void {
    var existing = (try resolver.lookupPrimary(alloc, table_name, key)) orelse return error.RowSelectorNotFound;
    defer existing.deinit(alloc);

    var parsed_existing = std.json.parseFromSlice(std.json.Value, alloc, existing.json, .{}) catch return error.InvalidRowsRequest;
    defer parsed_existing.deinit();
    if (parsed_existing.value != .object) return error.InvalidRowsRequest;
    var parsed_proposed = std.json.parseFromSlice(std.json.Value, alloc, proposed_row_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed_proposed.deinit();
    if (parsed_proposed.value != .object) return error.InvalidRowsRequest;
    var parsed_source = std.json.parseFromSlice(std.json.Value, alloc, source_row_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed_source.deinit();
    if (parsed_source.value != .object) return error.InvalidRowsRequest;

    if (!try typedConflictActionConditionsMatch(alloc, parsed_existing.value, parsed_proposed.value, parsed_source.value, conflict)) return;

    var operations = try typedConflictUpdateOperationsAlloc(alloc, conflict, parsed_existing.value, parsed_proposed.value, parsed_source.value);
    var operations_transferred = false;
    errdefer if (!operations_transferred) freeTransformOps(alloc, operations);
    operations = try extendOperationsWithOnUpdateAlloc(alloc, operations, schema);

    try appendVersionPredicateAlloc(alloc, predicates, key, existing.version);

    const projected_json = (try db_mod.transform.resolveDocumentTransform(alloc, existing.json, .{ .key = key, .operations = operations })) orelse return error.RowSelectorNotFound;
    defer alloc.free(projected_json);
    const planned_json = try plannedExistingRelationalRowJsonAlloc(alloc, schema, projected_json);
    defer alloc.free(planned_json);
    if (schemaHasGeneratedColumns(schema)) operations = try extendOperationsWithGeneratedColumnsAlloc(alloc, operations, schema, planned_json);

    if (req.returning_all or req.returning.len > 0 or req.returning_expressions.len > 0) {
        const projected = try insertSourceReturningProjectionAlloc(alloc, schema, req, planned_json);
        var projected_transferred = false;
        errdefer if (!projected_transferred) alloc.free(projected);
        try returning_rows.append(alloc, projected);
        projected_transferred = true;
    }

    const transform_key = try alloc.dupe(u8, key);
    var key_transferred = false;
    errdefer if (!key_transferred) alloc.free(transform_key);
    try transforms.append(alloc, .{ .key = transform_key, .operations = operations });
    key_transferred = true;
    operations_transferred = true;
}

fn typedConflictActionConditionsMatch(
    alloc: std.mem.Allocator,
    existing_row: std.json.Value,
    proposed_row: std.json.Value,
    source_row: std.json.Value,
    conflict: db_mod.types.RelationalRowsOnConflict,
) !bool {
    if (conflict.where_expression) |condition| {
        if (!try expressionConditionMatchesWithExplicitSource(alloc, existing_row, proposed_row, source_row, condition)) return false;
    }
    for (conflict.where_expressions) |condition| {
        if (!try expressionConditionMatchesWithExplicitSource(alloc, existing_row, proposed_row, source_row, condition)) return false;
    }
    if (!try conflictExpressionOrPredicateGroupsPass(alloc, existing_row, proposed_row, source_row, conflict.where_any)) return false;
    if (!try conflictExpressionNotPredicateGroupsPass(alloc, existing_row, proposed_row, source_row, conflict.where_not)) return false;
    return true;
}

fn conflictExpressionOrPredicateGroupsPass(
    alloc: std.mem.Allocator,
    existing_row: std.json.Value,
    proposed_row: ?std.json.Value,
    source_row: ?std.json.Value,
    groups: []const db_mod.types.RelationalRowsExpressionPredicateGroup,
) !bool {
    if (groups.len == 0) return true;
    for (groups) |group| {
        var group_passes = true;
        for (group.conditions) |condition| {
            if (!try expressionConditionMatchesWithExplicitSource(alloc, existing_row, proposed_row, source_row, condition)) {
                group_passes = false;
                break;
            }
        }
        if (group_passes) return true;
    }
    return false;
}

fn conflictExpressionNotPredicateGroupsPass(
    alloc: std.mem.Allocator,
    existing_row: std.json.Value,
    proposed_row: ?std.json.Value,
    source_row: ?std.json.Value,
    groups: []const db_mod.types.RelationalRowsExpressionPredicateGroup,
) !bool {
    for (groups) |group| {
        var group_passes = true;
        for (group.conditions) |condition| {
            if (!try expressionConditionMatchesWithExplicitSource(alloc, existing_row, proposed_row, source_row, condition)) {
                group_passes = false;
                break;
            }
        }
        if (group_passes) return false;
    }
    return true;
}

fn typedConflictUpdateOperationsAlloc(
    alloc: std.mem.Allocator,
    conflict: db_mod.types.RelationalRowsOnConflict,
    existing_row: std.json.Value,
    proposed_row: std.json.Value,
    source_row: std.json.Value,
) ![]db_mod.types.TransformOp {
    var operations = std.ArrayListUnmanaged(db_mod.types.TransformOp).empty;
    errdefer {
        for (operations.items) |op| {
            alloc.free(@constCast(op.path));
            if (op.value_json) |value_json| alloc.free(@constCast(value_json));
        }
        operations.deinit(alloc);
    }

    for (conflict.operations) |op| {
        const path = try alloc.dupe(u8, op.path);
        var path_transferred = false;
        errdefer if (!path_transferred) alloc.free(path);
        const value_json: ?[]const u8 = if (op.value_json) |value| try alloc.dupe(u8, value) else null;
        var value_transferred = false;
        errdefer if (!value_transferred) if (value_json) |value| alloc.free(value);
        try operations.append(alloc, .{ .op = op.op, .path = path, .value_json = value_json });
        path_transferred = true;
        value_transferred = true;
    }

    for (conflict.patch_expressions) |assignment| {
        const value_json = try expressionValueJsonWithExplicitSourceAlloc(alloc, existing_row, proposed_row, source_row, assignment.expression);
        var value_transferred = false;
        errdefer if (!value_transferred) alloc.free(value_json);
        const path = try alloc.dupe(u8, assignment.field);
        var path_transferred = false;
        errdefer if (!path_transferred) alloc.free(path);
        try operations.append(alloc, .{ .op = .set, .path = path, .value_json = value_json });
        path_transferred = true;
        value_transferred = true;
    }

    for (conflict.increment_expressions) |assignment| {
        const value_json = try expressionValueJsonWithExplicitSourceAlloc(alloc, existing_row, proposed_row, source_row, assignment.expression);
        var value_transferred = false;
        errdefer if (!value_transferred) alloc.free(value_json);
        try validateIncrementExpressionValueJson(alloc, value_json);
        const path = try alloc.dupe(u8, assignment.field);
        var path_transferred = false;
        errdefer if (!path_transferred) alloc.free(path);
        try operations.append(alloc, .{ .op = .inc, .path = path, .value_json = value_json });
        path_transferred = true;
        value_transferred = true;
    }

    for (conflict.json_set_expressions) |assignment| {
        const transform_path = try jsonSetTypedTransformPathAlloc(alloc, assignment.field, assignment.path);
        var path_transferred = false;
        errdefer if (!path_transferred) alloc.free(transform_path);
        const value_json = try expressionValueJsonWithExplicitSourceAlloc(alloc, existing_row, proposed_row, source_row, assignment.expression);
        var value_transferred = false;
        errdefer if (!value_transferred) alloc.free(value_json);
        try operations.append(alloc, .{ .op = .set, .path = transform_path, .value_json = value_json });
        path_transferred = true;
        value_transferred = true;
    }

    return try operations.toOwnedSlice(alloc);
}

fn jsonSetTypedTransformPathAlloc(
    alloc: std.mem.Allocator,
    field: []const u8,
    path: []const []const u8,
) ![]u8 {
    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.writeAll(field);
    for (path) |segment| {
        if (segment.len == 0 or std.mem.indexOfScalar(u8, segment, '.') != null) return error.InvalidRowsRequest;
        try writer.writeByte('.');
        try writer.writeAll(segment);
    }
    return try out.toOwnedSlice();
}

fn validateConflictTargetPredicateMatchesConstraint(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    unique_value: std.json.Value,
    constraint: runtime_schema.UniqueConstraint,
) !void {
    const where_value = unique_value.object.get("where");
    const where_expressions_value = unique_value.object.get("where_expressions");
    if (constraint.where.len == 0 and constraint.where_expressions.len == 0) {
        if (where_value != null) return error.InvalidRowsRequest;
        if (where_expressions_value != null) return error.InvalidRowsRequest;
        return;
    }
    if (constraint.where.len > 0) {
        if (where_expressions_value != null) return error.InvalidRowsRequest;
        const supplied = where_value orelse return error.InvalidRowsRequest;
        try validateUniquePredicateJsonMatches(alloc, supplied, constraint.where);
        return;
    }
    if (where_value != null) return error.InvalidRowsRequest;
    const supplied = where_expressions_value orelse return error.InvalidRowsRequest;
    const supplied_conditions = try parseRowsConflictWhereExpressionsAlloc(alloc, schema, supplied);
    defer freeRowsQueryExpressionConditions(alloc, supplied_conditions);
    if (!rowsQueryExpressionConditionListsEqual(supplied_conditions, constraint.where_expressions)) return error.InvalidRowsRequest;
}

fn rowsQueryExpressionConditionListsEqual(
    lhs: []const db_mod.types.RelationalRowsExpressionCondition,
    rhs: []const db_mod.types.RelationalRowsExpressionCondition,
) bool {
    if (lhs.len != rhs.len) return false;
    for (lhs, rhs) |left, right| {
        if (!rowsQueryExpressionConditionsEqual(left, right)) return false;
    }
    return true;
}

fn validateUniquePredicateJsonMatches(
    alloc: std.mem.Allocator,
    value: std.json.Value,
    predicates: []const runtime_schema.UniquePredicate,
) !void {
    if (value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(value.object, &.{"all"});
    const all_value = value.object.get("all") orelse return error.InvalidRowsRequest;
    if (all_value != .array or all_value.array.items.len != predicates.len) return error.InvalidRowsRequest;
    for (all_value.array.items, predicates) |item, predicate| {
        try validateUniquePredicateAtomJsonMatches(alloc, item, predicate);
    }
}

fn conflictActionConditionMatches(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    conflict_value: std.json.Value,
    existing_row: std.json.Value,
    proposed_row: ?std.json.Value,
) !bool {
    if (conflict_value.object.get("where_expression")) |condition_value| {
        const condition = try parseRowsExpressionConditionAlloc(alloc, schema, condition_value, true);
        defer freeRowsQueryExpressionCondition(alloc, condition);
        if (!try expressionConditionMatchesWithSources(alloc, existing_row, proposed_row, condition)) return false;
    }
    if (conflict_value.object.get("where_expressions")) |conditions_value| {
        const conditions = try parseRowsConflictWhereExpressionsAlloc(alloc, schema, conditions_value);
        defer freeRowsQueryExpressionConditions(alloc, conditions);
        for (conditions) |condition| {
            if (!try expressionConditionMatchesWithSources(alloc, existing_row, proposed_row, condition)) return false;
        }
    }
    if (conflict_value.object.get("where_any")) |groups_value| {
        const groups = try parseRowsConflictWhereExpressionGroupsAlloc(alloc, schema, groups_value);
        defer freeRowsQueryExpressionPredicateGroups(alloc, groups);
        if (!try conflictExpressionOrPredicateGroupsPass(alloc, existing_row, proposed_row, null, groups)) return false;
    }
    if (conflict_value.object.get("where_not")) |groups_value| {
        const groups = try parseRowsConflictWhereExpressionGroupsAlloc(alloc, schema, groups_value);
        defer freeRowsQueryExpressionPredicateGroups(alloc, groups);
        if (!try conflictExpressionNotPredicateGroupsPass(alloc, existing_row, proposed_row, null, groups)) return false;
    }
    return true;
}

fn validateUniquePredicateAtomJsonMatches(
    alloc: std.mem.Allocator,
    value: std.json.Value,
    predicate: runtime_schema.UniquePredicate,
) !void {
    if (value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(value.object, &.{ "field", "op", "value" });
    const field_value = value.object.get("field") orelse return error.InvalidRowsRequest;
    const op_value = value.object.get("op") orelse return error.InvalidRowsRequest;
    if (field_value != .string or !std.mem.eql(u8, field_value.string, predicate.field)) return error.InvalidRowsRequest;
    if (op_value != .string or !std.mem.eql(u8, op_value.string, expr_type.uniquePredicateOpToken(predicate.op))) return error.InvalidRowsRequest;

    const supplied_value = value.object.get("value");
    if (predicate.value_json) |expected_json| {
        const supplied = supplied_value orelse return error.InvalidRowsRequest;
        const supplied_json = try jsonValueStringifyAlloc(alloc, supplied);
        defer alloc.free(supplied_json);
        if (!std.mem.eql(u8, supplied_json, expected_json)) return error.InvalidRowsRequest;
    } else if (supplied_value != null) {
        return error.InvalidRowsRequest;
    }
}

pub fn physicalPrimaryKeyFromWhereAlloc(
    alloc: std.mem.Allocator,
    table_name: []const u8,
    schema: runtime_schema.TableSchema,
    where_value: std.json.Value,
    unique_resolver: ?UniqueSelectorResolver,
    missing_unique_ok: bool,
) !?[]u8 {
    if (where_value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(where_value.object, &.{ "primary", "unique" });
    if (where_value.object.get("primary") != null and where_value.object.get("unique") != null) return error.InvalidRowsRequest;
    const primary_value = where_value.object.get("primary") orelse {
        if (where_value.object.get("unique")) |unique_value| {
            const resolver = unique_resolver orelse return error.UnsupportedRowsSelector;
            if (unique_value != .object) return error.InvalidRowsRequest;
            try requireJsonObjectOnlyKeys(unique_value.object, &.{ "name", "values", "period" });
            const name_value = unique_value.object.get("name") orelse return error.InvalidRowsRequest;
            if (name_value != .string) return error.InvalidRowsRequest;
            const values_value = unique_value.object.get("values") orelse return error.InvalidRowsRequest;
            if (values_value != .object) return error.InvalidRowsRequest;
            const constraint = findUniqueConstraint(schema.unique_constraints, name_value.string) orelse return error.InvalidRowsRequest;
            const encoded_value = try uniqueConstraintValueFromValuesAlloc(alloc, schema, constraint, values_value);
            defer alloc.free(encoded_value);
            const resolved = if (constraint.without_overlaps_period) |period_name| blk: {
                const period_value = unique_value.object.get("period") orelse return error.InvalidRowsRequest;
                const encoded_point = try temporalSelectorPointBytesAlloc(alloc, schema, period_value, period_name);
                defer alloc.free(encoded_point);
                break :blk try resolver.resolveTemporalUnique(alloc, table_name, constraint.name, encoded_value, encoded_point);
            } else blk: {
                if (unique_value.object.get("period") != null) return error.InvalidRowsRequest;
                break :blk try resolver.resolveUnique(alloc, table_name, constraint.name, encoded_value);
            };
            return resolved orelse {
                if (missing_unique_ok) return null;
                return error.RowSelectorNotFound;
            };
        }
        return error.InvalidRowsRequest;
    };
    if (primary_value != .object) return error.InvalidRowsRequest;
    if (primary_value.object.get("period") != null or primary_value.object.get("values") != null) {
        const resolver = unique_resolver orelse return error.UnsupportedRowsSelector;
        try requireJsonObjectOnlyKeys(primary_value.object, &.{ "values", "period" });
        const values_value = primary_value.object.get("values") orelse return error.InvalidRowsRequest;
        if (values_value != .object) return error.InvalidRowsRequest;
        const period_value = primary_value.object.get("period") orelse return error.InvalidRowsRequest;
        const primary_key = schema.primary_key orelse return error.InvalidRowsRequest;
        const period_name = primary_key.without_overlaps_period orelse return error.InvalidRowsRequest;
        const encoded_value = try primaryKeyValueFromValuesAlloc(alloc, schema, primary_key, values_value);
        defer alloc.free(encoded_value);
        const encoded_point = try temporalSelectorPointBytesAlloc(alloc, schema, period_value, period_name);
        defer alloc.free(encoded_point);
        return (try resolver.resolveTemporalUnique(alloc, table_name, db_mod.relational_store.primary_key_constraint_name, encoded_value, encoded_point)) orelse {
            if (missing_unique_ok) return null;
            return error.RowSelectorNotFound;
        };
    }
    return try physicalPrimaryKeyFromPrimaryValuesAlloc(alloc, schema, primary_value);
}

pub fn physicalPrimaryKeyFromRowJsonAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    row_json: []const u8,
) ![]u8 {
    const primary_key = schema.primary_key orelse return error.InvalidRowsRequest;
    const selected_columns = try primaryKeyColumnsAlloc(alloc, schema, primary_key);
    defer alloc.free(selected_columns);
    const row_value = db_mod.document_mapper.buildRelationalRowValueAlloc(alloc, row_json, selected_columns) catch return error.InvalidRowsRequest;
    defer alloc.free(row_value);
    const tuple = db_mod.relational_store.primaryKeyTupleValueAlloc(alloc, row_value, primary_key) catch return error.InvalidRowsRequest;
    defer alloc.free(tuple);
    if (primary_key.without_overlaps_period) |period_name| {
        var span = try temporalPeriodSpanBytesFromRowAlloc(alloc, schema, row_json, period_name);
        defer span.deinit(alloc);
        return try physicalTemporalPrimaryKeyFromTupleAndSpanAlloc(alloc, tuple, span.start, span.end);
    }
    return try physicalPrimaryKeyFromTupleAlloc(alloc, tuple);
}

fn physicalPrimaryKeyFromPrimaryValuesAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    primary_value: std.json.Value,
) ![]u8 {
    const primary_json = try jsonValueStringifyAlloc(alloc, primary_value);
    defer alloc.free(primary_json);
    return try physicalPrimaryKeyFromRowJsonAlloc(alloc, schema, primary_json);
}

fn primaryKeyValueFromValuesAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    primary_key: runtime_schema.PrimaryKey,
    values: std.json.Value,
) ![]u8 {
    const selected_columns = try primaryKeyColumnsAlloc(alloc, schema, primary_key);
    defer alloc.free(selected_columns);
    const values_json = try jsonValueStringifyAlloc(alloc, values);
    defer alloc.free(values_json);
    const row_value = db_mod.document_mapper.buildRelationalRowValueAlloc(alloc, values_json, selected_columns) catch return error.InvalidRowsRequest;
    defer alloc.free(row_value);
    return db_mod.relational_store.primaryKeyTupleValueAlloc(alloc, row_value, primary_key) catch return error.InvalidRowsRequest;
}

fn primaryKeyValueFromRowJsonAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    primary_key: runtime_schema.PrimaryKey,
    row_json: []const u8,
) ![]u8 {
    const selected_columns = try primaryKeyColumnsAlloc(alloc, schema, primary_key);
    defer alloc.free(selected_columns);
    const row_value = db_mod.document_mapper.buildRelationalRowValueAlloc(alloc, row_json, selected_columns) catch return error.InvalidRowsRequest;
    defer alloc.free(row_value);
    return db_mod.relational_store.primaryKeyTupleValueAlloc(alloc, row_value, primary_key) catch return error.InvalidRowsRequest;
}

pub fn temporalPrimaryKeyRowContainsPointAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    row_json: []const u8,
    encoded_value: []const u8,
    encoded_point: []const u8,
) !bool {
    const primary_key = schema.primary_key orelse return error.InvalidRowsRequest;
    const period_name = primary_key.without_overlaps_period orelse return error.InvalidRowsRequest;
    const tuple = try primaryKeyValueFromRowJsonAlloc(alloc, schema, primary_key, row_json);
    defer alloc.free(tuple);
    if (!std.mem.eql(u8, tuple, encoded_value)) return false;
    var span = try temporalPeriodSpanBytesFromRowAlloc(alloc, schema, row_json, period_name);
    defer span.deinit(alloc);
    return db_mod.relational_store.temporalPeriodSpanBytesContainsPoint(span.start, span.end, encoded_point) catch return error.InvalidRowsRequest;
}

const TemporalPeriodSpanBytes = struct {
    start: []u8,
    end: []u8,

    fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        alloc.free(self.start);
        alloc.free(self.end);
        self.* = undefined;
    }
};

fn temporalPeriodSpanBytesFromRowAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    row_json: []const u8,
    period_name: []const u8,
) !TemporalPeriodSpanBytes {
    const period = findRelationalPeriod(schema.periods, period_name) orelse return error.InvalidRowsRequest;
    const start_column = findRelationalColumn(schema.relational_columns, period.start_column) orelse return error.InvalidRowsRequest;
    const end_column = findRelationalColumn(schema.relational_columns, period.end_column) orelse return error.InvalidRowsRequest;
    if (start_column.field_type != end_column.field_type) return error.InvalidRowsRequest;

    var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidRowsRequest;

    const start_json: ?[]u8 = if (jsonValueAtPath(parsed.value, start_column.path)) |value| blk: {
        break :blk try jsonValueStringifyAlloc(alloc, value.*);
    } else null;
    defer if (start_json) |json| alloc.free(json);
    const end_json: ?[]u8 = if (jsonValueAtPath(parsed.value, end_column.path)) |value| blk: {
        break :blk try jsonValueStringifyAlloc(alloc, value.*);
    } else null;
    defer if (end_json) |json| alloc.free(json);

    const start = db_mod.relational_store.temporalPeriodStartBoundBytesFromJsonAlloc(alloc, start_json, start_column) catch return error.InvalidRowsRequest;
    errdefer alloc.free(start);
    const end = db_mod.relational_store.temporalPeriodEndBoundBytesFromJsonAlloc(alloc, end_json, end_column) catch return error.InvalidRowsRequest;
    errdefer alloc.free(end);
    if (!(db_mod.relational_store.temporalPeriodSpanBytesValid(start, end) catch return error.InvalidRowsRequest)) return error.InvalidRowsRequest;
    return .{ .start = start, .end = end };
}

fn temporalSelectorPointBytesAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    period_value: std.json.Value,
    expected_period_name: []const u8,
) ![]u8 {
    if (period_value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(period_value.object, &.{ "name", "at" });
    const name_value = period_value.object.get("name") orelse return error.InvalidRowsRequest;
    if (name_value != .string or !std.mem.eql(u8, name_value.string, expected_period_name)) return error.InvalidRowsRequest;
    const at_value = period_value.object.get("at") orelse return error.InvalidRowsRequest;
    const period = findRelationalPeriod(schema.periods, expected_period_name) orelse return error.InvalidRowsRequest;
    const start_column = findRelationalColumn(schema.relational_columns, period.start_column) orelse return error.InvalidRowsRequest;
    const end_column = findRelationalColumn(schema.relational_columns, period.end_column) orelse return error.InvalidRowsRequest;
    if (start_column.field_type != end_column.field_type) return error.InvalidRowsRequest;
    const at_json = try jsonValueStringifyAlloc(alloc, at_value);
    defer alloc.free(at_json);
    return db_mod.relational_store.temporalPeriodBoundBytesFromJsonAlloc(alloc, at_json, start_column) catch return error.InvalidRowsRequest;
}

fn physicalPrimaryKeyFromTupleAlloc(alloc: std.mem.Allocator, tuple: []const u8) ![]u8 {
    const encoded_len = std.base64.url_safe_no_pad.Encoder.calcSize(tuple.len);
    const out = try alloc.alloc(u8, physical_primary_key_prefix.len + encoded_len);
    @memcpy(out[0..physical_primary_key_prefix.len], physical_primary_key_prefix);
    _ = std.base64.url_safe_no_pad.Encoder.encode(out[physical_primary_key_prefix.len..], tuple);
    return out;
}

fn physicalTemporalPrimaryKeyFromTupleAndSpanAlloc(
    alloc: std.mem.Allocator,
    tuple: []const u8,
    encoded_start: []const u8,
    encoded_end: []const u8,
) ![]u8 {
    var body = std.ArrayListUnmanaged(u8).empty;
    defer body.deinit(alloc);
    try body.ensureTotalCapacity(alloc, @sizeOf(u32) * 3 + tuple.len + encoded_start.len + encoded_end.len);
    try appendLengthPrefixedBytes(alloc, &body, tuple);
    try appendLengthPrefixedBytes(alloc, &body, encoded_start);
    try appendLengthPrefixedBytes(alloc, &body, encoded_end);
    return try physicalPrimaryKeyFromTupleAlloc(alloc, body.items);
}

fn appendLengthPrefixedBytes(
    alloc: std.mem.Allocator,
    out: *std.ArrayListUnmanaged(u8),
    bytes: []const u8,
) !void {
    if (bytes.len > std.math.maxInt(u32)) return error.InvalidRowsRequest;
    var len_buf: [@sizeOf(u32)]u8 = undefined;
    std.mem.writeInt(u32, &len_buf, @intCast(bytes.len), .big);
    try out.appendSlice(alloc, &len_buf);
    try out.appendSlice(alloc, bytes);
}

fn primaryKeyColumnsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    primary_key: runtime_schema.PrimaryKey,
) ![]runtime_schema.RelationalColumn {
    var selected = try alloc.alloc(runtime_schema.RelationalColumn, primary_key.columns.len);
    errdefer alloc.free(selected);
    for (primary_key.columns, 0..) |column_name, i| {
        selected[i] = findRelationalColumn(schema.relational_columns, column_name) orelse return error.InvalidRowsRequest;
    }
    return selected;
}

fn uniqueConstraintColumnsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    constraint: runtime_schema.UniqueConstraint,
) ![]runtime_schema.RelationalColumn {
    var selected = std.ArrayListUnmanaged(runtime_schema.RelationalColumn).empty;
    errdefer selected.deinit(alloc);
    for (constraint.columns) |column_name| {
        try appendUniqueConstraintSelectedColumn(alloc, &selected, schema, column_name);
    }
    for (constraint.expressions) |expression| {
        try appendUniqueConstraintUniqueExpressionColumns(alloc, &selected, schema, expression);
    }
    for (constraint.where) |predicate| {
        try appendUniqueConstraintSelectedColumn(alloc, &selected, schema, predicate.field);
    }
    for (constraint.where_expressions) |condition| {
        try appendUniqueConstraintExpressionConditionColumns(alloc, &selected, schema, condition);
    }
    return try selected.toOwnedSlice(alloc);
}

fn appendUniqueConstraintUniqueExpressionColumns(
    alloc: std.mem.Allocator,
    selected: *std.ArrayListUnmanaged(runtime_schema.RelationalColumn),
    schema: runtime_schema.TableSchema,
    expression: runtime_schema.UniqueExpression,
) anyerror!void {
    switch (expression.op) {
        .lower, .upper, .md5 => try appendUniqueConstraintSelectedColumn(alloc, selected, schema, expression.field),
        .expression => {
            const row_expression = expression.expression orelse return error.InvalidRowsRequest;
            try appendUniqueConstraintExpressionColumns(alloc, selected, schema, row_expression);
        },
    }
}

fn appendUniqueConstraintSelectedColumn(
    alloc: std.mem.Allocator,
    selected: *std.ArrayListUnmanaged(runtime_schema.RelationalColumn),
    schema: runtime_schema.TableSchema,
    field: []const u8,
) !void {
    if (relationalColumnListContains(selected.items, field)) return;
    const column = findRelationalColumn(schema.relational_columns, field) orelse return error.InvalidRowsRequest;
    try selected.append(alloc, column);
}

fn appendUniqueConstraintExpressionConditionColumns(
    alloc: std.mem.Allocator,
    selected: *std.ArrayListUnmanaged(runtime_schema.RelationalColumn),
    schema: runtime_schema.TableSchema,
    condition: db_mod.types.RelationalRowsExpressionCondition,
) anyerror!void {
    try appendUniqueConstraintExpressionColumns(alloc, selected, schema, condition.lhs);
    for (condition.rhs) |expression| {
        try appendUniqueConstraintExpressionColumns(alloc, selected, schema, expression);
    }
}

fn appendUniqueConstraintExpressionColumns(
    alloc: std.mem.Allocator,
    selected: *std.ArrayListUnmanaged(runtime_schema.RelationalColumn),
    schema: runtime_schema.TableSchema,
    expression: db_mod.types.RelationalRowsExpression,
) anyerror!void {
    if (expression.kind == .field) {
        if (expression.field_source != .row) return error.InvalidRowsRequest;
        try appendUniqueConstraintSelectedColumn(alloc, selected, schema, expression.field);
    }
    for (expression.operands) |operand| {
        try appendUniqueConstraintExpressionColumns(alloc, selected, schema, operand);
    }
    for (expression.case_branches) |branch| {
        try appendUniqueConstraintExpressionConditionColumns(alloc, selected, schema, branch.when);
        try appendUniqueConstraintExpressionColumns(alloc, selected, schema, branch.then);
    }
    for (expression.case_else) |case_else| {
        try appendUniqueConstraintExpressionColumns(alloc, selected, schema, case_else);
    }
}

fn relationalColumnListContains(columns: []const runtime_schema.RelationalColumn, field: []const u8) bool {
    for (columns) |column| {
        if (std.mem.eql(u8, column.path, field) or std.mem.eql(u8, column.name, field)) return true;
    }
    return false;
}

fn findUniqueConstraint(constraints: []const runtime_schema.UniqueConstraint, name: []const u8) ?runtime_schema.UniqueConstraint {
    for (constraints) |constraint| {
        if (constraint.validation_state != .enforced) continue;
        if (std.mem.eql(u8, constraint.name, name)) return constraint;
    }
    return null;
}

fn findRelationalColumn(columns: []const runtime_schema.RelationalColumn, name: []const u8) ?runtime_schema.RelationalColumn {
    for (columns) |column| {
        if (std.mem.eql(u8, column.path, name) or std.mem.eql(u8, column.name, name)) return column;
    }
    return null;
}

fn relationalJsonColumnSubpathIsValid(columns: []const runtime_schema.RelationalColumn, field: []const u8) bool {
    const dot = std.mem.indexOfScalar(u8, field, '.') orelse return false;
    if (dot == 0 or dot + 1 >= field.len) return false;
    const root = field[0..dot];
    const column = findRelationalColumn(columns, root) orelse return false;
    return column.field_type == .json;
}

fn findRelationalPeriod(periods: []const runtime_schema.RelationalPeriod, name: []const u8) ?runtime_schema.RelationalPeriod {
    for (periods) |period| {
        if (std.mem.eql(u8, period.name, name)) return period;
    }
    return null;
}

fn findRelationalColumnIndex(columns: []const runtime_schema.RelationalColumn, name: []const u8) ?usize {
    for (columns, 0..) |column, i| {
        if (std.mem.eql(u8, column.path, name) or std.mem.eql(u8, column.name, name)) return i;
    }
    return null;
}

fn uniqueConstraintValueFromValuesAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    constraint: runtime_schema.UniqueConstraint,
    values: std.json.Value,
) ![]u8 {
    const selected_columns = try uniqueConstraintColumnsAlloc(alloc, schema, constraint);
    defer alloc.free(selected_columns);
    const values_json = try jsonValueStringifyAlloc(alloc, values);
    defer alloc.free(values_json);
    const row_value = db_mod.document_mapper.buildRelationalRowValueAlloc(alloc, values_json, selected_columns) catch return error.InvalidRowsRequest;
    defer alloc.free(row_value);
    const tuple = (db_mod.relational_store.uniqueConstraintTupleValueWithColumnsAlloc(alloc, row_value, constraint, selected_columns) catch return error.InvalidRowsRequest) orelse return error.InvalidRowsRequest;
    return tuple;
}

fn uniqueConstraintValueFromRowAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    constraint: runtime_schema.UniqueConstraint,
    row_json: []const u8,
) !?[]u8 {
    const row_value = db_mod.document_mapper.buildRelationalRowValueAlloc(alloc, row_json, schema.relational_columns) catch return error.InvalidRowsRequest;
    defer alloc.free(row_value);
    return (db_mod.relational_store.uniqueConstraintTupleValueWithColumnsAlloc(alloc, row_value, constraint, schema.relational_columns) catch return error.InvalidRowsRequest);
}

fn updateTransformOperationsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    op_value: std.json.Value,
    existing_row: ?std.json.Value,
    proposed_row: ?std.json.Value,
) ![]db_mod.types.TransformOp {
    if (op_value != .object) return error.InvalidRowsRequest;
    var operations = std.ArrayListUnmanaged(db_mod.types.TransformOp).empty;
    errdefer {
        for (operations.items) |op| {
            alloc.free(@constCast(op.path));
            if (op.value_json) |value_json| alloc.free(@constCast(value_json));
        }
        operations.deinit(alloc);
    }

    var saw_mutation = false;
    if (op_value.object.get("patch")) |patch| {
        saw_mutation = true;
        if (patch != .object) return error.InvalidRowsRequest;
        try appendPatchTransformOperationsAlloc(alloc, schema, patch, false, &operations);
    }
    if (op_value.object.get("patch_expr")) |patch_expr| {
        saw_mutation = true;
        if (patch_expr != .object) return error.InvalidRowsRequest;
        const existing = existing_row orelse return error.InvalidRowsRequest;
        try appendPatchExpressionTransformOperationsAlloc(alloc, schema, existing, proposed_row, patch_expr, false, &operations);
    }
    if (op_value.object.get("increment")) |increment| {
        saw_mutation = true;
        if (increment != .object) return error.InvalidRowsRequest;
        try appendIncrementTransformOperationsAlloc(alloc, schema, increment, &operations);
    }
    if (op_value.object.get("increment_expr")) |increment_expr| {
        saw_mutation = true;
        if (increment_expr != .object) return error.InvalidRowsRequest;
        const existing = existing_row orelse return error.InvalidRowsRequest;
        try appendIncrementExpressionTransformOperationsAlloc(alloc, schema, existing, proposed_row, increment_expr, &operations);
    }
    if (op_value.object.get("json_set")) |json_set| {
        saw_mutation = true;
        try appendJsonSetTransformOperationsAlloc(alloc, schema, json_set, existing_row, proposed_row, false, &operations);
    }
    if (op_value.object.get("array_update")) |array_update| {
        saw_mutation = true;
        try appendArrayUpdateTransformOperationsAlloc(alloc, schema, array_update, &operations);
    }
    if (!saw_mutation) return error.InvalidRowsRequest;
    try validateRowsMutationUpdateTargetPaths(operations.items, &.{}, &.{}, &.{}, &.{});

    return try operations.toOwnedSlice(alloc);
}

fn rewriteIdentityTransformOperationsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    op_value: std.json.Value,
    existing_row: std.json.Value,
) ![]db_mod.types.TransformOp {
    if (op_value != .object) return error.InvalidRowsRequest;
    var operations = std.ArrayListUnmanaged(db_mod.types.TransformOp).empty;
    errdefer {
        for (operations.items) |op| {
            alloc.free(@constCast(op.path));
            if (op.value_json) |value_json| alloc.free(@constCast(value_json));
        }
        operations.deinit(alloc);
    }

    var saw_mutation = false;
    var saw_identity_mutation = false;
    if (op_value.object.get("patch")) |patch| {
        saw_mutation = true;
        if (patch != .object) return error.InvalidRowsRequest;
        saw_identity_mutation = saw_identity_mutation or patchTouchesPrimaryKey(schema.primary_key.?, patch);
        try appendPatchTransformOperationsAlloc(alloc, schema, patch, true, &operations);
    }
    if (op_value.object.get("patch_expr")) |patch_expr| {
        saw_mutation = true;
        if (patch_expr != .object) return error.InvalidRowsRequest;
        saw_identity_mutation = saw_identity_mutation or patchTouchesPrimaryKey(schema.primary_key.?, patch_expr);
        try appendPatchExpressionTransformOperationsAlloc(alloc, schema, existing_row, null, patch_expr, true, &operations);
    }
    if (op_value.object.get("increment")) |increment| {
        saw_mutation = true;
        if (increment != .object) return error.InvalidRowsRequest;
        if (patchTouchesPrimaryKey(schema.primary_key.?, increment)) return error.InvalidRowsRequest;
        try appendIncrementTransformOperationsAlloc(alloc, schema, increment, &operations);
    }
    if (op_value.object.get("increment_expr")) |increment_expr| {
        saw_mutation = true;
        if (increment_expr != .object) return error.InvalidRowsRequest;
        if (patchTouchesPrimaryKey(schema.primary_key.?, increment_expr)) return error.InvalidRowsRequest;
        try appendIncrementExpressionTransformOperationsAlloc(alloc, schema, existing_row, null, increment_expr, &operations);
    }
    if (op_value.object.get("json_set")) |json_set| {
        saw_mutation = true;
        try appendJsonSetTransformOperationsAlloc(alloc, schema, json_set, existing_row, null, false, &operations);
    }
    if (op_value.object.get("array_update")) |array_update| {
        saw_mutation = true;
        try appendArrayUpdateTransformOperationsAlloc(alloc, schema, array_update, &operations);
    }
    if (!saw_mutation or !saw_identity_mutation) return error.InvalidRowsRequest;
    try validateRowsMutationUpdateTargetPaths(operations.items, &.{}, &.{}, &.{}, &.{});

    return try operations.toOwnedSlice(alloc);
}

fn patchTouchesPrimaryKey(primary_key: runtime_schema.PrimaryKey, patch: std.json.Value) bool {
    if (patch != .object) return false;
    var it = patch.object.iterator();
    while (it.next()) |entry| {
        if (primaryKeyContains(primary_key, entry.key_ptr.*)) return true;
    }
    return false;
}

fn staticUpdateTransformOperationsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    op_value: std.json.Value,
    skip_json_set_expressions: bool,
    allow_primary_key: bool,
) ![]db_mod.types.TransformOp {
    if (op_value != .object) return error.InvalidRowsRequest;
    var operations = std.ArrayListUnmanaged(db_mod.types.TransformOp).empty;
    errdefer {
        for (operations.items) |op| {
            alloc.free(@constCast(op.path));
            if (op.value_json) |value_json| alloc.free(@constCast(value_json));
        }
        operations.deinit(alloc);
    }

    if (op_value.object.get("patch")) |patch| {
        if (patch != .object) return error.InvalidRowsRequest;
        try appendPatchTransformOperationsAlloc(alloc, schema, patch, allow_primary_key, &operations);
    }
    if (op_value.object.get("increment")) |increment| {
        if (increment != .object) return error.InvalidRowsRequest;
        try appendIncrementTransformOperationsAlloc(alloc, schema, increment, &operations);
    }
    if (op_value.object.get("json_set")) |json_set| {
        try appendJsonSetTransformOperationsAlloc(alloc, schema, json_set, null, null, skip_json_set_expressions, &operations);
    }
    if (op_value.object.get("array_update")) |array_update| {
        try appendArrayUpdateTransformOperationsAlloc(alloc, schema, array_update, &operations);
    }

    return try operations.toOwnedSlice(alloc);
}

fn parseRowsMutationExpressionAssignmentsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    maybe_assignments: ?std.json.Value,
    require_numeric: bool,
    allow_proposed_source: bool,
    allow_primary_key: bool,
    scalar_subqueries: []const db_mod.types.RelationalRowsScalarSubqueryProjection,
) ![]db_mod.types.RelationalRowsExpressionAssignment {
    const assignments_value = maybe_assignments orelse return &.{};
    if (assignments_value != .object) return error.InvalidRowsRequest;

    const assignments = try alloc.alloc(db_mod.types.RelationalRowsExpressionAssignment, assignments_value.object.count());
    var initialized: usize = 0;
    errdefer {
        for (assignments[0..initialized]) |assignment| {
            alloc.free(@constCast(assignment.field));
            freeRowsQueryExpression(alloc, assignment.expression);
        }
        alloc.free(assignments);
    }

    var it = assignments_value.object.iterator();
    while (it.next()) |entry| {
        const column = findRelationalColumn(schema.relational_columns, entry.key_ptr.*) orelse return error.InvalidRowsRequest;
        if (schema.primary_key) |primary_key| {
            if (!allow_primary_key and primaryKeyContains(primary_key, entry.key_ptr.*)) return error.InvalidRowsRequest;
        }
        if (require_numeric and column.field_type != .numeric) return error.InvalidRowsRequest;
        const expression = try parseRowsMutationExpressionWithScalarOutputsAlloc(alloc, schema, entry.value_ptr.*, scalar_subqueries);
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeRowsQueryExpression(alloc, expression);
        if (!allow_proposed_source and expressionUsesProposedSource(expression)) return error.InvalidRowsRequest;
        const references_scalar_output = rowsExpressionReferencesScalarOutput(expression, scalar_subqueries);
        if (!references_scalar_output and (require_numeric or column.field_type == .numeric or column.field_type == .datetime)) {
            try validateRowsQueryNumericExpression(alloc, schema, expression);
        } else if (!references_scalar_output and (column.field_type == .keyword or column.field_type == .text or column.field_type == .link)) {
            try validateRowsQueryTextExpression(alloc, schema, expression);
        }
        const field = try alloc.dupe(u8, column.path);
        var field_transferred = false;
        errdefer if (!field_transferred) alloc.free(field);
        assignments[initialized] = .{
            .field = field,
            .expression = expression,
        };
        field_transferred = true;
        expression_transferred = true;
        initialized += 1;
    }

    return assignments;
}

fn parseRowsJoinedMutationExpressionAssignmentsAlloc(
    alloc: std.mem.Allocator,
    target_schema: runtime_schema.TableSchema,
    source_schema: runtime_schema.TableSchema,
    maybe_assignments: ?std.json.Value,
    require_numeric: bool,
    allow_primary_key: bool,
) ![]db_mod.types.RelationalRowsExpressionAssignment {
    const assignments_value = maybe_assignments orelse return &.{};
    if (assignments_value != .object) return error.InvalidRowsRequest;

    const assignments = try alloc.alloc(db_mod.types.RelationalRowsExpressionAssignment, assignments_value.object.count());
    var initialized: usize = 0;
    errdefer {
        for (assignments[0..initialized]) |assignment| {
            alloc.free(@constCast(assignment.field));
            freeRowsQueryExpression(alloc, assignment.expression);
        }
        alloc.free(assignments);
    }

    var it = assignments_value.object.iterator();
    while (it.next()) |entry| {
        const column = findRelationalColumn(target_schema.relational_columns, entry.key_ptr.*) orelse return error.InvalidRowsRequest;
        if (target_schema.primary_key) |primary_key| {
            if (!allow_primary_key and primaryKeyContains(primary_key, entry.key_ptr.*)) return error.InvalidRowsRequest;
        }
        if (require_numeric and column.field_type != .numeric) return error.InvalidRowsRequest;
        const expression = try parseRowsExpressionWithSourceSchemaAlloc(alloc, target_schema, source_schema, entry.value_ptr.*, true);
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeRowsQueryExpression(alloc, expression);
        if (rowsExpressionUsesFieldSource(expression, .existing) or rowsExpressionUsesFieldSource(expression, .proposed)) return error.InvalidRowsRequest;
        const expression_type = try rowsExpressionOutputTypeWithSources(alloc, target_schema, source_schema, expression);
        const compatible = if (column.field_type == .json or column.field_type == .array)
            expression_type == column.field_type
        else
            rowsExpressionTypesComparable(column.field_type, expression_type);
        if (!compatible) return error.InvalidRowsRequest;
        if (require_numeric or column.field_type == .numeric) {
            try validateRowsQueryNumericExpressionWithSources(alloc, target_schema, source_schema, expression);
        } else if (column.field_type == .datetime) {
            const output_type = try rowsExpressionOutputTypeWithSources(alloc, target_schema, source_schema, expression);
            if (output_type != .datetime and output_type != .numeric) return error.InvalidRowsRequest;
        } else if (column.field_type == .keyword or column.field_type == .text or column.field_type == .link) {
            try validateRowsQueryTextExpressionWithSources(alloc, target_schema, source_schema, expression);
        }
        const field = try alloc.dupe(u8, column.path);
        var field_transferred = false;
        errdefer if (!field_transferred) alloc.free(field);
        assignments[initialized] = .{
            .field = field,
            .expression = expression,
        };
        field_transferred = true;
        expression_transferred = true;
        initialized += 1;
    }

    return assignments;
}

fn parseRowsInsertSourceAssignmentsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    assignments_value: std.json.Value,
) ![]const db_mod.types.RelationalRowsExpressionAssignment {
    return try parseRowsInsertSourceAssignmentsWithSchemasAlloc(alloc, schema, schema, assignments_value);
}

fn parseRowsInsertSourceAssignmentsWithSchemasAlloc(
    alloc: std.mem.Allocator,
    target_schema: runtime_schema.TableSchema,
    source_schema: runtime_schema.TableSchema,
    assignments_value: std.json.Value,
) ![]const db_mod.types.RelationalRowsExpressionAssignment {
    if (assignments_value != .array or assignments_value.array.items.len == 0) return error.InvalidRowsRequest;

    const assignments = try alloc.alloc(db_mod.types.RelationalRowsExpressionAssignment, assignments_value.array.items.len);
    var initialized: usize = 0;
    errdefer {
        for (assignments[0..initialized]) |assignment| {
            alloc.free(@constCast(assignment.field));
            freeRowsQueryExpression(alloc, assignment.expression);
        }
        alloc.free(assignments);
    }

    for (assignments_value.array.items) |item| {
        if (item != .object) return error.InvalidRowsRequest;
        try requireJsonObjectOnlyKeys(item.object, &.{ "target_field", "expr" });
        const target_value = item.object.get("target_field") orelse return error.InvalidRowsRequest;
        if (target_value != .string or target_value.string.len == 0) return error.InvalidRowsRequest;
        const column = findRelationalColumn(target_schema.relational_columns, target_value.string) orelse return error.InvalidRowsRequest;
        for (assignments[0..initialized]) |existing| {
            if (std.mem.eql(u8, existing.field, column.path)) return error.InvalidRowsRequest;
        }

        const expression_value = item.object.get("expr") orelse return error.InvalidRowsRequest;
        const expression = try parseRowsExpressionAlloc(alloc, source_schema, expression_value, true);
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeRowsQueryExpression(alloc, expression);
        if (expressionUsesInsertSourceDisallowedMutationSource(expression)) return error.InvalidRowsRequest;
        try validateRowsInsertSourceAssignmentType(alloc, source_schema, column, expression);

        const field = try alloc.dupe(u8, column.path);
        var field_transferred = false;
        errdefer if (!field_transferred) alloc.free(field);
        assignments[initialized] = .{
            .field = field,
            .expression = expression,
        };
        field_transferred = true;
        expression_transferred = true;
        initialized += 1;
    }

    return assignments;
}

fn validateRowsInsertSourceAssignmentType(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    column: runtime_schema.RelationalColumn,
    expression: db_mod.types.RelationalRowsExpression,
) !void {
    const expression_type = try rowsExpressionOutputType(alloc, schema, expression);
    const compatible = if (column.field_type == .json or column.field_type == .array)
        expression_type == column.field_type
    else
        rowsExpressionTypesComparable(column.field_type, expression_type);
    if (!compatible) return error.InvalidRowsRequest;
}

fn expressionUsesInsertSourceDisallowedMutationSource(expression: db_mod.types.RelationalRowsExpression) bool {
    if (expression.kind == .field and (expression.field_source == .existing or expression.field_source == .proposed)) return true;
    for (expression.operands) |operand| if (expressionUsesInsertSourceDisallowedMutationSource(operand)) return true;
    for (expression.case_branches) |branch| {
        if (expressionConditionUsesInsertSourceDisallowedMutationSource(branch.when) or expressionUsesInsertSourceDisallowedMutationSource(branch.then)) return true;
    }
    for (expression.case_else) |fallback| if (expressionUsesInsertSourceDisallowedMutationSource(fallback)) return true;
    return false;
}

fn expressionConditionUsesInsertSourceDisallowedMutationSource(condition: db_mod.types.RelationalRowsExpressionCondition) bool {
    if (expressionUsesInsertSourceDisallowedMutationSource(condition.lhs)) return true;
    for (condition.rhs) |rhs| if (expressionUsesInsertSourceDisallowedMutationSource(rhs)) return true;
    return false;
}

fn parseRowsOnConflictAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    conflict_value: std.json.Value,
) !db_mod.types.RelationalRowsOnConflict {
    if (conflict_value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(conflict_value.object, &.{ "target", "action", "patch", "patch_expr", "increment", "increment_expr", "json_set", "array_update", "where_expression", "where_expressions", "where_any", "where_not" });
    const target = try parseRowsConflictTargetAlloc(alloc, schema, conflict_value.object.get("target") orelse return error.InvalidRowsRequest);
    errdefer freeRowsConflictTarget(alloc, target);

    const action = switch (try parseConflictAction(conflict_value.object.get("action") orelse return error.InvalidRowsRequest)) {
        .update => db_mod.types.RelationalRowsConflictAction.update,
        .nothing => db_mod.types.RelationalRowsConflictAction.nothing,
    };

    const operations = try staticUpdateTransformOperationsAlloc(alloc, schema, conflict_value, true, false);
    errdefer freeTransformOps(alloc, operations);
    const patch_expressions = try parseRowsMutationExpressionAssignmentsAlloc(alloc, schema, conflict_value.object.get("patch_expr"), false, true, false, &.{});
    errdefer freeRowsExpressionAssignments(alloc, patch_expressions);
    const increment_expressions = try parseRowsMutationExpressionAssignmentsAlloc(alloc, schema, conflict_value.object.get("increment_expr"), true, true, false, &.{});
    errdefer freeRowsExpressionAssignments(alloc, increment_expressions);
    const json_set_expressions = try parseRowsMutationJsonSetExpressionAssignmentsAlloc(alloc, schema, conflict_value.object.get("json_set"), true);
    errdefer freeRowsJsonSetExpressionAssignments(alloc, json_set_expressions);

    const where_expression: ?db_mod.types.RelationalRowsExpressionCondition = if (conflict_value.object.get("where_expression")) |condition_value|
        try parseRowsExpressionConditionAlloc(alloc, schema, condition_value, true)
    else
        null;
    errdefer if (where_expression) |condition| freeRowsQueryExpressionCondition(alloc, condition);
    const where_expressions = try parseRowsConflictWhereExpressionsAlloc(alloc, schema, conflict_value.object.get("where_expressions"));
    errdefer freeRowsQueryExpressionConditions(alloc, where_expressions);
    const where_any = try parseRowsConflictWhereExpressionGroupsAlloc(alloc, schema, conflict_value.object.get("where_any"));
    errdefer freeRowsQueryExpressionPredicateGroups(alloc, where_any);
    const where_not = try parseRowsConflictWhereExpressionGroupsAlloc(alloc, schema, conflict_value.object.get("where_not"));
    errdefer freeRowsQueryExpressionPredicateGroups(alloc, where_not);

    if (action == .nothing) {
        if (operations.len != 0 or patch_expressions.len != 0 or increment_expressions.len != 0 or json_set_expressions.len != 0 or where_expression != null or where_expressions.len != 0 or where_any.len != 0 or where_not.len != 0) return error.InvalidRowsRequest;
    } else if (operations.len == 0 and patch_expressions.len == 0 and increment_expressions.len == 0 and json_set_expressions.len == 0) {
        return error.InvalidRowsRequest;
    }

    try validateRowsMutationUpdateTargetPaths(operations, patch_expressions, increment_expressions, json_set_expressions, &.{});

    return .{
        .target = target,
        .action = action,
        .operations = operations,
        .patch_expressions = patch_expressions,
        .increment_expressions = increment_expressions,
        .json_set_expressions = json_set_expressions,
        .where_expression = where_expression,
        .where_expressions = where_expressions,
        .where_any = where_any,
        .where_not = where_not,
    };
}

fn parseRowsConflictWhereExpressionsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    maybe_expressions: ?std.json.Value,
) ![]const db_mod.types.RelationalRowsExpressionCondition {
    const expressions_value = maybe_expressions orelse return &.{};
    if (expressions_value != .array) return error.InvalidRowsRequest;
    const out = try alloc.alloc(db_mod.types.RelationalRowsExpressionCondition, expressions_value.array.items.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |condition| freeRowsQueryExpressionCondition(alloc, condition);
        alloc.free(out);
    }
    for (expressions_value.array.items) |item| {
        out[initialized] = try parseRowsExpressionConditionAlloc(alloc, schema, item, true);
        initialized += 1;
    }
    return out;
}

fn parseRowsConflictWhereExpressionGroupsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    maybe_groups: ?std.json.Value,
) ![]const db_mod.types.RelationalRowsExpressionPredicateGroup {
    const groups_value = maybe_groups orelse return &.{};
    if (groups_value != .array or groups_value.array.items.len == 0) return error.InvalidRowsRequest;

    const groups = try alloc.alloc(db_mod.types.RelationalRowsExpressionPredicateGroup, groups_value.array.items.len);
    var initialized: usize = 0;
    errdefer {
        for (groups[0..initialized]) |group| freeRowsQueryExpressionConditions(alloc, group.conditions);
        alloc.free(groups);
    }

    for (groups_value.array.items) |branch| {
        if (branch != .object) return error.InvalidRowsRequest;
        try requireJsonObjectOnlyKeys(branch.object, &.{"all"});
        const conditions = try parseRowsConflictWhereExpressionsAlloc(alloc, schema, branch.object.get("all") orelse return error.InvalidRowsRequest);
        var conditions_transferred = false;
        errdefer if (!conditions_transferred) freeRowsQueryExpressionConditions(alloc, conditions);
        if (conditions.len == 0) return error.InvalidRowsRequest;
        groups[initialized] = .{ .conditions = conditions };
        conditions_transferred = true;
        initialized += 1;
    }
    return groups;
}

fn parseRowsConflictTargetAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    target_value: std.json.Value,
) !db_mod.types.RelationalRowsConflictTarget {
    if (target_value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(target_value.object, &.{ "any", "primary", "unique" });
    try validateConflictTargetObjectShape(target_value);
    if (target_value.object.get("any")) |any_value| {
        if (any_value != .bool or !any_value.bool) return error.InvalidRowsRequest;
        return .{ .kind = .any };
    }
    if (target_value.object.get("primary")) |primary_value| {
        if (primary_value != .bool or !primary_value.bool) return error.InvalidRowsRequest;
        return .{ .kind = .primary };
    }
    const unique_value = target_value.object.get("unique") orelse return error.InvalidRowsRequest;
    if (unique_value != .object) return error.InvalidRowsRequest;
    try requireJsonObjectOnlyKeys(unique_value.object, &.{ "name", "where", "where_expressions" });
    const name_value = unique_value.object.get("name") orelse return error.InvalidRowsRequest;
    if (name_value != .string or name_value.string.len == 0) return error.InvalidRowsRequest;
    const constraint = findUniqueConstraint(schema.unique_constraints, name_value.string) orelse return error.InvalidRowsRequest;
    const unique_name = try alloc.dupe(u8, constraint.name);
    errdefer alloc.free(unique_name);
    const unique_predicates = try parseRowsConflictTargetPredicateAlloc(alloc, schema, unique_value.object.get("where"), constraint);
    errdefer {
        freeQueryPredicates(alloc, unique_predicates);
        if (unique_predicates.len > 0) alloc.free(unique_predicates);
    }
    const unique_predicate_expressions = try parseRowsConflictTargetExpressionPredicateAlloc(alloc, schema, unique_value.object.get("where_expressions"), constraint);
    errdefer freeRowsQueryExpressionConditions(alloc, unique_predicate_expressions);
    return .{
        .kind = .unique,
        .unique_name = unique_name,
        .unique_predicates = unique_predicates,
        .unique_predicate_expressions = unique_predicate_expressions,
    };
}

fn parseRowsConflictTargetPredicateAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    maybe_where: ?std.json.Value,
    constraint: runtime_schema.UniqueConstraint,
) ![]const runtime_schema.RelationalCheck {
    if (constraint.where.len == 0) {
        if (maybe_where != null) return error.InvalidRowsRequest;
        return &.{};
    }
    const where_value = maybe_where orelse return error.InvalidRowsRequest;
    const predicates = try parseRowsQueryPredicatesAlloc(alloc, schema, where_value);
    errdefer {
        freeQueryPredicates(alloc, predicates);
        if (predicates.len > 0) alloc.free(predicates);
    }
    try validateConflictTargetPredicatesMatchConstraint(predicates, constraint);
    return predicates;
}

fn parseRowsConflictTargetExpressionPredicateAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    maybe_where_expressions: ?std.json.Value,
    constraint: runtime_schema.UniqueConstraint,
) ![]const db_mod.types.RelationalRowsExpressionCondition {
    if (constraint.where_expressions.len == 0) {
        if (maybe_where_expressions != null) return error.InvalidRowsRequest;
        return &.{};
    }
    const where_expressions = maybe_where_expressions orelse return error.InvalidRowsRequest;
    const predicates = try parseRowsConflictWhereExpressionsAlloc(alloc, schema, where_expressions);
    errdefer freeRowsQueryExpressionConditions(alloc, predicates);
    if (!rowsQueryExpressionConditionListsEqual(predicates, constraint.where_expressions)) return error.InvalidRowsRequest;
    return predicates;
}

fn validateConflictTargetPredicatesMatchConstraint(
    predicates: []const runtime_schema.RelationalCheck,
    constraint: runtime_schema.UniqueConstraint,
) !void {
    if (predicates.len != constraint.where.len) return error.InvalidRowsRequest;
    for (predicates, constraint.where) |actual, expected| {
        if (!std.mem.eql(u8, actual.field, expected.field)) return error.InvalidRowsRequest;
        if (!uniquePredicateOpMatchesRelationalCheck(actual.op, expected.op)) return error.InvalidRowsRequest;
        if (expected.value_json) |expected_json| {
            const actual_json = actual.value_json orelse return error.InvalidRowsRequest;
            if (!std.mem.eql(u8, actual_json, expected_json)) return error.InvalidRowsRequest;
        } else if (actual.value_json != null) {
            return error.InvalidRowsRequest;
        }
    }
}

fn validateTypedConflictTargetMatchesConstraint(
    target: db_mod.types.RelationalRowsConflictTarget,
    constraint: runtime_schema.UniqueConstraint,
) !void {
    try validateConflictTargetPredicatesMatchConstraint(target.unique_predicates, constraint);
    if (!rowsQueryExpressionConditionListsEqual(target.unique_predicate_expressions, constraint.where_expressions)) return error.InvalidRowsRequest;
}

fn uniquePredicateOpMatchesRelationalCheck(actual: runtime_schema.RelationalCheckOp, expected: runtime_schema.UniquePredicateOp) bool {
    return switch (expected) {
        .is_null => actual == .is_null,
        .is_not_null => actual == .is_not_null,
        .eq => actual == .eq,
        .ne => actual == .ne,
    };
}

fn freeRowsConflictTarget(alloc: std.mem.Allocator, target: db_mod.types.RelationalRowsConflictTarget) void {
    if (target.unique_name.len > 0) alloc.free(@constCast(target.unique_name));
    freeQueryPredicates(alloc, target.unique_predicates);
    if (target.unique_predicates.len > 0) alloc.free(target.unique_predicates);
    freeRowsQueryExpressionConditions(alloc, target.unique_predicate_expressions);
}

fn parseRowsMutationJsonSetExpressionAssignmentsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    maybe_json_set: ?std.json.Value,
    allow_proposed_source: bool,
) ![]db_mod.types.RelationalRowsJsonSetExpressionAssignment {
    const json_set = maybe_json_set orelse return &.{};
    if (json_set != .array) return error.InvalidRowsRequest;

    var assignments = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonSetExpressionAssignment).empty;
    errdefer {
        for (assignments.items) |assignment| {
            alloc.free(@constCast(assignment.field));
            for (assignment.path) |segment| alloc.free(@constCast(segment));
            if (assignment.path.len > 0) alloc.free(assignment.path);
            freeRowsQueryExpression(alloc, assignment.expression);
        }
        assignments.deinit(alloc);
    }

    for (json_set.array.items) |item| {
        if (item != .object) return error.InvalidRowsRequest;
        try requireJsonObjectOnlyKeys(item.object, &.{ "field", "path", "value", "expr" });
        if (item.object.get("value") != null) continue;
        const expr_value = item.object.get("expr") orelse return error.InvalidRowsRequest;

        const field_value = item.object.get("field") orelse return error.InvalidRowsRequest;
        if (field_value != .string or field_value.string.len == 0) return error.InvalidRowsRequest;
        const column = findRelationalColumn(schema.relational_columns, field_value.string) orelse return error.InvalidRowsRequest;
        if (column.field_type != .json) return error.InvalidRowsRequest;
        if (schema.primary_key) |primary_key| {
            if (primaryKeyContains(primary_key, field_value.string)) return error.InvalidRowsRequest;
        }

        const path_value = item.object.get("path") orelse return error.InvalidRowsRequest;
        if (path_value != .array or path_value.array.items.len == 0) return error.InvalidRowsRequest;
        const path = try alloc.alloc([]const u8, path_value.array.items.len);
        var path_initialized: usize = 0;
        errdefer {
            for (path[0..path_initialized]) |segment| alloc.free(@constCast(segment));
            alloc.free(path);
        }
        for (path_value.array.items) |segment| {
            if (segment != .string or segment.string.len == 0) return error.InvalidRowsRequest;
            if (std.mem.indexOfScalar(u8, segment.string, '.') != null) return error.InvalidRowsRequest;
            path[path_initialized] = try alloc.dupe(u8, segment.string);
            path_initialized += 1;
        }

        const expression = try parseRowsMutationExpressionAlloc(alloc, schema, expr_value);
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeRowsQueryExpression(alloc, expression);
        if (!allow_proposed_source and expressionUsesProposedSource(expression)) return error.InvalidRowsRequest;

        const field = try alloc.dupe(u8, column.path);
        var field_transferred = false;
        errdefer if (!field_transferred) alloc.free(field);

        try assignments.append(alloc, .{
            .field = field,
            .path = path,
            .expression = expression,
        });
        field_transferred = true;
        expression_transferred = true;
    }

    return try assignments.toOwnedSlice(alloc);
}

fn parseRowsJoinedMutationJsonSetExpressionAssignmentsAlloc(
    alloc: std.mem.Allocator,
    target_schema: runtime_schema.TableSchema,
    source_schema: runtime_schema.TableSchema,
    maybe_json_set: ?std.json.Value,
) ![]db_mod.types.RelationalRowsJsonSetExpressionAssignment {
    const json_set = maybe_json_set orelse return &.{};
    if (json_set != .array) return error.InvalidRowsRequest;

    var assignments = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonSetExpressionAssignment).empty;
    errdefer {
        for (assignments.items) |assignment| {
            alloc.free(@constCast(assignment.field));
            for (assignment.path) |segment| alloc.free(@constCast(segment));
            if (assignment.path.len > 0) alloc.free(assignment.path);
            freeRowsQueryExpression(alloc, assignment.expression);
        }
        assignments.deinit(alloc);
    }

    for (json_set.array.items) |item| {
        if (item != .object) return error.InvalidRowsRequest;
        try requireJsonObjectOnlyKeys(item.object, &.{ "field", "path", "value", "expr" });
        if (item.object.get("value") != null) continue;
        const expr_value = item.object.get("expr") orelse return error.InvalidRowsRequest;

        const field_value = item.object.get("field") orelse return error.InvalidRowsRequest;
        if (field_value != .string or field_value.string.len == 0) return error.InvalidRowsRequest;
        const column = findRelationalColumn(target_schema.relational_columns, field_value.string) orelse return error.InvalidRowsRequest;
        if (column.field_type != .json) return error.InvalidRowsRequest;
        if (target_schema.primary_key) |primary_key| {
            if (primaryKeyContains(primary_key, field_value.string)) return error.InvalidRowsRequest;
        }

        const path_value = item.object.get("path") orelse return error.InvalidRowsRequest;
        if (path_value != .array or path_value.array.items.len == 0) return error.InvalidRowsRequest;
        const path = try alloc.alloc([]const u8, path_value.array.items.len);
        var path_initialized: usize = 0;
        errdefer {
            for (path[0..path_initialized]) |segment| alloc.free(@constCast(segment));
            alloc.free(path);
        }
        for (path_value.array.items) |segment| {
            if (segment != .string or segment.string.len == 0) return error.InvalidRowsRequest;
            if (std.mem.indexOfScalar(u8, segment.string, '.') != null) return error.InvalidRowsRequest;
            path[path_initialized] = try alloc.dupe(u8, segment.string);
            path_initialized += 1;
        }

        const expression = try parseRowsExpressionWithSourceSchemaAlloc(alloc, target_schema, source_schema, expr_value, true);
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeRowsQueryExpression(alloc, expression);
        try validateRowsJoinMatchExpressionSources(expression);

        const field = try alloc.dupe(u8, column.path);
        var field_transferred = false;
        errdefer if (!field_transferred) alloc.free(field);

        try assignments.append(alloc, .{
            .field = field,
            .path = path,
            .expression = expression,
        });
        field_transferred = true;
        expression_transferred = true;
    }

    return try assignments.toOwnedSlice(alloc);
}

fn validateRowsMutationUpdateTargetPaths(
    operations: []const db_mod.types.TransformOp,
    patch_expressions: []const db_mod.types.RelationalRowsExpressionAssignment,
    increment_expressions: []const db_mod.types.RelationalRowsExpressionAssignment,
    json_set_expressions: []const db_mod.types.RelationalRowsJsonSetExpressionAssignment,
    source_assignments: []const db_mod.types.RelationalRowsJoinedMutationFieldAssignment,
) !void {
    for (operations, 0..) |lhs, i| {
        for (operations[i + 1 ..]) |rhs| {
            if (rowsMutationOperationPathsConflict(lhs, rhs)) return error.InvalidRowsRequest;
        }
        for (patch_expressions) |assignment| {
            if (rowsMutationDottedPathsConflict(lhs.path, assignment.field)) return error.InvalidRowsRequest;
        }
        for (increment_expressions) |assignment| {
            if (rowsMutationDottedPathsConflict(lhs.path, assignment.field)) return error.InvalidRowsRequest;
        }
        for (json_set_expressions) |assignment| {
            if (rowsMutationDottedPathConflictsJsonSetPath(lhs.path, assignment.field, assignment.path)) return error.InvalidRowsRequest;
        }
        for (source_assignments) |assignment| {
            if (rowsMutationDottedPathsConflict(lhs.path, assignment.field)) return error.InvalidRowsRequest;
        }
    }
    for (patch_expressions, 0..) |lhs, i| {
        for (patch_expressions[i + 1 ..]) |rhs| {
            if (rowsMutationDottedPathsConflict(lhs.field, rhs.field)) return error.InvalidRowsRequest;
        }
        for (increment_expressions) |assignment| {
            if (rowsMutationDottedPathsConflict(lhs.field, assignment.field)) return error.InvalidRowsRequest;
        }
        for (json_set_expressions) |assignment| {
            if (rowsMutationDottedPathConflictsJsonSetPath(lhs.field, assignment.field, assignment.path)) return error.InvalidRowsRequest;
        }
        for (source_assignments) |assignment| {
            if (rowsMutationDottedPathsConflict(lhs.field, assignment.field)) return error.InvalidRowsRequest;
        }
    }
    for (increment_expressions, 0..) |lhs, i| {
        for (increment_expressions[i + 1 ..]) |rhs| {
            if (rowsMutationDottedPathsConflict(lhs.field, rhs.field)) return error.InvalidRowsRequest;
        }
        for (json_set_expressions) |assignment| {
            if (rowsMutationDottedPathConflictsJsonSetPath(lhs.field, assignment.field, assignment.path)) return error.InvalidRowsRequest;
        }
        for (source_assignments) |assignment| {
            if (rowsMutationDottedPathsConflict(lhs.field, assignment.field)) return error.InvalidRowsRequest;
        }
    }
    for (json_set_expressions, 0..) |lhs, i| {
        for (json_set_expressions[i + 1 ..]) |rhs| {
            if (rowsMutationJsonSetPathsConflict(lhs.field, lhs.path, rhs.field, rhs.path)) return error.InvalidRowsRequest;
        }
        for (source_assignments) |assignment| {
            if (rowsMutationDottedPathConflictsJsonSetPath(assignment.field, lhs.field, lhs.path)) return error.InvalidRowsRequest;
        }
    }
    for (source_assignments, 0..) |lhs, i| {
        for (source_assignments[i + 1 ..]) |rhs| {
            if (rowsMutationDottedPathsConflict(lhs.field, rhs.field)) return error.InvalidRowsRequest;
        }
    }
}

fn rowsMutationOperationPathsConflict(lhs: db_mod.types.TransformOp, rhs: db_mod.types.TransformOp) bool {
    if (!rowsMutationDottedPathsConflict(lhs.path, rhs.path)) return false;
    return !(rowsMutationTransformOpIsArrayUpdate(lhs.op) and rowsMutationTransformOpIsArrayUpdate(rhs.op) and std.mem.eql(u8, lhs.path, rhs.path));
}

fn rowsMutationTransformOpIsArrayUpdate(op: db_mod.types.TransformOpType) bool {
    return switch (op) {
        .push, .pull, .add_to_set, .pop => true,
        else => false,
    };
}

fn rowsMutationDottedPathsConflict(lhs: []const u8, rhs: []const u8) bool {
    if (std.mem.eql(u8, lhs, rhs)) return true;
    return rowsMutationDottedPathIsAncestor(lhs, rhs) or rowsMutationDottedPathIsAncestor(rhs, lhs);
}

fn rowsMutationDottedPathIsAncestor(parent: []const u8, child: []const u8) bool {
    return parent.len < child.len and
        std.mem.startsWith(u8, child, parent) and
        child[parent.len] == '.';
}

fn rowsMutationDottedPathConflictsJsonSetPath(path: []const u8, json_field: []const u8, json_path: []const []const u8) bool {
    if (rowsMutationDottedPathsConflict(path, json_field)) return true;
    if (path.len <= json_field.len + 1) return false;
    if (!std.mem.startsWith(u8, path, json_field) or path[json_field.len] != '.') return false;
    return rowsMutationJsonSegmentsConflictDottedPath(json_path, path[json_field.len + 1 ..]);
}

fn rowsMutationJsonSetPathsConflict(
    lhs_field: []const u8,
    lhs_path: []const []const u8,
    rhs_field: []const u8,
    rhs_path: []const []const u8,
) bool {
    if (!std.mem.eql(u8, lhs_field, rhs_field)) return rowsMutationDottedPathsConflict(lhs_field, rhs_field);
    const shared = @min(lhs_path.len, rhs_path.len);
    for (lhs_path[0..shared], rhs_path[0..shared]) |lhs, rhs| {
        if (!std.mem.eql(u8, lhs, rhs)) return false;
    }
    return true;
}

fn rowsMutationJsonSegmentsConflictDottedPath(json_path: []const []const u8, dotted_path: []const u8) bool {
    if (json_path.len == 0 or dotted_path.len == 0) return false;
    var offset: usize = 0;
    for (json_path, 0..) |segment, i| {
        if (offset >= dotted_path.len) return true;
        if (!std.mem.startsWith(u8, dotted_path[offset..], segment)) return false;
        offset += segment.len;
        const dotted_done = offset == dotted_path.len;
        const json_done = i + 1 == json_path.len;
        if (!dotted_done and dotted_path[offset] != '.') return false;
        if (dotted_done or json_done) return true;
        offset += 1;
    }
    return offset == dotted_path.len;
}

fn expressionUsesProposedSource(expression: db_mod.types.RelationalRowsExpression) bool {
    if (expression.kind == .field and expression.field_source == .proposed) return true;
    for (expression.operands) |operand| if (expressionUsesProposedSource(operand)) return true;
    for (expression.case_branches) |branch| {
        if (expressionConditionUsesProposedSource(branch.when) or expressionUsesProposedSource(branch.then)) return true;
    }
    for (expression.case_else) |fallback| if (expressionUsesProposedSource(fallback)) return true;
    return false;
}

fn expressionConditionUsesProposedSource(condition: db_mod.types.RelationalRowsExpressionCondition) bool {
    if (expressionUsesProposedSource(condition.lhs)) return true;
    for (condition.rhs) |rhs| if (expressionUsesProposedSource(rhs)) return true;
    return false;
}

fn appendPatchTransformOperationsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    patch: std.json.Value,
    allow_primary_key: bool,
    operations: *std.ArrayListUnmanaged(db_mod.types.TransformOp),
) !void {
    var it = patch.object.iterator();
    while (it.next()) |entry| {
        const column = findRelationalColumn(schema.relational_columns, entry.key_ptr.*) orelse return error.InvalidRowsRequest;
        if (column.generated != null) return error.InvalidRowsRequest;
        if (!allow_primary_key and primaryKeyContains(schema.primary_key.?, entry.key_ptr.*)) return error.InvalidRowsRequest;
        const value_json = try jsonValueStringifyAlloc(alloc, entry.value_ptr.*);
        var value_json_transferred = false;
        errdefer if (!value_json_transferred) alloc.free(value_json);
        const path = try alloc.dupe(u8, column.path);
        var path_transferred = false;
        errdefer if (!path_transferred) alloc.free(path);
        try operations.append(alloc, .{
            .op = .set,
            .path = path,
            .value_json = value_json,
        });
        path_transferred = true;
        value_json_transferred = true;
    }
}

fn appendPatchExpressionTransformOperationsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    existing_row: std.json.Value,
    proposed_row: ?std.json.Value,
    patch_expr: std.json.Value,
    allow_primary_key: bool,
    operations: *std.ArrayListUnmanaged(db_mod.types.TransformOp),
) !void {
    var it = patch_expr.object.iterator();
    while (it.next()) |entry| {
        const column = findRelationalColumn(schema.relational_columns, entry.key_ptr.*) orelse return error.InvalidRowsRequest;
        if (column.generated != null) return error.InvalidRowsRequest;
        if (!allow_primary_key and primaryKeyContains(schema.primary_key.?, entry.key_ptr.*)) return error.InvalidRowsRequest;
        const expression = try parseRowsMutationExpressionAlloc(alloc, schema, entry.value_ptr.*);
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeRowsQueryExpression(alloc, expression);
        const value_json = try expressionValueJsonWithSourcesAlloc(alloc, existing_row, proposed_row, expression);
        var value_json_transferred = false;
        errdefer if (!value_json_transferred) alloc.free(value_json);
        const path = try alloc.dupe(u8, column.path);
        var path_transferred = false;
        errdefer if (!path_transferred) alloc.free(path);
        try operations.append(alloc, .{
            .op = .set,
            .path = path,
            .value_json = value_json,
        });
        path_transferred = true;
        value_json_transferred = true;
        expression_transferred = true;
        freeRowsQueryExpression(alloc, expression);
    }
}

fn appendIncrementTransformOperationsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    increment: std.json.Value,
    operations: *std.ArrayListUnmanaged(db_mod.types.TransformOp),
) !void {
    var it = increment.object.iterator();
    while (it.next()) |entry| {
        const column = findRelationalColumn(schema.relational_columns, entry.key_ptr.*) orelse return error.InvalidRowsRequest;
        if (column.field_type != .numeric) return error.InvalidRowsRequest;
        if (schema.primary_key) |primary_key| {
            if (primaryKeyContains(primary_key, entry.key_ptr.*)) return error.InvalidRowsRequest;
        }
        switch (entry.value_ptr.*) {
            .integer, .float, .number_string => {},
            else => return error.InvalidRowsRequest,
        }
        const value_json = try jsonValueStringifyAlloc(alloc, entry.value_ptr.*);
        var value_json_transferred = false;
        errdefer if (!value_json_transferred) alloc.free(value_json);
        const path = try alloc.dupe(u8, column.path);
        var path_transferred = false;
        errdefer if (!path_transferred) alloc.free(path);
        try operations.append(alloc, .{
            .op = .inc,
            .path = path,
            .value_json = value_json,
        });
        path_transferred = true;
        value_json_transferred = true;
    }
}

fn appendIncrementExpressionTransformOperationsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    existing_row: std.json.Value,
    proposed_row: ?std.json.Value,
    increment_expr: std.json.Value,
    operations: *std.ArrayListUnmanaged(db_mod.types.TransformOp),
) !void {
    var it = increment_expr.object.iterator();
    while (it.next()) |entry| {
        const column = findRelationalColumn(schema.relational_columns, entry.key_ptr.*) orelse return error.InvalidRowsRequest;
        if (column.field_type != .numeric) return error.InvalidRowsRequest;
        if (schema.primary_key) |primary_key| {
            if (primaryKeyContains(primary_key, entry.key_ptr.*)) return error.InvalidRowsRequest;
        }
        const expression = try parseRowsMutationExpressionAlloc(alloc, schema, entry.value_ptr.*);
        var expression_transferred = false;
        errdefer if (!expression_transferred) freeRowsQueryExpression(alloc, expression);
        try validateRowsQueryNumericExpression(alloc, schema, expression);
        const value_json = try expressionValueJsonWithSourcesAlloc(alloc, existing_row, proposed_row, expression);
        var value_json_transferred = false;
        errdefer if (!value_json_transferred) alloc.free(value_json);
        try validateIncrementExpressionValueJson(alloc, value_json);
        const path = try alloc.dupe(u8, column.path);
        var path_transferred = false;
        errdefer if (!path_transferred) alloc.free(path);
        try operations.append(alloc, .{
            .op = .inc,
            .path = path,
            .value_json = value_json,
        });
        path_transferred = true;
        value_json_transferred = true;
        expression_transferred = true;
        freeRowsQueryExpression(alloc, expression);
    }
}

fn validateIncrementExpressionValueJson(alloc: std.mem.Allocator, value_json: []const u8) !void {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, value_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    switch (parsed.value) {
        .integer, .float, .number_string => {},
        else => return error.InvalidRowsRequest,
    }
}

fn appendJsonSetTransformOperationsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    json_set: std.json.Value,
    existing_row: ?std.json.Value,
    proposed_row: ?std.json.Value,
    skip_expressions: bool,
    operations: *std.ArrayListUnmanaged(db_mod.types.TransformOp),
) !void {
    if (json_set != .array) return error.InvalidRowsRequest;
    for (json_set.array.items) |item| {
        if (item != .object) return error.InvalidRowsRequest;
        try requireJsonObjectOnlyKeys(item.object, &.{ "field", "path", "value", "expr" });
        const field_value = item.object.get("field") orelse return error.InvalidRowsRequest;
        if (field_value != .string or field_value.string.len == 0) return error.InvalidRowsRequest;
        const column = findRelationalColumn(schema.relational_columns, field_value.string) orelse return error.InvalidRowsRequest;
        if (column.field_type != .json) return error.InvalidRowsRequest;
        const path_value = item.object.get("path") orelse return error.InvalidRowsRequest;
        if (path_value != .array or path_value.array.items.len == 0) return error.InvalidRowsRequest;
        const value = item.object.get("value");
        const expr = item.object.get("expr");
        if ((value == null) == (expr == null)) return error.InvalidRowsRequest;
        if (expr != null and skip_expressions) continue;
        const transform_path = try jsonSetTransformPathAlloc(alloc, column.path, path_value);
        var path_transferred = false;
        errdefer if (!path_transferred) alloc.free(transform_path);
        const value_json = if (value) |literal|
            try jsonValueStringifyAlloc(alloc, literal)
        else blk: {
            const existing = existing_row orelse return error.InvalidRowsRequest;
            const expression = try parseRowsMutationExpressionAlloc(alloc, schema, expr.?);
            var expression_transferred = false;
            errdefer if (!expression_transferred) freeRowsQueryExpression(alloc, expression);
            const out = try expressionValueJsonWithSourcesAlloc(alloc, existing, proposed_row, expression);
            expression_transferred = true;
            freeRowsQueryExpression(alloc, expression);
            break :blk out;
        };
        var value_transferred = false;
        errdefer if (!value_transferred) alloc.free(value_json);
        try operations.append(alloc, .{
            .op = .set,
            .path = transform_path,
            .value_json = value_json,
        });
        path_transferred = true;
        value_transferred = true;
    }
}

fn appendArrayUpdateTransformOperationsAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    array_update: std.json.Value,
    operations: *std.ArrayListUnmanaged(db_mod.types.TransformOp),
) !void {
    if (array_update != .array) return error.InvalidRowsRequest;
    for (array_update.array.items) |item| {
        if (item != .object) return error.InvalidRowsRequest;
        try requireJsonObjectOnlyKeys(item.object, &.{ "field", "op", "value" });
        const field_value = item.object.get("field") orelse return error.InvalidRowsRequest;
        if (field_value != .string or field_value.string.len == 0) return error.InvalidRowsRequest;
        const column = findRelationalColumn(schema.relational_columns, field_value.string) orelse return error.InvalidRowsRequest;
        if (column.field_type != .array) return error.InvalidRowsRequest;
        if (schema.primary_key) |primary_key| {
            if (primaryKeyContains(primary_key, field_value.string)) return error.InvalidRowsRequest;
        }
        const op_value = item.object.get("op") orelse return error.InvalidRowsRequest;
        if (op_value != .string) return error.InvalidRowsRequest;
        const op: db_mod.types.TransformOpType = if (std.mem.eql(u8, op_value.string, "append"))
            .push
        else if (std.mem.eql(u8, op_value.string, "remove"))
            .pull
        else if (std.mem.eql(u8, op_value.string, "add_to_set"))
            .add_to_set
        else
            return error.InvalidRowsRequest;
        const value = item.object.get("value") orelse return error.InvalidRowsRequest;
        try validateRowsArrayUpdateElement(column, value);
        const value_json = try jsonValueStringifyAlloc(alloc, value);
        var value_transferred = false;
        errdefer if (!value_transferred) alloc.free(value_json);
        const path = try alloc.dupe(u8, column.path);
        var path_transferred = false;
        errdefer if (!path_transferred) alloc.free(path);
        try operations.append(alloc, .{
            .op = op,
            .path = path,
            .value_json = value_json,
        });
        path_transferred = true;
        value_transferred = true;
    }
}

fn validateRowsArrayUpdateElement(column: runtime_schema.RelationalColumn, value: std.json.Value) !void {
    const item_type = column.array_item_type orelse return error.InvalidRowsRequest;
    if (!rowsArrayItemValueMatches(item_type, value)) return error.InvalidRowsRequest;
}

fn rowsArrayItemValueMatches(item_type: runtime_schema.AntflyType, value: std.json.Value) bool {
    return switch (item_type) {
        .text, .keyword, .link, .html, .search_as_you_type, .blob, .geoshape => value == .string,
        .numeric => value == .integer or value == .float or value == .number_string,
        .datetime => value == .integer or value == .float or value == .number_string,
        .boolean => value == .bool,
        .geopoint => value == .array or value == .object,
        .json => true,
        .array => value == .array,
        .embedding => false,
    };
}

fn jsonSetTransformPathAlloc(
    alloc: std.mem.Allocator,
    field: []const u8,
    path_value: std.json.Value,
) ![]u8 {
    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.writeAll(field);
    for (path_value.array.items) |segment| {
        if (segment != .string or segment.string.len == 0) return error.InvalidRowsRequest;
        if (std.mem.indexOfScalar(u8, segment.string, '.') != null) return error.InvalidRowsRequest;
        try writer.writeByte('.');
        try writer.writeAll(segment.string);
    }
    return try out.toOwnedSlice();
}

fn primaryKeyContains(primary_key: runtime_schema.PrimaryKey, column: []const u8) bool {
    for (primary_key.columns) |component| {
        if (std.mem.eql(u8, component, column)) return true;
    }
    return false;
}

fn appendExpectedVersionPredicateAlloc(
    alloc: std.mem.Allocator,
    predicates: *std.ArrayListUnmanaged(db_mod.types.TransactionVersionPredicate),
    op_value: std.json.Value,
    key: []const u8,
) !void {
    const expected_version_value = op_value.object.get("expected_version") orelse return;
    const expected_version = try parseExpectedVersion(expected_version_value);
    const predicate_key = try alloc.dupe(u8, key);
    var predicate_key_transferred = false;
    errdefer if (!predicate_key_transferred) alloc.free(predicate_key);
    try predicates.append(alloc, .{
        .key = predicate_key,
        .expected_version = expected_version,
    });
    predicate_key_transferred = true;
}

fn appendVersionPredicateAlloc(
    alloc: std.mem.Allocator,
    predicates: *std.ArrayListUnmanaged(db_mod.types.TransactionVersionPredicate),
    key: []const u8,
    expected_version: u64,
) !void {
    const predicate_key = try alloc.dupe(u8, key);
    var predicate_key_transferred = false;
    errdefer if (!predicate_key_transferred) alloc.free(predicate_key);
    try predicates.append(alloc, .{
        .key = predicate_key,
        .expected_version = expected_version,
    });
    predicate_key_transferred = true;
}

fn returningBaseRowForKey(
    alloc: std.mem.Allocator,
    table_name: []const u8,
    key: []const u8,
    unique_resolver: ?UniqueSelectorResolver,
    op_value: std.json.Value,
) !?ResolvedPrimaryRow {
    if (!hasReturningProjection(op_value)) return null;
    const resolver = unique_resolver orelse return error.UnsupportedRowsSelector;
    return (try resolver.lookupPrimary(alloc, table_name, key)) orelse return error.RowSelectorNotFound;
}

fn lookupBaseRowForKey(
    alloc: std.mem.Allocator,
    table_name: []const u8,
    key: []const u8,
    unique_resolver: ?UniqueSelectorResolver,
) !ResolvedPrimaryRow {
    const resolver = unique_resolver orelse return error.UnsupportedRowsSelector;
    return (try resolver.lookupPrimary(alloc, table_name, key)) orelse return error.RowSelectorNotFound;
}

fn appendReturningProjectionAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    returning_rows: *std.ArrayListUnmanaged([]const u8),
    op_value: std.json.Value,
    row_json: []const u8,
) !void {
    if (!hasReturningProjection(op_value)) return;
    try appendReturningProjectionFromJsonAlloc(alloc, schema, returning_rows, op_value, row_json);
}

fn appendReturningProjectionFromJsonAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    returning_rows: *std.ArrayListUnmanaged([]const u8),
    op_value: std.json.Value,
    row_json: []const u8,
) !void {
    if (!hasReturningProjection(op_value)) return;
    const projected = try projectReturningRowAlloc(alloc, schema, op_value, row_json);
    var projected_transferred = false;
    errdefer if (!projected_transferred) alloc.free(projected);
    try returning_rows.append(alloc, projected);
    projected_transferred = true;
}

fn hasReturningProjection(op_value: std.json.Value) bool {
    if (op_value != .object) return false;
    return op_value.object.get("returning") != null or op_value.object.get("returning_expressions") != null;
}

fn hasIncrementExpression(op_value: std.json.Value) bool {
    if (op_value != .object) return false;
    return op_value.object.get("increment_expr") != null;
}

fn hasPatchExpression(op_value: std.json.Value) bool {
    if (op_value != .object) return false;
    return op_value.object.get("patch_expr") != null;
}

fn hasMutationExpression(op_value: std.json.Value) bool {
    return hasPatchExpression(op_value) or hasIncrementExpression(op_value) or hasJsonSetExpression(op_value);
}

fn hasJsonSetExpression(op_value: std.json.Value) bool {
    if (op_value != .object) return false;
    const json_set = op_value.object.get("json_set") orelse return false;
    if (json_set != .array) return false;
    for (json_set.array.items) |item| {
        if (item == .object and item.object.get("expr") != null) return true;
    }
    return false;
}

fn hasConflictActionCondition(op_value: std.json.Value) bool {
    if (op_value != .object) return false;
    if (op_value.object.get("where_expression") != null) return true;
    if (op_value.object.get("where_expressions")) |conditions| return conditions == .array and conditions.array.items.len != 0;
    if (op_value.object.get("where_any")) |groups| return groups == .array and groups.array.items.len != 0;
    if (op_value.object.get("where_not")) |groups| return groups == .array and groups.array.items.len != 0;
    return false;
}

fn projectReturningRowAlloc(
    alloc: std.mem.Allocator,
    schema: runtime_schema.TableSchema,
    op_value: std.json.Value,
    row_json: []const u8,
) ![]u8 {
    const returning_value = op_value.object.get("returning");
    const returning_expressions_value = op_value.object.get("returning_expressions");
    if (returning_value == null and returning_expressions_value == null) return error.InvalidRowsRequest;
    if (returning_value) |value| if (value != .array) return error.InvalidRowsRequest;
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidRowsRequest;
    defer parsed.deinit();
    if (parsed.value != .object) return error.InvalidRowsRequest;

    const expressions = try parseRowsQueryExpressionProjectionsAlloc(alloc, schema, returning_expressions_value);
    defer freeRowsQueryExpressionProjections(alloc, expressions);

    const returning_all = if (returning_value) |fields|
        fields.array.items.len == 1 and fields.array.items[0] == .string and std.mem.eql(u8, fields.array.items[0].string, "*")
    else
        false;
    try validateProjectReturningOutputs(returning_value, returning_all, expressions, parsed.value);
    if (returning_all and expressions.len == 0) return try alloc.dupe(u8, row_json);

    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    const writer = &out.writer;
    try writer.writeByte('{');
    var first = true;
    if (returning_all) {
        for (parsed.value.object.keys(), parsed.value.object.values()) |field, value| {
            if (!first) try writer.writeByte(',');
            first = false;
            try writer.print("{f}:", .{std.json.fmt(field, .{})});
            try std.json.Stringify.value(value, .{}, writer);
        }
    } else if (returning_value) |fields| {
        for (fields.array.items) |field_value| {
            if (field_value != .string) return error.InvalidRowsRequest;
            if (field_value.string.len == 0 or std.mem.eql(u8, field_value.string, "*")) return error.InvalidRowsRequest;
            if (!first) try writer.writeByte(',');
            first = false;
            try writer.print("{f}:", .{std.json.fmt(field_value.string, .{})});
            if (jsonValueAtPath(parsed.value, field_value.string)) |selected| {
                try std.json.Stringify.value(selected.*, .{}, writer);
            } else {
                try writer.writeAll("null");
            }
        }
    }
    for (expressions) |projection| {
        if (returning_all and parsed.value.object.get(projection.output) != null) return error.InvalidRowsRequest;
        if (!first) try writer.writeByte(',');
        first = false;
        try writer.print("{f}:", .{std.json.fmt(projection.output, .{})});
        const value_json = try expressionValueJsonAlloc(alloc, parsed.value, projection.expression);
        defer alloc.free(value_json);
        try writer.writeAll(value_json);
    }
    try writer.writeByte('}');
    return try out.toOwnedSlice();
}

fn validateProjectReturningOutputs(
    returning_value: ?std.json.Value,
    returning_all: bool,
    expressions: []const db_mod.types.RelationalRowsExpressionProjection,
    row: std.json.Value,
) !void {
    if (row != .object) return error.InvalidRowsRequest;
    if (returning_all) {
        for (expressions) |projection| {
            if (projection.output.len == 0) return error.InvalidRowsRequest;
            if (row.object.get(projection.output) != null) return error.InvalidRowsRequest;
            if (projectReturningExpressionOutputCount(expressions, projection.output) > 1) return error.InvalidRowsRequest;
        }
        return;
    }
    if (returning_value) |fields| {
        if (fields != .array) return error.InvalidRowsRequest;
        for (fields.array.items) |field_value| {
            if (field_value != .string or field_value.string.len == 0 or std.mem.eql(u8, field_value.string, "*")) return error.InvalidRowsRequest;
            if (projectReturningFieldOutputCount(fields.array.items, field_value.string) > 1) return error.InvalidRowsRequest;
            if (projectReturningExpressionOutputCount(expressions, field_value.string) > 0) return error.InvalidRowsRequest;
        }
    }
    for (expressions) |projection| {
        if (projection.output.len == 0) return error.InvalidRowsRequest;
        if (projectReturningExpressionOutputCount(expressions, projection.output) > 1) return error.InvalidRowsRequest;
        if (returning_value) |fields| {
            if (projectReturningFieldOutputCount(fields.array.items, projection.output) > 0) return error.InvalidRowsRequest;
        }
    }
}

fn projectReturningFieldOutputCount(fields: []const std.json.Value, output: []const u8) usize {
    var count: usize = 0;
    for (fields) |field_value| {
        if (field_value == .string and std.mem.eql(u8, field_value.string, output)) count += 1;
    }
    return count;
}

fn projectReturningExpressionOutputCount(expressions: []const db_mod.types.RelationalRowsExpressionProjection, output: []const u8) usize {
    var count: usize = 0;
    for (expressions) |projection| {
        if (std.mem.eql(u8, projection.output, output)) count += 1;
    }
    return count;
}

fn jsonValueAtPath(root: std.json.Value, path: []const u8) ?*const std.json.Value {
    if (root != .object) return null;
    var current: *const std.json.Value = &root;
    var parts = std.mem.splitScalar(u8, path, '.');
    while (parts.next()) |part| {
        if (part.len == 0 or current.* != .object) return null;
        current = current.object.getPtr(part) orelse return null;
    }
    return current;
}

fn parseExpectedVersion(value: std.json.Value) !u64 {
    return switch (value) {
        .integer => |integer| if (integer >= 0) @intCast(integer) else error.InvalidRowsRequest,
        .string => |text| std.fmt.parseUnsigned(u64, text, 10) catch return error.InvalidRowsRequest,
        else => error.InvalidRowsRequest,
    };
}

fn identityResponseJsonAlloc(alloc: std.mem.Allocator, selector: std.json.Value) ![]u8 {
    if (selector != .object) return error.InvalidRowsRequest;
    if (selector.object.get("primary")) |primary_value| {
        const primary_json = try jsonValueStringifyAlloc(alloc, primary_value);
        defer alloc.free(primary_json);
        return try std.fmt.allocPrint(alloc, "{{\"primary\":{s}}}", .{primary_json});
    }
    if (selector.object.get("unique")) |unique_value| {
        const unique_json = try jsonValueStringifyAlloc(alloc, unique_value);
        defer alloc.free(unique_json);
        return try std.fmt.allocPrint(alloc, "{{\"unique\":{s}}}", .{unique_json});
    }
    return error.InvalidRowsRequest;
}

fn jsonValueStringifyAlloc(alloc: std.mem.Allocator, value: std.json.Value) ![]u8 {
    var out: std.Io.Writer.Allocating = .init(alloc);
    errdefer out.deinit();
    try std.json.Stringify.value(value, .{}, &out.writer);
    return try out.toOwnedSlice();
}

fn freeWrites(alloc: std.mem.Allocator, writes: []const db_mod.types.BatchWrite) void {
    for (writes) |write| {
        alloc.free(@constCast(write.key));
        alloc.free(@constCast(write.value));
    }
}

fn freeDeletes(alloc: std.mem.Allocator, deletes: []const []const u8) void {
    for (deletes) |key| alloc.free(@constCast(key));
}

fn freeRelationalIdentityRewrites(alloc: std.mem.Allocator, rewrites: []const db_mod.types.RelationalIdentityRewrite) void {
    for (rewrites) |rewrite| {
        alloc.free(@constCast(rewrite.old_key));
        alloc.free(@constCast(rewrite.new_key));
        alloc.free(@constCast(rewrite.value));
    }
}

fn freeStringSlice(alloc: std.mem.Allocator, values: []const []const u8) void {
    for (values) |value| alloc.free(@constCast(value));
    if (values.len > 0) alloc.free(values);
}

fn freeOptionalKeys(alloc: std.mem.Allocator, keys: []const ?[]const u8) void {
    for (keys) |key| if (key) |value| alloc.free(@constCast(value));
}

fn freeTransformOps(alloc: std.mem.Allocator, operations: []const db_mod.types.TransformOp) void {
    for (operations) |op| {
        alloc.free(@constCast(op.path));
        if (op.value_json) |value_json| alloc.free(@constCast(value_json));
    }
    if (operations.len > 0) alloc.free(@constCast(operations));
}

fn freeTransforms(alloc: std.mem.Allocator, transforms: []const db_mod.types.DocumentTransform) void {
    for (transforms) |transform| {
        alloc.free(@constCast(transform.key));
        for (transform.operations) |op| {
            alloc.free(@constCast(op.path));
            if (op.value_json) |value_json| alloc.free(@constCast(value_json));
        }
        if (transform.operations.len > 0) alloc.free(@constCast(transform.operations));
    }
}

fn freePredicates(alloc: std.mem.Allocator, predicates: []const db_mod.types.TransactionVersionPredicate) void {
    for (predicates) |predicate| alloc.free(@constCast(predicate.key));
}

test "relational rows lake bridge lowers supported query to scan request" {
    const alloc = std.testing.allocator;
    const columns = [_]runtime_schema.RelationalColumn{
        .{ .name = "tenant", .path = "tenant", .field_type = .keyword },
        .{ .name = "amount", .path = "amount", .field_type = .numeric },
        .{ .name = "active", .path = "active", .field_type = .boolean },
    };
    const schema = runtime_schema.TableSchema{
        .storage_mode = .relational,
        .relational_columns = &columns,
    };
    const select = [_][]const u8{"amount"};
    const predicates = [_]runtime_schema.RelationalCheck{.{
        .name = "",
        .field = "tenant",
        .op = .eq,
        .value_json = "\"t2\"",
    }};
    const request = OwnedRowsQueryRequest{
        .select_all = false,
        .select = &select,
        .predicates = &predicates,
        .limit = 7,
    };

    var lake_request = try buildLakeRowsScanRequestForRowsQueryAlloc(alloc, schema, request);
    defer lake_request.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 1), lake_request.request.projected_columns.len);
    try std.testing.expectEqualStrings("amount", lake_request.request.projected_columns[0]);
    try std.testing.expectEqual(@as(usize, 7), lake_request.request.limit.?);
    try std.testing.expect(lake_request.request.predicate != null);
    try std.testing.expectEqual(lake_rows.PredicateOp.eq_bytes, lake_request.request.predicate.?.op);
    try std.testing.expectEqualStrings("tenant", lake_request.request.predicate.?.column);
    try std.testing.expectEqualStrings("t2", lake_request.request.predicate.?.bytes_value);
}

test "relational rows lake bridge supports field ordering before query limit" {
    const alloc = std.testing.allocator;
    const columns = [_]runtime_schema.RelationalColumn{
        .{ .name = "amount", .path = "amount", .field_type = .numeric },
        .{ .name = "rank", .path = "rank", .field_type = .numeric },
    };
    const schema = runtime_schema.TableSchema{
        .storage_mode = .relational,
        .relational_columns = &columns,
    };
    const select = [_][]const u8{"amount"};
    const order_by = [_]RowsQueryOrder{.{
        .field = "rank",
        .direction = .desc,
    }};
    const request = OwnedRowsQueryRequest{
        .select_all = false,
        .select = &select,
        .order_by = &order_by,
        .limit = 2,
    };

    var lake_request = try buildLakeRowsScanRequestForRowsQueryAlloc(alloc, schema, request);
    defer lake_request.deinit(alloc);

    try std.testing.expectEqual(@as(?usize, null), lake_request.request.limit);
    try std.testing.expectEqual(@as(usize, 2), lake_request.request.projected_columns.len);
    try std.testing.expectEqualStrings("amount", lake_request.request.projected_columns[0]);
    try std.testing.expectEqualStrings("rank", lake_request.request.projected_columns[1]);

    const amount_a = @constCast("amount"[0..]);
    const rank_a = @constCast("rank"[0..]);
    const amount_b = @constCast("amount"[0..]);
    const rank_b = @constCast("rank"[0..]);
    const amount_c = @constCast("amount"[0..]);
    const rank_c = @constCast("rank"[0..]);
    var cells_a = [_]lake_rows.ProjectedCell{
        .{ .name = amount_a, .value = .{ .i64 = 10 } },
        .{ .name = rank_a, .value = .{ .i64 = 1 } },
    };
    var cells_b = [_]lake_rows.ProjectedCell{
        .{ .name = amount_b, .value = .{ .i64 = 20 } },
        .{ .name = rank_b, .value = .{ .i64 = 3 } },
    };
    var cells_c = [_]lake_rows.ProjectedCell{
        .{ .name = amount_c, .value = .{ .i64 = 30 } },
        .{ .name = rank_c, .value = .{ .i64 = 2 } },
    };
    var projected = [_]lake_rows.ProjectedRow{
        .{ .row_ref = .{ .external = .{ .source_id = "events", .snapshot_id = "snap", .file_id = "a", .row_group_ordinal = 0, .row_ordinal = 0 } }, .cells = &cells_a },
        .{ .row_ref = .{ .external = .{ .source_id = "events", .snapshot_id = "snap", .file_id = "a", .row_group_ordinal = 0, .row_ordinal = 1 } }, .cells = &cells_b },
        .{ .row_ref = .{ .external = .{ .source_id = "events", .snapshot_id = "snap", .file_id = "a", .row_group_ordinal = 0, .row_ordinal = 2 } }, .cells = &cells_c },
    };

    var result = try buildRowsQueryResultFromLakeRowsAlloc(
        alloc,
        request,
        .{
            .rows = &projected,
            .total = 3,
        },
    );
    defer result.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 3), result.total);
    try std.testing.expectEqual(@as(usize, 2), result.rows.len);
    try std.testing.expectEqualStrings("{\"amount\":20}", result.rows[0]);
    try std.testing.expectEqualStrings("{\"amount\":30}", result.rows[1]);
}

test "relational rows lake bridge distinct on direct field expression inherits collation" {
    const alloc = std.testing.allocator;
    const schema = runtime_schema.TableSchema{
        .storage_mode = .relational,
        .relational_columns = &.{
            .{ .name = "id", .path = "id", .field_type = .keyword, .nullable = false },
            .{ .name = "name", .path = "name", .field_type = .keyword, .collation = "antfly.case_insensitive" },
        },
        .primary_key = .{ .columns = &.{"id"} },
    };

    var request = try parseRowsQueryRequest(
        alloc,
        "{\"select\":[\"id\",\"name\"],\"distinct_on_expressions\":[{\"field\":\"name\"}],\"order_by\":[{\"expr\":{\"field\":\"name\"}},{\"field\":\"id\"}]}",
        schema,
    );
    defer request.deinit(alloc);

    const id_b = @constCast("id"[0..]);
    const name_b = @constCast("name"[0..]);
    const value_b_id = @constCast("b"[0..]);
    const value_b_name = @constCast("Beta"[0..]);
    const id_c = @constCast("id"[0..]);
    const name_c = @constCast("name"[0..]);
    const value_c_id = @constCast("c"[0..]);
    const value_c_name = @constCast("beta"[0..]);
    const id_a = @constCast("id"[0..]);
    const name_a = @constCast("name"[0..]);
    const value_a_id = @constCast("a"[0..]);
    const value_a_name = @constCast("alpha"[0..]);
    var cells_b = [_]lake_rows.ProjectedCell{
        .{ .name = id_b, .value = .{ .bytes = value_b_id } },
        .{ .name = name_b, .value = .{ .bytes = value_b_name } },
    };
    var cells_c = [_]lake_rows.ProjectedCell{
        .{ .name = id_c, .value = .{ .bytes = value_c_id } },
        .{ .name = name_c, .value = .{ .bytes = value_c_name } },
    };
    var cells_a = [_]lake_rows.ProjectedCell{
        .{ .name = id_a, .value = .{ .bytes = value_a_id } },
        .{ .name = name_a, .value = .{ .bytes = value_a_name } },
    };
    var projected = [_]lake_rows.ProjectedRow{
