test "relational rows lake bridge lowers supported aggregate to scan request" {
    const alloc = std.testing.allocator;
    const columns = [_]runtime_schema.RelationalColumn{
        .{ .name = "tenant", .path = "tenant", .field_type = .keyword },
        .{ .name = "amount", .path = "amount", .field_type = .numeric },
        .{ .name = "discount", .path = "discount", .field_type = .numeric },
        .{ .name = "rank", .path = "rank", .field_type = .numeric },
        .{ .name = "status", .path = "status", .field_type = .keyword },
        .{ .name = "attrs", .path = "attrs", .field_type = .json },
        .{ .name = "tags", .path = "tags", .field_type = .array },
        .{ .name = "scope", .path = "scope", .field_type = .text },
        .{ .name = "created_at", .path = "created_at", .field_type = .datetime },
    };
    const schema = runtime_schema.TableSchema{
        .storage_mode = .relational,
        .relational_columns = &columns,
    };
    const predicates = [_]runtime_schema.RelationalCheck{.{
        .name = "",
        .field = "tenant",
        .op = .eq,
        .value_json = "\"t2\"",
    }};
    const net_amount_operands = [_]db_mod.types.RelationalRowsExpression{
        .{ .kind = .field, .field = "amount", .field_source = .row },
        .{ .kind = .field, .field = "discount", .field_source = .row },
    };
    const net_amount_expression = db_mod.types.RelationalRowsExpression{
        .kind = .sub,
        .operands = &net_amount_operands,
    };
    const rank_two_filter = [_]db_mod.types.RelationalRowsInPredicate{.{
        .field = "rank",
        .values_json = "[2]",
    }};
    const open_status_filter = [_]db_mod.types.RelationalRowsTextPatternPredicate{.{
        .field = "status",
        .pattern = "op%",
        .case_insensitive = true,
    }};
    const api_attrs_filter = [_]db_mod.types.RelationalRowsJsonContainsPredicate{.{
        .field = "attrs",
        .value_json = "{\"source\":\"api\"}",
    }};
    const hot_tag_filter = [_]db_mod.types.RelationalRowsArrayAnyPredicate{.{
        .field = "tags",
        .value_json = "\"hot\"",
    }};
    const lower_status_operands = [_]db_mod.types.RelationalRowsExpression{.{
        .kind = .field,
        .field = "status",
        .field_source = .row,
    }};
    const open_status_rhs = [_]db_mod.types.RelationalRowsExpression{.{
        .kind = .value,
        .value_json = "\"open\"",
    }};
    const open_status_expression_filter = [_]db_mod.types.RelationalRowsExpressionCondition{.{
        .lhs = .{ .kind = .lower, .operands = &lower_status_operands },
        .op = .eq,
        .rhs = &open_status_rhs,
    }};
    const string_to_array_operands = [_]db_mod.types.RelationalRowsExpression{
        .{ .kind = .field, .field = "scope", .field_source = .row },
        .{ .kind = .value, .value_json = "\" \"" },
    };
    const scope_write_filter = [_]db_mod.types.RelationalRowsExpressionArrayContainsPredicate{.{
        .expression = .{
            .kind = .string_to_array,
            .operands = &string_to_array_operands,
        },
        .value_json = "[\"write\"]",
    }};
    const aggregations = [_]db_mod.types.RelationalRowsAggregateSpec{
        .{ .name = "count_all", .op = .count },
        .{ .name = "sum_amount", .op = .sum, .field = "amount" },
        .{ .name = "latest_created_at", .op = .max, .field = "created_at" },
        .{ .name = "net_amount", .op = .sum, .expression = net_amount_expression },
        .{ .name = "rank_two_amount", .op = .sum, .field = "amount", .filter_in_predicates = &rank_two_filter },
        .{ .name = "open_amount", .op = .sum, .field = "amount", .filter_text_patterns = &open_status_filter },
        .{ .name = "api_attrs_amount", .op = .sum, .field = "amount", .filter_json_contains = &api_attrs_filter },
        .{ .name = "open_expr_amount", .op = .sum, .field = "amount", .filter_expressions = &open_status_expression_filter },
        .{ .name = "hot_tag_amount", .op = .sum, .field = "amount", .filter_array_any = &hot_tag_filter },
        .{ .name = "scope_write_amount", .op = .sum, .field = "amount", .filter_expression_array_contains = &scope_write_filter },
    };
    const request = OwnedRowsAggregateRequest{
        .source = .{ .predicates = &predicates },
        .aggregations = &aggregations,
    };

    var lake_request = try buildLakeRowsScanRequestForRowsAggregateAlloc(alloc, schema, request);
    defer lake_request.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 9), lake_request.request.projected_columns.len);
    try std.testing.expectEqualStrings("amount", lake_request.request.projected_columns[0]);
    try std.testing.expectEqualStrings("created_at", lake_request.request.projected_columns[1]);
    try std.testing.expectEqualStrings("discount", lake_request.request.projected_columns[2]);
    try std.testing.expectEqualStrings("rank", lake_request.request.projected_columns[3]);
    try std.testing.expectEqualStrings("status", lake_request.request.projected_columns[4]);
    try std.testing.expectEqualStrings("attrs", lake_request.request.projected_columns[5]);
    try std.testing.expectEqualStrings("tags", lake_request.request.projected_columns[6]);
    try std.testing.expectEqualStrings("scope", lake_request.request.projected_columns[7]);
    try std.testing.expectEqualStrings("tenant", lake_request.request.projected_columns[8]);
    try std.testing.expect(lake_request.request.limit == null);
    try std.testing.expect(lake_request.request.predicate != null);
    try std.testing.expectEqual(lake_rows.PredicateOp.eq_bytes, lake_request.request.predicate.?.op);
    try std.testing.expectEqualStrings("tenant", lake_request.request.predicate.?.column);
    try std.testing.expectEqualStrings("t2", lake_request.request.predicate.?.bytes_value);
}

test "relational rows lake bridge folds projected rows as aggregate result" {
    const alloc = std.testing.allocator;
    const amount_name = @constCast("amount"[0..]);
    var cells_0 = [_]lake_rows.ProjectedCell{.{ .name = amount_name, .value = .{ .i64 = 10 } }};
    var cells_1 = [_]lake_rows.ProjectedCell{.{ .name = amount_name, .value = .{ .i64 = 20 } }};
    var cells_2 = [_]lake_rows.ProjectedCell{.{ .name = amount_name, .value = null }};
    var projected = [_]lake_rows.ProjectedRow{
        .{ .row_ref = .{ .relational_key = "row:1" }, .cells = &cells_0 },
        .{ .row_ref = .{ .relational_key = "row:2" }, .cells = &cells_1 },
        .{ .row_ref = .{ .relational_key = "row:3" }, .cells = &cells_2 },
    };
    const aggregations = [_]db_mod.types.RelationalRowsAggregateSpec{
        .{ .name = "count_all", .op = .count },
        .{ .name = "count_amount", .op = .count, .field = "amount" },
        .{ .name = "sum_amount", .op = .sum, .field = "amount" },
        .{ .name = "min_amount", .op = .min, .field = "amount" },
        .{ .name = "max_amount", .op = .max, .field = "amount" },
        .{ .name = "avg_amount", .op = .avg, .field = "amount" },
    };
    const request = OwnedRowsAggregateRequest{ .aggregations = &aggregations };

    var result = try buildRowsAggregateResultFromLakeRowsAlloc(alloc, request, .{
        .rows = &projected,
        .total = 3,
    });
    defer result.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 1), result.total_groups);
    try std.testing.expectEqual(@as(usize, 1), result.rows.len);

    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, result.rows[0], .{});
    defer parsed.deinit();
    const object = parsed.value.object;
    try std.testing.expectEqual(@as(i64, 3), object.get("count_all").?.integer);
    try std.testing.expectEqual(@as(i64, 2), object.get("count_amount").?.integer);
    try std.testing.expectEqual(@as(i64, 30), object.get("sum_amount").?.integer);
    try std.testing.expectEqual(@as(i64, 10), object.get("min_amount").?.integer);
    try std.testing.expectEqual(@as(i64, 20), object.get("max_amount").?.integer);
    const avg_amount = object.get("avg_amount").?;
    switch (avg_amount) {
        .integer => |value| try std.testing.expectEqual(@as(i64, 15), value),
        .float => |value| try std.testing.expectApproxEqAbs(@as(f64, 15), value, 0.000001),
        else => return error.TestUnexpectedResult,
    }
}

