test "relational rows lake bridge applies aggregate output filters order and limit" {
    const alloc = std.testing.allocator;
    const tenant_name_0 = @constCast("tenant"[0..]);
    const amount_name_0 = @constCast("amount"[0..]);
    const tenant_name_1 = @constCast("tenant"[0..]);
    const amount_name_1 = @constCast("amount"[0..]);
    const tenant_name_2 = @constCast("tenant"[0..]);
    const amount_name_2 = @constCast("amount"[0..]);
    const tenant_name_3 = @constCast("tenant"[0..]);
    const amount_name_3 = @constCast("amount"[0..]);
    var cells_0 = [_]lake_rows.ProjectedCell{
        .{ .name = tenant_name_0, .value = .{ .i64 = 7 } },
        .{ .name = amount_name_0, .value = .{ .i64 = 10 } },
    };
    var cells_1 = [_]lake_rows.ProjectedCell{
        .{ .name = tenant_name_1, .value = .{ .i64 = 8 } },
        .{ .name = amount_name_1, .value = .{ .i64 = 20 } },
    };
    var cells_2 = [_]lake_rows.ProjectedCell{
        .{ .name = tenant_name_2, .value = .{ .i64 = 8 } },
        .{ .name = amount_name_2, .value = .{ .i64 = 30 } },
    };
    var cells_3 = [_]lake_rows.ProjectedCell{
        .{ .name = tenant_name_3, .value = .{ .i64 = 9 } },
        .{ .name = amount_name_3, .value = .{ .i64 = 40 } },
    };
    var projected = [_]lake_rows.ProjectedRow{
        .{ .row_ref = .{ .relational_key = "row:1" }, .cells = &cells_0 },
        .{ .row_ref = .{ .relational_key = "row:2" }, .cells = &cells_1 },
        .{ .row_ref = .{ .relational_key = "row:3" }, .cells = &cells_2 },
        .{ .row_ref = .{ .relational_key = "row:4" }, .cells = &cells_3 },
    };
    const group_by = [_][]const u8{"tenant"};
    const aggregations = [_]db_mod.types.RelationalRowsAggregateSpec{
        .{ .name = "row_count", .op = .count },
        .{ .name = "amount_sum", .op = .sum, .field = "amount" },
    };
    const having_predicates = [_]runtime_schema.RelationalCheck{.{
        .name = "",
        .field = "amount_sum",
        .op = .gt,
        .value_json = "20",
    }};
    const amount_minus_count_operands = [_]db_mod.types.RelationalRowsExpression{
        .{ .kind = .field, .field = "amount_sum", .field_source = .row },
        .{ .kind = .field, .field = "row_count", .field_source = .row },
    };
    const amount_minus_count = db_mod.types.RelationalRowsExpression{
        .kind = .sub,
        .operands = &amount_minus_count_operands,
    };
    const amount_minus_count_rhs = [_]db_mod.types.RelationalRowsExpression{.{ .kind = .value, .value_json = "30" }};
    const having_expressions = [_]db_mod.types.RelationalRowsExpressionCondition{.{
        .lhs = amount_minus_count,
        .op = .gt,
        .rhs = &amount_minus_count_rhs,
    }};
    const tenant_8_rhs = [_]db_mod.types.RelationalRowsExpression{.{ .kind = .value, .value_json = "8" }};
    const row_count_1_rhs = [_]db_mod.types.RelationalRowsExpression{.{ .kind = .value, .value_json = "1" }};
    const having_any_conditions_0 = [_]db_mod.types.RelationalRowsExpressionCondition{.{
        .lhs = .{ .kind = .field, .field = "tenant", .field_source = .row },
        .op = .eq,
        .rhs = &tenant_8_rhs,
    }};
    const having_any_conditions_1 = [_]db_mod.types.RelationalRowsExpressionCondition{.{
        .lhs = .{ .kind = .field, .field = "row_count", .field_source = .row },
        .op = .eq,
        .rhs = &row_count_1_rhs,
    }};
    const having_any = [_]db_mod.types.RelationalRowsExpressionPredicateGroup{
        .{ .conditions = &having_any_conditions_0 },
        .{ .conditions = &having_any_conditions_1 },
    };
    const tenant_7_rhs = [_]db_mod.types.RelationalRowsExpression{.{ .kind = .value, .value_json = "7" }};
    const having_not_conditions = [_]db_mod.types.RelationalRowsExpressionCondition{.{
        .lhs = .{ .kind = .field, .field = "tenant", .field_source = .row },
        .op = .eq,
        .rhs = &tenant_7_rhs,
    }};
    const having_not = [_]db_mod.types.RelationalRowsExpressionPredicateGroup{.{ .conditions = &having_not_conditions }};
    const order_by = [_]RowsQueryOrder{.{
        .expression = amount_minus_count,
        .direction = .desc,
    }};
    const request = OwnedRowsAggregateRequest{
        .group_by = &group_by,
        .aggregations = &aggregations,
        .having_predicates = &having_predicates,
        .having_expressions = &having_expressions,
        .having_any = &having_any,
        .having_not = &having_not,
        .order_by = &order_by,
        .limit = 1,
        .offset = 1,
    };

    var result = try buildRowsAggregateResultFromLakeRowsAlloc(alloc, request, .{
        .rows = &projected,
        .total = 4,
    });
    defer result.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 2), result.total_groups);
    try std.testing.expectEqual(@as(usize, 1), result.rows.len);
    try std.testing.expectEqualStrings("{\"tenant\":9,\"row_count\":1,\"amount_sum\":40}", result.rows[0]);
}

test "relational rows lake bridge applies scalar aggregate filters" {
    const alloc = std.testing.allocator;
    const tenant_name_0 = @constCast("tenant"[0..]);
    const amount_name_0 = @constCast("amount"[0..]);
    const rank_name_0 = @constCast("rank"[0..]);
    const status_name_0 = @constCast("status"[0..]);
    const status_value_0 = @constCast("closed"[0..]);
    const attrs_name_0 = @constCast("attrs"[0..]);
    const attrs_value_0 = @constCast("{\"source\":\"batch\"}"[0..]);
    const tenant_name_1 = @constCast("tenant"[0..]);
    const amount_name_1 = @constCast("amount"[0..]);
    const rank_name_1 = @constCast("rank"[0..]);
    const status_name_1 = @constCast("status"[0..]);
    const status_value_1 = @constCast("Open"[0..]);
    const attrs_name_1 = @constCast("attrs"[0..]);
    const attrs_value_1 = @constCast("{\"source\":\"api\",\"flags\":[\"open\"]}"[0..]);
    const tenant_name_2 = @constCast("tenant"[0..]);
    const amount_name_2 = @constCast("amount"[0..]);
    const rank_name_2 = @constCast("rank"[0..]);
    const status_name_2 = @constCast("status"[0..]);
    const status_value_2 = @constCast("pending"[0..]);
    const attrs_name_2 = @constCast("attrs"[0..]);
    const attrs_value_2 = @constCast("{\"source\":\"api\"}"[0..]);
    var cells_0 = [_]lake_rows.ProjectedCell{
        .{ .name = tenant_name_0, .value = .{ .i64 = 7 } },
        .{ .name = amount_name_0, .value = .{ .i64 = 10 } },
        .{ .name = rank_name_0, .value = .{ .i64 = 1 } },
        .{ .name = status_name_0, .value = .{ .bytes = status_value_0 } },
        .{ .name = attrs_name_0, .value = .{ .json = attrs_value_0 } },
    };
    var cells_1 = [_]lake_rows.ProjectedCell{
        .{ .name = tenant_name_1, .value = .{ .i64 = 8 } },
        .{ .name = amount_name_1, .value = .{ .i64 = 20 } },
        .{ .name = rank_name_1, .value = .{ .i64 = 3 } },
        .{ .name = status_name_1, .value = .{ .bytes = status_value_1 } },
        .{ .name = attrs_name_1, .value = .{ .json = attrs_value_1 } },
    };
    var cells_2 = [_]lake_rows.ProjectedCell{
        .{ .name = tenant_name_2, .value = .{ .i64 = 8 } },
        .{ .name = amount_name_2, .value = .{ .i64 = 30 } },
        .{ .name = rank_name_2, .value = .{ .i64 = 2 } },
        .{ .name = status_name_2, .value = .{ .bytes = status_value_2 } },
        .{ .name = attrs_name_2, .value = .{ .json = attrs_value_2 } },
    };
    var projected = [_]lake_rows.ProjectedRow{
        .{ .row_ref = .{ .relational_key = "row:1" }, .cells = &cells_0 },
        .{ .row_ref = .{ .relational_key = "row:2" }, .cells = &cells_1 },
        .{ .row_ref = .{ .relational_key = "row:3" }, .cells = &cells_2 },
    };
    const group_by = [_][]const u8{"tenant"};
    const filter_predicates = [_]runtime_schema.RelationalCheck{.{
        .name = "",
        .field = "amount",
        .op = .gte,
        .value_json = "20",
    }};
    const rank_two_filter = [_]db_mod.types.RelationalRowsInPredicate{.{
        .field = "rank",
        .values_json = "[2]",
    }};
    const rank_not_two_filter = [_]db_mod.types.RelationalRowsInPredicate{.{
        .field = "rank",
        .values_json = "[2]",
        .negated = true,
    }};
    const open_status_filter = [_]db_mod.types.RelationalRowsTextPatternPredicate{.{
        .field = "status",
        .pattern = "op%",
        .case_insensitive = true,
    }};
    const not_open_status_filter = [_]db_mod.types.RelationalRowsTextPatternPredicate{.{
        .field = "status",
        .pattern = "op%",
        .case_insensitive = true,
        .negated = true,
    }};
    const api_attrs_filter = [_]db_mod.types.RelationalRowsJsonContainsPredicate{.{
        .field = "attrs",
        .value_json = "{\"source\":\"api\"}",
    }};
    const source_api_filter = [_]db_mod.types.RelationalRowsJsonPathEqPredicate{.{
        .field = "attrs",
        .path = "source",
        .value_json = "\"api\"",
    }};
    const flags_exists_filter = [_]db_mod.types.RelationalRowsJsonPathExistsPredicate{.{
        .field = "attrs",
        .path = "flags",
    }};
    const lower_status_operands = [_]db_mod.types.RelationalRowsExpression{.{
        .kind = .field,
        .field = "status",
        .field_source = .row,
    }};
    const open_status_rhs = [_]db_mod.types.RelationalRowsExpression{.{
        .kind = .value,
        .value_json = "\"open\"",
    }};
    const open_status_expression_filter = [_]db_mod.types.RelationalRowsExpressionCondition{.{
        .lhs = .{ .kind = .lower, .operands = &lower_status_operands },
        .op = .eq,
        .rhs = &open_status_rhs,
    }};
    const amount_minus_rank_operands = [_]db_mod.types.RelationalRowsExpression{
        .{ .kind = .field, .field = "amount", .field_source = .row },
        .{ .kind = .field, .field = "rank", .field_source = .row },
    };
    const amount_minus_rank_rhs = [_]db_mod.types.RelationalRowsExpression{.{
        .kind = .value,
        .value_json = "18",
    }};
    const amount_minus_rank_filter = [_]db_mod.types.RelationalRowsExpressionCondition{.{
        .lhs = .{ .kind = .sub, .operands = &amount_minus_rank_operands },
        .op = .gte,
        .rhs = &amount_minus_rank_rhs,
    }};
    const aggregations = [_]db_mod.types.RelationalRowsAggregateSpec{
        .{ .name = "row_count", .op = .count },
        .{ .name = "large_amount_sum", .op = .sum, .field = "amount", .filter_predicates = &filter_predicates },
        .{ .name = "rank_two_amount_sum", .op = .sum, .field = "amount", .filter_in_predicates = &rank_two_filter },
        .{ .name = "rank_not_two_amount_sum", .op = .sum, .field = "amount", .filter_in_predicates = &rank_not_two_filter },
        .{ .name = "open_amount_sum", .op = .sum, .field = "amount", .filter_text_patterns = &open_status_filter },
        .{ .name = "not_open_amount_sum", .op = .sum, .field = "amount", .filter_text_patterns = &not_open_status_filter },
        .{ .name = "api_attrs_amount_sum", .op = .sum, .field = "amount", .filter_json_contains = &api_attrs_filter },
        .{ .name = "source_api_amount_sum", .op = .sum, .field = "amount", .filter_json_path_eq = &source_api_filter },
        .{ .name = "flags_amount_sum", .op = .sum, .field = "amount", .filter_json_path_exists = &flags_exists_filter },
        .{ .name = "open_expr_amount_sum", .op = .sum, .field = "amount", .filter_expressions = &open_status_expression_filter },
        .{ .name = "large_net_expr_amount_sum", .op = .sum, .field = "amount", .filter_expressions = &amount_minus_rank_filter },
    };
    const request = OwnedRowsAggregateRequest{
        .group_by = &group_by,
        .aggregations = &aggregations,
    };

    var result = try buildRowsAggregateResultFromLakeRowsAlloc(alloc, request, .{
        .rows = &projected,
        .total = 3,
    });
    defer result.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 2), result.total_groups);
    try std.testing.expectEqual(@as(usize, 2), result.rows.len);
    try std.testing.expectEqualStrings("{\"tenant\":7,\"row_count\":1,\"large_amount_sum\":0,\"rank_two_amount_sum\":0,\"rank_not_two_amount_sum\":10,\"open_amount_sum\":0,\"not_open_amount_sum\":10,\"api_attrs_amount_sum\":0,\"source_api_amount_sum\":0,\"flags_amount_sum\":0,\"open_expr_amount_sum\":0,\"large_net_expr_amount_sum\":0}", result.rows[0]);
    try std.testing.expectEqualStrings("{\"tenant\":8,\"row_count\":2,\"large_amount_sum\":50,\"rank_two_amount_sum\":30,\"rank_not_two_amount_sum\":20,\"open_amount_sum\":20,\"not_open_amount_sum\":30,\"api_attrs_amount_sum\":50,\"source_api_amount_sum\":50,\"flags_amount_sum\":20,\"open_expr_amount_sum\":20,\"large_net_expr_amount_sum\":30}", result.rows[1]);
}

test "relational rows lake bridge applies array aggregate filters" {
    const alloc = std.testing.allocator;
    const tenant_name_0 = @constCast("tenant"[0..]);
    const amount_name_0 = @constCast("amount"[0..]);
