        "{\"operations\":[{\"op\":\"update\",\"where\":{\"primary\":{\"id\":\"u1\"}},\"json_set\":[{\"field\":\"attrs\",\"path\":[\"billing\",\"plan\"],\"expr\":{\"op\":\"lower\",\"args\":[{\"field\":\"status\",\"source\":\"existing\"}]}}],\"returning\":[\"attrs.billing.plan\"]}]}",
