        std.testing.allocator,
        "{\"where\":{\"field\":\"status\",\"op\":\"eq\",\"value\":\"open\"},\"order_by\":[{\"field\":\"created_at\",\"expr\":{\"field\":\"amount\"}}]}",
        schema,
