    try std.testing.expectError(error.InvalidRowsRequest, parseRowsWindowRequest(
        std.testing.allocator,
        "{\"windows\":[{\"as\":\"bad_ntile\",\"function\":\"ntile\",\"order_by\":[{\"field\":\"amount\"}]}]}",
        schema,
