        schema,
    );
    defer sorted_merge_join_plan.deinit(alloc);
    var sorted_merge_join_result = try executeRowsJoinPlanOnJsonRowsAlloc(alloc, schema, sorted_merge_join_plan, rows[0..], rows[0..], rows[0..]);
    defer sorted_merge_join_result.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 8), sorted_merge_join_result.total_rows);
    try std.testing.expectEqual(db_mod.types.RelationalRowsJoinStrategy.merge, sorted_merge_join_result.strategy_selection.?.requested);
    try std.testing.expectEqual(db_mod.types.RelationalRowsJoinStrategy.merge, sorted_merge_join_result.strategy_selection.?.selected);
    try std.testing.expectEqualStrings("{\"left_id\":\"a\",\"right_id\":\"a\"}", sorted_merge_join_result.rows[0]);
    try std.testing.expectEqualStrings("{\"left_id\":\"b\",\"right_id\":\"b\"}", sorted_merge_join_result.rows[3]);
    try std.testing.expectEqualStrings("{\"left_id\":\"d\",\"right_id\":\"d\"}", sorted_merge_join_result.rows[7]);

    var hinted_auto_merge_join_plan = try parseRowsJoinPlanRequest(
        alloc,
        "{\"join\":{\"left\":{\"order_by\":[{\"field\":\"tenant\"},{\"field\":\"id\"}]},\"right\":{\"order_by\":[{\"field\":\"tenant\"},{\"field\":\"id\"}]},\"planning_hints\":{\"left\":{\"estimated_cardinality\":1000},\"right\":{\"estimated_cardinality\":1000},\"right_lookup_index\":\"available\"},\"on\":[{\"left_field\":\"tenant\",\"right_field\":\"tenant\"}],\"select\":[{\"as\":\"left_id\",\"side\":\"left\",\"field\":\"id\"},{\"as\":\"right_id\",\"side\":\"right\",\"field\":\"id\"}],\"order_by\":[{\"field\":\"left_id\"},{\"field\":\"right_id\"}]}}",
        schema,
    );
    defer hinted_auto_merge_join_plan.deinit(alloc);
    var hinted_auto_merge_join_result = try executeRowsJoinPlanOnJsonRowsAlloc(alloc, schema, hinted_auto_merge_join_plan, rows[0..], rows[0..], rows[0..]);
    defer hinted_auto_merge_join_result.deinit(alloc);
    try std.testing.expectEqual(db_mod.types.RelationalRowsJoinStrategy.auto, hinted_auto_merge_join_result.strategy_selection.?.requested);
    try std.testing.expectEqual(db_mod.types.RelationalRowsJoinStrategy.merge, hinted_auto_merge_join_result.strategy_selection.?.selected);
    try std.testing.expectEqual(@as(usize, 1000), hinted_auto_merge_join_result.strategy_selection.?.left_rows);
    try std.testing.expectEqual(@as(usize, 1000), hinted_auto_merge_join_result.strategy_selection.?.right_rows);
    try std.testing.expectEqual(db_mod.types.RelationalRowsJoinLookupIndexHint.available, hinted_auto_merge_join_result.strategy_selection.?.right_lookup_index);

    var lateral_plan = try parseRowsLateralPlanRequest(
        alloc,
        "{\"ctes\":[{\"name\":\"open_rows\",\"query\":{\"where\":{\"field\":\"status\",\"op\":\"eq\",\"value\":\"open\"},\"select\":[\"id\",\"tenant\",\"amount\",\"created_at\"]}}],\"lateral\":{\"left\":{\"where\":{\"field\":\"status\",\"op\":\"eq\",\"value\":\"open\"},\"order_by\":[{\"field\":\"id\"}]},\"right\":{\"source_cte\":\"open_rows\",\"order_by\":[{\"field\":\"created_at\",\"direction\":\"desc\"}],\"limit\":1},\"correlations\":[{\"left_field\":\"tenant\",\"right_field\":\"tenant\"}],\"select\":[{\"as\":\"left_id\",\"side\":\"left\",\"field\":\"id\"},{\"as\":\"latest_id\",\"side\":\"right\",\"field\":\"id\"}],\"order_by\":[{\"field\":\"left_id\"}]}}",
        schema,
    );
    defer lateral_plan.deinit(alloc);
    var lateral_result = try executeRowsLateralPlanOnJsonRowsAlloc(alloc, schema, lateral_plan, rows[0..], rows[0..], rows[0..]);
    defer lateral_result.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 3), lateral_result.total_rows);
    try std.testing.expectEqualStrings("{\"left_id\":\"a\",\"latest_id\":\"b\"}", lateral_result.rows[0]);
    try std.testing.expectEqualStrings("{\"left_id\":\"b\",\"latest_id\":\"b\"}", lateral_result.rows[1]);
    try std.testing.expectEqualStrings("{\"left_id\":\"c\",\"latest_id\":\"c\"}", lateral_result.rows[2]);

    var ranged_lateral_plan = try parseRowsLateralPlanRequest(
        alloc,
        "{\"ctes\":[{\"name\":\"open_rows\",\"query\":{\"where\":{\"field\":\"status\",\"op\":\"eq\",\"value\":\"open\"},\"select\":[\"id\",\"tenant\",\"amount\",\"created_at\"]}}],\"lateral\":{\"left\":{\"where\":{\"field\":\"status\",\"op\":\"eq\",\"value\":\"open\"},\"order_by\":[{\"field\":\"id\"}]},\"right\":{\"source_cte\":\"open_rows\",\"order_by\":[{\"field\":\"created_at\",\"direction\":\"desc\"}],\"limit\":1},\"correlations\":[{\"left_field\":\"tenant\",\"right_field\":\"tenant\"}],\"select\":[{\"as\":\"left_id\",\"side\":\"left\",\"field\":\"id\"},{\"as\":\"latest_id\",\"side\":\"right\",\"field\":\"id\"}],\"order_by\":[{\"field\":\"left_id\"}]}}",
        schema,
    );
    defer ranged_lateral_plan.deinit(alloc);
    ranged_lateral_plan.left_ranges = try singleRowsDocKeyRangeFromRowsAlloc(alloc, schema, rows[0], rows[2]);
    ranged_lateral_plan.right_ranges = try singleRowsDocKeyRangeFromRowsAlloc(alloc, schema, rows[0], rows[2]);
    var ranged_lateral_result = try executeRowsLateralPlanOnJsonRowsAlloc(alloc, schema, ranged_lateral_plan, rows[0..], rows[0..], rows[0..]);
    defer ranged_lateral_result.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 2), ranged_lateral_result.total_rows);
    try std.testing.expectEqualStrings("{\"left_id\":\"a\",\"latest_id\":\"b\"}", ranged_lateral_result.rows[0]);
    try std.testing.expectEqualStrings("{\"left_id\":\"b\",\"latest_id\":\"b\"}", ranged_lateral_result.rows[1]);

    var db_lateral_result = try executeRowsLateralPlanFromDbAlloc(alloc, &db, schema, ranged_lateral_plan);
    defer db_lateral_result.deinit(alloc);
