        "{\"expressions\":[{\"as\":\"bad\",\"expr\":{\"op\":\"case\",\"cases\":[{\"when\":{\"lhs\":{\"field\":\"email\"},\"op\":\"is_null\"},\"then\":{\"value\":\"missing\"},\"extra\":true}],\"else\":{\"value\":\"ok\"}}}]}",
