test "relational rows api query contract parses typed row claim request" {
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"rank":{"type":"numeric"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try @import("../schema/mod.zig").parseValidatedTableSchema(std.testing.allocator, schema_json);
    defer parsed.deinit(std.testing.allocator);
    const schema = try @import("../schema/mod.zig").deriveRuntimeTableSchema(std.testing.allocator, parsed);
    defer runtime_schema.freeSchema(std.testing.allocator, schema);

    var request = try parseRowsQueryRequest(
        std.testing.allocator,
        "{\"where\":{\"field\":\"status\",\"op\":\"eq\",\"value\":\"ready\"},\"row_claim\":{\"mode\":\"for_update\",\"wait_policy\":\"skip_locked\",\"lease_ms\":45000,\"owner_id\":\"session:7\",\"transaction_id\":\"00112233445566778899aabbccddeeff\"},\"limit\":10}",
        schema,
    );
    defer request.deinit(std.testing.allocator);

    const claim = request.row_claim orelse return error.TestExpectedEqual;
    try std.testing.expectEqual(db_mod.types.RowClaimMode.for_update, claim.mode);
    try std.testing.expectEqual(db_mod.types.RowClaimWaitPolicy.skip_locked, claim.wait_policy);
    try std.testing.expectEqual(db_mod.types.RowClaimWaitPolicy.skip_locked, claim.effectiveWaitPolicy());
    try std.testing.expect(claim.skip_locked);
    try std.testing.expectEqual(@as(u64, 45_000), claim.lease_ms);
    try std.testing.expectEqualStrings("session:7", claim.owner_id);
    try std.testing.expectEqual(@as(u8, 0x00), claim.txn_id.?[0]);
    try std.testing.expectEqual(@as(u8, 0x11), claim.txn_id.?[1]);
    try std.testing.expectEqual(@as(u8, 0xff), claim.txn_id.?[15]);

    try std.testing.expectError(error.InvalidRowsRequest, parseRowsQueryRequest(
        std.testing.allocator,
        "{\"row_claim\":{\"transaction_id\":\"001122\"}}",
        schema,
    ));
    try std.testing.expectError(error.InvalidRowsRequest, parseRowsQueryRequest(
        std.testing.allocator,
        "{\"row_claim\":{\"transaction_id\":\"00112233445566778899aabbccddeeff\"}}",
        schema,
    ));
    try std.testing.expectError(error.InvalidRowsRequest, parseRowsQueryRequest(
        std.testing.allocator,
        "{\"row_claim\":{\"owner_id\":\"\",\"transaction_id\":\"00112233445566778899aabbccddeeff\"}}",
        schema,
    ));
    try std.testing.expectError(error.InvalidRowsRequest, parseRowsQueryRequest(
        std.testing.allocator,
        "{\"row_claim\":{\"transaction_id\":\"00112233445566778899aabbccddeefg\"}}",
        schema,
    ));
    try std.testing.expectError(error.InvalidRowsRequest, parseRowsQueryRequest(
        std.testing.allocator,
        "{\"row_claim\":{\"transaction_id\":\"00112233445566778899aabbccddeeff\",\"unknown\":true}}",
        schema,
    ));
    try std.testing.expectError(error.InvalidRowsRequest, parseRowsQueryRequest(
        std.testing.allocator,
        "{\"row_claim\":{\"txn_id\":\"00112233445566778899aabbccddeeff\"}}",
        schema,
    ));
    try std.testing.expectError(error.InvalidRowsRequest, parseRowsQueryRequest(
        std.testing.allocator,
        "{\"row_claim\":{\"wait_policy\":\"skip_locked\",\"skip_locked\":false,\"owner_id\":\"session:bad\",\"transaction_id\":\"00112233445566778899aabbccddeeff\"}}",
        schema,
    ));
    try std.testing.expectError(error.InvalidRowsRequest, parseRowsQueryRequest(
        std.testing.allocator,
        "{\"row_claim\":{\"wait_policy\":\"later\",\"owner_id\":\"session:bad\",\"transaction_id\":\"00112233445566778899aabbccddeeff\"}}",
        schema,
    ));
    try std.testing.expectError(error.InvalidRowsRequest, parseRowsQueryRequest(
        std.testing.allocator,
        "{\"row_claim\":{\"lease_ms\":0,\"owner_id\":\"session:bad\",\"transaction_id\":\"00112233445566778899aabbccddeeff\"}}",
        schema,
    ));
    try std.testing.expectError(error.InvalidRowsRequest, parseRowsQueryRequest(
        std.testing.allocator,
        "{\"source_cte\":\"materialized_ready\",\"row_claim\":{\"mode\":\"for_update\",\"owner_id\":\"session:cte\",\"transaction_id\":\"00112233445566778899aabbccddeeff\"}}",
        schema,
    ));

    var no_key_update_request = try parseRowsQueryRequest(
        std.testing.allocator,
        "{\"row_claim\":{\"mode\":\"for_no_key_update\",\"wait_policy\":\"skip_locked\",\"owner_id\":\"session:no-key\",\"transaction_id\":\"00112233445566778899aabbccddeeff\"}}",
        schema,
    );
    defer no_key_update_request.deinit(std.testing.allocator);
    try std.testing.expectEqual(db_mod.types.RowClaimMode.for_no_key_update, no_key_update_request.row_claim.?.mode);
    try std.testing.expectEqual(db_mod.types.RowClaimWaitPolicy.skip_locked, no_key_update_request.row_claim.?.wait_policy);
    try std.testing.expect(no_key_update_request.row_claim.?.effectiveSkipLocked());

    var share_request = try parseRowsQueryRequest(
        std.testing.allocator,
        "{\"row_claim\":{\"mode\":\"for_share\",\"wait_policy\":\"wait\",\"owner_id\":\"session:share\",\"transaction_id\":\"00112233445566778899aabbccddeeff\"}}",
        schema,
    );
    defer share_request.deinit(std.testing.allocator);
    try std.testing.expectEqual(db_mod.types.RowClaimMode.for_share, share_request.row_claim.?.mode);
    try std.testing.expectEqual(db_mod.types.RowClaimWaitPolicy.wait, share_request.row_claim.?.wait_policy);
    try std.testing.expect(!share_request.row_claim.?.effectiveSkipLocked());

    var key_share_request = try parseRowsQueryRequest(
        std.testing.allocator,
        "{\"row_claim\":{\"mode\":\"for_key_share\",\"wait_policy\":\"nowait\",\"owner_id\":\"session:key-share\",\"transaction_id\":\"00112233445566778899aabbccddeeff\"}}",
        schema,
    );
    defer key_share_request.deinit(std.testing.allocator);
    try std.testing.expectEqual(db_mod.types.RowClaimMode.for_key_share, key_share_request.row_claim.?.mode);
    try std.testing.expectEqual(db_mod.types.RowClaimWaitPolicy.nowait, key_share_request.row_claim.?.wait_policy);
    try std.testing.expect(!key_share_request.row_claim.?.effectiveSkipLocked());

    var nowait_request = try parseRowsQueryRequest(
        std.testing.allocator,
        "{\"row_claim\":{\"wait_policy\":\"nowait\",\"owner_id\":\"session:nowait\",\"transaction_id\":\"00112233445566778899aabbccddeeff\"}}",
        schema,
    );
    defer nowait_request.deinit(std.testing.allocator);
    try std.testing.expectEqual(db_mod.types.RowClaimWaitPolicy.nowait, nowait_request.row_claim.?.wait_policy);
    try std.testing.expect(!nowait_request.row_claim.?.skip_locked);
    try std.testing.expect(!nowait_request.row_claim.?.effectiveSkipLocked());
}

test "relational rows mutation source contract parses claimed update plans" {
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"amount":{"type":"numeric"},"expires_at_ns":{"type":"datetime"},"attrs":{"type":"json"}},"required":["id","status"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try @import("../schema/mod.zig").parseValidatedTableSchema(std.testing.allocator, schema_json);
    defer parsed.deinit(std.testing.allocator);
    const schema = try @import("../schema/mod.zig").deriveRuntimeTableSchema(std.testing.allocator, parsed);
    defer runtime_schema.freeSchema(std.testing.allocator, schema);

    var request = try parseRowsMutationSourceRequest(
        std.testing.allocator,
        "{\"op\":\"update\",\"source\":{\"where\":{\"field\":\"status\",\"op\":\"eq\",\"value\":\"ready\"},\"order_by\":[{\"field\":\"amount\",\"direction\":\"asc\"}],\"limit\":2,\"row_claim\":{\"mode\":\"for_update\",\"skip_locked\":true,\"owner_id\":\"session:mutation\",\"transaction_id\":\"00112233445566778899aabbccddeeff\"}},\"patch\":{\"status\":\"claimed\"},\"returning\":[\"id\",\"status\"],\"returning_expressions\":[{\"as\":\"amount_plus_one\",\"expr\":{\"op\":\"add\",\"args\":[{\"field\":\"amount\"},{\"value\":1}]}}]}",
        schema,
    );
    defer request.deinit(std.testing.allocator);

    try std.testing.expectEqual(db_mod.types.RelationalRowsMutationKind.update, request.req.kind);
    try std.testing.expectEqual(@as(usize, 1), request.req.source.predicates.len);
    try std.testing.expectEqualStrings("status", request.req.source.predicates[0].field);
    try std.testing.expectEqual(@as(usize, 1), request.req.source.order_by.len);
    try std.testing.expectEqual(@as(u32, 2), request.req.source.limit.?);
    try std.testing.expect(request.req.source.row_claim != null);
    try std.testing.expect(request.req.source.row_claim.?.skip_locked);
    try std.testing.expectEqual(@as(usize, 1), request.req.operations.len);
    try std.testing.expectEqual(db_mod.types.TransformOpType.set, request.req.operations[0].op);
    try std.testing.expectEqualStrings("status", request.req.operations[0].path);
